INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掛け合わせる」は対象を「を」で取る。「馬とロバを」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「馬とロバの掛け合わせると」は動詞に続かず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「馬とロバに掛け合わせると」は対象を示す「に」が不自然で、「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「馬とロバへ掛け合わせると」は意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「掛け合わせる」は対象を「を」で取る。「馬とロバを」が正しい。", "の": "連体修飾の助詞で、「馬とロバの掛け合わせると」は動詞に続かず文が成り立たない。", "に": "「馬とロバに掛け合わせると」は対象を示す「に」が不自然で、「を」が必要。", "へ": "「へ」は方向を示すので、「馬とロバへ掛け合わせると」は意味が合わない。"}, "error_tags": {"の": "連体の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掛け合わせる」は対象を「を」で取る。「野菜を」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「野菜から掛け合わせて」は起点の意味になり、対象を組み合わせる文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「野菜より掛け合わせて」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「野菜の掛け合わせて」では動詞に続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「掛け合わせる」は対象を「を」で取る。「野菜を」が正しい。", "から": "「野菜から掛け合わせて」は起点の意味になり、対象を組み合わせる文として不自然。", "より": "比較の「より」は「野菜より掛け合わせて」では意味が通らない。", "の": "「野菜の掛け合わせて」では動詞に続かず、文が成り立たない。"}, "error_tags": {"から": "起点の誤り", "より": "比較の誤り", "の": "連体の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものをいっしょにする。", "primary_collocate": null, "pronunciation": "かけあわせる", "ipa": "kakeawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "農家は甘い品種と病気に強い品種を掛け合わせて、新しい米を作った。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "農家[のうか]は甘[あま]い品種[ひんしゅ]と病気[びょうき]に強[つよ]い品種[ひんしゅ]を掛[か]け合[あ]わせて、新[あたら]しい米[こめ]を作[つく]った。", "sentence_source": "generated"}, {"text": "馬とロバを掛け合わせると、ラバが生まれる。", "target_word": "掛け合わせる", "complexity_tier": "T3", "furigana": "馬[うま]とロバを掛[か]け合[あ]わせると、ラバが生[う]まれる。", "sentence_source": "generated"}, {"text": "研究者は、寒さに強い花と色の濃い花を掛け合わせようとしている。", "target_word": "掛け合わせよう", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、寒[さむ]さに強[つよ]い花[はな]と色[いろ]の濃[こ]い花[はな]を掛[か]け合[あ]わせようとしている。", "sentence_source": "generated"}, {"text": "犬の品種を掛け合わせた雑種は、性格が親に似ないこともある。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "犬[いぬ]の品種[ひんしゅ]を掛[か]け合[あ]わせた雑種[ざっしゅ]は、性格[せいかく]が親[おや]に似[に]ないこともある。", "sentence_source": "generated"}, {"text": "このみかんは、二種類の果物を掛け合わせて作られた。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "このみかんは、二種類[にしゅるい]の果物[くだもの]を掛[か]け合[あ]わせて作[つく]られた。", "sentence_source": "generated"}, {"text": "牛の品種を掛け合わせて、肉の質をよくする研究が続いている。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "牛[うし]の品種[ひんしゅ]を掛[か]け合[あ]わせて、肉[にく]の質[しつ]をよくする研究[けんきゅう]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "長所が異なる二つの方法を掛け合わせたところ、結果が大きく改善した。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "長所[ちょうしょ]が異[こと]なる二[ふた]つの方法[ほうほう]を掛[か]け合[あ]わせたところ、結果[けっか]が大[おお]きく改善[かいぜん]した。", "sentence_source": "generated"}, {"text": "二つの野菜を掛け合わせてできた新種が、市場に並んだ。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "二[ふた]つの野菜[やさい]を掛[か]け合[あ]わせてできた新種[しんしゅ]が、市場[いちば]に並[なら]んだ。", "sentence_source": "generated"}, {"text": "品種を掛け合わせるには、花粉をほかの花につける必要がある。", "target_word": "掛け合わせる", "complexity_tier": "T3", "furigana": "品種[ひんしゅ]を掛[か]け合[あ]わせるには、花粉[かふん]をほかの花[はな]につける必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "優れた親同士を掛け合わせたので、子馬の成長が楽しみだ。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "優[すぐ]れた親同士[おやどうし]を掛[か]け合[あ]わせたので、子馬[こうま]の成長[せいちょう]が楽[たの]しみだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け合わせる", "label": "終止形"}, {"form": "掛け合わせ", "label": "連用形"}, {"form": "掛け合わせた", "label": "夕形"}, {"form": "掛け合わせて", "label": "て形"}, {"form": "掛け合わせない", "label": "否定形"}, {"form": "掛け合わせれば", "label": "仮定形"}, {"form": "掛け合わせよう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "動植物の品種など二つ以上のものを交配させたり、いっしょにしたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け合わせて", "is_correct": true, "explanation": "て形で、「掛け合わせて、」と後ろの「新しい米を作った」へ手段としてつながる。"}, {"text": "育てよう", "is_correct": false, "explanation": "意志形なので文が途中で止まり、「作った」へつながらない。"}, {"text": "作れば", "is_correct": false, "explanation": "仮定形なので「作れば、新しい米を作った」となり、文の流れが合わない。"}, {"text": "混ぜよう", "is_correct": false, "explanation": "意志形は勧誘の意味になり、作った結果を述べる文に合わない。"}], "explanations": {"掛け合わせて": "て形で、「掛け合わせて、」と後ろの「新しい米を作った」へ手段としてつながる。", "育てよう": "意志形なので文が途中で止まり、「作った」へつながらない。", "作れば": "仮定形なので「作れば、新しい米を作った」となり、文の流れが合わない。", "混ぜよう": "意志形は勧誘の意味になり、作った結果を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "掛け合わせて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベランダの手すりに布団を掛け合わせて、日に当てた。", "explanation": "ここは〈掛ける〉（物をかけて干す）の意味。掛け合わせるは品種や要素を合わせる意味で、布団を手すりにかける場面には使わない。"}, {"text": "門に鍵を掛け合わせて、家を出た。", "explanation": "ここは〈掛ける〉（錠をおろす）の意味。掛け合わせるは品種や要素を合わせる意味で、鍵を門にかける場面には使わない。"}, {"text": "担当の役所に何度も掛け合わせて、補助金を頼んだ。", "explanation": "ここは〈掛け合う〉（交渉する）の意味。掛け合わせるは交配や組み合わせの意味で、役所との交渉には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け合わせた", "is_correct": true, "explanation": "夕形で「ところ」に続き、「二つの方法を組み合わせた結果」を表す。"}, {"text": "掛け合わせ", "is_correct": false, "explanation": "連用形は「ところ」に続かず、文が成り立たない。"}, {"text": "掛け合わせて", "is_correct": false, "explanation": "て形は「ところ」の前に置けず、不自然になる。"}, {"text": "掛け合わせれば", "is_correct": false, "explanation": "仮定形は「ところ」の前に置けず、文が成り立たない。"}], "explanations": {"掛け合わせた": "夕形で「ところ」に続き、「二つの方法を組み合わせた結果」を表す。", "掛け合わせ": "連用形は「ところ」に続かず、文が成り立たない。", "掛け合わせて": "て形は「ところ」の前に置けず、不自然になる。", "掛け合わせれば": "仮定形は「ところ」の前に置けず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "掛け合わせた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁に時計を掛け合わせて、部屋を飾った。", "explanation": "ここは〈掛ける〉の意味。掛け合わせるは品種や要素を合わせる意味で、時計を壁にかける場面には使わない。"}, {"text": "川に橋を掛け合わせて、向こう岸へ渡した。", "explanation": "ここは〈架ける〉の意味。掛け合わせるは品種や要素を合わせる意味で、橋を架ける場面には使わない。"}, {"text": "シャツのボタンを一つずつ掛け合わせて、ずれないように留めた。", "explanation": "ここは〈掛ける〉（ボタンを留める）の意味。掛け合わせるは別々のものを合わせて新しいものを生む意味で、ボタンを留める動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "牛と水牛を掛け合わせる、丈夫な雑種を作った。", "corrected_sentence": "牛と水牛を掛け合わせて、丈夫な雑種を作った。", "error_description": "「掛け合わせて」のて形を終止形「掛け合わせる」にすると、後ろの「丈夫な雑種を作った」へ続かず文が途切れる。正しくは「掛け合わせて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掛け合わせる", "is_correct": true, "explanation": "終止形で「と」の前に置き、「掛け合わせると〜になる」という一般的な条件と結果を表す。"}, {"text": "掛け合わせ", "is_correct": false, "explanation": "連用形は「と」に続かず、文が成り立たない。"}, {"text": "掛け合わせない", "is_correct": false, "explanation": "否定形だと「掛け合わせないと」となり、ラバが生まれるという結果が逆になる。"}, {"text": "掛け合わせて", "is_correct": false, "explanation": "て形は「と」の条件の前に置けず、文が成り立たない。"}], "correct_form": "掛け合わせる", "base_form": "掛け合わせる", "form_label": "終止形", "sentence_index": 1, "explanations": {"掛け合わせる": "終止形で「と」の前に置き、「掛け合わせると〜になる」という一般的な条件と結果を表す。", "掛け合わせ": "連用形は「と」に続かず、文が成り立たない。", "掛け合わせない": "否定形だと「掛け合わせないと」となり、ラバが生まれるという結果が逆になる。", "掛け合わせて": "て形は「と」の条件の前に置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52169, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鶏と七面鳥に掛け合わせて、新しい鳥を育てた。", "corrected_sentence": "鶏と七面鳥を掛け合わせて、新しい鳥を育てた。", "error_description": "「掛け合わせる」は対象を「を」で取る。「七面鳥に」は誤りで、正しくは「七面鳥を掛け合わせて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掛け合わせて", "is_correct": true, "explanation": "て形で、「できた新種」へ手段・結果としてつながる。"}, {"text": "掛け合わせる", "is_correct": false, "explanation": "終止形では「掛け合わせる新種」となり、すでに作られた新種という意味に合わない。"}, {"text": "掛け合わせよう", "is_correct": false, "explanation": "意志形は勧誘の意味になり、すでに出来た新種を述べる文に合わない。"}, {"text": "掛け合わせれば", "is_correct": false, "explanation": "仮定形は「もし掛け合わせれば」の意味になり、「できた」という完了した事実に合わない。"}], "correct_form": "掛け合わせて", "base_form": "掛け合わせる", "form_label": "て形", "sentence_index": 7, "explanations": {"掛け合わせて": "て形で、「できた新種」へ手段・結果としてつながる。", "掛け合わせる": "終止形では「掛け合わせる新種」となり、すでに作られた新種という意味に合わない。", "掛け合わせよう": "意志形は勧誘の意味になり、すでに出来た新種を述べる文に合わない。", "掛け合わせれば": "仮定形は「もし掛け合わせれば」の意味になり、「できた」という完了した事実に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掛け合わせる」は組み合わせる対象を「を」で取る。「味を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「味が掛け合わせた」では味が主語になり、作る人が組み合わせる文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「味に掛け合わせた」は対象を示す「に」が不自然で、「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「味へ掛け合わせた」は意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「掛け合わせる」は組み合わせる対象を「を」で取る。「味を」が正しい。", "が": "「味が掛け合わせた」では味が主語になり、作る人が組み合わせる文として成り立たない。", "に": "「味に掛け合わせた」は対象を示す「に」が不自然で、「を」が必要。", "へ": "「へ」は方向を示すので、「味へ掛け合わせた」は意味が合わない。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掛け合わせる」は組み合わせる対象を「を」で取る。「強みを」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「強みから掛け合わせて」は起点の意味になり、対象を組み合わせる文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「強みより掛け合わせて」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「強みの掛け合わせて」では動詞に続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「掛け合わせる」は組み合わせる対象を「を」で取る。「強みを」が正しい。", "から": "「強みから掛け合わせて」は起点の意味になり、対象を組み合わせる文として不自然。", "より": "比較の「より」は「強みより掛け合わせて」では意味が通らない。", "の": "「強みの掛け合わせて」では動詞に続かず、文が成り立たない。"}, "error_tags": {"から": "起点の誤り", "より": "比較の誤り", "の": "連体の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数のものを組み合わせて一つにすること。", "primary_collocate": null, "pronunciation": "かけあわせる", "ipa": "kakeawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "その解答の一つが、ピーナッツバターとジャムを掛け合わせたサンドイッチの構築にある。", "target_word": "掛け合わせた", "complexity_tier": "T4", "furigana": "その解答[かいとう]の一[ひと]つが、ピーナッツバターとジャムを掛[か]け合[あ]わせたサンドイッチの構築[こうちく]にある。", "sentence_source": "mined"}, {"text": "和と洋の味を掛け合わせた新しいデザートが、店の人気商品になった。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "和[わ]と洋[よう]の味[あじ]を掛[か]け合[あ]わせた新[あたら]しいデザートが、店[みせ]の人気商品[にんきしょうひん]になった。", "sentence_source": "generated"}, {"text": "二つの童話を掛け合わせて、新しい物語を作った。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "二[ふた]つの童話[どうわ]を掛[か]け合[あ]わせて、新[あたら]しい物語[ものがたり]を作[つく]った。", "sentence_source": "generated"}, {"text": "伝統の技術と最新の機械を掛け合わせれば、これまでにない製品ができる。", "target_word": "掛け合わせれば", "complexity_tier": "T3", "furigana": "伝統[でんとう]の技術[ぎじゅつ]と最新[さいしん]の機械[きかい]を掛[か]け合[あ]わせれば、これまでにない製品[せいひん]ができる。", "sentence_source": "generated"}, {"text": "この服は、二つの模様を掛け合わせたデザインが特徴だ。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "この服[ふく]は、二[ふた]つの模様[もよう]を掛[か]け合[あ]わせたデザインが特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "音楽とダンスを掛け合わせた舞台は、若い客に好評だった。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "音楽[おんがく]とダンスを掛[か]け合[あ]わせた舞台[ぶたい]は、若[わか]い客[きゃく]に好評[こうひょう]だった。", "sentence_source": "generated"}, {"text": "彼は、料理と科学を掛け合わせる発想で、新しい調理法を考えた。", "target_word": "掛け合わせる", "complexity_tier": "T3", "furigana": "彼[かれ]は、料理[りょうり]と科学[かがく]を掛[か]け合[あ]わせる発想[はっそう]で、新[あたら]しい調理法[ちょうりほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "二つの会社の強みを掛け合わせて、新しいサービスを始めることになった。", "target_word": "掛け合わせて", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の強[つよ]みを掛[か]け合[あ]わせて、新[あたら]しいサービスを始[はじ]めることになった。", "sentence_source": "generated"}, {"text": "絵本と音楽を掛け合わせたイベントを、図書館で開く予定だ。", "target_word": "掛け合わせた", "complexity_tier": "T3", "furigana": "絵本[えほん]と音楽[おんがく]を掛[か]け合[あ]わせたイベントを、図書館[としょかん]で開[ひら]く予定[よてい]だ。", "sentence_source": "generated"}, {"text": "異なる分野の知識を掛け合わせることで、独自の研究が生まれた。", "target_word": "掛け合わせる", "complexity_tier": "T3", "furigana": "異[こと]なる分野[ぶんや]の知識[ちしき]を掛[か]け合[あ]わせることで、独自[どくじ]の研究[けんきゅう]が生[う]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け合わせる", "label": "終止形"}, {"form": "掛け合わせ", "label": "連用形"}, {"form": "掛け合わせた", "label": "夕形"}, {"form": "掛け合わせて", "label": "て形"}, {"form": "掛け合わせない", "label": "否定形"}, {"form": "掛け合わせれば", "label": "仮定形"}, {"form": "掛け合わせよう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "味・技術・発想など別々のものを組み合わせ、新しい一つのものにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け合わせた", "is_correct": true, "explanation": "連体形（夕形）で「サンドイッチ」を修飾し、二つを組み合わせて作ったという意味になり、文が通る。"}, {"text": "混ぜて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「サンドイッチ」へつながらない。"}, {"text": "作れば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、ここでは文が成り立たない。"}, {"text": "刻もう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「サンドイッチの構築」へ続かない。"}], "explanations": {"掛け合わせた": "連体形（夕形）で「サンドイッチ」を修飾し、二つを組み合わせて作ったという意味になり、文が通る。", "混ぜて": "て形は名詞を修飾できず、「サンドイッチ」へつながらない。", "作れば": "仮定形は名詞を修飾できず、ここでは文が成り立たない。", "刻もう": "意志形は名詞を修飾できず、「サンドイッチの構築」へ続かない。"}, "sentence_index": 0, "correct_answer": "掛け合わせた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物干しに洗濯物を掛け合わせて、干した。", "explanation": "ここは〈掛ける〉（物をかける）の意味。掛け合わせるは要素を組み合わせて一つにする意味で、洗濯物を物干しにかける場面には使わない。"}, {"text": "担当の部署に何度も掛け合わせて、値段の見直しを頼んだ。", "explanation": "ここは〈掛け合う〉（交渉する）の意味。掛け合わせるは組み合わせる意味で、相手に掛け合う交渉には使わない。"}, {"text": "壁に絵を掛け合わせて、部屋を飾った。", "explanation": "ここは〈掛ける〉（吊るす）の意味。掛け合わせるは組み合わせる意味で、壁に物をかける場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け合わせる", "is_correct": true, "explanation": "終止形で名詞「発想」を修飾し、「料理と科学を組み合わせる」発想という意味になり文が通る。"}, {"text": "煮て", "is_correct": false, "explanation": "て形は名詞を修飾できず、「発想」へつながらない。"}, {"text": "焼けば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文が成り立たない。"}, {"text": "炒めよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文の流れが途切れる。"}], "explanations": {"掛け合わせる": "終止形で名詞「発想」を修飾し、「料理と科学を組み合わせる」発想という意味になり文が通る。", "煮て": "て形は名詞を修飾できず、「発想」へつながらない。", "焼けば": "仮定形は名詞を修飾できず、文が成り立たない。", "炒めよう": "意志形は名詞を修飾できず、文の流れが途切れる。"}, "sentence_index": 6, "correct_answer": "掛け合わせる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の戸に鍵を掛け合わせて、家を出た。", "explanation": "ここは〈掛ける〉（錠をおろす）の意味。掛け合わせるは組み合わせて一つにする意味で、戸に鍵をかける動作には使わない。"}, {"text": "川に橋を掛け合わせて、向こう岸へ渡した。", "explanation": "ここは〈架ける〉（橋を渡す）の意味。掛け合わせるは組み合わせて一つにする意味で、橋を架ける場面には使わない。"}, {"text": "二つの仕事を掛け合わせて、週末も働いている。", "explanation": "ここは〈掛け持つ〉の意味。掛け合わせるは組み合わせる意味で、同時に二つの仕事を担当する意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスと陶器の技法に掛け合わせて、新しい器を作った。", "corrected_sentence": "ガラスと陶器の技法を掛け合わせて、新しい器を作った。", "error_description": "「掛け合わせる」は組み合わせる対象を「を」で取る。「技法に」は誤りで、正しくは「技法を掛け合わせて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掛け合わせた", "is_correct": true, "explanation": "夕形で、既に作られた完了の意味。「新しいデザート」を修飾し、店の人気商品になった経緯と合う。"}, {"text": "掛け合わせよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「新しいデザート」へつながらない。"}, {"text": "掛け合わせて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「新しいデザート」へつながらない。"}, {"text": "掛け合わせれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文が成り立たない。"}], "correct_form": "掛け合わせた", "base_form": "掛け合わせる", "form_label": "夕形", "sentence_index": 1, "explanations": {"掛け合わせた": "夕形で、既に作られた完了の意味。「新しいデザート」を修飾し、店の人気商品になった経緯と合う。", "掛け合わせよう": "意志形は名詞を修飾できず、「新しいデザート」へつながらない。", "掛け合わせて": "て形は名詞を修飾できず、「新しいデザート」へつながらない。", "掛け合わせれば": "仮定形は名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二種類の材料を掛け合わせれ、新しい味が生まれる。", "corrected_sentence": "二種類の材料を掛け合わせれば、新しい味が生まれる。", "error_description": "仮定形は「掛け合わせれば」。「ば」が抜けると「れ」だけが残り、文として続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掛け合わせて", "is_correct": true, "explanation": "て形で、後ろの「新しいサービスを始める」へ手段としてつながる。"}, {"text": "掛け合わせた", "is_correct": false, "explanation": "夕形だと文がそこで一度完結し、後ろの「新しいサービスを始める」へ続かない。"}, {"text": "掛け合わせない", "is_correct": false, "explanation": "否定形だと「組み合わせないで」の意味になり、組み合わせてサービスを始めたという内容に反する。"}, {"text": "掛け合わせよう", "is_correct": false, "explanation": "意志形は勧誘の意味になり、既に決まったことを述べる文に合わない。"}], "correct_form": "掛け合わせて", "base_form": "掛け合わせる", "form_label": "て形", "sentence_index": 7, "explanations": {"掛け合わせて": "て形で、後ろの「新しいサービスを始める」へ手段としてつながる。", "掛け合わせた": "夕形だと文がそこで一度完結し、後ろの「新しいサービスを始める」へ続かない。", "掛け合わせない": "否定形だと「組み合わせないで」の意味になり、組み合わせてサービスを始めたという内容に反する。", "掛け合わせよう": "意志形は勧誘の意味になり、既に決まったことを述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
