INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「バリアが」は「ある」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「を」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するが、後ろに名詞が続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。存在を表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「バリアが」は「ある」の主語を示す。", "を": "「ある」は目的語を取らないので、「を」は合わない。", "の": "「の」は名詞を修飾するが、後ろに名詞が続かず文が成り立たない。", "へ": "「へ」は移動の方向を示す。存在を表す文には合わない。"}, "error_tags": {"を": "目的語", "の": "連体", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをさえぎるもののことです。", "primary_collocate": null, "pronunciation": "ばりあ", "ipa": "baɾia", "syllable_count": 3, "sentences": [{"text": "ゲームの主人公は、バリアで敵の攻撃を防いだ。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "ゲームの主人公[しゅじんこう]は、バリアで敵[てき]の攻撃[こうげき]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "この装置は、光のバリアで虫が入るのをさえぎる。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "この装置[そうち]は、光[ひかり]のバリアで虫[むし]が入[はい]るのをさえぎる。", "sentence_source": "generated"}, {"text": "映画の宇宙船は、バリアを張って隕石を防いだ。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "映画[えいが]の宇宙船[うちゅうせん]は、バリアを張[は]って隕石[いんせき]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "道路の工事現場には、赤いバリアが並んでいる。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "道路[どうろ]の工事現場[こうじげんば]には、赤[あか]いバリアが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "池のまわりにバリアを立てて、子どもが入らないようにした。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "池[いけ]のまわりにバリアを立[た]てて、子[こ]どもが入[はい]らないようにした。", "sentence_source": "generated"}, {"text": "ゲームの中で、バリアが消えて、キャラクターが倒れた。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "ゲームの中[なか]で、バリアが消[き]えて、キャラクターが倒[たお]れた。", "sentence_source": "generated"}, {"text": "魔法使いはバリアを作り、仲間を守った。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "魔法使[まほうつか]いはバリアを作[つく]り、仲間[なかま]を守[まも]った。", "sentence_source": "generated"}, {"text": "駐車場の入口に、車を止めるバリアがある。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]の入口[いりぐち]に、車[くるま]を止[と]めるバリアがある。", "sentence_source": "generated"}, {"text": "工事中は大きなバリアが人をさえぎり、道に入れなかった。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]は大[おお]きなバリアが人[ひと]をさえぎり、道[みち]に入[はい]れなかった。", "sentence_source": "generated"}, {"text": "兄は、バリアが張れるキャラクターが好きだ。", "target_word": "バリア", "complexity_tier": "T2", "furigana": "兄[あに]は、バリアが張[は]れるキャラクターが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バリア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "攻撃や人・ものの侵入をさえぎる壁や柵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T4: contains vocabulary far above tier T4: さえぎり (Zipf 1.35)']::text[], '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バリア", "is_correct": true, "explanation": "攻撃をさえぎる見えない壁の意味で、敵の攻撃を防ぐ文に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は甘味料で、敵の攻撃を防ぐ働きはない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の文章で、攻撃を防ぐものではない。"}, {"text": "味噌", "is_correct": false, "explanation": "味噌は調味料で、攻撃を防ぐ役には立たない。"}], "explanations": {"バリア": "攻撃をさえぎる見えない壁の意味で、敵の攻撃を防ぐ文に合う。", "砂糖": "砂糖は甘味料で、敵の攻撃を防ぐ働きはない。", "歌詞": "歌詞は歌の文章で、攻撃を防ぐものではない。", "味噌": "味噌は調味料で、攻撃を防ぐ役には立たない。"}, "sentence_index": 0, "correct_answer": "バリア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トイレに入って、バリアを流した。", "explanation": "バリアは物をさえぎる壁で、水を流す設備ではない。"}, {"text": "買い物のバリアに野菜を入れた。", "explanation": "バリアは仕切りで、野菜を入れる容器ではない。"}, {"text": "その選手は、バリアを勢いよく投げた。", "explanation": "バリアは投げて使う物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バリア", "is_correct": true, "explanation": "作れるものとして自然で、仲間を守る文に合う。"}, {"text": "深呼吸", "is_correct": false, "explanation": "深呼吸は行為で、「作る」の対象にはならない。"}, {"text": "咳", "is_correct": false, "explanation": "咳は体の反応で、「作る」の対象にはならない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸音で、「作る」の対象にはならない。"}], "explanations": {"バリア": "作れるものとして自然で、仲間を守る文に合う。", "深呼吸": "深呼吸は行為で、「作る」の対象にはならない。", "咳": "咳は体の反応で、「作る」の対象にはならない。", "寝息": "寝息は眠っている人の呼吸音で、「作る」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "バリア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テニスのバリアが切れてしまった。", "explanation": "バリアは物をさえぎる壁で、テニスの網の役は果たさない。"}, {"text": "誕生日に、バリアを焼いた。", "explanation": "バリアは焼いて食べる菓子ではない。"}, {"text": "母はバリアを見ながら料理を作った。", "explanation": "バリアは料理の手順を書いたものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロボットは、バリアが張って敵の攻撃を防いだ。", "corrected_sentence": "ロボットは、バリアを張って敵の攻撃を防いだ。", "error_description": "「張る」の目的語は「を」で、「バリアが」は誤り。「バリアを張る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事現場の人が、通路にバリアが置いた。", "corrected_sentence": "工事現場の人が、通路にバリアを置いた。", "error_description": "「置く」の目的語は「を」で、「バリアが」は誤り。「バリアを置く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「バリアが弱くなる」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「弱くなる」は自動詞なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するが、後ろに名詞が続かず「弱くなると」と文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。状態の変化を表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「バリアが弱くなる」の主語を示す。", "を": "「を」は他動詞の目的語を示すが、「弱くなる」は自動詞なので合わない。", "の": "「の」は名詞を修飾するが、後ろに名詞が続かず「弱くなると」と文が続かない。", "へ": "「へ」は移動の方向を示す。状態の変化を表す文には合わない。"}, "error_tags": {"を": "目的語", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
