INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物理的または抽象的な障害物や仕切り。特に、水分や熱などの移動を防ぐ膜や壁。", "primary_collocate": null, "pronunciation": "ばりあ", "ipa": "baɾia", "syllable_count": 3, "sentences": [{"text": "このクリームは、肌の水分が逃げないようにバリアを作る。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "このクリームは、肌[はだ]の水分[すいぶん]が逃[に]げないようにバリアを作[つく]る。", "sentence_source": "generated"}, {"text": "皮膚のバリアが弱くなると、乾燥しやすい。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "皮膚[ひふ]のバリアが弱[よわ]くなると、乾燥[かんそう]しやすい。", "sentence_source": "generated"}, {"text": "ビニールのバリアが、湿気が壁に入るのを防ぐ。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "ビニールのバリアが、湿気[しっけ]が壁[かべ]に入[はい]るのを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "言葉のバリアがあって、最初は意見がうまく伝わらなかった。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "言葉[ことば]のバリアがあって、最初[さいしょ]は意見[いけん]がうまく伝[つた]わらなかった。", "sentence_source": "generated"}, {"text": "窓の断熱フィルムは、熱を通さないバリアになる。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "窓[まど]の断熱[だんねつ]フィルムは、熱[ねつ]を通[とお]さないバリアになる。", "sentence_source": "generated"}, {"text": "年齢のバリアをこえて、みんなが仲よくなった。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "年齢[ねんれい]のバリアをこえて、みんなが仲[なか]よくなった。", "sentence_source": "generated"}, {"text": "肌のバリアを守るために、洗いすぎないほうがいい。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "肌[はだ]のバリアを守[まも]るために、洗[あら]いすぎないほうがいい。", "sentence_source": "generated"}, {"text": "この塗料は、水を通さないバリアとして屋根を守る。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "この塗料[とりょう]は、水[みず]を通[とお]さないバリアとして屋根[やね]を守[まも]る。", "sentence_source": "generated"}, {"text": "文化のちがいがバリアになって、交渉が進まなかった。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "文化[ぶんか]のちがいがバリアになって、交渉[こうしょう]が進[すす]まなかった。", "sentence_source": "generated"}, {"text": "熱が逃げないよう、壁の内側に薄いバリアを入れた。", "target_word": "バリア", "complexity_tier": "T3", "furigana": "熱[ねつ]が逃[に]げないよう、壁[かべ]の内側[うちがわ]に薄[うす]いバリアを入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バリア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水分・熱の移動を防ぐ膜や、交流を妨げる抽象的な壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バリア", "is_correct": true, "explanation": "水分が逃げないように作るものとして自然で、膜や壁の意味に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸音で、「作る」の対象にはならない。"}, {"text": "咳", "is_correct": false, "explanation": "咳は体の反応で、水分の移動を防ぐものを作る文には合わない。"}, {"text": "深呼吸", "is_correct": false, "explanation": "深呼吸は行為で、「作る」の対象にはならない。"}], "explanations": {"バリア": "水分が逃げないように作るものとして自然で、膜や壁の意味に合う。", "寝息": "寝息は眠っている人の呼吸音で、「作る」の対象にはならない。", "咳": "咳は体の反応で、水分の移動を防ぐものを作る文には合わない。", "深呼吸": "深呼吸は行為で、「作る」の対象にはならない。"}, "sentence_index": 0, "correct_answer": "バリア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このバリアは、インクがよく出る。", "explanation": "ここは〈ペン〉の意味。バリアは水分や熱をさえぎる膜や壁で、インクを出す道具ではない。"}, {"text": "夜は、リビングでバリアを見て過ごす。", "explanation": "ここは〈テレビ〉の意味。バリアは見るものではなく、水分や熱をさえぎる膜や壁を指す。"}, {"text": "汗をバリアで拭く。", "explanation": "ここは〈タオル〉の意味。バリアは拭く道具ではなく、水分や熱の移動をさえぎる膜や壁を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バリア", "is_correct": true, "explanation": "肌を守る膜の意味で、「守るために」の文に合う。"}, {"text": "紙粘土", "is_correct": false, "explanation": "紙粘土は工作の材料で、肌を守る対象にはならない。"}, {"text": "味噌", "is_correct": false, "explanation": "味噌は調味料で、「肌の味噌を守る」とは言えない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は髪の乱れで、守る対象として文が成り立たない。"}], "explanations": {"バリア": "肌を守る膜の意味で、「守るために」の文に合う。", "紙粘土": "紙粘土は工作の材料で、肌を守る対象にはならない。", "味噌": "味噌は調味料で、「肌の味噌を守る」とは言えない。", "寝癖": "寝癖は髪の乱れで、守る対象として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "バリア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉が渇いたので、バリアを一気に飲んだ。", "explanation": "ここは〈ジュース〉の意味。バリアは飲み物ではない。"}, {"text": "寒いので、足にバリアを履いた。", "explanation": "ここは〈靴下〉の意味。バリアは足に履く物ではない。"}, {"text": "車の中でバリアを聴いた。", "explanation": "ここは〈ラジオ〉の意味。バリアは音を流す機器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この塗料は、屋根に水を通さないバリアが作る。", "corrected_sentence": "この塗料は、屋根に水を通さないバリアを作る。", "error_description": "「作る」の目的語は「を」で、「バリアが」は誤り。「バリアを作る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52172, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この家では、床下に薄いバリアを投げた。", "corrected_sentence": "この家では、床下に薄いバリアを敷いた。", "error_description": "膜やシートを対象にする動詞は「敷く」で、「投げる」は「バリア」と組まないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べる」は対象を「を」で取る。「ラズベリーを」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ラズベリーが食べたら」は主語になり、食べる対象として合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ラズベリーに食べたら」は相手や場所を示す「に」になり、食べる対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「ラズベリーへ食べたら」は方向を示すので、食べる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「食べる」は対象を「を」で取る。「ラズベリーを」が正しい。", "が": "「ラズベリーが食べたら」は主語になり、食べる対象として合わない。", "に": "「ラズベリーに食べたら」は相手や場所を示す「に」になり、食べる対象を表せない。", "へ": "「ラズベリーへ食べたら」は方向を示すので、食べる対象を表せない。"}, "error_tags": {"が": "主語の誤り", "に": "相手・場所の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
