INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さな赤い実で、甘くて酸っぱい果物です。", "primary_collocate": null, "pronunciation": "らずべりー", "ipa": "ɾazɯbeɾiː", "syllable_count": 5, "sentences": [{"text": "弟はラズベリーが大好きで、スーパーで見つけるといつも買ってほしいと言う。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "弟(おとうと)はラズベリーが大好(だいす)きで、スーパーで見(み)つけるといつも買(か)ってほしいと言(い)う。", "sentence_source": "generated"}, {"text": "赤いラズベリーをひと粒食べたら、思ったより酸っぱかった。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "赤(あか)いラズベリーをひと粒(つぶ)食(た)べたら、思(おも)ったより酸(す)っぱかった。", "sentence_source": "generated"}, {"text": "デザートにラズベリーを添えると、見た目がきれいになります。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "デザートにラズベリーを添(そ)えると、見(み)た目(め)がきれいになります。", "sentence_source": "generated"}, {"text": "ラズベリーのアイスクリームは、甘さと酸味のバランスがちょうどいい。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "ラズベリーのアイスクリームは、甘(あま)さと酸味(さんみ)のバランスがちょうどいい。", "sentence_source": "generated"}, {"text": "森を歩いていたら、道ばたでラズベリーを見つけた。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "森(もり)を歩(ある)いていたら、道(みち)ばたでラズベリーを見(み)つけた。", "sentence_source": "generated"}, {"text": "冷凍のラズベリーをミキサーに入れて、ジュースを作った。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "冷凍(れいとう)のラズベリーをミキサーに入(い)れて、ジュースを作(つく)った。", "sentence_source": "generated"}, {"text": "彼女はラズベリーのタルトを選び、私はチョコレートケーキにした。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "彼女(かのじょ)はラズベリーのタルトを選(えら)び、私(わたし)はチョコレートケーキにした。", "sentence_source": "generated"}, {"text": "ラズベリーは小さいけれど、香りがとてもよい。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "ラズベリーは小(ちい)さいけれど、香(かお)りがとてもよい。", "sentence_source": "generated"}, {"text": "朝食にラズベリーとバナナをのせたオートミールを食べた。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "朝食(ちょうしょく)にラズベリーとバナナをのせたオートミールを食(た)べた。", "sentence_source": "generated"}, {"text": "友達にもらったラズベリーを、みんなで分けて食べました。", "target_word": "ラズベリー", "complexity_tier": "T3", "furigana": "友達(ともだち)にもらったラズベリーを、みんなで分(わ)けて食(た)べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラズベリー", "label": "基本形"}, {"form": "ラズベリーの", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "小さくて赤い、甘酸っぱい果物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: 酸っぱかっ (Zipf 1.45)']::text[], '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラズベリー", "is_correct": true, "explanation": "「弟はラズベリーが大好き」で、スーパーで見つけて買える食べ物として文が通る。"}, {"text": "ピアノ", "is_correct": false, "explanation": "スーパーで見つけて買える物ではなく、「買ってほしい」の文脈に合わない。"}, {"text": "大理石", "is_correct": false, "explanation": "食べ物ではなく、スーパーで買ってほしいという文脈に合わない。"}, {"text": "石炭", "is_correct": false, "explanation": "食べ物ではなく、スーパーで見つけると買ってほしいという文に合わない。"}], "explanations": {"ラズベリー": "「弟はラズベリーが大好き」で、スーパーで見つけて買える食べ物として文が通る。", "ピアノ": "スーパーで見つけて買える物ではなく、「買ってほしい」の文脈に合わない。", "大理石": "食べ物ではなく、スーパーで買ってほしいという文脈に合わない。", "石炭": "食べ物ではなく、スーパーで見つけると買ってほしいという文に合わない。"}, "sentence_index": 0, "correct_answer": "ラズベリー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラズベリーを細かく刻んで、うどんの薬味にした。", "explanation": "ここは〈ねぎ〉をうどんの薬味にする使い方。ラズベリーは甘酸っぱい果物でジャムやデザートに使うので、薬味には合わない。"}, {"text": "ラズベリーのヘタを取ってから、アイスクリームに載せた。", "explanation": "ここは〈いちご〉のヘタの話。ラズベリーは実が小さな粒の集まりで、ヘタを取る果物として扱わない。"}, {"text": "ラズベリーの皮を一つずつむいて、食べやすくした。", "explanation": "ここは〈みかん〉の皮をむく場面。ラズベリーは皮をむかずに食べるので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラズベリー", "is_correct": true, "explanation": "果物の名前で、「〜のタルト」として自然に入り、文の意味が通る。"}, {"text": "鉄骨", "is_correct": false, "explanation": "建物の材料で食べられず、「鉄骨のタルト」は成り立たない。"}, {"text": "段ボール", "is_correct": false, "explanation": "箱の材料で、タルトの材料にならないので文が通らない。"}, {"text": "陶器", "is_correct": false, "explanation": "食器であり、タルトにはならないので文が成り立たない。"}], "explanations": {"ラズベリー": "果物の名前で、「〜のタルト」として自然に入り、文の意味が通る。", "鉄骨": "建物の材料で食べられず、「鉄骨のタルト」は成り立たない。", "段ボール": "箱の材料で、タルトの材料にならないので文が通らない。", "陶器": "食器であり、タルトにはならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ラズベリー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ラズベリーを塩漬けにして、梅干しを作った。", "explanation": "ここは、うめの実を塩に漬けて干す保存食の話。ラズベリーはその材料にならず、梅干しは作れないので、この使い方は合わない。"}, {"text": "ラズベリーの房をはさみで切って、皿に盛った。", "explanation": "ここは〈ぶどう〉の房の話。ラズベリーは房で実る果物ではないので、この使い方は合わない。"}, {"text": "ラズベリーの芯を抜いて、輪切りにした。", "explanation": "ここは〈りんご〉の芯を抜く話。ラズベリーを芯を抜いて輪切りにする使い方はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝食にラズベリーが添えたら、家族が喜んだ。", "corrected_sentence": "朝食にラズベリーを添えたら、家族が喜んだ。", "error_description": "「添える」は対象を「を」で取る。「ラズベリーが」では主語扱いになり誤り。正しくは「ラズベリーを添えたら」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ラズベリーを洗う、水を切った。", "corrected_sentence": "ラズベリーを洗って、水を切った。", "error_description": "「洗う」は「洗って」のて形。終止形の「洗う」だと後ろの「水を切った」へ続かず、文が途切れる。正しくは「洗って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在の主語を示す格助詞。片割れが『あった』の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、『あった』は目的語を取らないので文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "存在場所を示すが、主語には使えない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表し、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "存在の主語を示す格助詞。片割れが『あった』の主語として正しい。", "を": "目的語を示すが、『あった』は目的語を取らないので文が成り立たない。", "に": "存在場所を示すが、主語には使えない。", "で": "場所や手段を表し、主語にはならない。"}, "error_tags": {"を": "目的語", "に": "存在場所・帰着点", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。片割れが『見つからない』の主語として正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、見つからないの主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、見つからないの主語としては文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を表し、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。片割れが『見つからない』の主語として正しい。", "へ": "方向を表すが、見つからないの主語にはならない。", "から": "起点を表すが、見つからないの主語としては文が成り立たない。", "より": "比較や起点を表し、主語にはならない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ふたつで一組になるものの、片方のこと。", "primary_collocate": null, "pronunciation": "かたわれ", "ipa": "katawaɾe", "syllable_count": 4, "sentences": [{"text": "ピアスの片割れを落としてしまい、駅で探し回った。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "ピアスの片割(かたわ)れを落(お)としてしまい、駅(えき)で探(さが)し回(まわ)った。", "sentence_source": "generated"}, {"text": "左のスリッパの片割れが、なぜかベッドの下にあった。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "左(ひだり)のスリッパの片割(かたわ)れが、なぜかベッドの下(した)にあった。", "sentence_source": "generated"}, {"text": "対のブックエンドの片割れだけが、古本屋に売られていた。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "対(つい)のブックエンドの片割(かたわ)れだけが、古本屋(ふるほんや)に売(う)られていた。", "sentence_source": "generated"}, {"text": "ワイヤレスイヤホンの片割れが壊れてしまい、片耳だけで聞いている。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "ワイヤレスイヤホンの片割(かたわ)れが壊(こわ)れてしまい、片耳(かたみみ)だけで聞(き)いている。", "sentence_source": "generated"}, {"text": "箸の片割れが折れて、一膳としては使えなくなった。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "箸(はし)の片割(かたわ)れが折(お)れて、一膳(いちぜん)としては使(つか)えなくなった。", "sentence_source": "generated"}, {"text": "このカフスボタンは片割れがなくて、ひとつだけ残っている。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "このカフスボタンは片割(かたわ)れがなくて、ひとつだけ残(のこ)っている。", "sentence_source": "generated"}, {"text": "ペアのマグカップの片割れを、姉が持っていった。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "ペアのマグカップの片割(かたわ)れを、姉(あね)が持(も)っていった。", "sentence_source": "generated"}, {"text": "イヤリングの片割れが見つからないので、残った方も使えない。", "target_word": "片割れ", "complexity_tier": "T3", "furigana": "イヤリングの片割(かたわ)れが見(み)つからないので、残(のこ)った方(ほう)も使(つか)えない。", "sentence_source": "generated"}, {"text": "二つ吊るしていた風鈴の片割れが割れて、一つだけが窓辺で鳴っている。", "target_word": "片割れ", "complexity_tier": "T4", "furigana": "二(ふた)つ吊(つ)るしていた風鈴(ふうりん)の片割(かたわ)れが割(わ)れて、一(ひと)つだけが窓辺(まどべ)で鳴(な)っている。", "sentence_source": "generated"}, {"text": "亡くなった妻と使っていた湯のみの片割れを、形見として大切にしている。", "target_word": "片割れ", "complexity_tier": "T4", "furigana": "亡(な)くなった妻(つま)と使(つか)っていた湯(ゆ)のみの片割(かたわ)れを、形見(かたみ)として大切(たいせつ)にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "片割れ", "label": "基本形"}, {"form": "片割れの", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "二つで一組になるもののうちの片方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '054d68fb-c4d4-40c1-91e6-960db9c1bc1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "片割れ", "is_correct": true, "explanation": "ふたつで一組のピアスの片方を指し、落とした対象として自然に成り立つ。"}, {"text": "手袋", "is_correct": false, "explanation": "ピアスと一緒に落とすものとしては成り立たず、ピアスの一部も指さない。"}, {"text": "懐中時計", "is_correct": false, "explanation": "ピアスの部品として結びつかず、この文の対象にはならない。"}, {"text": "絵筆", "is_correct": false, "explanation": "ピアスとは無関係で、落とした対象として文が成り立たない。"}], "explanations": {"片割れ": "ふたつで一組のピアスの片方を指し、落とした対象として自然に成り立つ。", "手袋": "ピアスと一緒に落とすものとしては成り立たず、ピアスの一部も指さない。", "懐中時計": "ピアスの部品として結びつかず、この文の対象にはならない。", "絵筆": "ピアスとは無関係で、落とした対象として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "片割れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上の本の片割れを、図書館に返した。", "explanation": "本は二つで一組にならないので〈片割れ〉とは呼ばない。ここは一冊の一部を言う場面。"}, {"text": "庭の片割れに、古い机を置いた。", "explanation": "ここは〈片隅〉の意味。片割れは対になるものの一方を指し、庭の場所を言う語ではない。"}, {"text": "夕立の片割れが、午後には止んだ。", "explanation": "雨は二つで一組にならないので〈片割れ〉とは言わない。ここは〈残り〉の意味で使える語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排水口", "is_correct": false, "explanation": "流しの排水の出口で、マグカップと一緒に持っていくものではない。"}, {"text": "天井", "is_correct": false, "explanation": "建物の上部で、持っていける対象ではない。"}, {"text": "片割れ", "is_correct": true, "explanation": "ペアのマグカップの片方を指し、姉が持っていったものとして成り立つ。"}, {"text": "煙突", "is_correct": false, "explanation": "建物に付く設備で、マグカップのペアの一方とは結びつかない。"}], "explanations": {"排水口": "流しの排水の出口で、マグカップと一緒に持っていくものではない。", "天井": "建物の上部で、持っていける対象ではない。", "片割れ": "ペアのマグカップの片方を指し、姉が持っていったものとして成り立つ。", "煙突": "建物に付く設備で、マグカップのペアの一方とは結びつかない。"}, "sentence_index": 6, "correct_answer": "片割れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の片割れを、週末に登った。", "explanation": "ここは〈一部〉の意味。片割れは対になるものの一方で、山全体の一部を指す語ではない。"}, {"text": "試験の片割れを終えて、休憩に入った。", "explanation": "ここは〈前半〉の意味。片割れは対になるものの一方で、試験の進行を区切る語ではない。"}, {"text": "空の片割れに、虹がかかった。", "explanation": "ここは〈一角〉の意味。片割れは対になるものの一方で、空の一部分には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ピアスの片割れが、小さな箱にしまった。", "corrected_sentence": "ピアスの片割れを、小さな箱にしまった。", "error_description": "正しくは『を』。『しまう』の対象を示すのは『を』で、『が』は主語になり目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52175, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯のみの片割れの、食器棚にしまっておいた。", "corrected_sentence": "湯のみの片割れを、食器棚にしまっておいた。", "error_description": "正しくは『を』。『しまう』の対象を示すのは『を』で、『の』は連体修飾を表し目的語にはならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21bd40f8-8293-4533-9d0f-f7a2c65278d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
