INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「切片」は「小さすぎて」の主語なので「が」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、「小さすぎて」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すため、形容詞「小さすぎて」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「小さすぎて」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「切片」は「小さすぎて」の主語なので「が」が正しい。", "から": "「から」は起点を表すため、「小さすぎて」の主語にはならない。", "と": "「と」は並列や相手を表すため、形容詞「小さすぎて」の主語にはならない。", "へ": "「へ」は方向を表すため、「小さすぎて」の主語にはならない。"}, "error_tags": {"から": "起点", "と": "相手・共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "切った小さなかたまりのこと。", "primary_collocate": null, "pronunciation": "せっぺん", "ipa": "seppeɴ", "syllable_count": 4, "sentences": [{"text": "実験のために、銅線から数ミリの切片を切り取った。", "target_word": "切片", "complexity_tier": "T3", "furigana": "実験[じっけん]のために、銅線[どうせん]から数[すう]ミリの切片[せっぺん]を切[き]り取[と]った。", "sentence_source": "generated"}, {"text": "彼は固いチーズを小さく切り、切片[せっぺん]を皿に並べた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "彼は固いチーズを小さく切り、切片[せっぺん]を皿に並べた。", "sentence_source": "generated"}, {"text": "床に落ちた金属の切片を、子どもが踏まないように掃除した。", "target_word": "切片", "complexity_tier": "T3", "furigana": "床[ゆか]に落[お]ちた金属[きんぞく]の切片[せっぺん]を、子[こ]どもが踏[ふ]まないように掃除[そうじ]した。", "sentence_source": "generated"}, {"text": "先生は石けんの切片を水に入れて、溶ける様子を見せた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "先生[せんせい]は石[せっ]けんの切片[せっぺん]を水[みず]に入[い]れて、溶[と]ける様子[ようす]を見[み]せた。", "sentence_source": "generated"}, {"text": "木材の切片が散らばっているので、作業場では靴をはいてください。", "target_word": "切片", "complexity_tier": "T3", "furigana": "木材[もくざい]の切片[せっぺん]が散[ち]らばっているので、作業場[さぎょうば]では靴[くつ]をはいてください。", "sentence_source": "generated"}, {"text": "肉の切片を鍋に入れると、すぐに色が変わった。", "target_word": "切片", "complexity_tier": "T3", "furigana": "肉[にく]の切片[せっぺん]を鍋[なべ]に入[い]れると、すぐに色[いろ]が変[か]わった。", "sentence_source": "generated"}, {"text": "チョコレートの切片[せっぺん]を鍋に入れると、すぐに溶け始めた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "チョコレートの切片[せっぺん]を鍋に入れると、すぐに溶け始めた。", "sentence_source": "generated"}, {"text": "実験で使う金属の切片が小さすぎて、ピンセットでもつかめなかった。", "target_word": "切片", "complexity_tier": "T3", "furigana": "実験[じっけん]で使[つか]う金属[きんぞく]の切片[せっぺん]が小[ちい]さすぎて、ピンセットでもつかめなかった。", "sentence_source": "generated"}, {"text": "竹の切片を火にくべると、ぱちぱちと音がした。", "target_word": "切片", "complexity_tier": "T3", "furigana": "竹[たけ]の切片[せっぺん]を火[ひ]にくべると、ぱちぱちと音[おと]がした。", "sentence_source": "generated"}, {"text": "紙の切片に番号を書いて、箱の中から一枚ずつ引いた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "紙[かみ]の切片[せっぺん]に番号[ばんごう]を書[か]いて、箱[はこ]の中[なか]から一枚[いちまい]ずつ引[ひ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切片", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "切片: 物を切って出た小さなかたまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切片", "is_correct": true, "explanation": "「銅線から数ミリの切片を切り取った」は、切ってできた小さなかたまりとして自然。"}, {"text": "水滴", "is_correct": false, "explanation": "水滴は切り取る対象ではないので、「数ミリの水滴を切り取った」は不自然。"}, {"text": "粒子", "is_correct": false, "explanation": "粒子は切り取って取り出すものではないので、文脈に合わない。"}, {"text": "接着剤", "is_correct": false, "explanation": "接着剤を数ミリ切り取る場面は想定しにくく、文脈に合わない。"}], "explanations": {"切片": "「銅線から数ミリの切片を切り取った」は、切ってできた小さなかたまりとして自然。", "水滴": "水滴は切り取る対象ではないので、「数ミリの水滴を切り取った」は不自然。", "粒子": "粒子は切り取って取り出すものではないので、文脈に合わない。", "接着剤": "接着剤を数ミリ切り取る場面は想定しにくく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "切片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂糖の切片が、コップの底に残っていた。", "explanation": "ここは〈粒〉の意味。砂糖のように細かく散らばる小さな粒は粒と言い、切り取った切片とは合わない。"}, {"text": "割れたガラス瓶の切片を、掃除機で集めた。", "explanation": "ここは〈破片〉の意味。切片は切り取ってできたかたまりを指し、割れてできたかけらには使わない。"}, {"text": "古い新聞の切片が、本の間から出てきた。", "explanation": "ここは〈断片〉の意味。切片は切ったものの一部を指し、文章や記録の一部を表す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切片", "is_correct": true, "explanation": "「チョコレートの切片を鍋に入れると、すぐに溶け始めた」は、溶けるかたまりとして自然。"}, {"text": "風船", "is_correct": false, "explanation": "風船は鍋に入れて溶けるものではないので、文脈に合わない。"}, {"text": "針金", "is_correct": false, "explanation": "針金は溶けるものではなく、チョコレートと組み合わせる文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団を鍋に入れて溶ける場面は考えられず、文脈に合わない。"}], "explanations": {"切片": "「チョコレートの切片を鍋に入れると、すぐに溶け始めた」は、溶けるかたまりとして自然。", "風船": "風船は鍋に入れて溶けるものではないので、文脈に合わない。", "針金": "針金は溶けるものではなく、チョコレートと組み合わせる文脈に合わない。", "座布団": "座布団を鍋に入れて溶ける場面は考えられず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "切片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遺跡で、古い茶碗の切片が見つかった。", "explanation": "ここは〈残片〉の意味。切片は切り取ってできた小さなかたまりで、遺跡から出た器の欠けらには使わない。"}, {"text": "砕けたコンクリートの切片が道路に散らばった。", "explanation": "ここは〈砕片〉の意味。切片は切ってできたものを指し、砕けて散ったものには使わない。"}, {"text": "床に落ちて割れたコップの切片を拾い集めた。", "explanation": "ここは〈欠片〉の意味。切片は切り取ったかたまりを指し、割れて落ちたかけらには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は金属の切片に一つずつ箱に入れた。", "corrected_sentence": "先生は金属の切片を一つずつ箱に入れた。", "error_description": "「切片」の後ろの助詞が誤り。「入れる」の対象は「を」で示すので「切片を」が正しい。「に」は場所や相手を表すため、目的語には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業台の上で、ワイヤーから切片を数枚切り取りた。", "corrected_sentence": "作業台の上で、ワイヤーから切片を数枚切り取った。", "error_description": "動詞の過去形が誤り。五段動詞「切り取る」の過去形は促音を入れて「切り取った」になり、「切り取りた」は文法上成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「切片」は「切って作る」の目的語なので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すため、「切って作った」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を表すため、「切る」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、「切る」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「切片」は「切って作る」の目的語なので「を」が正しい。", "が": "「が」は主語を表すため、「切って作った」の目的語にはならない。", "に": "「に」は場所や相手を表すため、「切る」の目的語にはならない。", "で": "「で」は手段や場所を表すため、「切る」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "場所・方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「切片」は「作った」の目的語なので「を」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「作った」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すため、「作った」の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すため、「作った」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「切片」は「作った」の目的語なので「を」が正しい。", "へ": "「へ」は方向を表すため、「作った」の目的語にはならない。", "と": "「と」は並列や相手を表すため、「作った」の目的語にはならない。", "より": "「より」は比較や起点を表すため、「作った」の目的語にはならない。"}, "error_tags": {"へ": "方向", "と": "相手・共同", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある物から切り取られた、薄い一片。", "primary_collocate": null, "pronunciation": "せっぺん", "ipa": "seppeɴ", "syllable_count": 4, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "切片", "complexity_tier": "T4", "furigana": "次[つ]いで、ラズベリー等[など]のジャムを対[つい]になる片割[かたわ]れ、あるいは同一[どういつ]の切片[せっぺん]上[じょう]に重[かさ]ね合[あ]わせる。\n\n甘味[かんみ]と塩気[しおけ]、滑[なめ]らかさと顆粒感[かりゅうかん]が口腔内[こうくうない]で織[お]りなす対照的[たいしょうてき]なハーモニーは、単[たん]なる栄養補給[えいようほきゅう]の域[いき]を超[こ]え、短時間[たんじかん]での認知機能回復[にんちきのうかいふく]をもたらし、合理性[ごうりせい]と美学[びがく]が融合[ゆうごう]した食[しょく]の営[いとな]みとして完成[かんせい]する。", "sentence_source": "mined"}, {"text": "顕微鏡で観察するために、肝臓の切片を薄く切って作った。", "target_word": "切片", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で観察[かんさつ]するために、肝臓[かんぞう]の切片[せっぺん]を薄[うす]く切[き]って作[つく]った。", "sentence_source": "generated"}, {"text": "組織の切片は薄すぎて、手で持つと破れてしまいそうだった。", "target_word": "切片", "complexity_tier": "T3", "furigana": "組織[そしき]の切片[せっぺん]は薄[うす]すぎて、手[て]で持[も]つと破[やぶ]れてしまいそうだった。", "sentence_source": "generated"}, {"text": "研究者は、ガラスの板に切片をのせて染色液をたらした。", "target_word": "切片", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、ガラスの板[いた]に切片[せっぺん]をのせて染色液[せんしょくえき]をたらした。", "sentence_source": "generated"}, {"text": "この切片は光を通すほど薄いので、細胞の形がよく見える。", "target_word": "切片", "complexity_tier": "T3", "furigana": "この切片[せっぺん]は光[ひかり]を通[とお]すほど薄[うす]いので、細胞[さいぼう]の形[かたち]がよく見[み]える。", "sentence_source": "generated"}, {"text": "木の幹から切片を取り、年輪の数を数えて樹齢を調べた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]から切片[せっぺん]を取[と]り、年輪[ねんりん]の数[かず]を数[かぞ]えて樹齢[じゅれい]を調[しら]べた。", "sentence_source": "generated"}, {"text": "切片が厚すぎたため、顕微鏡では細胞の中が見えなかった。", "target_word": "切片", "complexity_tier": "T3", "furigana": "切片[せっぺん]が厚[あつ]すぎたため、顕微鏡[けんびきょう]では細胞[さいぼう]の中[なか]が見[み]えなかった。", "sentence_source": "generated"}, {"text": "学生は冷凍した腎臓から薄い切片を何枚も作った。", "target_word": "切片", "complexity_tier": "T3", "furigana": "学生[がくせい]は冷凍[れいとう]した腎臓[じんぞう]から薄[うす]い切片[せっぺん]を何枚[なんまい]も作[つく]った。", "sentence_source": "generated"}, {"text": "先生は切片を一枚ずつピンセットで運び、容器の水に浮かべた。", "target_word": "切片", "complexity_tier": "T3", "furigana": "先生[せんせい]は切片[せっぺん]を一枚[いちまい]ずつピンセットで運[はこ]び、容器[ようき]の水[みず]に浮[う]かべた。", "sentence_source": "generated"}, {"text": "化石の切片を磨いて薄くすると、内部の模様がはっきり見える。", "target_word": "切片", "complexity_tier": "T3", "furigana": "化石[かせき]の切片[せっぺん]を磨[みが]いて薄[うす]くすると、内部[ないぶ]の模様[もよう]がはっきり見[み]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切片", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "切片: 組織や物から薄く切り取った一枚の薄片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切片", "is_correct": true, "explanation": "「同一の切片上」は薄く切った一枚を指し、ジャムを重ねる場所として文脈に合う。"}, {"text": "粉末", "is_correct": false, "explanation": "粉末は薄い一枚の面を指さないため、「同一の粉末上に重ね合わせる」は不自然。"}, {"text": "結晶", "is_correct": false, "explanation": "結晶は固まりの形を指すので、薄く切り取った一枚の場に当てはまらない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤はジャムを重ねる台にはならず、文脈に合わない。"}], "explanations": {"切片": "「同一の切片上」は薄く切った一枚を指し、ジャムを重ねる場所として文脈に合う。", "粉末": "粉末は薄い一枚の面を指さないため、「同一の粉末上に重ね合わせる」は不自然。", "結晶": "結晶は固まりの形を指すので、薄く切り取った一枚の場に当てはまらない。", "洗剤": "洗剤はジャムを重ねる台にはならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "切片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雲の切れ間から、青空の切片がのぞいた。", "explanation": "ここは〈一片〉の意味。雲の切れ間から見える空の部分は一片で言い表すもので、薄く切り取った切片とは合わない。"}, {"text": "割れた皿の切片を拾い集めた。", "explanation": "ここは〈破片〉の意味。切片は薄く切り取った一片を指し、割れてできたかけらには使わない。"}, {"text": "古い手紙の切片が、引き出しの奥から見つかった。", "explanation": "ここは〈断片〉の意味。切片は切り取った一片のことで、文章や記録の一部を表す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切片", "is_correct": true, "explanation": "「切片が厚すぎたため、顕微鏡で細胞が見えなかった」は、観察する標本として自然。"}, {"text": "財布", "is_correct": false, "explanation": "財布は顕微鏡で観察する標本ではなく、厚さも細胞の見え方と関係しないので、文脈に合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は顕微鏡の観察対象ではなく、厚すぎて細胞が見えないという文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は顕微鏡の観察対象ではなく、文脈に合わない。"}], "explanations": {"切片": "「切片が厚すぎたため、顕微鏡で細胞が見えなかった」は、観察する標本として自然。", "財布": "財布は顕微鏡で観察する標本ではなく、厚さも細胞の見え方と関係しないので、文脈に合わない。", "靴下": "靴下は顕微鏡の観察対象ではなく、厚すぎて細胞が見えないという文脈に合わない。", "座布団": "座布団は顕微鏡の観察対象ではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "切片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園では、落ち葉の切片が風に舞っていた。", "explanation": "ここは〈欠片〉の意味。切片は切り取って薄くした一片を指し、自然に散った落ち葉の一部には使わない。"}, {"text": "古代の土器の切片が発掘された。", "explanation": "ここは〈残片〉の意味。切片は切り取られた一片を指し、遺跡から出た器の欠けらには使わない。"}, {"text": "崩れた岩の切片が川に流れていった。", "explanation": "ここは〈砕片〉の意味。切片は切ってできたものを指し、崩れて砕けた破片には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は肝臓の切片で顕微鏡で観察した。", "corrected_sentence": "先生は肝臓の切片を顕微鏡で観察した。", "error_description": "「切片」の後ろの助詞が誤り。「観察する」の対象は「を」で示すので「切片を」が正しい。「で」は手段や場所を表すため、目的語には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52178, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凍らせた肝臓を薄く切って、切片を編んだ。", "corrected_sentence": "凍らせた肝臓を薄く切って、切片を作った。", "error_description": "「切片」に続く動詞が誤り。薄く切って得た切片は「作る」で表すので「作った」が正しい。「編んだ」は糸などを組み合わせる動作で、切片には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
