INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52179, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "何かをしたあとに、続けて別のことをするという意味です。", "primary_collocate": null, "pronunciation": "ついで", "ipa": "tsɯide", "syllable_count": 3, "sentences": [{"text": "市長があいさつをし、次いで来賓の代表が話をした。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "市長[しちょう]があいさつをし、次[つ]いで来賓[らいひん]の代表[だいひょう]が話[はなし]をした。", "sentence_source": "generated"}, {"text": "まず野菜を切り、次いで肉を炒めます。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "まず野菜[やさい]を切[き]り、次[つ]いで肉[にく]を炒[いた]めます。", "sentence_source": "generated"}, {"text": "彼は大学を卒業し、次いで大学院に進んだ。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]を卒業[そつぎょう]し、次[つ]いで大学院[だいがくいん]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "地震が起き、次いで大きな津波が町をおそった。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]き、次[つ]いで大[おお]きな津波[つなみ]が町[まち]をおそった。", "sentence_source": "generated"}, {"text": "校長先生の話があり、次いで生徒会長がスピーチをした。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "校長先生[こうちょうせんせい]の話[はなし]があり、次[つ]いで生徒会長[せいとかいちょう]がスピーチをした。", "sentence_source": "generated"}, {"text": "受付で名前を書き、次いで検温を受けてください。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "受付[うけつけ]で名前[なまえ]を書[か]き、次[つ]いで検温[けんおん]を受[う]けてください。", "sentence_source": "generated"}, {"text": "首相が到着し、次いで各国の代表が会場に入った。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "首相[しゅしょう]が到着[とうちゃく]し、次[つ]いで各国[かっこく]の代表[だいひょう]が会場[かいじょう]に入[はい]った。", "sentence_source": "generated"}, {"text": "社長は新製品を発表し、次いで今後の計画を説明した。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は新製品[しんせいひん]を発表[はっぴょう]し、次[つ]いで今後[こんご]の計画[けいかく]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "一曲目が終わると、次いで有名な曲が演奏された。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "一曲目[いっきょくめ]が終[お]わると、次[つ]いで有名[ゆうめい]な曲[きょく]が演奏[えんそう]された。", "sentence_source": "generated"}, {"text": "彼は手を洗い、次いでうがいをしてから食事の準備を始めた。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "彼[かれ]は手[て]を洗[あら]い、次[つ]いでうがいをしてから食事[しょくじ]の準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "次いで", "label": "基本形（副詞）"}, {"form": "次ぐ", "label": "動詞の辞書形"}], "register": "formal", "sense_fingerprint": "ある出来事のあとに続けて、次の出来事が起こる・行われる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: おそっ (Zipf 1.99)']::text[], '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52179, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次いで", "is_correct": true, "explanation": "「次いで」は〈あとに続けて〉の意味。市長のあいさつの後に来賓が話すという順序に合う。"}, {"text": "逆に", "is_correct": false, "explanation": "「逆に」は反対の意味。前の出来事に続く順序を表さないので合わない。"}, {"text": "特に", "is_correct": false, "explanation": "「特に」は特別にという意味。順序を述べる文には入らない。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然」は思いがけなく起きたことを表す。あいさつの流れには合わない。"}], "explanations": {"次いで": "「次いで」は〈あとに続けて〉の意味。市長のあいさつの後に来賓が話すという順序に合う。", "逆に": "「逆に」は反対の意味。前の出来事に続く順序を表さないので合わない。", "特に": "「特に」は特別にという意味。順序を述べる文には入らない。", "偶然": "「偶然」は思いがけなく起きたことを表す。あいさつの流れには合わない。"}, "sentence_index": 0, "correct_answer": "次いで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は父の店を次いで経営している。", "explanation": "ここは別の語「継いで」（受け継ぐ）。次いでは〈あとに続けて〉の意味なので、受け継ぐの意味には使わない。"}, {"text": "彼女は歌いながら、次いで踊った。", "explanation": "ここは〈同時に〉の意味。次いでは〈あとに続けて〉なので、同時に行う動作には合わない。"}, {"text": "帰りの次いでに、本屋へ寄った。", "explanation": "ここは別の語「ついで」（序で、何かの機会に）。次いでは〈あとに続けて〉の意味で、機会のついでは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52179, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次いで", "is_correct": true, "explanation": "「次いで」はあとに続く順序を表す。首相の到着の後に各国の代表が入ることを示す。"}, {"text": "慌てて", "is_correct": false, "explanation": "「慌てて」は急ぐ様子を表す。順序を述べる文の空欄には入らない。"}, {"text": "最初に", "is_correct": false, "explanation": "「最初に」は一番目を表す。到着の後に入るという流れと矛盾する。"}, {"text": "反対に", "is_correct": false, "explanation": "「反対に」は逆の意味。到着と入場の流れには合わない。"}], "explanations": {"次いで": "「次いで」はあとに続く順序を表す。首相の到着の後に各国の代表が入ることを示す。", "慌てて": "「慌てて」は急ぐ様子を表す。順序を述べる文の空欄には入らない。", "最初に": "「最初に」は一番目を表す。到着の後に入るという流れと矛盾する。", "反対に": "「反対に」は逆の意味。到着と入場の流れには合わない。"}, "sentence_index": 6, "correct_answer": "次いで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は祖父の跡を次いで、農場を守っている。", "explanation": "ここは別の語「継いで」（受け継ぐ）。次いでは〈あとに続けて〉の意味なので、受け継ぐの意味では使わない。"}, {"text": "通院の次いでに、駅前で買い物をした。", "explanation": "ここは別の語「ついで」（序で）。次いでは〈あとに続けて〉の意味で、機会のついでは表さないので合わない。"}, {"text": "彼はコップに水を次いで飲んだ。", "explanation": "ここは別の語「注いで」（液体を入れる）。次いでは〈あとに続けて〉の意味なので、注ぐの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "まず会場を片付け、次いて受付を閉じた。", "corrected_sentence": "まず会場を片付け、次いで受付を閉じた。", "error_description": "「次ぐ」のテ形は「次いで」。「次いて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議が終わり、次で懇親会が始まった。", "corrected_sentence": "会議が終わり、次いで懇親会が始まった。", "error_description": "「次で」は「次の駅で」などの意味の別表現で、「会議のあとに続けて」の副詞「次いで」の代わりにはならないので誤り。正しくは「次いで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「裏付けを取る」の「を」。「取る」は目的語に「を」をとり、証拠を得るという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「取る」は他動詞なので、目的語には「を」が必要。「が」では「裏付けが取る」となり不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」は、「取る」の目的語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「取る」の対象を示す「に」は入らない。"}], "correct_answer": "を", "explanations": {"を": "「裏付けを取る」の「を」。「取る」は目的語に「を」をとり、証拠を得るという意味になる。", "が": "「取る」は他動詞なので、目的語には「を」が必要。「が」では「裏付けが取る」となり不自然。", "で": "手段を表す「で」は、「取る」の目的語を示せない。", "に": "「取る」の対象を示す「に」は入らない。"}, "error_tags": {"が": "「取る」は他動詞なので、目的語には「を」が必要", "で": "手段を表す「で」は、「取る」の目的語を示せない", "に": "「取る」の対象を示す「に」は入らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「裏付けが取れる」の「が」。「取れる」は可能形で、主語に「が」をとる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表すので、ここでは「取れる」の主語にも対象にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「取れる」の対象を示す「に」は入らない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」は、「取れる」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「裏付けが取れる」の「が」。「取れる」は可能形で、主語に「が」をとる。", "と": "「と」は並列や引用を表すので、ここでは「取れる」の主語にも対象にもならない。", "に": "「取れる」の対象を示す「に」は入らない。", "で": "手段を表す「で」は、「取れる」の主語を示せない。"}, "error_tags": {"に": "「取れる」の対象を示す「に」は入らない", "で": "手段を表す「で」は、「取れる」の主語を示せない", "と": "「と」は並列・引用を表すので、ここでは「取れる」の主語にも対象にもならない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが本当だと言えるための、しっかりした理由や証拠のこと。", "primary_collocate": null, "pronunciation": "うらづけ", "ipa": "ɯɾadzɯke", "syllable_count": 4, "sentences": [{"text": "この説には科学的な裏付けがないので、まだ信じられません。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "この説[せつ]には科学的[かがくてき]な裏付[うらづ]けがないので、まだ信[しん]じられません。", "sentence_source": "generated"}, {"text": "警察は犯人の話の裏付けを取るために、現場の防犯カメラを調べた。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "警察[けいさつ]は犯人[はんにん]の話[はなし]の裏付[うらづ]けを取[と]るために、現場[げんば]の防犯[ぼうはん]カメラを調[しら]べた。", "sentence_source": "generated"}, {"text": "売り上げが伸びるという予想には、十分な裏付けがある。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが伸[の]びるという予想[よそう]には、十分[じゅうぶん]な裏付[うらづ]けがある。", "sentence_source": "generated"}, {"text": "裏付けのない噂を、そのまま友達に話してはいけない。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "裏付[うらづ]けのない噂[うわさ]を、そのまま友達[ともだち]に話[はな]してはいけない。", "sentence_source": "generated"}, {"text": "彼女の主張は、実験の結果によって裏付けが得られた。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の主張[しゅちょう]は、実験[じっけん]の結果[けっか]によって裏付[うらづ]けが得[え]られた。", "sentence_source": "generated"}, {"text": "数字という裏付けがあれば、上司も計画に反対しにくいだろう。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "数字[すうじ]という裏付[うらづ]けがあれば、上司[じょうし]も計画[けいかく]に反対[はんたい]しにくいだろう。", "sentence_source": "generated"}, {"text": "研究者は自分の考えの裏付けとなるデータを集めている。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は自分[じぶん]の考[かんが]えの裏付[うらづ]けとなるデータを集[あつ]めている。", "sentence_source": "generated"}, {"text": "証言の裏付けが取れるまで、記者は記事を出さなかった。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "証言[しょうげん]の裏付[うらづ]けが取[と]れるまで、記者[きしゃ]は記事[きじ]を出[だ]さなかった。", "sentence_source": "generated"}, {"text": "何の裏付けもなく人を疑うのは、よくないことだ。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "何[なん]の裏付[うらづ]けもなく人[ひと]を疑[うたが]うのは、よくないことだ。", "sentence_source": "generated"}, {"text": "新しい調査が、専門家の意見に確かな裏付けを与えた。", "target_word": "裏付け", "complexity_tier": "T3", "furigana": "新[あたら]しい調査[ちょうさ]が、専門家[せんもんか]の意見[いけん]に確[たし]かな裏付[うらづ]けを与[あた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "裏付け", "label": "基本形"}, {"form": "裏付ける", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "主張や説が正しいことを支える根拠・証拠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裏付け", "is_correct": true, "explanation": "正解。「科学的な裏付け」は、説を支える証拠のこと。「ないので信じられない」と文脈が合う。"}, {"text": "足音", "is_correct": false, "explanation": "歩く音を表す語で、「科学的な足音がない」は意味が通らず空所に合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ているときに出す声のことで、説の正しさを支える文脈には入らない。"}, {"text": "昼寝", "is_correct": false, "explanation": "休息の意味で、「科学的な昼寝がない」は空所に入らない。"}], "explanations": {"裏付け": "正解。「科学的な裏付け」は、説を支える証拠のこと。「ないので信じられない」と文脈が合う。", "足音": "歩く音を表す語で、「科学的な足音がない」は意味が通らず空所に合わない。", "寝言": "寝ているときに出す声のことで、説の正しさを支える文脈には入らない。", "昼寝": "休息の意味で、「科学的な昼寝がない」は空所に入らない。"}, "sentence_index": 0, "correct_answer": "裏付け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "クラスのみんなの裏付けを得て、委員長に立候補した。", "explanation": "ここは〈支持・応援〉の意味。裏付けは説や主張が正しいと示す根拠で、人からの支持は指さないので合わない。"}, {"text": "その裏付けは冷静で、だれもが納得した。", "explanation": "ここは〈判断〉の意味。裏付けは証拠で、冷静さや行いの様子は表さないので合わない。"}, {"text": "彼女は強い裏付けを、大きな声で繰り返した。", "explanation": "ここは〈主張〉の意味。裏付けは主張を支える証拠で、声高に繰り返すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裏付け", "is_correct": true, "explanation": "正解。「考えの裏付けとなるデータ」は、考えを支える証拠のこと。"}, {"text": "寝癖", "is_correct": false, "explanation": "髪の乱れを表す語で、データの役割を表す文脈には合わない。"}, {"text": "食器", "is_correct": false, "explanation": "食事に使う道具で、「考えの食器となるデータ」は意味をなさない。"}, {"text": "雨具", "is_correct": false, "explanation": "雨をしのぐ道具で、考えを支えるデータとは結びつかない。"}], "explanations": {"裏付け": "正解。「考えの裏付けとなるデータ」は、考えを支える証拠のこと。", "寝癖": "髪の乱れを表す語で、データの役割を表す文脈には合わない。", "食器": "食事に使う道具で、「考えの食器となるデータ」は意味をなさない。", "雨具": "雨をしのぐ道具で、考えを支えるデータとは結びつかない。"}, "sentence_index": 6, "correct_answer": "裏付け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この商品には一年間の裏付けがついている。", "explanation": "ここは〈保証〉の意味。保証は品質や期間を約束することで、裏付けは証拠や根拠なので合わない。"}, {"text": "先生は生徒に、遅刻しないよう裏付けをした。", "explanation": "ここは〈注意〉の意味。裏付けは証拠や根拠で、人に注意を与える行為は指さないので合わない。"}, {"text": "彼は裏付けがなくて、すぐに疲れてしまう。", "explanation": "ここは〈体力〉の意味。裏付けは証拠や根拠で、体の力は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "検察は、供述の裏付けに取った。", "corrected_sentence": "検察は、供述の裏付けを取った。", "error_description": "「取る」は目的語に「を」をとるので、「に」は誤り。正しくは「裏付けを取る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52181, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の主張は、実験で裏付けれた。", "corrected_sentence": "彼の主張は、実験で裏付けられた。", "error_description": "受身は「られる」で作るので、「れ」だけでは誤り。正しくは「裏付けられた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
