INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52183, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物や飲み物の、あまい味のことです。", "primary_collocate": null, "pronunciation": "あまみ", "ipa": "amami", "syllable_count": 3, "sentences": [{"text": "このりんごは、甘みが強くてとてもおいしい。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "このりんごは、甘[あま]みが強[つよ]くてとてもおいしい。", "sentence_source": "generated"}, {"text": "砂糖を入れなくても、かぼちゃには自然な甘みがある。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "砂糖[さとう]を入[い]れなくても、かぼちゃには自然[しぜん]な甘[あま]みがある。", "sentence_source": "generated"}, {"text": "コーヒーに牛乳を入れると、甘みが出て飲みやすくなります。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "コーヒーに牛乳[ぎゅうにゅう]を入[い]れると、甘[あま]みが出[で]て飲[の]みやすくなります。", "sentence_source": "generated"}, {"text": "冬に食べるみかんは、甘みが増しておいしくなる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "冬[ふゆ]に食[た]べるみかんは、甘[あま]みが増[ま]しておいしくなる。", "sentence_source": "generated"}, {"text": "このお茶は、最初に苦みを感じ、あとから甘みが広がる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は、最初[さいしょ]に苦[にが]みを感[かん]じ、あとから甘[あま]みが広[ひろ]がる。", "sentence_source": "generated"}, {"text": "弟は甘みの強いジュースばかり飲んで、母に注意された。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "弟[おとうと]は甘[あま]みの強[つよ]いジュースばかり飲[の]んで、母[はは]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "玉ねぎをよく炒めると、甘みが出てスープがおいしくなる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "玉[たま]ねぎをよく炒[いた]めると、甘[あま]みが出[で]てスープがおいしくなる。", "sentence_source": "generated"}, {"text": "このケーキは甘みが少ないので、甘いものが苦手な父も食べられた。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "このケーキは甘[あま]みが少[すく]ないので、甘[あま]いものが苦手[にがて]な父[ちち]も食[た]べられた。", "sentence_source": "generated"}, {"text": "塩を少し加えると、すいかの甘みがいっそう引き立つ。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "塩[しお]を少[すこ]し加[くわ]えると、すいかの甘[あま]みがいっそう引[ひ]き立[た]つ。", "sentence_source": "generated"}, {"text": "日本酒のほのかな甘みが、焼き魚によく合った。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "日本酒[にほんしゅ]のほのかな甘[あま]みが、焼[や]き魚[ざかな]によく合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘み", "label": "基本形"}, {"form": "甘い", "label": "形容詞形"}], "register": "neutral", "sense_fingerprint": "食べ物・飲み物が持つ、あまい味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52183, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甘み", "is_correct": true, "explanation": "正解。「甘みが強い」は、食べ物の甘い味の強さを表す。"}, {"text": "産地", "is_correct": false, "explanation": "生まれた場所を表す語で、味の強さの主語にはならない。"}, {"text": "収穫日", "is_correct": false, "explanation": "収穫した日付のことで、味の強さを表す文脈には入らない。"}, {"text": "品種", "is_correct": false, "explanation": "作物の種類を表す語で、「品種が強くて」は空所に合わない。"}], "explanations": {"甘み": "正解。「甘みが強い」は、食べ物の甘い味の強さを表す。", "産地": "生まれた場所を表す語で、味の強さの主語にはならない。", "収穫日": "収穫した日付のことで、味の強さを表す文脈には入らない。", "品種": "作物の種類を表す語で、「品種が強くて」は空所に合わない。"}, "sentence_index": 0, "correct_answer": "甘み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "審判の甘みが目立ち、選手から不満の声が上がった。", "explanation": "ここは〈判定の甘さ〉の意味。甘みは味わいを表し、判定がゆるいことは指さないので合わない。"}, {"text": "弟は甘みが強くて、いつも母にくっついている。", "explanation": "ここは〈甘え〉の意味。甘みは味の甘さで、人に頼る気持ちは指さないので合わない。"}, {"text": "夕焼けの甘みが強くて、空が真っ赤に染まった。", "explanation": "ここは〈色〉の意味。甘みは味の性質で、夕焼けの色の濃さは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52183, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘み", "is_correct": true, "explanation": "正解。「甘みが出て」は、加熱した食材から甘い味が生まれることを表す。"}, {"text": "包装", "is_correct": false, "explanation": "商品を包む作業や材料で、味が出る文脈には合わない。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届けることで、スープの味の変化とは関係しない。"}, {"text": "生産者", "is_correct": false, "explanation": "作物を作る人のことで、味が出るという文脈には入らない。"}], "explanations": {"甘み": "正解。「甘みが出て」は、加熱した食材から甘い味が生まれることを表す。", "包装": "商品を包む作業や材料で、味が出る文脈には合わない。", "配送": "荷物を届けることで、スープの味の変化とは関係しない。", "生産者": "作物を作る人のことで、味が出るという文脈には入らない。"}, "sentence_index": 6, "correct_answer": "甘み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この麻婆豆腐は甘みが強くて、汗が止まらない。", "explanation": "ここは〈辛み〉の意味。麻婆豆腐の刺激は辛みで、甘みは糖の味なので合わない。"}, {"text": "彼は甘みで人をだますのが得意だ。", "explanation": "ここは〈甘い言葉〉の意味。甘みは味わいで、言葉や誘いの甘さは指さないので合わない。"}, {"text": "このブラックコーヒーは甘みが強くて、朝の眠気が覚める。", "explanation": "ここは〈苦み〉の意味。ブラックコーヒーの特徴は苦みで、甘みは糖の味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52183, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この桃は甘みが高くて、みずみずしい。", "corrected_sentence": "この桃は甘みが強くて、みずみずしい。", "error_description": "味の強さは「強い」で表すので、「高い」は甘みの修飾として不自然。正しくは「甘みが強い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52183, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "にんじんをよく煮ると、甘みを出て味が優しくなる。", "corrected_sentence": "にんじんをよく煮ると、甘みが出て味が優しくなる。", "error_description": "「出る」は自動詞なので、主語の「甘み」に「が」をつける。「を」は他動詞用の格助詞で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
