INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52184, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "糖分などによって感じられる、あまい味わい。また、その度合い。", "primary_collocate": null, "pronunciation": "あまみ", "ipa": "amami", "syllable_count": 3, "sentences": [{"text": "このいちごは糖度が高く、上品な甘みがある。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "このいちごは糖度[とうど]が高[たか]く、上品[じょうひん]な甘[あま]みがある。", "sentence_source": "generated"}, {"text": "果物の甘みは、収穫の時期によって大きく変わる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "果物[くだもの]の甘[あま]みは、収穫[しゅうかく]の時期[じき]によって大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "ジャムの甘みを抑えるために、砂糖の量を半分にした。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "ジャムの甘[あま]みを抑[おさ]えるために、砂糖[さとう]の量[りょう]を半分[はんぶん]にした。", "sentence_source": "generated"}, {"text": "メロンは熟すほど、甘みが強くなる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "メロンは熟[じゅく]すほど、甘[あま]みが強[つよ]くなる。", "sentence_source": "generated"}, {"text": "この紅茶は甘みが控えめで、食事中にも飲みやすい。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "この紅茶[こうちゃ]は甘[あま]みが控[ひか]えめで、食事中[しょくじちゅう]にも飲[の]みやすい。", "sentence_source": "generated"}, {"text": "同じ品種でも、日当たりが悪い畑では甘みが足りない。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "同[おな]じ品種[ひんしゅ]でも、日当[ひあ]たりが悪[わる]い畑[はたけ]では甘[あま]みが足[た]りない。", "sentence_source": "generated"}, {"text": "子ども向けのお菓子は、大人には甘みがくどく感じられる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "子[こ]ども向[む]けのお菓子[かし]は、大人[おとな]には甘[あま]みがくどく感[かん]じられる。", "sentence_source": "generated"}, {"text": "さつまいもを焼くと、でんぷんが糖に変わって甘みが増す。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "さつまいもを焼[や]くと、でんぷんが糖[とう]に変[か]わって甘[あま]みが増[ま]す。", "sentence_source": "generated"}, {"text": "このワインは甘みと酸味のバランスがとてもよい。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "このワインは甘[あま]みと酸味[さんみ]のバランスがとてもよい。", "sentence_source": "generated"}, {"text": "トマトの甘みは、水を減らして育てると強くなると言われる。", "target_word": "甘み", "complexity_tier": "T3", "furigana": "トマトの甘[あま]みは、水[みず]を減[へ]らして育[そだ]てると強[つよ]くなると言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘み", "label": "基本形"}, {"form": "甘い", "label": "形容詞形"}], "register": "neutral", "sense_fingerprint": "糖分による味わいと、その強さの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甘み", "is_correct": true, "explanation": "正解。「上品な甘みがある」は、糖分による味わいのこと。"}, {"text": "皮むき", "is_correct": false, "explanation": "果物の皮を取る作業で、味わいを表す文脈には入らない。"}, {"text": "下ごしらえ", "is_correct": false, "explanation": "調理の前準備のことで、「上品な下ごしらえがある」は空所に合わない。"}, {"text": "追熟", "is_correct": false, "explanation": "果物を熟させることで、味わいの名詞としては空所に合わない。"}], "explanations": {"甘み": "正解。「上品な甘みがある」は、糖分による味わいのこと。", "皮むき": "果物の皮を取る作業で、味わいを表す文脈には入らない。", "下ごしらえ": "調理の前準備のことで、「上品な下ごしらえがある」は空所に合わない。", "追熟": "果物を熟させることで、味わいの名詞としては空所に合わない。"}, "sentence_index": 0, "correct_answer": "甘み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は甘みが強くて、いつも母に頼っている。", "explanation": "ここは〈甘え〉の意味。甘みは糖による味わいで、人に頼る気持ちは指さないので合わない。"}, {"text": "熟しきっていないレモンは甘みが強くて、顔がゆがむほどだ。", "explanation": "ここは〈酸味〉の意味。熟しきっていないレモンの刺激は酸っぱさで、甘みは糖の味なので合わない。"}, {"text": "メロンは熟すほど、甘みの色が濃くなる。", "explanation": "ここは〈色〉の意味。甘みは味わいで、色の濃さは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘み", "is_correct": true, "explanation": "正解。「甘みがくどく感じられる」は、糖分による味わいが強すぎることを表す。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸音で、味の感じ方を表す文脈には入らない。"}, {"text": "足音", "is_correct": false, "explanation": "歩く音のことで、「くどく感じられる」の主語にはならない。"}, {"text": "寝癖", "is_correct": false, "explanation": "髪の乱れを表す語で、味わいの文脈には合わない。"}], "explanations": {"甘み": "正解。「甘みがくどく感じられる」は、糖分による味わいが強すぎることを表す。", "寝息": "眠っている人の呼吸音で、味の感じ方を表す文脈には入らない。", "足音": "歩く音のことで、「くどく感じられる」の主語にはならない。", "寝癖": "髪の乱れを表す語で、味わいの文脈には合わない。"}, "sentence_index": 6, "correct_answer": "甘み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この唐辛子は甘みが強くて、舌がひりひりする。", "explanation": "ここは〈辛み〉の意味。唐辛子の刺激は辛みで、甘みは糖の味なので合わない。"}, {"text": "彼は甘みを使って、いつも人の気持ちをなだめる。", "explanation": "ここは〈甘い言葉〉の意味。甘みは味わいで、人の機嫌を取る言葉の甘さは指さないので合わない。"}, {"text": "この布は甘みがなめらかで、肌に優しい。", "explanation": "ここは〈手触り〉の意味。甘みは糖の味わいで、布の触り心地は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この梨は甘みが重くて、シャキシャキしている。", "corrected_sentence": "この梨は甘みが強くて、シャキシャキしている。", "error_description": "甘みの度合いは「強い」で表すので、「重い」は不自然。正しくは「甘みが強い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "焼いたさつまいもは、甘みが増るので人気がある。", "corrected_sentence": "焼いたさつまいもは、甘みが増すので人気がある。", "error_description": "「増す」は五段動詞なので、「増る」とは活用しない。正しくは「甘みが増す」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
