INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52185, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物の味の一つで、しょっぱい感じのことです。", "primary_collocate": null, "pronunciation": "しおけ", "ipa": "ɕioke", "syllable_count": 3, "sentences": [{"text": "海の近くでとれた野菜は、ほんのり塩気を感じておいしい。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くでとれた野菜[やさい]は、ほんのり塩気[しおけ]を感[かん]じておいしい。", "sentence_source": "generated"}, {"text": "ポテトチップスの塩気が、冷たいビールによく合う。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "ポテトチップスの塩気[しおけ]が、冷[つめ]たいビールによく合[あ]う。", "sentence_source": "generated"}, {"text": "子どもにはこの味噌汁は塩気が強いので、お湯でうすめた。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "子[こ]どもにはこの味噌汁[みそしる]は塩気[しおけ]が強[つよ]いので、お湯[ゆ]でうすめた。", "sentence_source": "generated"}, {"text": "塩気のあるクッキーは、甘いものが苦手な人にも人気だ。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "塩気[しおけ]のあるクッキーは、甘[あま]いものが苦手[にがて]な人[ひと]にも人気[にんき]だ。", "sentence_source": "generated"}, {"text": "塩ゆでした枝豆から、ちょうどよい塩気が口の中に広がった。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "塩[しお]ゆでした枝豆[えだまめ]から、ちょうどよい塩気[しおけ]が口[くち]の中[なか]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "母の作る卵焼きは、砂糖を使わず、塩気だけで味をつけている。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "母[はは]の作[つく]る卵焼[たまごや]きは、砂糖[さとう]を使[つか]わず、塩気[しおけ]だけで味[あじ]をつけている。", "sentence_source": "generated"}, {"text": "運動したあとは、汗をかいたので塩気のあるものが食べたくなる。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "運動[うんどう]したあとは、汗[あせ]をかいたので塩気[しおけ]のあるものが食[た]べたくなる。", "sentence_source": "generated"}, {"text": "塩辛は塩気が強いため、少しずつご飯にのせて食べる。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "塩辛[しおから]は塩気[しおけ]が強[つよ]いため、少[すこ]しずつご飯[はん]にのせて食[た]べる。", "sentence_source": "generated"}, {"text": "ポテトチップスをかじると、すぐに強い塩気[しおけ]が口に広がった。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "ポテトチップスをかじると、すぐに強い塩気[しおけ]が口に広がった。", "sentence_source": "generated"}, {"text": "塩気のきいたおにぎりは、夏のお弁当にぴったりだ。", "target_word": "塩気", "complexity_tier": "T3", "furigana": "塩気[しおけ]のきいたおにぎりは、夏[なつ]のお弁当[べんとう]にぴったりだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塩気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "塩気: 食べ物の味の一つ、しょっぱい感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52185, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塩気", "is_correct": true, "explanation": "「ほんのり塩気を感じておいしい」は味を表す表現として自然で、文脈に合う。"}, {"text": "寒気", "is_correct": false, "explanation": "寒気は感じるものとして味わいには使わず、「ほんのり寒気を感じておいしい」は不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は味わうものではないので、「ほんのり眠気を感じておいしい」は文脈に合わない。"}, {"text": "熱気", "is_correct": false, "explanation": "熱気は味の要素ではないので、「ほんのり熱気を感じておいしい」は不自然。"}], "explanations": {"塩気": "「ほんのり塩気を感じておいしい」は味を表す表現として自然で、文脈に合う。", "寒気": "寒気は感じるものとして味わいには使わず、「ほんのり寒気を感じておいしい」は不自然。", "眠気": "眠気は味わうものではないので、「ほんのり眠気を感じておいしい」は文脈に合わない。", "熱気": "熱気は味の要素ではないので、「ほんのり熱気を感じておいしい」は不自然。"}, "sentence_index": 0, "correct_answer": "塩気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "わさびの塩気が、鼻にツンと来る。", "explanation": "ここは〈辛味〉の意味。ツンとした刺激は辛さで、塩の味を表す塩気とは合わない。"}, {"text": "コーヒーの塩気が、後味にほろ苦く残る。", "explanation": "ここは〈苦味〉の意味。ほろ苦さは苦味の要素で、塩の味を指す塩気とは合わない。"}, {"text": "お香の塩気が、部屋にほのかに香った。", "explanation": "ここは〈香り〉の意味。香るのは匂いなので、味を表す塩気とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52185, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塩気", "is_correct": true, "explanation": "「汗をかいたので塩気のあるものが食べたくなる」は、塩味を求める文脈に合う。"}, {"text": "倦怠", "is_correct": false, "explanation": "倦怠は食べたくなる対象ではないので、「倦怠のあるもの」は文脈に合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は食べ物の性質ではないので、「足音のあるもの」は文脈に合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は食べ物の性質ではないので、「寝息のあるもの」は文脈に合わない。"}], "explanations": {"塩気": "「汗をかいたので塩気のあるものが食べたくなる」は、塩味を求める文脈に合う。", "倦怠": "倦怠は食べたくなる対象ではないので、「倦怠のあるもの」は文脈に合わない。", "足音": "足音は食べ物の性質ではないので、「足音のあるもの」は文脈に合わない。", "寝息": "寝息は食べ物の性質ではないので、「寝息のあるもの」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "塩気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レモンの塩気が口の中に広がり、さっぱりした。", "explanation": "ここは〈酸味〉の意味。レモンの味は酸っぱさで、塩の味を指す塩気は合わない。"}, {"text": "渋いお茶の塩気が、舌に残って気になる。", "explanation": "ここは〈渋味〉の意味。舌に残る渋さは渋味で、塩の味を表す塩気とは合わない。"}, {"text": "健康診断で、塩気の量が多いと注意された。", "explanation": "ここは〈塩分〉の意味。量を指す場合は塩分を使い、味わいを表す塩気は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52185, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この煮物は塩気を控えめで、素材の味がよくわかる。", "corrected_sentence": "この煮物は塩気が控えめで、素材の味がよくわかる。", "error_description": "助詞が誤り。形容動詞「控えめ」の主語になるので「塩気が」が正しい。「を」は目的語を表すため、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52185, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この味噌汁は塩気が穏やかくて、朝でも飲みやすい。", "corrected_sentence": "この味噌汁は塩気が穏やかで、朝でも飲みやすい。", "error_description": "活用形が誤り。形容動詞「穏やか」の接続形は「穏やかで」で、「穏やかくて」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「毛布を」の「を」で、重ね合わせる動作の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「毛布へ重ね合わせて」では目的語が立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「毛布から重ね合わせて」は動作の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す助詞だが、ここでは毛布が道具ではなく対象なので合わない。"}], "correct_answer": "を", "explanations": {"を": "「毛布を」の「を」で、重ね合わせる動作の目的語を示す。", "へ": "方向を示す助詞で、「毛布へ重ね合わせて」では目的語が立たない。", "から": "起点を示す助詞で、「毛布から重ね合わせて」は動作の対象にならない。", "で": "手段を示す助詞だが、ここでは毛布が道具ではなく対象なので合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
