INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、ほかのものの上にのせること。", "primary_collocate": null, "pronunciation": "かさねあわせる", "ipa": "kasaneawaseɾɯ", "syllable_count": 7, "sentences": [{"text": "母は娘の小さな手の上に自分の手を重ね合わせた。", "target_word": "重ね合わせた", "complexity_tier": "T3", "furigana": "母[はは]は娘[むすめ]の小[ちい]さな手[て]の上[うえ]に自分[じぶん]の手[て]を重[かさ]ね合[あ]わせた。", "sentence_source": "generated"}, {"text": "寒い夜は、布団の上に毛布を重ね合わせて眠った。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "寒[さむ]い夜[よる]は、布団[ふとん]の上[うえ]に毛布[もうふ]を重[かさ]ね合[あ]わせて眠[ねむ]った。", "sentence_source": "generated"}, {"text": "彼は焼いた板の上に、もう一枚の板を重ね合わせて固定した。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "彼[かれ]は焼[や]いた板[いた]の上[うえ]に、もう一枚[いちまい]の板[いた]を重[かさ]ね合[あ]わせて固定[こてい]した。", "sentence_source": "generated"}, {"text": "絵の具が乾いてから、その上に別の色を重ね合わせると深みが出る。", "target_word": "重ね合わせる", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]が乾[かわ]いてから、その上[うえ]に別[べつ]の色[いろ]を重[かさ]ね合[あ]わせると深[ふか]みが出[で]る。", "sentence_source": "generated"}, {"text": "紙の上にトレーシングペーパーを重ね合わせて、絵をなぞった。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "紙[かみ]の上[うえ]にトレーシングペーパーを重[かさ]ね合[あ]わせて、絵[え]をなぞった。", "sentence_source": "generated"}, {"text": "薄い板を三枚重ね合わせて、棚の段を作った。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "薄[うす]い板[いた]を三枚[さんまい]重[かさ]ね合[あ]わせて、棚[たな]の段[だん]を作[つく]った。", "sentence_source": "generated"}, {"text": "黒い布の上に白い布を重ね合わせると、模様がはっきり見える。", "target_word": "重ね合わせる", "complexity_tier": "T3", "furigana": "黒[くろ]い布[ぬの]の上[うえ]に白[しろ]い布[ぬの]を重[かさ]ね合[あ]わせると、模様[もよう]がはっきり見[み]える。", "sentence_source": "generated"}, {"text": "写真の上に薄い紙を重ね合わせて、傷がつかないようにしまった。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "写真[しゃしん]の上[うえ]に薄[うす]い紙[かみ]を重[かさ]ね合[あ]わせて、傷[きず]がつかないようにしまった。", "sentence_source": "generated"}, {"text": "厚い本の上に辞書を重ね合わせたら、机が高くなった。", "target_word": "重ね合わせたら", "complexity_tier": "T3", "furigana": "厚[あつ]い本[ほん]の上[うえ]に辞書[じしょ]を重[かさ]ね合[あ]わせたら、机[つくえ]が高[たか]くなった。", "sentence_source": "generated"}, {"text": "氷の上に板を重ね合わせて、慎重に川を渡った。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "氷[こおり]の上[うえ]に板[いた]を重[かさ]ね合[あ]わせて、慎重[しんちょう]に川[かわ]を渡[わた]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ね合わせる", "label": "辞書形"}, {"form": "重ね合わせます", "label": "丁寧形"}, {"form": "重ね合わせて", "label": "て形"}, {"form": "重ね合わせた", "label": "た形"}, {"form": "重ね合わせない", "label": "否定形"}, {"form": "重ね合わせれば", "label": "仮定形"}, {"form": "重ね合わせよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "重ね合わせる: あるものを別のものの上にのせて置く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ね合わせた", "is_correct": true, "explanation": "た形で、母が手を重ねたという完了の出来事に合う。"}, {"text": "煮詰めた", "is_correct": false, "explanation": "煮て水分を飛ばす動作で、手の上に手を置く場面と合わない。"}, {"text": "撹拌した", "is_correct": false, "explanation": "材料をかき混ぜる動作で、手を重ねる行為とは合わない。"}, {"text": "発酵させた", "is_correct": false, "explanation": "微生物の働きで変化させる動作で、手の上に手を置く文脈に合わない。"}], "explanations": {"重ね合わせた": "た形で、母が手を重ねたという完了の出来事に合う。", "煮詰めた": "煮て水分を飛ばす動作で、手の上に手を置く場面と合わない。", "撹拌した": "材料をかき混ぜる動作で、手を重ねる行為とは合わない。", "発酵させた": "微生物の働きで変化させる動作で、手の上に手を置く文脈に合わない。"}, "sentence_index": 0, "correct_answer": "重ね合わせた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糸を針の穴に重ね合わせて通した。", "explanation": "ここは〈通す〉の意味。〈重ね合わせる〉はものを上にのせることで、細い穴に通す動作は表さない。"}, {"text": "スープを重ね合わせて、かき混ぜた。", "explanation": "ここは〈かき混ぜる〉の意味。〈重ね合わせる〉はものを上にのせることで、液体を混ぜる動作には使わない。"}, {"text": "黒板の文字を重ね合わせて消した。", "explanation": "ここは〈消す〉の意味。〈重ね合わせる〉はものを上にのせることで、文字を取り除く動作は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ね合わせる", "is_correct": true, "explanation": "辞書形に「と」が続いて条件を表し、布を重ねた結果を述べる文に合う。"}, {"text": "溶かす", "is_correct": false, "explanation": "物質を溶かす動作で、布を重ねる場面とは合わない。"}, {"text": "冷やし固める", "is_correct": false, "explanation": "温度を下げて固める動作で、布の模様を見る文脈に合わない。"}, {"text": "発酵させる", "is_correct": false, "explanation": "微生物で変化させる動作で、布の重ね合わせとは関係がない。"}], "explanations": {"重ね合わせる": "辞書形に「と」が続いて条件を表し、布を重ねた結果を述べる文に合う。", "溶かす": "物質を溶かす動作で、布を重ねる場面とは合わない。", "冷やし固める": "温度を下げて固める動作で、布の模様を見る文脈に合わない。", "発酵させる": "微生物で変化させる動作で、布の重ね合わせとは関係がない。"}, "sentence_index": 6, "correct_answer": "重ね合わせる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍵を机の上に重ね合わせて、ドアを開けた。", "explanation": "ここは〈開ける〉の意味。〈重ね合わせる〉はものを上にのせることで、鍵を使ってドアを開く動作は表さない。"}, {"text": "粉を重ね合わせて、ふるいにかけた。", "explanation": "ここは〈ふるう〉の意味。〈重ね合わせる〉はものを上にのせることで、粉をふるう動作には使わない。"}, {"text": "フラスコに薬品を重ね合わせて、熱した。", "explanation": "ここは〈熱する〉の意味。〈重ね合わせる〉はものを上にのせることで、薬品を加熱する動作は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒いので、ベッドに毛布を重ね合わせで寝た。", "corrected_sentence": "寒いので、ベッドに毛布を重ね合わせて寝た。", "error_description": "て形は「て」になる。「合わせで」と濁らせるのは誤りで、「重ね合わせて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重ね合わせて", "is_correct": true, "explanation": "て形で、後ろの「眠った」へつながる文の流れに合う。"}, {"text": "重ね合わせる", "is_correct": false, "explanation": "辞書形は文を言い切る形で、「眠った」へ続けるとつながらない。"}, {"text": "重ね合わせた", "is_correct": false, "explanation": "た形は完了を表し、同時に行った動作の流れを示せない。"}, {"text": "重ね合わせない", "is_correct": false, "explanation": "否定形は重ねない意味になり、文の内容と逆になる。"}], "correct_form": "重ね合わせて", "base_form": "重ね合わせる", "form_label": "て形", "sentence_index": 1, "explanations": {"重ね合わせて": "て形で、後ろの「眠った」へつながる文の流れに合う。", "重ね合わせる": "辞書形は文を言い切る形で、「眠った」へ続けるとつながらない。", "重ね合わせた": "た形は完了を表し、同時に行った動作の流れを示せない。", "重ね合わせない": "否定形は重ねない意味になり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52187, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薄いフィルムを二枚重ね合わせるに、色が変わって見える。", "corrected_sentence": "薄いフィルムを二枚重ね合わせると、色が変わって見える。", "error_description": "条件を表す「と」が必要。「重ね合わせるに」は「に」が続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重ね合わせて", "is_correct": true, "explanation": "て形で、後ろの「傷がつかないように」へつながる文に合う。"}, {"text": "重ね合わせます", "is_correct": false, "explanation": "丁寧形は文末で使う形で、後ろの節へ続けると文がつながらない。"}, {"text": "重ね合わせれば", "is_correct": false, "explanation": "仮定形で条件を表すが、ここは動作の流れを示す形なので合わない。"}, {"text": "重ね合わせよう", "is_correct": false, "explanation": "意向形は意志を表し、実際にしまった出来事の説明に合わない。"}], "correct_form": "重ね合わせて", "base_form": "重ね合わせる", "form_label": "て形", "sentence_index": 7, "explanations": {"重ね合わせて": "て形で、後ろの「傷がつかないように」へつながる文に合う。", "重ね合わせます": "丁寧形は文末で使う形で、後ろの節へ続けると文がつながらない。", "重ね合わせれば": "仮定形で条件を表すが、ここは動作の流れを示す形なので合わない。", "重ね合わせよう": "意向形は意志を表し、実際にしまった出来事の説明に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「重ね合わせる」に続いて条件を作る助詞で、文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、動詞の直後に置くと文が続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す助詞で、動詞の直後には置けず文が続かない。"}, {"text": "に", "is_correct": false, "explanation": "位置や方向を示す助詞で、条件節を作れない。"}], "correct_answer": "と", "explanations": {"と": "「重ね合わせる」に続いて条件を作る助詞で、文の流れに合う。", "を": "目的語を示す助詞だが、動詞の直後に置くと文が続かない。", "で": "手段を示す助詞で、動詞の直後には置けず文が続かない。", "に": "位置や方向を示す助詞で、条件節を作れない。"}, "error_tags": {"を": "目的語", "で": "手段", "に": "位置・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数のものを、互いに重なるようにして一つの上に置くこと。また、重ねて合わせること。", "primary_collocate": null, "pronunciation": "かさねあわせる", "ipa": "kasaneawaseɾɯ", "syllable_count": 7, "sentences": [{"text": "ラズベリーなどのジャムを、対になる片割れか、同じ切片の上に重ね合わせる。", "target_word": "重ね合わせる", "complexity_tier": "T3", "furigana": "ラズベリーなどのジャムを、対[つい]になる片割[かたわ]れか、同[おな]じ切片[せっぺん]の上[うえ]に重[かさ]ね合[あ]わせる。", "sentence_source": "generated"}, {"text": "二枚の透明なシートをずれないように重ね合わせると、図がひとつになる。", "target_word": "重ね合わせる", "complexity_tier": "T3", "furigana": "二枚[にまい]の透明[とうめい]なシートをずれないように重[かさ]ね合[あ]わせると、図[ず]がひとつになる。", "sentence_source": "generated"}, {"text": "折り紙の角をきちんと重ね合わせてから、真ん中で折ってください。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "折[お]り紙[がみ]の角[かど]をきちんと重[かさ]ね合[あ]わせてから、真[ま]ん中[なか]で折[お]ってください。", "sentence_source": "generated"}, {"text": "地図を重ね合わせて、昔の川の流れと今の道を比べた。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "地図[ちず]を重[かさ]ね合[あ]わせて、昔[むかし]の川[かわ]の流[なが]れと今[いま]の道[みち]を比[くら]べた。", "sentence_source": "generated"}, {"text": "テープの両端を重ね合わせて、輪にした。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "テープの両端[りょうたん]を重[かさ]ね合[あ]わせて、輪[わ]にした。", "sentence_source": "generated"}, {"text": "型紙を布の上に重ね合わせ、印をつけてから切った。", "target_word": "重ね合わせ", "complexity_tier": "T3", "furigana": "型紙[かたがみ]を布[ぬの]の上[うえ]に重[かさ]ね合[あ]わせ、印[しるし]をつけてから切[き]った。", "sentence_source": "generated"}, {"text": "二つの三角形を重ね合わせたら、ぴったり同じ大きさだった。", "target_word": "重ね合わせた", "complexity_tier": "T3", "furigana": "二[ふた]つの三角形[さんかっけい]を重[かさ]ね合[あ]わせたら、ぴったり同[おな]じ大[おお]きさだった。", "sentence_source": "generated"}, {"text": "写真を重ね合わせて、事故の前と後の様子を比較した。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "写真[しゃしん]を重[かさ]ね合[あ]わせて、事故[じこ]の前[まえ]と後[あと]の様子[ようす]を比較[ひかく]した。", "sentence_source": "generated"}, {"text": "薄いガーゼを三枚重ね合わせて、傷口に当てた。", "target_word": "重ね合わせて", "complexity_tier": "T3", "furigana": "薄[うす]いガーゼを三枚[さんまい]重[かさ]ね合[あ]わせて、傷口[きずぐち]に当[あ]てた。", "sentence_source": "generated"}, {"text": "色のついたセロハンを重ね合わせると、新しい色ができる。", "target_word": "重ね合わせる", "complexity_tier": "T3", "furigana": "色[いろ]のついたセロハンを重[かさ]ね合[あ]わせると、新[あたら]しい色[いろ]ができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ね合わせる", "label": "辞書形"}, {"form": "重ね合わせます", "label": "丁寧形"}, {"form": "重ね合わせて", "label": "て形"}, {"form": "重ね合わせた", "label": "た形"}, {"form": "重ね合わせない", "label": "否定形"}, {"form": "重ね合わせれば", "label": "仮定形"}, {"form": "重ね合わせよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "重ね合わせる: 複数のものをぴったり重なるように重ねて合わせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ね合わせる", "is_correct": true, "explanation": "切片の上に重ねて合わせるという意味で、文脈に合う。"}, {"text": "煮詰める", "is_correct": false, "explanation": "水分を飛ばして濃くする動作で、切片の上に載せる流れに合わない。"}, {"text": "乾燥させる", "is_correct": false, "explanation": "水分を抜く動作で、ジャムを切片に重ねる説明にならない。"}, {"text": "撹拌する", "is_correct": false, "explanation": "材料をかき混ぜる動作で、切片の上に置く文脈と合わない。"}], "explanations": {"重ね合わせる": "切片の上に重ねて合わせるという意味で、文脈に合う。", "煮詰める": "水分を飛ばして濃くする動作で、切片の上に載せる流れに合わない。", "乾燥させる": "水分を抜く動作で、ジャムを切片に重ねる説明にならない。", "撹拌する": "材料をかき混ぜる動作で、切片の上に置く文脈と合わない。"}, "sentence_index": 0, "correct_answer": "重ね合わせる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ばらばらの部品を重ね合わせて、一つの機械にまとめた。", "explanation": "ここは〈組み立てる〉の意味。〈重ね合わせる〉は重なるように合わせることで、部品を組んで一つの機械にする意味ではない。"}, {"text": "二種類の薬を重ね合わせて、効果を確かめた。", "explanation": "ここは〈組み合わせる〉の意味。〈重ね合わせる〉は物を重ねて合わせる意味で、二種類の薬を組み合わせて使う場面には合わない。"}, {"text": "先生に質問を重ね合わせた。", "explanation": "ここは〈重ねる〉の意味（質問を続けて重ねる）。〈重ね合わせる〉は物を重ねて合わせる意味で、質問を続けることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ね合わせた", "is_correct": true, "explanation": "「たら」に続く形で、三角形を重ねた結果を表し、文に合う。"}, {"text": "溶かした", "is_correct": false, "explanation": "物質を液体にする動作で、三角形の形を比べる文脈に合わない。"}, {"text": "発酵させた", "is_correct": false, "explanation": "微生物の働きで変化させる動作で、図形の大きさの話に合わない。"}, {"text": "冷やし固めた", "is_correct": false, "explanation": "温度を下げて固める動作で、図形を重ねて比べる文脈と合わない。"}], "explanations": {"重ね合わせた": "「たら」に続く形で、三角形を重ねた結果を表し、文に合う。", "溶かした": "物質を液体にする動作で、三角形の形を比べる文脈に合わない。", "発酵させた": "微生物の働きで変化させる動作で、図形の大きさの話に合わない。", "冷やし固めた": "温度を下げて固める動作で、図形を重ねて比べる文脈と合わない。"}, "sentence_index": 6, "correct_answer": "重ね合わせた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "時計の時刻を重ね合わせた。", "explanation": "ここは〈時刻を合わせる〉の意味。〈重ね合わせる〉は物を重ねることで、時刻を設定する意味にはならない。"}, {"text": "体重計に重ね合わせて、体重を量った。", "explanation": "ここは〈乗る〉の意味。体重計に乗るのは一人の動作で、〈重ね合わせる〉は二つ以上を重ねて合わせることなので合わない。"}, {"text": "ラジオの周波数を重ね合わせて、番組を聴いた。", "explanation": "ここは〈周波数を合わせる〉の意味。〈重ね合わせる〉は物を重ねることで、電波の周波数を合わせる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二枚の透明なシートを重ね合わせに、図がひとつになる。", "corrected_sentence": "二枚の透明なシートを重ね合わせると、図がひとつになる。", "error_description": "条件を表す「と」が必要。「に」は動詞の後に続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重ね合わせる", "is_correct": true, "explanation": "辞書形に「と」が続いて条件を表している。"}, {"text": "重ね合わせた", "is_correct": false, "explanation": "た形は完了の意味になり、「と」に続けても一般的な条件の文に合わない。"}, {"text": "重ね合わせて", "is_correct": false, "explanation": "て形は「と」に続かず、文の形が合わない。"}, {"text": "重ね合わせよう", "is_correct": false, "explanation": "意向形は意志や意図を表し、ここで示される条件の意味に合わない。"}], "correct_form": "重ね合わせる", "base_form": "重ね合わせる", "form_label": "辞書形＋と（条件）", "sentence_index": 1, "explanations": {"重ね合わせる": "辞書形に「と」が続いて条件を表している。", "重ね合わせた": "た形は完了の意味になり、「と」に続けても一般的な条件の文に合わない。", "重ね合わせて": "て形は「と」に続かず、文の形が合わない。", "重ね合わせよう": "意向形は意志や意図を表し、ここで示される条件の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52188, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二枚の紙を重ね合わせたり、端がぴったり揃った。", "corrected_sentence": "二枚の紙を重ね合わせたら、端がぴったり揃った。", "error_description": "条件を表す「たら」が必要。「たり」は例示の並列で、後ろの文が続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重ね合わせて", "is_correct": true, "explanation": "て形で、後ろに「傷がつかないように」が続く文の流れに合う。"}, {"text": "重ね合わせる", "is_correct": false, "explanation": "辞書形は文を終える形で、ここでは後ろに続く形が必要。"}, {"text": "重ね合わせない", "is_correct": false, "explanation": "否定形は「ない」で打ち消すため、重ねるという動作の意味が逆になる。"}, {"text": "重ね合わせます", "is_correct": false, "explanation": "丁寧形は文末に使う形で、後ろの節に続けると不自然になる。"}], "correct_form": "重ね合わせて", "base_form": "重ね合わせる", "form_label": "て形", "sentence_index": 7, "explanations": {"重ね合わせて": "て形で、後ろに「傷がつかないように」が続く文の流れに合う。", "重ね合わせる": "辞書形は文を終える形で、ここでは後ろに続く形が必要。", "重ね合わせない": "否定形は「ない」で打ち消すため、重ねるという動作の意味が逆になる。", "重ね合わせます": "丁寧形は文末に使う形で、後ろの節に続けると不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「口腔の奥」の「の」で、口腔の中の場所を修飾する正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、「口腔が奥」では場所の説明にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「口腔を奥」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「口腔で奥」では場所の説明にならない。"}], "correct_answer": "の", "explanations": {"の": "「口腔の奥」の「の」で、口腔の中の場所を修飾する正しい助詞。", "が": "主語を示す助詞だが、「口腔が奥」では場所の説明にならない。", "を": "目的語を示す助詞で、「口腔を奥」では意味が通らない。", "で": "手段や場所を示すが、「口腔で奥」では場所の説明にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「口腔の乾き」の「の」で、口腔の状態を修飾する正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す助詞で、「口腔に乾き」では所有の関係が表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「口腔へ乾き」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「口腔から乾き」では状態の説明にならない。"}], "correct_answer": "の", "explanations": {"の": "「口腔の乾き」の「の」で、口腔の状態を修飾する正しい助詞。", "に": "位置を示す助詞で、「口腔に乾き」では所有の関係が表せない。", "へ": "方向を示す助詞で、「口腔へ乾き」では意味が通らない。", "から": "起点を示す助詞で、「口腔から乾き」では状態の説明にならない。"}, "error_tags": {"に": "位置", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口の中", "primary_collocate": null, "pronunciation": "こうこう", "ipa": "koːkoː", "syllable_count": 4, "sentences": [{"text": "赤ちゃんは何でも口腔に入れて確かめようとする。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは何[なん]でも口腔[こうこう]に入[い]れて確[たし]かめようとする。", "sentence_source": "generated"}, {"text": "口腔の奥にできものができて、食事が痛かった。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "口腔[こうこう]の奥[おく]にできものができて、食事[しょくじ]が痛[いた]かった。", "sentence_source": "generated"}, {"text": "検査では、まず口腔の中を見て、のどの様子も確かめます。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "検査[けんさ]では、まず口腔[こうこう]の中[なか]を見[み]て、のどの様子[ようす]も確[たし]かめます。", "sentence_source": "generated"}, {"text": "冷たい水で口腔をすすぐと、気分がすっきりする。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]で口腔[こうこう]をすすぐと、気分[きぶん]がすっきりする。", "sentence_source": "generated"}, {"text": "口腔の粘膜は弱いので、熱いものには注意が必要だ。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "口腔[こうこう]の粘膜[ねんまく]は弱[よわ]いので、熱[あつ]いものには注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "飴が口腔でゆっくり溶けていく。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "飴[あめ]が口腔[こうこう]でゆっくり溶[と]けていく。", "sentence_source": "generated"}, {"text": "彼は口腔に食べ物を入れたまま話して、注意された。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "彼[かれ]は口腔[こうこう]に食[た]べ物[もの]を入[い]れたまま話[はな]して、注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "口腔の乾きを防ぐため、こまめに水分をとった。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "口腔[こうこう]の乾[かわ]きを防[ふせ]ぐため、こまめに水分[すいぶん]をとった。", "sentence_source": "generated"}, {"text": "歯科医は口腔の状態を見て、虫歯の場所を教えてくれた。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "歯科医[しかい]は口腔[こうこう]の状態[じょうたい]を見[み]て、虫歯[むしば]の場所[ばしょ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "のどが痛いときは、口腔を大きく開けて見せてください。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "のどが痛[いた]いときは、口腔[こうこう]を大[おお]きく開[あ]けて見[み]せてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口腔", "label": "基本形"}], "register": "中立（やや硬い書き言葉）", "sense_fingerprint": "口の中という場所。歯・舌・粘膜のある部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "口の中という場所で、赤ちゃんが物を入れる場所として自然に合う。"}, {"text": "手のひら", "is_correct": false, "explanation": "手の内側の面であり、物を入れて確かめる場所にはならない。"}, {"text": "耳たぶ", "is_correct": false, "explanation": "耳の下の柔らかい部分で、物を入れて確かめる場所ではない。"}, {"text": "足の裏", "is_correct": false, "explanation": "足の底の面で、物を入れる空間ではないので合わない。"}], "explanations": {"口腔": "口の中という場所で、赤ちゃんが物を入れる場所として自然に合う。", "手のひら": "手の内側の面であり、物を入れて確かめる場所にはならない。", "耳たぶ": "耳の下の柔らかい部分で、物を入れて確かめる場所ではない。", "足の裏": "足の底の面で、物を入れる空間ではないので合わない。"}, "sentence_index": 0, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足の指の間を口腔と呼ぶ。", "explanation": "ここは〈指の間〉の意味。〈口腔〉は口の中の空間を指すので、足の指の間には使えない。"}, {"text": "鍋の口腔でスープを煮込んだ。", "explanation": "ここは〈中〉の意味。鍋の内側を指す語で、〈口腔〉は人や動物の口の中なので合わない。"}, {"text": "パソコンの口腔にUSBを挿した。", "explanation": "ここは〈差し込み口〉の意味。〈口腔〉は口の中の空間で、機器の差し込み口を指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "口の中という場所で、食べ物を入れたまま話す文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食べ物を入れる家具で、口に入れたまま話すことはできない。"}, {"text": "鞄", "is_correct": false, "explanation": "物を入れる袋で、食べ物を入れたまま話す文脈には合わない。"}, {"text": "胃", "is_correct": false, "explanation": "食べ物を入れる臓器だが、口を使って話す文脈には合わない。"}], "explanations": {"口腔": "口の中という場所で、食べ物を入れたまま話す文脈に合う。", "冷蔵庫": "食べ物を入れる家具で、口に入れたまま話すことはできない。", "鞄": "物を入れる袋で、食べ物を入れたまま話す文脈には合わない。", "胃": "食べ物を入れる臓器だが、口を使って話す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この瓶の口腔を開けて、中身を注いだ。", "explanation": "ここは〈口〉の意味。瓶の口を指す語で、〈口腔〉は人や動物の口の中を表すので合わない。"}, {"text": "耳の口腔を綿棒で掃除した。", "explanation": "ここは〈耳穴〉の意味。耳の穴を掃除する場面で、〈口腔〉は耳には使わない。"}, {"text": "ペンの口腔からインクが漏れた。", "explanation": "ここは〈ペン先〉の意味。インクを出す先端を指す語で、〈口腔〉は人や動物の口の中を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬を口腔で含んで、ゆっくり溶かした。", "corrected_sentence": "薬を口腔に含んで、ゆっくり溶かした。", "error_description": "「含む」は場所を表す「に」を取る。「口腔で」の「で」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52189, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に、口腔がやさしく洗った。", "corrected_sentence": "寝る前に、口腔をやさしく洗った。", "error_description": "「洗う」の目的語には「を」が要る。「口腔が」は主語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「口腔に入り」の「に」で、入る先を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、「入る」は移動先を取るので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「入る」の移動先には使えない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「口腔が入り」では文が崩れる。"}], "correct_answer": "に", "explanations": {"に": "「口腔に入り」の「に」で、入る先を示す正しい助詞。", "を": "目的語を示す助詞だが、「入る」は移動先を取るので合わない。", "で": "場所や手段を示すが、「入る」の移動先には使えない。", "が": "主語を示す助詞で、「口腔が入り」では文が崩れる。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
