INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口の中の空間。食べ物や飲み物が入る場所。", "primary_collocate": null, "pronunciation": "こうこう", "ipa": "koːkoː", "syllable_count": 4, "sentences": [{"text": "飴を口腔に入れると、甘い味がゆっくり広がる。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "飴[あめ]を口腔[こうこう]に入[い]れると、甘[あま]い味[あじ]がゆっくり広[ひろ]がる。", "sentence_source": "generated"}, {"text": "食べ物はまず口腔に入り、歯でかみ砕かれます。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]はまず口腔[こうこう]に入[はい]り、歯[は]でかみ砕[くだ]かれます。", "sentence_source": "generated"}, {"text": "口腔が乾くと、話しにくくなるので水を飲んだ。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "口腔[こうこう]が乾[かわ]くと、話[はな]しにくくなるので水[みず]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "医者は懐中電灯で患者の口腔を調べた。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "医者[いしゃ]は懐中電灯[かいちゅうでんとう]で患者[かんじゃ]の口腔[こうこう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "熱いスープを飲んで、口腔をやけどしてしまった。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "熱[あつ]いスープを飲[の]んで、口腔[こうこう]をやけどしてしまった。", "sentence_source": "generated"}, {"text": "毎晩の歯みがきは、口腔を清潔に保つために欠かせない。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "毎晩[まいばん]の歯[は]みがきは、口腔[こうこう]を清潔[せいけつ]に保[たも]つために欠[か]かせない。", "sentence_source": "generated"}, {"text": "口腔の広さは人によって少しずつ違う。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "口腔[こうこう]の広[ひろ]さは人[ひと]によって少[すこ]しずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "薬を飲み込む前に、口腔に水をふくんでおくと楽だ。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]み込[こ]む前[まえ]に、口腔[こうこう]に水[みず]をふくんでおくと楽[らく]だ。", "sentence_source": "generated"}, {"text": "辛い料理を食べたら、口腔全体がひりひりした。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "辛[から]い料理[りょうり]を食[た]べたら、口腔[こうこう]全体[ぜんたい]がひりひりした。", "sentence_source": "generated"}, {"text": "歯医者で口腔の写真を撮ってもらった。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]で口腔[こうこう]の写真[しゃしん]を撮[と]ってもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口腔", "label": "基本形"}], "register": "中立（やや硬い書き言葉）", "sense_fingerprint": "口の中の空間そのもの。食べ物や飲み物が入る場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "口の中の空間を指し、飴を入れる場所として自然に合う。"}, {"text": "唾液", "is_correct": false, "explanation": "口の中の液体であり、飴を入れる場所にはならない。"}, {"text": "歯列", "is_correct": false, "explanation": "歯の並びを指し、飴を入れる場所としては合わない。"}, {"text": "喉頭", "is_correct": false, "explanation": "声を出す器官で、飴を入れる場所としては合わない。"}], "explanations": {"口腔": "口の中の空間を指し、飴を入れる場所として自然に合う。", "唾液": "口の中の液体であり、飴を入れる場所にはならない。", "歯列": "歯の並びを指し、飴を入れる場所としては合わない。", "喉頭": "声を出す器官で、飴を入れる場所としては合わない。"}, "sentence_index": 0, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この文章は口腔で書かれていて、読みやすい。", "explanation": "ここは〈口語〉の意味。〈口腔〉は口の中の空間で、文体を表す言葉ではない。"}, {"text": "手術で口腔を開いて、虫垂を取った。", "explanation": "ここは〈腹腔〉の意味。腹の中の空間を開く場面で、口の中を開くとは言わない。"}, {"text": "木の幹に口腔ができて、リスが住んでいる。", "explanation": "ここは〈空洞〉の意味。木の中の空いた部分を指す言葉で、〈口腔〉は体の一部なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "口の中の空間を指し、「口腔の広さ」として人による違いを述べる文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す言葉で、「広さ」とは合わない。"}, {"text": "発汗", "is_correct": false, "explanation": "汗をかく現象で、広さの話題に合わない。"}, {"text": "呼吸数", "is_correct": false, "explanation": "一分間の呼吸の回数で、空間の広さを表せない。"}], "explanations": {"口腔": "口の中の空間を指し、「口腔の広さ」として人による違いを述べる文に合う。", "体重": "体の重さを表す言葉で、「広さ」とは合わない。", "発汗": "汗をかく現象で、広さの話題に合わない。", "呼吸数": "一分間の呼吸の回数で、空間の広さを表せない。"}, "sentence_index": 6, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の質問に、彼女は口腔で答えた。", "explanation": "ここは〈口頭で〉の意味。口で話すことを表す語で、〈口腔〉は体の空間を指すので合わない。"}, {"text": "風邪で口腔が詰まって、息がしにくい。", "explanation": "ここは〈鼻腔〉の意味。鼻の奥の空間が詰まる場面で、〈口腔〉の部位とは違う。"}, {"text": "銀行の口腔にお金を振り込んだ。", "explanation": "ここは〈口座〉の意味。振り込み先の口座を指す語で、〈口腔〉は体の一部なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うがい薬で口腔にすすいだ。", "corrected_sentence": "うがい薬で口腔をすすいだ。", "error_description": "「すすぐ」は目的語に「を」をとる。「口腔に」の「に」が誤りで、「口腔を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52190, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "うがいで口腔が清潔に保った。", "corrected_sentence": "うがいで口腔を清潔に保った。", "error_description": "「保つ」の目的語には「を」が要る。「口腔が」は主語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「たまる」の主語を示す「が」。白い顆粒がたまったという関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「たまる」は自動詞なので目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "直後の「コップの底に」に既に「に」があり、顆粒に続けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すが、「たまる」の主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「たまる」の主語を示す「が」。白い顆粒がたまったという関係を表す。", "を": "「たまる」は自動詞なので目的語の「を」は取れない。", "に": "直後の「コップの底に」に既に「に」があり、顆粒に続けると文が成り立たない。", "で": "「で」は手段や場所を表すが、「たまる」の主語の位置には入らない。"}, "error_tags": {"を": "目的語", "に": "場所の重複", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「集める」の目的語を示す「を」。散らばった顆粒を集めるという関係に合う。"}, {"text": "が", "is_correct": false, "explanation": "「集めた」の主語ではないので、顆粒に「が」を付けると文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を表し、動作の対象を示せないので文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、集める対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「集める」の目的語を示す「を」。散らばった顆粒を集めるという関係に合う。", "が": "「集めた」の主語ではないので、顆粒に「が」を付けると文が成り立たない。", "の": "「の」は連体修飾を表し、動作の対象を示せないので文が崩れる。", "と": "「と」は並列や相手を表すが、集める対象には使えない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さなつぶのこと。", "primary_collocate": null, "pronunciation": "かりゅう", "ipa": "kaɾʲɯː", "syllable_count": 2, "sentences": [{"text": "顕微鏡で見ると、細胞の中に小さな顆粒が見えた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、細胞[さいぼう]の中[なか]に小[ちい]さな顆粒[かりゅう]が見[み]えた。", "sentence_source": "generated"}, {"text": "白い顆粒がコップの底にたまっていた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "白[しろ]い顆粒[かりゅう]がコップの底[そこ]にたまっていた。", "sentence_source": "generated"}, {"text": "塩の顆粒が大きいので、ミルで細かくした。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "塩[しお]の顆粒[かりゅう]が大[おお]きいので、ミルで細[こま]かくした。", "sentence_source": "generated"}, {"text": "袋を振ると、中の顆粒がさらさらと音を立てた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "袋[ふくろ]を振[ふ]ると、中[なか]の顆粒[かりゅう]がさらさらと音[おと]を立[た]てた。", "sentence_source": "generated"}, {"text": "顆粒の大きさをそろえるため、機械でふるい分ける。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "顆粒[かりゅう]の大[おお]きさをそろえるため、機械[きかい]でふるい分[わ]ける。", "sentence_source": "generated"}, {"text": "こぼれた顆粒を掃除機で吸い取った。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "こぼれた顆粒[かりゅう]を掃除機[そうじき]で吸[す]い取[と]った。", "sentence_source": "generated"}, {"text": "雨にぬれて、肥料の顆粒がとけてしまった。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、肥料[ひりょう]の顆粒[かりゅう]がとけてしまった。", "sentence_source": "generated"}, {"text": "机の上に散らばった顆粒を、手のひらに集めた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に散[ち]らばった顆粒[かりゅう]を、手[て]のひらに集[あつ]めた。", "sentence_source": "generated"}, {"text": "この肥料は顆粒がそろっていて、まき方にむらが出にくい。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "この肥料は顆粒[かりゅう]がそろっていて、まき方にむらが出にくい。", "sentence_source": "generated"}, {"text": "顆粒が一つずつ光って見えるほど、近くで写真を撮った。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "顆粒[かりゅう]が一[ひと]つずつ光[ひか]って見[み]えるほど、近[ちか]くで写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顆粒", "label": "基本形"}], "register": "中立（やや硬い書き言葉）", "sense_fingerprint": "一つ一つの小さなつぶ。細胞内の粒や砂・塩のつぶなど", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顆粒", "is_correct": true, "explanation": "顕微鏡で見える細胞内の小さな粒を指す。文脈の「小さな〜が見えた」に合う。"}, {"text": "天井", "is_correct": false, "explanation": "天井は細胞の中にあるものではなく、顕微鏡で見る対象として成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は細胞の観察とは関係がなく、「細胞の中に」の位置にも入らない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は細胞内の構造ではなく、顕微鏡観察の文脈に合わない。"}], "explanations": {"顆粒": "顕微鏡で見える細胞内の小さな粒を指す。文脈の「小さな〜が見えた」に合う。", "天井": "天井は細胞の中にあるものではなく、顕微鏡で見る対象として成り立たない。", "会議": "会議は細胞の観察とは関係がなく、「細胞の中に」の位置にも入らない。", "手紙": "手紙は細胞内の構造ではなく、顕微鏡観察の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "顆粒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ろうそくの顆粒が溶けて、床に垂れた。", "explanation": "ここは〈ろう〉の意味。溶けて垂れるのはろうであり、固い粒の顆粒とは言わない。"}, {"text": "夜空に顆粒が散らばって、きれいだった。", "explanation": "ここは〈星〉の意味。夜空に散らばる光の点は星であり、顆粒とは言わない。"}, {"text": "たき火の顆粒がゆらゆらと立ち上った。", "explanation": "ここは〈煙〉の意味。立ち上るのは煙であり、固い粒の顆粒は立ち上がらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顆粒", "is_correct": true, "explanation": "肥料の粒状の固体を指す。雨にぬれて溶けた状態として文に合う。"}, {"text": "氷", "is_correct": false, "explanation": "氷は肥料の粒ではなく、肥料の顆粒として溶けるという文脈に合わない。"}, {"text": "泥", "is_correct": false, "explanation": "泥は肥料の粒ではなく、溶けるという表現とも合わない。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は肥料の形状を表さず、溶けるという動きとも合わない。"}], "explanations": {"顆粒": "肥料の粒状の固体を指す。雨にぬれて溶けた状態として文に合う。", "氷": "氷は肥料の粒ではなく、肥料の顆粒として溶けるという文脈に合わない。", "泥": "泥は肥料の粒ではなく、溶けるという表現とも合わない。", "雑草": "雑草は肥料の形状を表さず、溶けるという動きとも合わない。"}, "sentence_index": 6, "correct_answer": "顆粒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ダイヤモンドの顆粒が一つずつ光って見えた。", "explanation": "ここは〈宝石〉の意味。光って見える宝石のきらめきは宝石と言い、顆粒とは言わない。"}, {"text": "眠気の顆粒が頭の中をゆっくり流れていった。", "explanation": "ここは〈眠気〉の意味。頭の中を流れるのは眠気であり、顆粒とは言わない。"}, {"text": "夕焼けの顆粒が山の端を染めた。", "explanation": "ここは〈光〉の意味。山の端を染めるのは夕焼けの光であり、顆粒とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の上に顆粒を散らばった。", "corrected_sentence": "机の上に顆粒が散らばった。", "error_description": "「散らばる」は自動詞なので、主語の顆粒には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52191, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "顆粒を濾過して、大きさをそろえた。", "corrected_sentence": "顆粒をふるいにかけて、大きさをそろえた。", "error_description": "顆粒の大きさを揃える方法は「ふるいにかける」が自然。「濾過」は主に液体に使うので、顆粒には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
