INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52192, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "粒状の小さな固体。粉末と塊の中間の状態。", "primary_collocate": null, "pronunciation": "かりゅう", "ipa": "kaɾʲɯː", "syllable_count": 3, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "顆粒", "complexity_tier": "T4", "furigana": "次[つ]いで、ラズベリー等[とう]のジャムを対[つい]になる片割[かたわ]れ、あるいは同一[どういつ]の切片上[せっぺんじょう]に重[かさ]ね合[あ]わせる。\n\n甘味[かんみ]と塩気[しおけ]、滑[なめ]らかさと顆粒感[かりゅうかん]が口腔内[こうこうない]で織[お]りなす対照的[たいしょうてき]なハーモニーは、単[たん]なる栄養補給[えいようほきゅう]の域[いき]を超[こ]え、短時間[たんじかん]での認知機能回復[にんちきのうかいふく]をもたらし、合理性[ごうりせい]と美学[びがく]が融合[ゆうごう]した食[しょく]の営[いとな]みとして完成[かんせい]する。", "sentence_source": "mined"}, {"text": "この薬は顆粒なので、水なしでも飲みやすい。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "この薬[くすり]は顆粒[かりゅう]なので、水[みず]なしでも飲[の]みやすい。", "sentence_source": "generated"}, {"text": "粉末より顆粒のほうが、水に溶かすときに散らばりにくい。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]より顆粒[かりゅう]のほうが、水[みず]に溶[と]かすときに散[ち]らばりにくい。", "sentence_source": "generated"}, {"text": "顆粒のだしをお湯に入れると、すぐに溶けて味噌汁ができる。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "顆粒[かりゅう]のだしをお湯[ゆ]に入[い]れると、すぐに溶[と]けて味噌汁[みそしる]ができる。", "sentence_source": "generated"}, {"text": "肥料は顆粒の状態で売られていて、土にまきやすい。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "肥料[ひりょう]は顆粒[かりゅう]の状態[じょうたい]で売[う]られていて、土[つち]にまきやすい。", "sentence_source": "generated"}, {"text": "砂糖は粉ではなく、顆粒のものを選んだ。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "砂糖[さとう]は粉[こな]ではなく、顆粒[かりゅう]のものを選[えら]んだ。", "sentence_source": "generated"}, {"text": "子どもは粉の薬が苦手で、顆粒の薬をゼリーに混ぜて飲んでいる。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "子[こ]どもは粉[こな]の薬[くすり]が苦手[にがて]で、顆粒[かりゅう]の薬[くすり]をゼリーに混[ま]ぜて飲[の]んでいる。", "sentence_source": "generated"}, {"text": "洗剤が顆粒なので、袋の底に固まらず最後まで使える。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "洗剤[せんざい]が顆粒[かりゅう]なので、袋[ふくろ]の底[そこ]に固[かた]まらず最後[さいご]まで使[つか]える。", "sentence_source": "generated"}, {"text": "湿気で顆粒が固まってしまい、ふるいにかけた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "湿気[しっけ]で顆粒[かりゅう]が固[かた]まってしまい、ふるいにかけた。", "sentence_source": "generated"}, {"text": "缶の中の顆粒を、スプーンで一杯すくって入れた。", "target_word": "顆粒", "complexity_tier": "T3", "furigana": "缶[かん]の中[なか]の顆粒[かりゅう]を、スプーンで一杯[いっぱい]すくって入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顆粒", "label": "基本形"}], "register": "中立（やや硬い書き言葉）", "sense_fingerprint": "粉末と塊の中間の、粒状に加工された固体（薬・調味料など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52192, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顆粒", "is_correct": true, "explanation": "文中の「顆粒感」の語幹。粒状に加工された固体を指し、「滑らかさ」と対比される食感として合う。"}, {"text": "錠剤", "is_correct": false, "explanation": "錠剤は成形された薬の形で、口当たりの対比を表す語としては合わない。"}, {"text": "液体", "is_correct": false, "explanation": "液体は粒状の固体ではないので、「顆粒感」の位置には入らない。"}, {"text": "繊維", "is_correct": false, "explanation": "繊維は糸状の質感を指し、粒状の食感を表す語としては合わない。"}], "explanations": {"顆粒": "文中の「顆粒感」の語幹。粒状に加工された固体を指し、「滑らかさ」と対比される食感として合う。", "錠剤": "錠剤は成形された薬の形で、口当たりの対比を表す語としては合わない。", "液体": "液体は粒状の固体ではないので、「顆粒感」の位置には入らない。", "繊維": "繊維は糸状の質感を指し、粒状の食感を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "顆粒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小麦粉は顆粒状なので、ふるいにかけてから使う。", "explanation": "ここは〈粉末〉の意味。小麦粉のようなさらさらした細かい粉は粉末と言い、粉と塊の中間の粒を指す顆粒とは言わない。"}, {"text": "顆粒を半分に割って、水で流し込んだ。", "explanation": "ここは〈錠剤〉の意味。錠剤は割って飲むが、顆粒は粒そのものなので割るとは言わない。"}, {"text": "海岸の顆粒は細かく、靴の中まで入ってくる。", "explanation": "ここは〈砂〉の意味。砂浜の砂は砂と言い、顆粒とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52192, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顆粒", "is_correct": true, "explanation": "文中の「顆粒の薬」の語。粒状に加工された薬を指し、粉薬を避けて混ぜられる形として合う。"}, {"text": "目薬", "is_correct": false, "explanation": "目薬は点眼する液体の薬で、ゼリーに混ぜて飲む薬とは合わない。"}, {"text": "湿布", "is_correct": false, "explanation": "湿布は皮膚に貼る薬で、飲ませる用途とは合わない。"}, {"text": "軟膏", "is_correct": false, "explanation": "軟膏は塗る薬で、ゼリーに混ぜて飲ませることはできない。"}], "explanations": {"顆粒": "文中の「顆粒の薬」の語。粒状に加工された薬を指し、粉薬を避けて混ぜられる形として合う。", "目薬": "目薬は点眼する液体の薬で、ゼリーに混ぜて飲む薬とは合わない。", "湿布": "湿布は皮膚に貼る薬で、飲ませる用途とは合わない。", "軟膏": "軟膏は塗る薬で、ゼリーに混ぜて飲ませることはできない。"}, "sentence_index": 6, "correct_answer": "顆粒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓の結露が顆粒になって、ガラスを伝って流れた。", "explanation": "ここは〈水滴〉の意味。結露の水玉は液体の水滴であり、固い粒の顆粒とは言わない。"}, {"text": "春は顆粒が飛んで、くしゃみが止まらない。", "explanation": "ここは〈花粉〉の意味。空中に飛んでくしゃみを起こすのは花粉であり、顆粒とは言わない。"}, {"text": "雨で道がぬかるみ、顆粒がはねて靴にくっついた。", "explanation": "ここは〈泥〉の意味。ぬかるみではねるのは泥であり、顆粒とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52192, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "顆粒を水に溶けて、すぐに味噌汁になった。", "corrected_sentence": "顆粒が水に溶けて、すぐに味噌汁になった。", "error_description": "「溶ける」は自動詞なので、主語の顆粒には「が」を使う。「を」は誤り。", "correct_sentence_indices": [1, 2, 3]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52192, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この肥料は顆粒状に、土にまきやすい。", "corrected_sentence": "この肥料は顆粒状で、土にまきやすい。", "error_description": "状態を表すには「で」を使う。「に」にすると、顆粒状であるという述語が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
