INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52193, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "さわったとき、つるつるしていること。", "primary_collocate": null, "pronunciation": "なめらか", "ipa": "nameɾaka", "syllable_count": 4, "sentences": [{"text": "赤ちゃんの肌は、触るとびっくりするほど滑らかだ。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの肌[はだ]は、触[さわ]るとびっくりするほど滑[なめ]らかだ。", "sentence_source": "generated"}, {"text": "磨いた石の表面は、手で触れると滑らかだった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "磨[みが]いた石[いし]の表面[ひょうめん]は、手[て]で触[ふ]れると滑[なめ]らかだった。", "sentence_source": "generated"}, {"text": "絹のスカーフは滑らかで、手からするりと落ちた。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "絹[きぬ]のスカーフは滑[なめ]らかで、手[て]からするりと落[お]ちた。", "sentence_source": "generated"}, {"text": "職人がやすりをかけたので、木の机は滑らかになった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "職人[しょくにん]がやすりをかけたので、木[き]の机[つくえ]は滑[なめ]らかになった。", "sentence_source": "generated"}, {"text": "滑らかな革の財布は、手になじんで使いやすい。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "滑[なめ]らかな革[かわ]の財布[さいふ]は、手[て]になじんで使[つか]いやすい。", "sentence_source": "generated"}, {"text": "氷の表面は滑らかで、ざらつきが全くなかった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "氷[こおり]の表面[ひょうめん]は滑[なめ]らかで、ざらつきが全[まった]くなかった。", "sentence_source": "generated"}, {"text": "陶器のカップは、指でなぞるとつるつるして滑らかだ。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "陶器[とうき]のカップは、指[ゆび]でなぞるとつるつるして滑[なめ]らかだ。", "sentence_source": "generated"}, {"text": "川の石は水に長く削られて、滑らかな形になった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "川[かわ]の石[いし]は水[みず]に長[なが]く削[けず]られて、滑[なめ]らかな形[かたち]になった。", "sentence_source": "generated"}, {"text": "新品のシーツは滑らかで、寝心地がよかった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "新品[しんぴん]のシーツは滑[なめ]らかで、寝心地[ねごこち]がよかった。", "sentence_source": "generated"}, {"text": "手すりがよく拭かれていて、滑らかで気持ちがよかった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "手[て]すりがよく拭[ふ]かれていて、滑[なめ]らかで気持[きも]ちがよかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滑らか", "label": "語幹"}, {"form": "滑らかだ", "label": "終止形"}, {"form": "滑らかな", "label": "連体形"}, {"form": "滑らかに", "label": "連用形"}, {"form": "滑らかで", "label": "中止形"}, {"form": "滑らかだった", "label": "過去形"}], "register": "中立", "sense_fingerprint": "手で触れたとき、でこぼこやざらつきがなくつるつるしているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52193, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滑らか", "is_correct": true, "explanation": "触ったときの肌のつるつるした感触を表す。びっくりするほどという程度表現に合う。"}, {"text": "派手", "is_correct": false, "explanation": "派手は見た目の華やかさを表し、触った感触を表す文には合わない。"}, {"text": "確か", "is_correct": false, "explanation": "確かは確実さを表し、肌の感触を述べる文には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は性格や雰囲気を表し、肌の感触には使えない。"}], "explanations": {"滑らか": "触ったときの肌のつるつるした感触を表す。びっくりするほどという程度表現に合う。", "派手": "派手は見た目の華やかさを表し、触った感触を表す文には合わない。", "確か": "確かは確実さを表し、肌の感触を述べる文には合わない。", "陽気": "陽気は性格や雰囲気を表し、肌の感触には使えない。"}, "sentence_index": 0, "correct_answer": "滑らか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の英語は滑らかで、聞き手が言葉に詰まることがない。", "explanation": "ここは〈流暢〉の意味。話し方のよどみなさは流暢で表し、触った感触の滑らかさとは別の意味なので使えない。"}, {"text": "お湯は滑らかで、手を入れられないほどだった。", "explanation": "ここは〈熱い〉の意味。温度の高さは熱いで表し、滑らかでは言えない。"}, {"text": "会議は滑らかに進んで、予定より早く終わった。", "explanation": "ここは〈円滑〉の意味。物事の進み方の良さは円滑で表し、触った感触の滑らかさとは別の意味なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52193, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滑らか", "is_correct": true, "explanation": "陶器を指でなぞったときのつるつるした感触を表す。「つるつるして」と並ぶ表現に合う。"}, {"text": "賑やか", "is_correct": false, "explanation": "賑やかは人の声や場の活気を表し、陶器の感触には合わない。"}, {"text": "大げさ", "is_correct": false, "explanation": "大げさは態度や表現の誇張を表し、物の感触には使えない。"}, {"text": "饒舌", "is_correct": false, "explanation": "饒舌は話し好きな様子を表し、陶器の手触りには合わない。"}], "explanations": {"滑らか": "陶器を指でなぞったときのつるつるした感触を表す。「つるつるして」と並ぶ表現に合う。", "賑やか": "賑やかは人の声や場の活気を表し、陶器の感触には合わない。", "大げさ": "大げさは態度や表現の誇張を表し、物の感触には使えない。", "饒舌": "饒舌は話し好きな様子を表し、陶器の手触りには合わない。"}, "sentence_index": 6, "correct_answer": "滑らか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の演説は滑らかで、一度も言いよどまなかった。", "explanation": "ここは〈流暢〉の意味。話し方のよどみなさは流暢で表し、触った感触の滑らかさとは別の意味なので使えない。"}, {"text": "夜風は滑らかで、頬がひりひりした。", "explanation": "ここは〈冷たい〉の意味。ひりひりする冷たさを表すのは冷たいであり、滑らかは言わない。"}, {"text": "交渉は滑らかに進み、思ったより早くまとまった。", "explanation": "ここは〈円滑〉の意味。物事の進み方の良さは円滑で表し、触った感触の滑らかさとは別の意味なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52193, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表面は滑らかが、角は少し引っかかる。", "corrected_sentence": "表面は滑らかだが、角は少し引っかかる。", "error_description": "「滑らか」は述語として使うため、「だが」で後ろに続ける必要がある。「が」だけでは述語が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "滑らかだった", "is_correct": true, "explanation": "文中の「滑らかだった」の形。断定の「だ」の過去形で、文末で状態を言い切っている。"}, {"text": "滑らかに", "is_correct": false, "explanation": "連用形で、文末では言い切れない。後ろに動詞が続かないと文が成り立たないので合わない。"}, {"text": "滑らかで", "is_correct": false, "explanation": "中止形で、「で、」と続ける形。ここは文末で言い切るので合わない。"}, {"text": "滑らかな", "is_correct": false, "explanation": "連体形で、後ろに名詞が必要。ここは文末の述語なので合わない。"}], "correct_form": "滑らかだった", "base_form": "滑らか", "form_label": "過去形", "sentence_index": 1, "explanations": {"滑らかだった": "文中の「滑らかだった」の形。断定の「だ」の過去形で、文末で状態を言い切っている。", "滑らかに": "連用形で、文末では言い切れない。後ろに動詞が続かないと文が成り立たないので合わない。", "滑らかで": "中止形で、「で、」と続ける形。ここは文末で言い切るので合わない。", "滑らかな": "連体形で、後ろに名詞が必要。ここは文末の述語なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52193, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペーパーをかけた床は、足で触れると滑らかな感じられる。", "corrected_sentence": "ペーパーをかけた床は、足で触れると滑らかに感じられる。", "error_description": "「感じられる」に続けるには連用形の「に」が必要。「な」は連体形で、後ろに名詞がないと文が続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "滑らかな", "is_correct": true, "explanation": "文中の「滑らかな形」の形。後ろの「形」を修飾する連体形。"}, {"text": "滑らか", "is_correct": false, "explanation": "語幹だけでは後ろの名詞「形」を修飾できず、「滑らかな」の形が必要なので合わない。"}, {"text": "滑らかに", "is_correct": false, "explanation": "連用形で、後ろに「なる」などの動詞や述語が続く形。ここは名詞「形」を修飾する形が必要なので合わない。"}, {"text": "滑らかだ", "is_correct": false, "explanation": "終止形で、名詞「形」に直接続けられない。連体形が必要なので合わない。"}], "correct_form": "滑らかな", "base_form": "滑らか", "form_label": "連体形", "sentence_index": 7, "explanations": {"滑らかな": "文中の「滑らかな形」の形。後ろの「形」を修飾する連体形。", "滑らか": "語幹だけでは後ろの名詞「形」を修飾できず、「滑らかな」の形が必要なので合わない。", "滑らかに": "連用形で、後ろに「なる」などの動詞や述語が続く形。ここは名詞「形」を修飾する形が必要なので合わない。", "滑らかだ": "終止形で、名詞「形」に直接続けられない。連体形が必要なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
