INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52194, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "表面がなめらかで、ざらつきがないさま。また、口当たりがなめらかなこと。", "primary_collocate": null, "pronunciation": "なめらか", "ipa": "nameɾaka", "syllable_count": 4, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "滑らか", "complexity_tier": "T4", "furigana": "次[つ]いで、ラズベリー等[とう]のジャムを対[つい]になる片割[かたわ]れ、あるいは同一[どういつ]の切片上[せっぺんじょう]に重[かさ]ね合[あ]わせる。\n\n甘味[かんみ]と塩気[しおけ]、滑[なめ]らかさと顆粒感[かりゅうかん]が口腔内[こうこうない]で織[お]りなす対照的[たいしょうてき]なハーモニーは、単[たん]なる栄養補給[えいようほきゅう]の域[いき]を超[こ]え、短時間[たんじかん]での認知機能回復[にんちきのうかいふく]をもたらし、合理性[ごうりせい]と美学[びがく]が融合[ゆうごう]した食[しょく]の営[いとな]みとして完成[かんせい]する。", "sentence_source": "mined"}, {"text": "このプリンはとても滑らかで、口の中でとろけた。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "このプリンはとても滑[なめ]らかで、口[くち]の中[なか]でとろけた。", "sentence_source": "generated"}, {"text": "滑らかな舌ざわりを出すために、豆乳を何度もこした。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "滑[なめ]らかな舌[した]ざわりを出[だ]すために、豆乳[とうにゅう]を何度[なんど]もこした。", "sentence_source": "generated"}, {"text": "ポタージュを裏ごしして、滑らかに仕上げた。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "ポタージュを裏[うら]ごしして、滑[なめ]らかに仕上[しあ]げた。", "sentence_source": "generated"}, {"text": "このワインは滑らかな口当たりで、初心者にも飲みやすい。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "このワインは滑[なめ]らかな口当[くちあ]たりで、初心者[しょしんしゃ]にも飲[の]みやすい。", "sentence_source": "generated"}, {"text": "ダマが残っていて、ソースが滑らかにならなかった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "ダマが残[のこ]っていて、ソースが滑[なめ]らかにならなかった。", "sentence_source": "generated"}, {"text": "生クリームを加えると、スープがぐっと滑らかになる。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "生[なま]クリームを加[くわ]えると、スープがぐっと滑[なめ]らかになる。", "sentence_source": "generated"}, {"text": "滑らかなチョコレートは、口の中ですぐ溶ける。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "滑[なめ]らかなチョコレートは、口[くち]の中[なか]ですぐ溶[と]ける。", "sentence_source": "generated"}, {"text": "ミキサーで十分に混ぜたので、滑らかな食感になった。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "ミキサーで十分[じゅうぶん]に混[ま]ぜたので、滑[なめ]らかな食感[しょっかん]になった。", "sentence_source": "generated"}, {"text": "このごま豆腐は滑らかで、そのまま食べるのがおいしい。", "target_word": "滑らか", "complexity_tier": "T3", "furigana": "このごま豆腐[どうふ]は滑[なめ]らかで、そのまま食[た]べるのがおいしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滑らか", "label": "語幹"}, {"form": "滑らかだ", "label": "終止形"}, {"form": "滑らかな", "label": "連体形"}, {"form": "滑らかに", "label": "連用形"}, {"form": "滑らかで", "label": "中止形"}], "register": "中立", "sense_fingerprint": "ざらつきや固まりがなく、口当たり・舌ざわりが滑らかなさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: 6 words above tier T4 (max 5): 片割れ (Zipf 2.88), 切片 (Zipf 1.86), 重ね合わ (Zipf 2.98), 塩気 (Zipf 2.57), 顆粒 (Zipf 2.99), 織りなす (Zipf 2.63)','sentence 2 above tier T4: contains vocabulary far above tier T4: 舌ざわり (Zipf 1.2)']::text[], 'a151bbd1-e63e-46f9-b576-fa318ae4b591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52194, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滑らか", "is_correct": true, "explanation": "文中の「滑らかさ」の語幹。ざらつきのない口当たりを指し、顆粒感と対比される。"}, {"text": "静か", "is_correct": false, "explanation": "静かさは音や雰囲気を表し、口当たりや食感の対比には合わない。"}, {"text": "元気", "is_correct": false, "explanation": "元気さは人の活力を表し、食感の話題には合わない。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静さは心の落ち着きを表し、食感の対比としては成り立たない。"}], "explanations": {"滑らか": "文中の「滑らかさ」の語幹。ざらつきのない口当たりを指し、顆粒感と対比される。", "静か": "静かさは音や雰囲気を表し、口当たりや食感の対比には合わない。", "元気": "元気さは人の活力を表し、食感の話題には合わない。", "冷静": "冷静さは心の落ち着きを表し、食感の対比としては成り立たない。"}, "sentence_index": 0, "correct_answer": "滑らか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交渉は滑らかに進み、予定より早くまとまった。", "explanation": "ここは〈円滑〉の意味。物事の進み方の良さは円滑で表し、表面や口当たりの滑らかさとは別の意味なので使えない。"}, {"text": "この湯は滑らかで、足を入れるのにちょうどいい。", "explanation": "ここは〈湯加減〉の意味。湯の温かさは湯加減で表し、滑らかは触ったときの表面や口当たりの感触に使うので温度には合わない。"}, {"text": "彼の演奏は滑らかで、指が止まることがない。", "explanation": "ここは〈流暢〉の意味。演奏のよどみなさは流暢で表し、表面や口当たりの滑らかさとは別の意味なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52194, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滑らか", "is_correct": true, "explanation": "スープの口当たりがぐっと変わることを表す。生クリームを加えた結果として合う。"}, {"text": "派手", "is_correct": false, "explanation": "派手は見た目の華やかさを表し、スープの食感の変化には合わない。"}, {"text": "確か", "is_correct": false, "explanation": "確かは確実さを表し、食感の変化を述べる文には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は人の性格や雰囲気を表し、スープの状態には合わない。"}], "explanations": {"滑らか": "スープの口当たりがぐっと変わることを表す。生クリームを加えた結果として合う。", "派手": "派手は見た目の華やかさを表し、スープの食感の変化には合わない。", "確か": "確かは確実さを表し、食感の変化を述べる文には合わない。", "陽気": "陽気は人の性格や雰囲気を表し、スープの状態には合わない。"}, "sentence_index": 6, "correct_answer": "滑らか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は滑らかで、ずっと騒がしい。", "explanation": "ここは〈騒がしい〉の意味。音の大きさは騒がしいで表し、滑らかは触った感触や口当たりの話なので合わない。"}, {"text": "会議は滑らかに進み、思ったより早く結論が出た。", "explanation": "ここは〈円滑〉の意味。物事の進み方の良さは円滑で表し、口当たりの滑らかさとは別の意味なので使えない。"}, {"text": "彼女の話は滑らかで、質問にすぐ答えが返ってくる。", "explanation": "ここは〈流暢〉の意味。話し方のよどみなさは流暢で表し、食感の滑らかさとは別の意味なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52194, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクリームは滑らかな、口当たりがよい。", "corrected_sentence": "このクリームは滑らかで、口当たりがよい。", "error_description": "「滑らか」を述語として続けるには中止形の「で」が必要。「な」は連体形で、後ろに名詞がないと文が続かない。", "correct_sentence_indices": [1, 2, 4]}, "level_4": {"options": [{"text": "滑らかで", "is_correct": true, "explanation": "文中の「滑らかで」の形。形状詞に「で」をつけて、後ろの「口の中でとろけた」へ続けている（中止形）。"}, {"text": "滑らかだ", "is_correct": false, "explanation": "終止形で文を言い切る形。ここは「で、」と続けて後ろに文が続くので合わない。"}, {"text": "滑らかな", "is_correct": false, "explanation": "連体形で、後ろに名詞が必要。ここは名詞が続かず「で、」と続くので合わない。"}, {"text": "滑らかさ", "is_correct": false, "explanation": "名詞形で、形容の述語として働かないので文が成り立たない。"}], "correct_form": "滑らかで", "base_form": "滑らか", "form_label": "中止形", "sentence_index": 1, "explanations": {"滑らかで": "文中の「滑らかで」の形。形状詞に「で」をつけて、後ろの「口の中でとろけた」へ続けている（中止形）。", "滑らかだ": "終止形で文を言い切る形。ここは「で、」と続けて後ろに文が続くので合わない。", "滑らかな": "連体形で、後ろに名詞が必要。ここは名詞が続かず「で、」と続くので合わない。", "滑らかさ": "名詞形で、形容の述語として働かないので文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52194, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生地を裏ごししたので、口当たりが滑らかくなった。", "corrected_sentence": "生地を裏ごししたので、口当たりが滑らかになった。", "error_description": "形状詞の「滑らか」を「〜になる」に続けるには連用形の「に」が必要。「く」は形容詞の活用で、形状詞には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "滑らかな", "is_correct": true, "explanation": "文中の「滑らかな」の形。後ろの「チョコレート」を修飾する連体形。"}, {"text": "滑らか", "is_correct": false, "explanation": "語幹だけでは後ろの名詞「チョコレート」を修飾できず、「滑らかな」の形が必要なので合わない。"}, {"text": "滑らかだった", "is_correct": false, "explanation": "過去の状態を言う形。ここは今の一般的な性質（すぐ溶ける）を述べているので時制が合わない。"}, {"text": "滑らかだ", "is_correct": false, "explanation": "終止形で、「チョコレート」に直接続けられない。連体形が必要なので合わない。"}], "correct_form": "滑らかな", "base_form": "滑らか", "form_label": "連体形", "sentence_index": 7, "explanations": {"滑らかな": "文中の「滑らかな」の形。後ろの「チョコレート」を修飾する連体形。", "滑らか": "語幹だけでは後ろの名詞「チョコレート」を修飾できず、「滑らかな」の形が必要なので合わない。", "滑らかだった": "過去の状態を言う形。ここは今の一般的な性質（すぐ溶ける）を述べているので時制が合わない。", "滑らかだ": "終止形で、「チョコレート」に直接続けられない。連体形が必要なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f179698-3c33-4e18-a36a-27c1fc1f98c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ハーモニーを聞いて」で、聞く対象を示す。ここでは正しい。"}, {"text": "に", "is_correct": false, "explanation": "帰着や相手を示す。「ハーモニーに聞いて」では、聞く対象として成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「ハーモニーで聞いて」では、聞く対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "主格。「ハーモニーが聞いて」では、聞く主体が人でないため文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「ハーモニーを聞いて」で、聞く対象を示す。ここでは正しい。", "に": "帰着や相手を示す。「ハーモニーに聞いて」では、聞く対象として成立しない。", "で": "手段や場所を示す。「ハーモニーで聞いて」では、聞く対象を表せない。", "が": "主格。「ハーモニーが聞いて」では、聞く主体が人でないため文が成立しない。"}, "error_tags": {"に": "帰着・相手の格", "で": "手段・場所の格", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「ハーモニーと響かせた」では、響かせる対象として成立しない。"}, {"text": "を", "is_correct": true, "explanation": "「きれいなハーモニーを響かせた」で、響かせる対象を示す。ここでは正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「ハーモニーへ響かせた」では、響かせる対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す。「ハーモニーの響かせた」では、響かせる対象として文が成立しない。"}], "correct_answer": "を", "explanations": {"と": "並列や相手を示す。「ハーモニーと響かせた」では、響かせる対象として成立しない。", "を": "「きれいなハーモニーを響かせた」で、響かせる対象を示す。ここでは正しい。", "へ": "方向を示す。「ハーモニーへ響かせた」では、響かせる対象を表せない。", "の": "所属や修飾を示す。「ハーモニーの響かせた」では、響かせる対象として文が成立しない。"}, "error_tags": {"と": "並列・相手の格", "へ": "方向の格", "の": "修飾・所属の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが、うまく合わさって、きれいな感じになること。", "primary_collocate": null, "pronunciation": "はーもにー", "ipa": "haːmoniː", "syllable_count": 5, "sentences": [{"text": "三人の歌声がぴったり合って、きれいなハーモニーになった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "三人[さんにん]の歌声[うたごえ]がぴったり合[あ]って、きれいなハーモニーになった。", "sentence_source": "generated"}, {"text": "合唱のハーモニーを聞いて、思わず拍手をした。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "合唱[がっしょう]のハーモニーを聞[き]いて、思[おも]わず拍手[はくしゅ]をした。", "sentence_source": "generated"}, {"text": "ピアノとバイオリンのハーモニーが心地よかった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "ピアノとバイオリンのハーモニーが心地[ここち]よかった。", "sentence_source": "generated"}, {"text": "姉と妹は声が似ているので、ハーモニーがとてもきれいだ。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "姉[あね]と妹[いもうと]は声[こえ]が似[に]ているので、ハーモニーがとてもきれいだ。", "sentence_source": "generated"}, {"text": "毎日練習を重ねて、ハーモニーが上手に作れるようになった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]を重[かさ]ねて、ハーモニーが上手[じょうず]に作[つく]れるようになった。", "sentence_source": "generated"}, {"text": "高い声と低い声のハーモニーで、歌が深みのある響きになった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "高[たか]い声[こえ]と低[ひく]い声[こえ]のハーモニーで、歌[うた]が深[ふか]みのある響[ひび]きになった。", "sentence_source": "generated"}, {"text": "楽器の音が合わないと、ハーモニーが崩れてしまう。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "楽器[がっき]の音[おと]が合[あ]わないと、ハーモニーが崩[くず]れてしまう。", "sentence_source": "generated"}, {"text": "学園祭で、クラス全員がきれいなハーモニーを響かせた。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "学園祭[がくえんさい]で、クラス全員[ぜんいん]がきれいなハーモニーを響[ひび]かせた。", "sentence_source": "generated"}, {"text": "この曲は、二つの声が重なるハーモニーが一番の聞きどころだ。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "この曲[きょく]は、二[ふた]つの声[こえ]が重[かさ]なるハーモニーが一番[いちばん]の聞[き]きどころだ。", "sentence_source": "generated"}, {"text": "夜の教会に、オルガンとコーラスのハーモニーが流れていた。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "夜[よる]の教会[きょうかい]に、オルガンとコーラスのハーモニーが流[なが]れていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ハーモニー", "label": "基本形"}], "register": "標準", "sense_fingerprint": "声や楽器の音がうまく重なってできるきれいな響き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ハーモニー", "is_correct": true, "explanation": "「きれいなハーモニーになった」で、歌声が合わさって生まれる美しい響きを指す。ここでは正しい。"}, {"text": "寝息", "is_correct": false, "explanation": "名詞だが、「きれいな寝息になった」とは言わず、歌声の響きを表せない。"}, {"text": "手品", "is_correct": false, "explanation": "名詞だが、「きれいな手品になった」は文の意味に合わず、この位置には入らない。"}, {"text": "火事", "is_correct": false, "explanation": "名詞だが、「きれいな火事になった」は成立せず、歌声の状態を表せない。"}], "explanations": {"ハーモニー": "「きれいなハーモニーになった」で、歌声が合わさって生まれる美しい響きを指す。ここでは正しい。", "寝息": "名詞だが、「きれいな寝息になった」とは言わず、歌声の響きを表せない。", "手品": "名詞だが、「きれいな手品になった」は文の意味に合わず、この位置には入らない。", "火事": "名詞だが、「きれいな火事になった」は成立せず、歌声の状態を表せない。"}, "sentence_index": 0, "correct_answer": "ハーモニー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋はハーモニーの明かりが暗くて、本が読みにくい。", "explanation": "ここは〈明るさ〉の意味。ハーモニーは響きの調和を指し、光の明るさを表すためには使わない。"}, {"text": "この歌手は、ハーモニーの値段が高くて、チケットが買えない。", "explanation": "ここは〈価格〉の意味。ハーモニーは響きの調和を指し、値段を表すために使うことはできない。"}, {"text": "このダンスはハーモニーが速くて、踊りにくい。", "explanation": "ここは〈リズム〉の意味。ハーモニーは和音の響きを指し、拍の速さや規則を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ハーモニー", "is_correct": true, "explanation": "「ハーモニーが崩れてしまう」で、楽器の音が合わないことで失われる響きの調和を指す。ここでは正しい。"}, {"text": "体重", "is_correct": false, "explanation": "名詞だが、「体重が崩れる」は音の響きの状態を表せず、文の意味に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "名詞だが、「年齢が崩れる」とは言わず、この位置には入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "名詞だが、「寿命が崩れる」は成立せず、楽器の音の状態を表せない。"}], "explanations": {"ハーモニー": "「ハーモニーが崩れてしまう」で、楽器の音が合わないことで失われる響きの調和を指す。ここでは正しい。", "体重": "名詞だが、「体重が崩れる」は音の響きの状態を表せず、文の意味に合わない。", "年齢": "名詞だが、「年齢が崩れる」とは言わず、この位置には入らない。", "寿命": "名詞だが、「寿命が崩れる」は成立せず、楽器の音の状態を表せない。"}, "sentence_index": 6, "correct_answer": "ハーモニー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の教会で、ハーモニーの荷物を忘れて帰った。", "explanation": "ここは〈持ち物〉の意味。ハーモニーは響きの調和を指し、荷物として持ち運ぶものではない。"}, {"text": "迷惑メールのハーモニーが大量に届いて、受信箱がいっぱいになった。", "explanation": "ここは〈迷惑メール〉の意味。ハーモニーは調和した響きを指し、大量の不要なメールを表すことはできない。"}, {"text": "夜の教会で、オルガンとハーモニーを吹いた。", "explanation": "ここは〈ハーモニカ〉の意味。ハーモニーは響きの調和を指し、吹いて鳴らす楽器の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人の歌声がハーモニーをなった。", "corrected_sentence": "三人の歌声がハーモニーになった。", "error_description": "「〜になる」は「に」を取る。「を」を使うと誤りになる。正しくは「ハーモニーになった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52195, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ピアノの音と歌声がハーモニーで奏でた。", "corrected_sentence": "ピアノの音と歌声がハーモニーを奏でた。", "error_description": "「奏でる」は目的語に「を」を取る。「で」を使うと誤りになる。正しくは「ハーモニーを奏でた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "目的語を示す。「ハーモニーを美しく」とすると、「美しい」の主語が立たず文が成立しない。"}, {"text": "が", "is_correct": true, "explanation": "「ハーモニーが美しい」で、ハーモニーが美しいと評価される主語を示す。ここでは正しい。"}, {"text": "に", "is_correct": false, "explanation": "位置や対象を示す。「ハーモニーに美しく」では、「美しい」の主語として成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「ハーモニーで美しく」では、主語を示す役割を果たせない。"}], "correct_answer": "が", "explanations": {"を": "目的語を示す。「ハーモニーを美しく」とすると、「美しい」の主語が立たず文が成立しない。", "が": "「ハーモニーが美しい」で、ハーモニーが美しいと評価される主語を示す。ここでは正しい。", "に": "位置や対象を示す。「ハーモニーに美しく」では、「美しい」の主語として成立しない。", "で": "手段や場所を示す。「ハーモニーで美しく」では、主語を示す役割を果たせない。"}, "error_tags": {"を": "目的語の格", "に": "位置・対象の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素が調和して、心地よい統一感や美しさを生み出すこと。", "primary_collocate": null, "pronunciation": "はーもにー", "ipa": "haːmoniː", "syllable_count": 3, "sentences": [{"text": "甘味と塩気が口の中で一つになり、対照的なハーモニーが生まれる。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "甘味[かんみ]と塩気[しおけ]が口[くち]の中[なか]で一[ひと]つになり、対照的[たいしょうてき]なハーモニーが生[う]まれる。", "sentence_source": "generated"}, {"text": "色と形のハーモニーが美しく、この部屋は見ていて落ち着く。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "色[いろ]と形[かたち]のハーモニーが美[うつく]しく、この部屋[へや]は見[み]ていて落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "新しいビルは古い町並みとハーモニーを生んでいて、景色を壊していない。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "新[あたら]しいビルは古[ふる]い町並[まちな]みとハーモニーを生[う]んでいて、景色[けしき]を壊[こわ]していない。", "sentence_source": "generated"}, {"text": "辛さと酸味が作るハーモニーが、このスープの一番の魅力だ。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "辛[から]さと酸味[さんみ]が作[つく]るハーモニーが、このスープの一番[いちばん]の魅力[みりょく]だ。", "sentence_source": "generated"}, {"text": "選手それぞれの個性が重なって、チームに見事なハーモニーが生まれた。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "選手[せんしゅ]それぞれの個性[こせい]が重[かさ]なって、チームに見事[みごと]なハーモニーが生[う]まれた。", "sentence_source": "generated"}, {"text": "いろいろな食材の香りがハーモニーを奏で、一口食べただけで笑顔になった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "いろいろな食材[しょくざい]の香[かお]りがハーモニーを奏[かな]で、一口[ひとくち]食[た]べただけで笑顔[えがお]になった。", "sentence_source": "generated"}, {"text": "木の家具と白い壁がハーモニーを作り出し、温かい雰囲気の店になった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "木[き]の家具[かぐ]と白[しろ]い壁[かべ]がハーモニーを作[つく]り出[だ]し、温[あたた]かい雰囲気[ふんいき]の店[みせ]になった。", "sentence_source": "generated"}, {"text": "意見がばらばらで、会議にはハーモニーがまるでなかった。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "意見[いけん]がばらばらで、会議[かいぎ]にはハーモニーがまるでなかった。", "sentence_source": "generated"}, {"text": "三種類のチーズが口の中で一つのハーモニーになる。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "三種類[さんしゅるい]のチーズが口[くち]の中[なか]で一[ひと]つのハーモニーになる。", "sentence_source": "generated"}, {"text": "自然と建物のハーモニーを大切にして、この公園は設計された。", "target_word": "ハーモニー", "complexity_tier": "T3", "furigana": "自然[しぜん]と建物[たてもの]のハーモニーを大切[たいせつ]にして、この公園[こうえん]は設計[せっけい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ハーモニー", "label": "基本形"}], "register": "標準", "sense_fingerprint": "色・味・人・形など複数の要素が調和して生まれる統一感や美しさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ハーモニー", "is_correct": true, "explanation": "「対照的なハーモニー」で、異なる味や食感が調和して生まれる統一感を指す。ここでは正しい。"}, {"text": "美しく", "is_correct": false, "explanation": "形容詞の連用形。「対照的な美しく」と名詞を修飾できないため、空欄には入らない。"}, {"text": "散らばって", "is_correct": false, "explanation": "動詞の連用形。「対照的な散らばって」とは続かないので、名詞の位置に合わない。"}, {"text": "溶けて", "is_correct": false, "explanation": "動詞の連用形。「対照的な溶けて」とは続かず、「ハーモニー」の位置に入らない。"}], "explanations": {"ハーモニー": "「対照的なハーモニー」で、異なる味や食感が調和して生まれる統一感を指す。ここでは正しい。", "美しく": "形容詞の連用形。「対照的な美しく」と名詞を修飾できないため、空欄には入らない。", "散らばって": "動詞の連用形。「対照的な散らばって」とは続かないので、名詞の位置に合わない。", "溶けて": "動詞の連用形。「対照的な溶けて」とは続かず、「ハーモニー」の位置に入らない。"}, "sentence_index": 0, "correct_answer": "ハーモニー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このメニューは、ハーモニーの値段が高くて、学生には手が出ない。", "explanation": "ここは〈価格〉の意味。ハーモニーは要素が調和する統一感を指し、値段を表すために使うことはできない。"}, {"text": "二つの党のハーモニーは激しく、議会は毎日もめている。", "explanation": "ここは〈対立〉の意味。ハーモニーは要素が調和することなので、争いの激しさを表す語としては使えない。"}, {"text": "この店は、ハーモニーが豊富で、どれを頼んでも満足する。", "explanation": "ここは〈種類〉の意味。ハーモニーは要素が合わさった統一感を指し、数の多さを表すために使うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ハーモニー", "is_correct": true, "explanation": "「ハーモニーを作り出し」で、家具と壁が調和して生まれる統一感を指す。ここでは正しい。"}, {"text": "体重", "is_correct": false, "explanation": "名詞だが、「体重を作り出す」とは言わないため、空欄に入らない。"}, {"text": "年齢", "is_correct": false, "explanation": "名詞だが、「年齢を作り出す」は成立しないため、この位置には入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "名詞だが、「寿命を作り出す」とは言わないので、文の意味に合わない。"}], "explanations": {"ハーモニー": "「ハーモニーを作り出し」で、家具と壁が調和して生まれる統一感を指す。ここでは正しい。", "体重": "名詞だが、「体重を作り出す」とは言わないため、空欄に入らない。", "年齢": "名詞だが、「年齢を作り出す」は成立しないため、この位置には入らない。", "寿命": "名詞だが、「寿命を作り出す」とは言わないので、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "ハーモニー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の話はハーモニーが少なくて、聞き取りにくい。", "explanation": "ここは〈語数〉の意味。ハーモニーは要素の調和を指し、言葉の数を表すために使うことはできない。"}, {"text": "このバスは、ハーモニーが遅いので乗り遅れた。", "explanation": "ここは〈速さ〉の意味。ハーモニーは調和した統一感を指し、乗り物の速度を表すことはできない。"}, {"text": "彼女は、ハーモニーを立てて家計を管理している。", "explanation": "ここは〈計画〉の意味。ハーモニーは要素が調和する統一感を指し、計画を立てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は色と形のハーモニーを美しい。", "corrected_sentence": "この部屋は色と形のハーモニーが美しい。", "error_description": "「美しい」が主語を取るときは「が」を使う。「を」を使うと、ハーモニーが目的語になってしまい誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52196, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の内装は木と白のハーモニーで満ちている。", "corrected_sentence": "店の内装は木と白のハーモニーに満ちている。", "error_description": "「満ちる」は「に」を取る。「で」を使うと誤りになる。正しくは「ハーモニーに満ちている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
