INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52197, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "おなかがすいたときに、体にエネルギーを入れること。", "primary_collocate": null, "pronunciation": "ほきゅう", "ipa": "hokʲɯː", "syllable_count": 3, "sentences": [{"text": "おなかがすいたので、おにぎりでエネルギーを補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "おなかがすいたので、おにぎりでエネルギーを補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "試合の前に、バナナを食べてすばやくエネルギーを補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、バナナを食[た]べてすばやくエネルギーを補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "練習の合間に、チョコレートで補給するのが私の習慣だ。", "target_word": "補給", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の合間[あいま]に、チョコレートで補給[ほきゅう]するのが私[わたし]の習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "長い会議で空腹になり、休憩中にクッキーで補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "長[なが]い会議[かいぎ]で空腹[くうふく]になり、休憩中[きゅうけいちゅう]にクッキーで補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "朝から何も食べていなくて、昼前にはもう補給が必要だった。", "target_word": "補給", "complexity_tier": "T3", "furigana": "朝[あさ]から何[なに]も食[た]べていなくて、昼前[ひるまえ]にはもう補給[ほきゅう]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "マラソンの途中、おなかがすいてきたのでゼリーを飲んで補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "マラソンの途中[とちゅう]、おなかがすいてきたのでゼリーを飲[の]んで補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "兄は部活のあと、おやつで補給してから勉強を始める。", "target_word": "補給", "complexity_tier": "T3", "furigana": "兄[あに]は部活[ぶかつ]のあと、おやつで補給[ほきゅう]してから勉強[べんきょう]を始[はじ]める。", "sentence_source": "generated"}, {"text": "腹ぺこで倒れそうだったので、パンを買って補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "腹[はら]ぺこで倒[たお]れそうだったので、パンを買[か]って補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "遠足の山道では、休むたびにあめを食べて補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "遠足[えんそく]の山道[やまみち]では、休[やす]むたびにあめを食[た]べて補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "夜勤の途中でおなかがすいたら、軽食で補給するようにしている。", "target_word": "補給", "complexity_tier": "T3", "furigana": "夜勤[やきん]の途中[とちゅう]でおなかがすいたら、軽食[けいしょく]で補給[ほきゅう]するようにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "補給", "label": "基本形"}, {"form": "補給する", "label": "動詞形"}, {"form": "補給した", "label": "過去形"}, {"form": "補給して", "label": "て形"}], "register": "話し言葉寄り（日常）", "sense_fingerprint": "空腹のときに、食べ物で体にエネルギーを入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52197, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "補給", "is_correct": true, "explanation": "正解。「エネルギーを補給した」で、空腹時に食べ物で体に力を入れる意味に合う。"}, {"text": "注文", "is_correct": false, "explanation": "「エネルギーを注文した」は意味が通らない。注文は料理などを頼む意味で、体に力を入れる文脈には合わない。"}, {"text": "点検", "is_correct": false, "explanation": "「エネルギーを点検した」は不自然。点検は機械や設備を調べる意味で、ここでは使わない。"}, {"text": "整理", "is_correct": false, "explanation": "「エネルギーを整理した」は不自然。整理は物を片付ける意味で、体にエネルギーを入れる文には合わない。"}], "explanations": {"補給": "正解。「エネルギーを補給した」で、空腹時に食べ物で体に力を入れる意味に合う。", "注文": "「エネルギーを注文した」は意味が通らない。注文は料理などを頼む意味で、体に力を入れる文脈には合わない。", "点検": "「エネルギーを点検した」は不自然。点検は機械や設備を調べる意味で、ここでは使わない。", "整理": "「エネルギーを整理した」は不自然。整理は物を片付ける意味で、体にエネルギーを入れる文には合わない。"}, "sentence_index": 0, "correct_answer": "補給"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の損害を保険会社が補給してくれて、被害者は安心した。", "explanation": "ここは〈補償〉の意味。失った分を金銭で埋め合わせる意味で、足りないものを足す〈補給〉とは合わない。"}, {"text": "台風で壊れた屋根を業者が補給した。", "explanation": "ここは〈補修〉の意味。壊れた部分を直す意味で、足りないものを足す〈補給〉とは違う。"}, {"text": "古い橋を鉄板で補給した。", "explanation": "ここは〈補強〉の意味。弱い部分を固めて強くする意味で、足りないものを足す〈補給〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52197, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "補給", "is_correct": true, "explanation": "正解。「おやつで補給してから勉強を始める」で、食べ物で体にエネルギーを入れる意味に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「おやつで掃除してから」は意味が通らない。掃除は部屋などをきれいにする意味。"}, {"text": "検査", "is_correct": false, "explanation": "「おやつで検査してから」は不自然。検査は品質や健康を調べる意味で、ここでは使わない。"}, {"text": "整頓", "is_correct": false, "explanation": "「おやつで整頓してから」は不自然。整頓は物を整える意味で、食べ物の文脈には合わない。"}], "explanations": {"補給": "正解。「おやつで補給してから勉強を始める」で、食べ物で体にエネルギーを入れる意味に合う。", "掃除": "「おやつで掃除してから」は意味が通らない。掃除は部屋などをきれいにする意味。", "検査": "「おやつで検査してから」は不自然。検査は品質や健康を調べる意味で、ここでは使わない。", "整頓": "「おやつで整頓してから」は不自然。整頓は物を整える意味で、食べ物の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "補給"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "写真の暗い部分の明るさを補給した。", "explanation": "ここは〈補正〉の意味。ずれや不足を直して整える意味で、体にエネルギーを入れる〈補給〉とは違う。"}, {"text": "説明の最後に補給を加えた。", "explanation": "ここは〈補足〉の意味。足りない情報を付け加える意味で、体にエネルギーを入れる〈補給〉とは違う。"}, {"text": "副部長は社長を補給している。", "explanation": "ここは〈補佐〉の意味。上の人を助ける意味で、体にエネルギーを入れる〈補給〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52197, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "練習のあと、ゼリーでエネルギーに補給した。", "corrected_sentence": "練習のあと、ゼリーでエネルギーを補給した。", "error_description": "「エネルギーに補給した」は誤り。「補給する」は「エネルギーを補給する」と「を」で補給の対象を示すので、正しくは「を」。「に」にすると意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52197, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜勤の前に軽食で補給んで、仮眠をとった。", "corrected_sentence": "夜勤の前に軽食で補給して、仮眠をとった。", "error_description": "「補給んで」は誤り。「する」のて形は「して」で、「〜んで」は「飲んで」などの形。正しくは「補給して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
