INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52198, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体内に不足した栄養やエネルギーを補い、与えること。", "primary_collocate": null, "pronunciation": "ほきゅう", "ipa": "hokʲɯː", "syllable_count": 3, "sentences": [{"text": "体調を保つため、食事で不足したビタミンを補給する。", "target_word": "補給", "complexity_tier": "T3", "furigana": "体調[たいちょう]を保[たも]つため、食事[しょくじ]で不足[ふそく]したビタミンを補給[ほきゅう]する。", "sentence_source": "generated"}, {"text": "運動のあとは、汗で失われた水分を補給することが大切だ。", "target_word": "補給", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、汗[あせ]で失[うしな]われた水分[すいぶん]を補給[ほきゅう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "野菜が少ない生活だと、ビタミンの補給が不十分になる。", "target_word": "補給", "complexity_tier": "T3", "furigana": "野菜[やさい]が少[すく]ない生活[せいかつ]だと、ビタミンの補給[ほきゅう]が不十分[ふじゅうぶん]になる。", "sentence_source": "generated"}, {"text": "病気で食欲がない患者に、点滴で栄養を補給した。", "target_word": "補給", "complexity_tier": "T3", "furigana": "病気[びょうき]で食欲[しょくよく]がない患者[かんじゃ]に、点滴[てんてき]で栄養[えいよう]を補給[ほきゅう]した。", "sentence_source": "generated"}, {"text": "汗をたくさんかいたので、塩分を補給するために塩あめをなめた。", "target_word": "補給", "complexity_tier": "T3", "furigana": "汗[あせ]をたくさんかいたので、塩分[えんぶん]を補給[ほきゅう]するために塩[しお]あめをなめた。", "sentence_source": "generated"}, {"text": "登山中は、こまめに水分を補給しないと体調を崩す。", "target_word": "補給", "complexity_tier": "T3", "furigana": "登山中[とざんちゅう]は、こまめに水分[すいぶん]を補給[ほきゅう]しないと体調[たいちょう]を崩[くず]す。", "sentence_source": "generated"}, {"text": "不足しがちな鉄分の補給には、レバーやほうれん草がよいとされている。", "target_word": "補給", "complexity_tier": "T3", "furigana": "不足[ふそく]しがちな鉄分[てつぶん]の補給[ほきゅう]には、レバーやほうれん草[そう]がよいとされている。", "sentence_source": "generated"}, {"text": "赤ちゃんには、母乳で必要な栄養を補給することが大切だ。", "target_word": "補給", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんには、母乳[ぼにゅう]で必要[ひつよう]な栄養[えいよう]を補給[ほきゅう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "朝食を食べない人は、脳に必要な糖分を補給できない。", "target_word": "補給", "complexity_tier": "T3", "furigana": "朝食[ちょうしょく]を食[た]べない人[ひと]は、脳[のう]に必要[ひつよう]な糖分[とうぶん]を補給[ほきゅう]できない。", "sentence_source": "generated"}, {"text": "夏の暑い日は、水分と塩分の補給を忘れないでください。", "target_word": "補給", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]い日[ひ]は、水分[すいぶん]と塩分[えんぶん]の補給[ほきゅう]を忘[わす]れないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "補給", "label": "基本形"}, {"form": "補給する", "label": "動詞形"}, {"form": "補給した", "label": "過去形"}, {"form": "補給して", "label": "て形"}, {"form": "補給させる", "label": "使役形"}], "register": "標準", "sense_fingerprint": "水分・塩分・ビタミンなど、体に足りない栄養を補って与えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52198, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "補給", "is_correct": true, "explanation": "「不足したビタミンを補給する」で、足りない成分を体に補うことを指す。ここでは正しい。"}, {"text": "修理", "is_correct": false, "explanation": "「ビタミンを修理する」は成り立たず、体に足りないものを補う意味に合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「ビタミンを掃除する」は意味が通らない。"}, {"text": "解体", "is_correct": false, "explanation": "「ビタミンを解体する」は成り立たず、文の意味に合わない。"}], "explanations": {"補給": "「不足したビタミンを補給する」で、足りない成分を体に補うことを指す。ここでは正しい。", "修理": "「ビタミンを修理する」は成り立たず、体に足りないものを補う意味に合わない。", "掃除": "「ビタミンを掃除する」は意味が通らない。", "解体": "「ビタミンを解体する」は成り立たず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "補給"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は道路の舗装を補給した。", "explanation": "ここは〈整備〉の意味。補給は不足したものを足すことで、道路を手入れして直す意味では使わない。"}, {"text": "古い部品を、補給で新しいものに取り替えた。", "explanation": "ここは〈交換〉の意味。補給は不足を足すことで、古いものを新しいものに取り替える意味では使わない。"}, {"text": "壁の割れ目を、補強として補給した。", "explanation": "ここは〈補強〉の意味。補給は不足を足すことで、構造を強くする意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52198, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "補給", "is_correct": true, "explanation": "「鉄分の補給には」で、不足した鉄分を体に補うことを指す。ここでは正しい。"}, {"text": "沈殿", "is_correct": false, "explanation": "名詞だが、「鉄分の沈殿には」とは言わず、栄養をとる文脈に合わない。"}, {"text": "冷却", "is_correct": false, "explanation": "名詞だが、「鉄分の冷却には」は文脈に合わず、栄養の話として成立しない。"}, {"text": "発酵", "is_correct": false, "explanation": "名詞だが、「鉄分の発酵には」は意味が通らず、この位置には入らない。"}], "explanations": {"補給": "「鉄分の補給には」で、不足した鉄分を体に補うことを指す。ここでは正しい。", "沈殿": "名詞だが、「鉄分の沈殿には」とは言わず、栄養をとる文脈に合わない。", "冷却": "名詞だが、「鉄分の冷却には」は文脈に合わず、栄養の話として成立しない。", "発酵": "名詞だが、「鉄分の発酵には」は意味が通らず、この位置には入らない。"}, "sentence_index": 6, "correct_answer": "補給"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布の中身が少なくなったので、お金を補給して節約した。", "explanation": "ここは〈節約〉の意味。補給は不足を足すことで、出費を抑える意味はない。"}, {"text": "古い道路の傷みを、補給して直した。", "explanation": "ここは〈補修〉の意味。補給は不足したものを足すことで、壊れた物を直すことは指さない。"}, {"text": "散らかった部屋の物を補給して整理した。", "explanation": "ここは〈整理〉の意味。補給は不足を足すことで、散らかった物をまとめて片付ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52198, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汗をかいたので塩分に補給した。", "corrected_sentence": "汗をかいたので塩分を補給した。", "error_description": "「補給する」は目的語に「を」を取る。「に」を使うと誤りになる。正しくは「塩分を補給した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の暑い日は、水分に補給してください。", "corrected_sentence": "夏の暑い日は、水分を補給してください。", "error_description": "「補給する」は目的語に「を」を取る。「に」を使うと誤りになる。正しくは「水分を補給してください」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「対照が美しい」で、対照が主語になる形。"}, {"text": "を", "is_correct": false, "explanation": "「対照を美しく」は目的語の形になり、「美しい」は目的語を取らないので誤り。"}, {"text": "に", "is_correct": false, "explanation": "「対照に美しく」は位置や相手を示す形で、主語の形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「対照で美しく」は手段や場所を示す形で、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「対照が美しい」で、対照が主語になる形。", "を": "「対照を美しく」は目的語の形になり、「美しい」は目的語を取らないので誤り。", "に": "「対照に美しく」は位置や相手を示す形で、主語の形にならない。", "で": "「対照で美しく」は手段や場所を示す形で、主語にならない。"}, "error_tags": {"が": "主語の格（正解）", "を": "目的語の格の誤り", "に": "位置・相手の格の誤り", "で": "手段・場所の格の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「対照に言葉を失った」で、言葉を失う原因を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「対照を、彼は言葉を失った」は原因を示せず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「対照へ」は方向を示す形で、言葉を失う原因を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「対照と」は並べる形で、原因を表す文に合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「対照に言葉を失った」で、言葉を失う原因を「に」で示す。", "を": "「対照を、彼は言葉を失った」は原因を示せず、文として成り立たない。", "へ": "「対照へ」は方向を示す形で、言葉を失う原因を表せない。", "と": "「対照と」は並べる形で、原因を表す文に合わない。"}, "error_tags": {"に": "原因の格（正解）", "を": "目的語の格の誤り", "へ": "方向の格の誤り", "と": "並列の格の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものをくらべて、ちがうところがはっきりしていること。", "primary_collocate": null, "pronunciation": "たいしょう", "ipa": "taiɕoː", "syllable_count": 4, "sentences": [{"text": "兄は静かな性格で、弟はにぎやかな性格だから、二人は見事な対照をなしている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "兄[あに]は静[しず]かな性格[せいかく]で、弟[おとうと]はにぎやかな性格[せいかく]だから、二人[ふたり]は見事[みごと]な対照[たいしょう]をなしている。", "sentence_source": "generated"}, {"text": "白い雪と赤い花の対照が美しく、思わず写真を撮った。", "target_word": "対照", "complexity_tier": "T3", "furigana": "白[しろ]い雪[ゆき]と赤[あか]い花[はな]の対照[たいしょう]が美[うつく]しく、思[おも]わず写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "暑かった去年の夏と対照をなすように、今年は雨の日が多かった。", "target_word": "対照", "complexity_tier": "T3", "furigana": "暑[あつ]かった去年[きょねん]の夏[なつ]と対照[たいしょう]をなすように、今年[ことし]は雨[あめ]の日[ひ]が多[おお]かった。", "sentence_source": "generated"}, {"text": "ビルが並ぶ都会と、田んぼが広がる村では、くらしの対照が際立っている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "ビルが並[なら]ぶ都会[とかい]と、田[た]んぼが広[ひろ]がる村[むら]では、くらしの対照[たいしょう]が際立[きわだ]っている。", "sentence_source": "generated"}, {"text": "明るい色の服を着た妹は、黒い服の私と対照をなして目立った。", "target_word": "対照", "complexity_tier": "T3", "furigana": "明[あか]るい色[いろ]の服[ふく]を着[き]た妹[いもうと]は、黒[くろ]い服[ふく]の私[わたし]と対照[たいしょう]をなして目立[めだ]った。", "sentence_source": "generated"}, {"text": "この絵は、光と影の対照によって、人物の姿が立体的に見える。", "target_word": "対照", "complexity_tier": "T3", "furigana": "この絵[え]は、光[ひかり]と影[かげ]の対照[たいしょう]によって、人物[じんぶつ]の姿[すがた]が立体的[りったいてき]に見[み]える。", "sentence_source": "generated"}, {"text": "二つの案は長所と短所の対照がはっきりしているので、選びやすい。", "target_word": "対照", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]は長所[ちょうしょ]と短所[たんしょ]の対照[たいしょう]がはっきりしているので、選[えら]びやすい。", "sentence_source": "generated"}, {"text": "豪華な式場と質素な家との対照に、彼は言葉を失った。", "target_word": "対照", "complexity_tier": "T3", "furigana": "豪華[ごうか]な式場[しきじょう]と質素[しっそ]な家[いえ]との対照[たいしょう]に、彼[かれ]は言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "前半の暗い場面があるからこそ、最後の明るい場面との対照が印象に残る。", "target_word": "対照", "complexity_tier": "T3", "furigana": "前半[ぜんはん]の暗[くら]い場面[ばめん]があるからこそ、最後[さいご]の明[あか]るい場面[ばめん]との対照[たいしょう]が印象[いんしょう]に残[のこ]る。", "sentence_source": "generated"}, {"text": "赤と青は、色の対照をなす組み合わせとしてよく使われる。", "target_word": "対照", "complexity_tier": "T3", "furigana": "赤[あか]と青[あお]は、色[いろ]の対照[たいしょう]をなす組[く]み合[あ]わせとしてよく使[つか]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対照", "label": "基本形"}, {"form": "対照的", "label": "形容動詞化（〜的）"}, {"form": "対照的に", "label": "副詞的用法"}], "register": "標準", "sense_fingerprint": "二つのものを並べたとき、違いがはっきり目立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対照", "is_correct": true, "explanation": "正解。「見事な対照をなしている」で、二人の性格の違いがはっきり際立つ意味に合う。"}, {"text": "手段", "is_correct": false, "explanation": "「見事な手段をなしている」は言えず、性格の違いの話に合わない。"}, {"text": "好意", "is_correct": false, "explanation": "「見事な好意をなしている」は言えず、性格の違いを表す文には合わない。"}, {"text": "反省", "is_correct": false, "explanation": "「見事な反省をなしている」は言えず、違いが際立つ意味にならない。"}], "explanations": {"対照": "正解。「見事な対照をなしている」で、二人の性格の違いがはっきり際立つ意味に合う。", "手段": "「見事な手段をなしている」は言えず、性格の違いの話に合わない。", "好意": "「見事な好意をなしている」は言えず、性格の違いを表す文には合わない。", "反省": "「見事な反省をなしている」は言えず、違いが際立つ意味にならない。"}, "sentence_index": 0, "correct_answer": "対照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この事故に対照を取った。", "explanation": "「対策」と書く語。「対照」には「対策」の意味はない。"}, {"text": "客からの苦情に丁寧に対照した。", "explanation": "「対応」と書く語。「対照」には「対応」の意味はない。"}, {"text": "ライバル企業に対照する方法を考えた。", "explanation": "「対抗」と書く語。「対照」には「対抗」の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対照", "is_correct": true, "explanation": "正解。「長所と短所の対照がはっきりしている」で、二つの案の違いを表す。"}, {"text": "手続き", "is_correct": false, "explanation": "「長所と短所の手続きがはっきりしている」は意味が通らない。"}, {"text": "相談", "is_correct": false, "explanation": "「長所と短所の相談がはっきりしている」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「長所と短所の天気がはっきりしている」は意味が通らない。"}], "explanations": {"対照": "正解。「長所と短所の対照がはっきりしている」で、二つの案の違いを表す。", "手続き": "「長所と短所の手続きがはっきりしている」は意味が通らない。", "相談": "「長所と短所の相談がはっきりしている」は意味が通らない。", "天気": "「長所と短所の天気がはっきりしている」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "対照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "調査の対照を広げて、データを集めた。", "explanation": "「対象」と書く語。「対照」には「対象」の意味はない。"}, {"text": "二人は昼から将棋で対照した。", "explanation": "「対局」と書く語。「対照」には「対局」の意味はない。"}, {"text": "雨漏りに対照して、業者を呼んだ。", "explanation": "「対処」と書く語。「対照」には「対処」の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼と夜の雰囲気の対照を際立っている。", "corrected_sentence": "昼と夜の雰囲気の対照が際立っている。", "error_description": "「対照を際立っている」は誤り。「際立つ」は主語に「が」を取るので、正しくは「対照が際立っている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52201, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤と緑の服は対照をなっていて、目を引く。", "corrected_sentence": "赤と緑の服は対照をなしていて、目を引く。", "error_description": "「対照をなっていて」は誤り。「対照をなす」の「なす」が正しく、「なる」の形は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「対照をなす」で、「なす」の目的語として「を」が対照に付く。"}, {"text": "が", "is_correct": false, "explanation": "「対照がなしている」は主語の形になり、「なす」の目的語になっていないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「対照になしている」は「なす」が目的語を取る形と合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「対照でなしている」は手段や場所を示す形になり、「なす」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「対照をなす」で、「なす」の目的語として「を」が対照に付く。", "が": "「対照がなしている」は主語の形になり、「なす」の目的語になっていないので不自然。", "に": "「対照になしている」は「なす」が目的語を取る形と合わず不自然。", "で": "「対照でなしている」は手段や場所を示す形になり、「なす」の目的語にならない。"}, "error_tags": {"を": "目的語（正解）", "が": "主語の格の誤り", "に": "位置・相手の格の誤り", "で": "手段・場所の格の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの物事を比べたとき、その違いがはっきりしていること。また、その違い。", "primary_collocate": null, "pronunciation": "たいしょう", "ipa": "taiɕoː", "syllable_count": 4, "sentences": [{"text": "甘いお菓子と辛い料理は、味の対照がはっきりしている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "甘[あま]いお菓子[かし]と辛[から]い料理[りょうり]は、味[あじ]の対照[たいしょう]がはっきりしている。", "sentence_source": "generated"}, {"text": "兄は社交的だが、弟は無口で、二人の性格は見事な対照をなしている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "兄[あに]は社交的[しゃこうてき]だが、弟[おとうと]は無口[むくち]で、二人[ふたり]の性格[せいかく]は見事[みごと]な対照[たいしょう]をなしている。", "sentence_source": "generated"}, {"text": "雪の白と木の黒が、はっきりした対照を作っている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "雪[ゆき]の白[しろ]と木[き]の黒[くろ]が、はっきりした対照[たいしょう]を作[つく]っている。", "sentence_source": "generated"}, {"text": "明るい都会と静かな田舎は、あらゆる点で対照をなしている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "明[あか]るい都会[とかい]と静[しず]かな田舎[いなか]は、あらゆる点[てん]で対照[たいしょう]をなしている。", "sentence_source": "generated"}, {"text": "昼間の暑さとの対照で、夜の風がいっそう冷たく感じられた。", "target_word": "対照", "complexity_tier": "T3", "furigana": "昼間[ひるま]の暑[あつ]さとの対照[たいしょう]で、夜[よる]の風[かぜ]がいっそう冷[つめ]たく感[かん]じられた。", "sentence_source": "generated"}, {"text": "この絵は、赤い服と青い背景の対照が印象的だ。", "target_word": "対照", "complexity_tier": "T3", "furigana": "この絵[え]は、赤[あか]い服[ふく]と青[あお]い背景[はいけい]の対照[たいしょう]が印象的[いんしょうてき]だ。", "sentence_source": "generated"}, {"text": "両チームの戦い方は対照をなしていて、守りの強さと攻めの速さがはっきり分かれた。", "target_word": "対照", "complexity_tier": "T3", "furigana": "両[りょう]チームの戦[たたか]い方[かた]は対照[たいしょう]をなしていて、守[まも]りの強[つよ]さと攻[せ]めの速[はや]さがはっきり分[わ]かれた。", "sentence_source": "generated"}, {"text": "派手な姉の部屋と、物の少ない妹の部屋は、鮮やかな対照だった。", "target_word": "対照", "complexity_tier": "T3", "furigana": "派手[はで]な姉[あね]の部屋[へや]と、物[もの]の少[すく]ない妹[いもうと]の部屋[へや]は、鮮[あざ]やかな対照[たいしょう]だった。", "sentence_source": "generated"}, {"text": "豪華な宮殿の前に貧しい家が並び、その対照に胸が痛んだ。", "target_word": "対照", "complexity_tier": "T3", "furigana": "豪華[ごうか]な宮殿[きゅうでん]の前[まえ]に貧[まず]しい家[いえ]が並[なら]び、その対照[たいしょう]に胸[むね]が痛[いた]んだ。", "sentence_source": "generated"}, {"text": "作者は、都会の騒がしさと山の静けさの対照を、この詩で描いている。", "target_word": "対照", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は、都会[とかい]の騒[さわ]がしさと山[やま]の静[しず]けさの対照[たいしょう]を、この詩[し]で描[えが]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対照", "label": "基本形"}, {"form": "対照する", "label": "動詞形"}, {"form": "対照した", "label": "過去形"}, {"form": "対照して", "label": "て形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "二つのものを比べたときに、違いがくっきり目立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対照", "is_correct": true, "explanation": "正解。「味の対照がはっきりしている」の名詞で、違いが際立つ意味に合う。"}, {"text": "切片", "is_correct": false, "explanation": "「切片的な」は言えず、ここで指す違いの際立ちという意味にも合わない。"}, {"text": "顆粒", "is_correct": false, "explanation": "「顆粒的な」は言えず、味の違いを表す文には合わない。"}, {"text": "片割れ", "is_correct": false, "explanation": "「片割れ的な」は言えず、対の一方を指す語で違いの際立ちを表さない。"}], "explanations": {"対照": "正解。「味の対照がはっきりしている」の名詞で、違いが際立つ意味に合う。", "切片": "「切片的な」は言えず、ここで指す違いの際立ちという意味にも合わない。", "顆粒": "「顆粒的な」は言えず、味の違いを表す文には合わない。", "片割れ": "「片割れ的な」は言えず、対の一方を指す語で違いの際立ちを表さない。"}, "sentence_index": 0, "correct_answer": "対照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社長と対照して、将来について話し合った。", "explanation": "ここは〈対話〉の意味。言葉を交わし話し合う意味で、違いを比べる〈対照〉とは合わない。"}, {"text": "強豪チームに対照して、作戦を練った。", "explanation": "ここは〈対抗〉の意味。相手と張り合って立ち向かう意味で、違いを際立たせる〈対照〉は使えない。"}, {"text": "この問題に対照を取った。", "explanation": "ここは〈対策〉の意味。問題を解決する手立てを指すので、違いを比べる〈対照〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対照", "is_correct": true, "explanation": "正解。「対照をなしている」で、二つの戦い方の違いがはっきり際立つ意味に合う。"}, {"text": "手段", "is_correct": false, "explanation": "「手段をなしている」は言えず、戦い方の違いを表す文に合わない。"}, {"text": "反省", "is_correct": false, "explanation": "「反省をなしている」は言えず、戦い方の違いを表す文には合わない。"}, {"text": "好意", "is_correct": false, "explanation": "「好意をなしている」は言えず、チームの戦い方の違いを表す意味ではない。"}], "explanations": {"対照": "正解。「対照をなしている」で、二つの戦い方の違いがはっきり際立つ意味に合う。", "手段": "「手段をなしている」は言えず、戦い方の違いを表す文に合わない。", "反省": "「反省をなしている」は言えず、戦い方の違いを表す文には合わない。", "好意": "「好意をなしている」は言えず、チームの戦い方の違いを表す意味ではない。"}, "sentence_index": 6, "correct_answer": "対照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究者は研究の対照を広げた。", "explanation": "ここは〈対象〉の意味。調べたり扱ったりする相手を指す語で、違いを際立たせる〈対照〉とは違うので合わない。"}, {"text": "客からの苦情に丁寧に対照した。", "explanation": "ここは〈対応〉の意味。相手の求めに応じて処理する意味で、比べて違いを示す〈対照〉とは違う。"}, {"text": "二人は決勝で対照した。", "explanation": "ここは〈対戦〉の意味。試合で相手と勝負する意味で、違いを比べて示す〈対照〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤と白の対照を際立っている。", "corrected_sentence": "赤と白の対照が際立っている。", "error_description": "「対照を際立っている」は誤り。「際立つ」は「〜が際立つ」と主語に「が」を取るので、正しくは「対照が際立っている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52202, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人の服の色は対照をなっていて、写真映えする。", "corrected_sentence": "二人の服の色は対照をなしていて、写真映えする。", "error_description": "「対照をなっていて」は誤り。「対照をなす」の「なす」が正しく、「なる」の形は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不合理", "is_correct": true, "explanation": "道理に合わないことを表し、合理の対義語として辞書にも並ぶ。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然は道理と関係なく起こることで、合理の対義語ではない。"}, {"text": "根拠", "is_correct": false, "explanation": "根拠は判断のよりどころで、道理に合うかどうかとは別の語。"}, {"text": "流行", "is_correct": false, "explanation": "流行は世の中で広まる傾向のことで、道理との対立は表さない。"}], "correct_answer": "不合理", "explanations": {"不合理": "道理に合わないことを表し、合理の対義語として辞書にも並ぶ。", "偶然": "偶然は道理と関係なく起こることで、合理の対義語ではない。", "根拠": "根拠は判断のよりどころで、道理に合うかどうかとは別の語。", "流行": "流行は世の中で広まる傾向のことで、道理との対立は表さない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不合理", "is_correct": true, "explanation": "道理に合わないことを表し、合理の対義語として辞書にも並ぶ。"}, {"text": "習慣", "is_correct": false, "explanation": "習慣は繰り返される行動のことで、合理の対義語ではない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は物事の長さを表す語で、道理との対立は表さない。"}, {"text": "気質", "is_correct": false, "explanation": "気質は生まれ持った性格のことで、道理との対立を表さない。"}], "correct_answer": "不合理", "explanations": {"不合理": "道理に合わないことを表し、合理の対義語として辞書にも並ぶ。", "習慣": "習慣は繰り返される行動のことで、合理の対義語ではない。", "時間": "時間は物事の長さを表す語で、道理との対立は表さない。", "気質": "気質は生まれ持った性格のことで、道理との対立を表さない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "道理に合っていること。", "primary_collocate": null, "pronunciation": "ごうり", "ipa": "ɡoːɾi", "syllable_count": 3, "sentences": [{"text": "彼の言い分には合理があるので、反対していた人も黙ってしまった。", "target_word": "合理", "complexity_tier": "T3", "furigana": "彼[かれ]の言[い]い分[ぶん]には合理[ごうり]があるので、反対[はんたい]していた人[ひと]も黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "その決定は合理を欠いていると、多くの社員が感じた。", "target_word": "合理", "complexity_tier": "T3", "furigana": "その決定[けってい]は合理[ごうり]を欠[か]いていると、多[おお]くの社員[しゃいん]が感[かん]じた。", "sentence_source": "generated"}, {"text": "子どもの話でも、合理があれば耳を傾けるべきだ。", "target_word": "合理", "complexity_tier": "T3", "furigana": "子[こ]どもの話[はなし]でも、合理[ごうり]があれば耳[みみ]を傾[かたむ]けるべきだ。", "sentence_source": "generated"}, {"text": "証拠のない噂話に合理は認められない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "証拠[しょうこ]のない噂話[うわさばなし]に合理[ごうり]は認[みと]められない。", "sentence_source": "generated"}, {"text": "裁判官は、双方の主張のどちらに合理があるかを慎重に考えた。", "target_word": "合理", "complexity_tier": "T3", "furigana": "裁判官[さいばんかん]は、双方[そうほう]の主張[しゅちょう]のどちらに合理[ごうり]があるかを慎重[しんちょう]に考[かんが]えた。", "sentence_source": "generated"}, {"text": "理由も示さずに断るのは、合理に反する行いだ。", "target_word": "合理", "complexity_tier": "T3", "furigana": "理由[りゆう]も示[しめ]さずに断[ことわ]るのは、合理[ごうり]に反[はん]する行[おこな]いだ。", "sentence_source": "generated"}, {"text": "規則を変えるなら、だれもが納得する合理が必要だ。", "target_word": "合理", "complexity_tier": "T3", "furigana": "規則[きそく]を変[か]えるなら、だれもが納得[なっとく]する合理[ごうり]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "値上げに合理があるのかを説明しない会社に、客は不満を持った。", "target_word": "合理", "complexity_tier": "T3", "furigana": "値上[ねあ]げに合理[ごうり]があるのかを説明[せつめい]しない会社[かいしゃ]に、客[きゃく]は不満[ふまん]を持[も]った。", "sentence_source": "generated"}, {"text": "合理と不合理を見分ける力は、学校の勉強だけでは身につかない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "合理[ごうり]と不合理[ふごうり]を見分[みわ]ける力[ちから]は、学校[がっこう]の勉強[べんきょう]だけでは身[み]につかない。", "sentence_source": "generated"}, {"text": "彼女の意見は筋が通っていて、聞けば聞くほど合理があると思えた。", "target_word": "合理", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の意見[いけん]は筋[すじ]が通[とお]っていて、聞[き]けば聞[き]くほど合理[ごうり]があると思[おも]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合理", "label": "基本形"}, {"form": "合理的", "label": "形容動詞化（〜的）"}, {"form": "合理性", "label": "名詞化（〜性）"}, {"form": "不合理", "label": "否定形（不〜）"}], "register": "標準", "sense_fingerprint": "言い分や判断が道理にかなっていて、理屈が通ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合理", "is_correct": true, "explanation": "「道理に合っていること」の意味で、言い分に筋が通っていたから反対者が黙った、と文が自然につながる。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、言い分の道理には当てはまらない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は声や音の大きさを表し、言い分の筋道を指せない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合で、言い分には使えない。"}], "explanations": {"合理": "「道理に合っていること」の意味で、言い分に筋が通っていたから反対者が黙った、と文が自然につながる。", "体重": "体重は体の重さのことで、言い分の道理には当てはまらない。", "音量": "音量は声や音の大きさを表し、言い分の筋道を指せない。", "湿度": "湿度は空気中の水分の割合で、言い分には使えない。"}, "sentence_index": 0, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りのあまり合理を失い、大声で怒鳴り続けた。", "explanation": "ここは〈理性〉の意味。理性は失うものだが、道理に合うことを表す合理は失うものではないので合わない。"}, {"text": "彼は合理をこねて、なかなか結論を出さない。", "explanation": "ここは〈理屈〉の意味。理屈はこねるが、道理に合う状態を指す合理はこねる対象にならない。"}, {"text": "この説は合理が整っていて、実験でも確かめられた。", "explanation": "ここは〈理論〉の意味。理論は整えるものだが、合理は道理に合うことを指すので、体系の組み立てには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合理", "is_correct": true, "explanation": "「道理に合っていること」の意味で、納得させる根拠として文の流れに合う。"}, {"text": "照明", "is_correct": false, "explanation": "照明は明かりのことで、納得する規則の必要性とはつながらない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の背の高さを表し、規則の話には当てはまらない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、規則を納得させる要素として使えない。"}], "explanations": {"合理": "「道理に合っていること」の意味で、納得させる根拠として文の流れに合う。", "照明": "照明は明かりのことで、納得する規則の必要性とはつながらない。", "身長": "身長は人の背の高さを表し、規則の話には当てはまらない。", "天気": "天気は空模様のことで、規則を納得させる要素として使えない。"}, "sentence_index": 6, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察は、事故の合理をもう一度詳しく調べた。", "explanation": "ここは〈理由〉の意味。事故の原因を指すのは理由で、道理に合う性質の合理は使わない。"}, {"text": "彼女は英語の合理が深く、難しい文章もすらすら読める。", "explanation": "ここは〈理解〉の意味。語学の習熟は理解と言い、道理に合うことを表す合理は使えない。"}, {"text": "三平方の合理は、中学で習う基本の一つだ。", "explanation": "ここは〈定理〉の意味。数学の定理は定理と言い、合理は道理に合う性質を指す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "証拠の少ない推測に合理をあるとは言えない。", "corrected_sentence": "証拠の少ない推測に合理があるとは言えない。", "error_description": "「ある」の主語になる「合理」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52203, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "理由を聞かずに責めるのは、合理に反す行いだ。", "corrected_sentence": "理由を聞かずに責めるのは、合理に反する行いだ。", "error_description": "「反する」はサ変動詞。「反す」は誤りで、連体形は「反する」になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
