INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52204, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事の筋道が通っていて、無駄がないこと。また、そのさま。", "primary_collocate": null, "pronunciation": "ごうり", "ipa": "ɡoːɾi", "syllable_count": 3, "sentences": [{"text": "祖父は仕事の手順を見直し、無駄を省く合理を何よりも大切にしていた。", "target_word": "合理", "complexity_tier": "T4", "furigana": "祖父[そふ]は仕事[しごと]の手順[てじゅん]を見直[みなお]し、無駄[むだ]を省[はぶ]く合理[ごうり]を何[なに]よりも大切[たいせつ]にしていた。", "sentence_source": "generated"}, {"text": "彼は何事にも合理を重んじ、無駄な買い物は決してしない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "彼[かれ]は何事[なにごと]にも合理[ごうり]を重[おも]んじ、無駄[むだ]な買[か]い物[もの]は決[けっ]してしない。", "sentence_source": "generated"}, {"text": "工場では合理を追求して、作業の手順がすべて見直された。", "target_word": "合理", "complexity_tier": "T3", "furigana": "工場[こうじょう]では合理[ごうり]を追求[ついきゅう]して、作業[さぎょう]の手順[てじゅん]がすべて見直[みなお]された。", "sentence_source": "generated"}, {"text": "この台所は合理を第一に考えて設計されている。", "target_word": "合理", "complexity_tier": "T3", "furigana": "この台所[だいどころ]は合理[ごうり]を第一[だいいち]に考[かんが]えて設計[せっけい]されている。", "sentence_source": "generated"}, {"text": "合理だけを追い求めると、人づき合いが冷たくなることもある。", "target_word": "合理", "complexity_tier": "T3", "furigana": "合理[ごうり]だけを追[お]い求[もと]めると、人[ひと]づき合[あ]いが冷[つめ]たくなることもある。", "sentence_source": "generated"}, {"text": "新しい店長は合理を優先して、使われない棚をすべて撤去した。", "target_word": "合理", "complexity_tier": "T3", "furigana": "新[あたら]しい店長[てんちょう]は合理[ごうり]を優先[ゆうせん]して、使[つか]われない棚[たな]をすべて撤去[てっきょ]した。", "sentence_source": "generated"}, {"text": "感情と合理のあいだで、彼はなかなか決められなかった。", "target_word": "合理", "complexity_tier": "T3", "furigana": "感情[かんじょう]と合理[ごうり]のあいだで、彼[かれ]はなかなか決[き]められなかった。", "sentence_source": "generated"}, {"text": "祖母の家事は合理の塊で、水も時間も少しも無駄にしない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "祖母[そぼ]の家事[かじ]は合理[ごうり]の塊[かたまり]で、水[みず]も時間[じかん]も少[すこ]しも無駄[むだ]にしない。", "sentence_source": "generated"}, {"text": "合理を求める会社でも、人の気持ちまで数字で測ることはできない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "合理[ごうり]を求[もと]める会社[かいしゃ]でも、人[ひと]の気持[きも]ちまで数字[すうじ]で測[はか]ることはできない。", "sentence_source": "generated"}, {"text": "住む場所を決めるなら合理が大切で、駅の近くのほうが毎日の移動に無駄がない。", "target_word": "合理", "complexity_tier": "T3", "furigana": "住[す]む場所[ばしょ]を決[き]めるなら合理[ごうり]が大切[たいせつ]で、駅[えき]の近[ちか]くのほうが毎日[まいにち]の移動[いどう]に無駄[むだ]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合理", "label": "基本形"}, {"form": "合理的", "label": "形容動詞化（〜的）"}, {"form": "合理性", "label": "名詞化（〜性）"}, {"form": "不合理", "label": "否定形（不〜）"}], "register": "標準", "sense_fingerprint": "筋道が通っていて、手間や費用に無駄がないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52204, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合理", "is_correct": true, "explanation": "正解。「無駄を省く合理」の名詞で、筋道が通って無駄がない意味に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「無駄を省く感情」は言えず、効率を述べる文には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「無駄を省く天気」は言えず、手順の効率を述べる文に合わない。"}, {"text": "身長", "is_correct": false, "explanation": "「無駄を省く身長」は言えず、ここで述べる効率の意味には合わない。"}], "explanations": {"合理": "正解。「無駄を省く合理」の名詞で、筋道が通って無駄がない意味に合う。", "感情": "「無駄を省く感情」は言えず、効率を述べる文には合わない。", "天気": "「無駄を省く天気」は言えず、手順の効率を述べる文に合わない。", "身長": "「無駄を省く身長」は言えず、ここで述べる効率の意味には合わない。"}, "sentence_index": 0, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の合理を伸ばした。", "explanation": "ここは〈利益〉の意味。もうけを指すので、筋道や無駄のなさを表す〈合理〉とは違う。"}, {"text": "怒りを合理で抑えた。", "explanation": "ここは〈理性〉の意味。感情に流されず考える心の働きを指す語で、物事の筋道を表す〈合理〉とは言い換えられない。"}, {"text": "合理を省いて、作業を速く終えた。", "explanation": "ここは〈無駄を省く〉の意味。余計なものを削る意味で、筋道や効率を表す〈合理〉は省く対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52204, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合理", "is_correct": true, "explanation": "正解。「感情と合理のあいだで」の対になる語で、感情と筋道の対比を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「感情と天気のあいだで」は意味が通らない。"}, {"text": "照明", "is_correct": false, "explanation": "「感情と照明のあいだで」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "「感情と季節のあいだで」は意味が通らない。"}], "explanations": {"合理": "正解。「感情と合理のあいだで」の対になる語で、感情と筋道の対比を表す。", "天気": "「感情と天気のあいだで」は意味が通らない。", "照明": "「感情と照明のあいだで」は意味が通らない。", "季節": "「感情と季節のあいだで」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合理をしないでゆっくり休んでね。", "explanation": "ここは〈無理〉の意味。体や物事に負担をかける、またはそうしない意味で、筋道が通っているという〈合理〉とは別の語なので合わない。"}, {"text": "この合理は実験で確かめられている。", "explanation": "ここは〈理論〉の意味。考えを体系立てて説明する枠組みを指すので、物事の筋道が通っている状態を表す〈合理〉とは違う。"}, {"text": "この事業は合理が合うと判断した。", "explanation": "ここは〈採算〉の意味。収入と費用の釣り合いを指す語で、筋道や無駄のなさを表す〈合理〉とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52204, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は在庫を合理に管理している。", "corrected_sentence": "この店は在庫を合理的に管理している。", "error_description": "「合理に管理」は誤り。「合理」は名詞なので、副詞として使うには「合理的に」と「的」が必要。正しくは「合理的に管理している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52204, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "感情より合理に優先して決めた。", "corrected_sentence": "感情より合理を優先して決めた。", "error_description": "「合理に優先して」は誤り。「優先する」は「〜を優先する」と「を」で優先の対象を示すので、正しくは「合理を優先して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
