INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52205, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ねんれいが ちいさい こと。", "primary_collocate": null, "pronunciation": "わかい", "ipa": "wa.ka.i", "syllable_count": 3, "sentences": [{"text": "新しい先生はまだ若いですが、教え方がとても上手です。", "target_word": "若い", "complexity_tier": "T2", "furigana": "新[あたら]しい先生[せんせい]はまだ若[わか]いですが、教[おし]え方[かた]がとても上手[じょうず]です。", "sentence_source": "generated"}, {"text": "この会社には若い人がたくさん働いています。", "target_word": "若い", "complexity_tier": "T2", "furigana": "この会社[かいしゃ]には若[わか]い人[ひと]がたくさん働[はたら]いています。", "sentence_source": "generated"}, {"text": "祖母は年のわりに若く見えるので、よく驚かれる。", "target_word": "若く", "complexity_tier": "T3", "furigana": "祖母[そぼ]は年[とし]のわりに若[わか]く見[み]えるので、よく驚[おどろ]かれる。", "sentence_source": "generated"}, {"text": "若いときに、いろいろなことを経験しておきたい。", "target_word": "若い", "complexity_tier": "T3", "furigana": "若[わか]いときに、いろいろなことを経験[けいけん]しておきたい。", "sentence_source": "generated"}, {"text": "私は若いから、まだ体力に自信がある。", "target_word": "若い", "complexity_tier": "T2", "furigana": "私[わたし]は若[わか]いから、まだ体力[たいりょく]に自信[じしん]がある。", "sentence_source": "generated"}, {"text": "あの店の店長は若くて、私と同じ二十五歳だ。", "target_word": "若く", "complexity_tier": "T2", "furigana": "あの店[みせ]の店長[てんちょう]は若[わか]くて、私[わたし]と同[おな]じ二十五歳[にじゅうごさい]だ。", "sentence_source": "generated"}, {"text": "公園では、若い夫婦が子どもと遊んでいた。", "target_word": "若い", "complexity_tier": "T2", "furigana": "公園[こうえん]では、若[わか]い夫婦[ふうふ]が子[こ]どもと遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "年上の人だけでなく、若い人の意見も聞きたい。", "target_word": "若い", "complexity_tier": "T3", "furigana": "年上[としうえ]の人[ひと]だけでなく、若[わか]い人[ひと]の意見[いけん]も聞[き]きたい。", "sentence_source": "generated"}, {"text": "若かった父は、毎日自転車で町を回って新聞を配っていた。", "target_word": "若かった", "complexity_tier": "T3", "furigana": "若[わか]かった父[ちち]は、毎日[まいにち]自転車[じてんしゃ]で町[まち]を回[まわ]って新聞[しんぶん]を配[くば]っていた。", "sentence_source": "generated"}, {"text": "この仕事は若くない人には少し大変かもしれません。", "target_word": "若くない", "complexity_tier": "T3", "furigana": "この仕事[しごと]は若[わか]くない人[ひと]には少[すこ]し大変[たいへん]かもしれません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "若い", "label": "基本形"}, {"form": "若く", "label": "連用形"}, {"form": "若かった", "label": "過去形"}, {"form": "若くない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "年齢が小さい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "若い", "is_correct": true, "explanation": "形容詞の終止形。『まだ若いですが』で文が成立する。"}, {"text": "若く", "is_correct": false, "explanation": "連用形。『まだ若くですが』と文中で言い切れず、文が成立しない。"}, {"text": "若さ", "is_correct": false, "explanation": "名詞。『まだ若さですが』は文として続かない。"}, {"text": "若ければ", "is_correct": false, "explanation": "仮定形。『まだ若ければですが』は成立しない。"}], "explanations": {"若い": "形容詞の終止形。『まだ若いですが』で文が成立する。", "若く": "連用形。『まだ若くですが』と文中で言い切れず、文が成立しない。", "若さ": "名詞。『まだ若さですが』は文として続かない。", "若ければ": "仮定形。『まだ若ければですが』は成立しない。"}, "sentence_index": 0, "correct_answer": "若い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の料理は若いので、味がまだ安定していない。", "explanation": "ここは〈未熟〉の意味。出来ばえの未熟さは年齢の『若い』とは別義で、この義項では使わない。"}, {"text": "この辞書は若いので、かばんに入らない。", "explanation": "ここは〈厚い〉の意味。辞書の厚みを『若い』とは言わない。『厚い』が正しい。"}, {"text": "彼女の字は若くて、読みにくい。", "explanation": "ここは〈幼い〉の意味。字が子どもっぽいことは『幼い』で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "若い", "is_correct": true, "explanation": "連体形。『若い夫婦』で名詞を修飾する自然な形。"}, {"text": "若々しく", "is_correct": false, "explanation": "形容詞『若々しい』の連用形。夫婦を修飾できず、『若々しく夫婦』は成り立たない。"}, {"text": "若げ", "is_correct": false, "explanation": "名詞（若者らしい未熟さ）。『若げ夫婦』では修飾関係が成り立たない。"}, {"text": "若返る", "is_correct": false, "explanation": "動詞。『若返る夫婦』では修飾が成立せず、文の意味も合わない。"}], "explanations": {"若い": "連体形。『若い夫婦』で名詞を修飾する自然な形。", "若々しく": "形容詞『若々しい』の連用形。夫婦を修飾できず、『若々しく夫婦』は成り立たない。", "若げ": "名詞（若者らしい未熟さ）。『若げ夫婦』では修飾関係が成り立たない。", "若返る": "動詞。『若返る夫婦』では修飾が成立せず、文の意味も合わない。"}, "sentence_index": 6, "correct_answer": "若い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この自転車は若いので、まだ乗り心地がいい。", "explanation": "ここは〈新しい〉の意味。自転車が新品であることは『若い』では言わず、『新しい』を使う。"}, {"text": "このつり橋は若いので、強風にも耐えられる。", "explanation": "ここは〈強い〉の意味。つり橋の丈夫さを『若い』で言うことはできず、『強い』が正しい。"}, {"text": "この箱は若いので、一人では持ち上がらない。", "explanation": "ここは〈重い〉の意味。箱の重さを『若い』では表せず、『重い』を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は私に若いので、まだ大学生だ。", "corrected_sentence": "妹は私より若いので、まだ大学生だ。", "error_description": "比較の助詞の誤り。『若い』と比べる相手は『より』で示す。『私に』では比較が成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "若い", "is_correct": true, "explanation": "連体形。『若い人』で名詞『人』を修飾する正しい形。"}, {"text": "若く", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、『若く人』は成り立たない。"}, {"text": "若くて", "is_correct": false, "explanation": "て形。名詞を修飾できず、『若くて人』は文が続かない。"}, {"text": "若かろう", "is_correct": false, "explanation": "推量の形。『若かろう人』は文法的に成り立たない。"}], "correct_form": "若い", "base_form": "若い", "form_label": "連体形", "sentence_index": 1, "explanations": {"若い": "連体形。『若い人』で名詞『人』を修飾する正しい形。", "若く": "連用形。名詞を直接修飾できず、『若く人』は成り立たない。", "若くて": "て形。名詞を修飾できず、『若くて人』は文が続かない。", "若かろう": "推量の形。『若かろう人』は文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は若いで、まだ小学生だ。", "corrected_sentence": "弟は若くて、まだ小学生だ。", "error_description": "活用の誤り。『若い』に『で』は続かない。並列には連用形『若くて』を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "若い", "is_correct": true, "explanation": "連体形。「年上の人だけでなく、若い人の意見」で名詞「人」を修飾する正しい形。"}, {"text": "若かった", "is_correct": false, "explanation": "過去形。過去の状態を表し、今の若い人を指す文脈と合わない。"}, {"text": "若くない", "is_correct": false, "explanation": "否定形。『年上の人』と重なる『若くない人』になり、『若い人』との対比が崩れる。"}, {"text": "若ければ", "is_correct": false, "explanation": "仮定形。名詞の前に置けず、「若ければ人」は成り立たない。"}], "correct_form": "若い", "base_form": "若い", "form_label": "連体形", "sentence_index": 7, "explanations": {"若い": "連体形。「年上の人だけでなく、若い人の意見」で名詞「人」を修飾する正しい形。", "若かった": "過去形。過去の状態を表し、今の若い人を指す文脈と合わない。", "若くない": "否定形。『年上の人』と重なる『若くない人』になり、『若い人』との対比が崩れる。", "若ければ": "仮定形。名詞の前に置けず、「若ければ人」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
