INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52206, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "年齢が若いさま。若々しい。", "primary_collocate": null, "pronunciation": "わかい", "ipa": "wa.ka.i", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "若き", "complexity_tier": "T5", "furigana": "修業[しゅぎょう]の途上[とじょう]にある若[わか]きパン職人[しょくにん]は、夜明[よあ]け前[まえ]の凛[りん]とした空気[くうき]が張[は]り詰[つ]めるアトリエにて、野生[やせい]の酵母[こうぼ]が織[お]りなす微細[びさい]かつ劇的[げきてき]な化学[かがく]反応[はんのう]と黙々[もくもく]と格闘[かくとう]していた。", "sentence_source": "mined"}, {"text": "彼は若いころ、毎朝五時に起きて走っていたそうだ。", "target_word": "若い", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]いころ、毎朝[まいあさ]五時[ごじ]に起[お]きて走[はし]っていたそうだ。", "sentence_source": "generated"}, {"text": "若い先生は生徒の気持ちがよくわかるので、人気がある。", "target_word": "若い", "complexity_tier": "T3", "furigana": "若[わか]い先生[せんせい]は生徒[せいと]の気持[きも]ちがよくわかるので、人気[にんき]がある。", "sentence_source": "generated"}, {"text": "祖母は七十歳だが、考え方がとても若い。", "target_word": "若い", "complexity_tier": "T3", "furigana": "祖母[そぼ]は七十歳[ななじゅっさい]だが、考[かんが]え方[かた]がとても若[わか]い。", "sentence_source": "generated"}, {"text": "妹は私より三つ若いので、まだ大学生だ。", "target_word": "若い", "complexity_tier": "T3", "furigana": "妹[いもうと]は私[わたし]より三[みっ]つ若[わか]いので、まだ大学生[だいがくせい]だ。", "sentence_source": "generated"}, {"text": "若いうちにいろいろな国を見ておきたい。", "target_word": "若い", "complexity_tier": "T3", "furigana": "若[わか]いうちにいろいろな国[くに]を見[み]ておきたい。", "sentence_source": "generated"}, {"text": "あの俳優は若く見えるが、実はもう五十歳だ。", "target_word": "若く", "complexity_tier": "T3", "furigana": "あの俳優[はいゆう]は若[わか]く見[み]えるが、実[じつ]はもう五十歳[ごじっさい]だ。", "sentence_source": "generated"}, {"text": "この会社は社員の平均年齢が若いため、新しい企画が次々に出る。", "target_word": "若い", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は社員[しゃいん]の平均[へいきん]年齢[ねんれい]が若[わか]いため、新[あたら]しい企画[きかく]が次々[つぎつぎ]に出[で]る。", "sentence_source": "generated"}, {"text": "若き日の父は、小さな工場で働きながら夜は学校に通った。", "target_word": "若き", "complexity_tier": "T4", "furigana": "若[わか]き日[ひ]の父[ちち]は、小[ちい]さな工場[こうじょう]で働[はたら]きながら夜[よる]は学校[がっこう]に通[かよ]った。", "sentence_source": "generated"}, {"text": "店長は若いのに、五人の部下をまとめている。", "target_word": "若い", "complexity_tier": "T3", "furigana": "店長[てんちょう]は若[わか]いのに、五人[ごにん]の部下[ぶか]をまとめている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "若い", "label": "基本形"}, {"form": "若く", "label": "連用形"}, {"form": "若かった", "label": "過去形"}, {"form": "若くない", "label": "否定形"}, {"form": "若き", "label": "連体形（文語）"}], "register": "中立", "sense_fingerprint": "年齢が低い・若々しい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 張り詰める (Zipf 1.07)']::text[], 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "若き", "is_correct": true, "explanation": "文語的な連体形。『若きパン職人』の形で名詞を修飾する。"}, {"text": "若さ", "is_correct": false, "explanation": "名詞。『若さパン職人』では修飾が成り立たず、職人を直接修飾できない。"}, {"text": "若者", "is_correct": false, "explanation": "名詞。『若者パン職人』では修飾関係が成り立たず、『若者の』と書く必要がある。"}, {"text": "若げ", "is_correct": false, "explanation": "名詞（若者らしい未熟さ）。職人を修飾できず、文の意味も合わない。"}], "explanations": {"若き": "文語的な連体形。『若きパン職人』の形で名詞を修飾する。", "若さ": "名詞。『若さパン職人』では修飾が成り立たず、職人を直接修飾できない。", "若者": "名詞。『若者パン職人』では修飾関係が成り立たず、『若者の』と書く必要がある。", "若げ": "名詞（若者らしい未熟さ）。職人を修飾できず、文の意味も合わない。"}, "sentence_index": 0, "correct_answer": "若き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この靴は若いので、まだ履きやすい。", "explanation": "ここは〈新しい〉の意味。靴が新品であることは『若い』では言わない。『若い』は年齢や若々しさに使う。"}, {"text": "この計画は若いので、細かい点はまだ決まっていない。", "explanation": "ここは〈初期段階〉の意味。計画の進み具合は『若い』では言わず、『まだ初期段階だ』などで表す。"}, {"text": "この話は若いので、結末がまだ決まっていない。", "explanation": "ここは〈未完成〉の意味。話の出来ばえを『若い』では表せず、『未完成』で言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "若く", "is_correct": true, "explanation": "連用形。『見える』を修飾し、『若く見える』と自然に続く。"}, {"text": "若い", "is_correct": false, "explanation": "終止・連体形。『見える』を修飾できず、『若い見える』は誤り。"}, {"text": "若かった", "is_correct": false, "explanation": "過去形。『若かった見える』とは続かない。"}, {"text": "若々しい", "is_correct": false, "explanation": "形容詞の終止形。『若々しい見える』では文が続かない。『若々しく見える』なら可。"}], "explanations": {"若く": "連用形。『見える』を修飾し、『若く見える』と自然に続く。", "若い": "終止・連体形。『見える』を修飾できず、『若い見える』は誤り。", "若かった": "過去形。『若かった見える』とは続かない。", "若々しい": "形容詞の終止形。『若々しい見える』では文が続かない。『若々しく見える』なら可。"}, "sentence_index": 6, "correct_answer": "若く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の字は若くて、読みにくい。", "explanation": "ここは〈幼い〉の意味。字が子どもっぽいことは『幼い』で表し、『若い』では言わない。"}, {"text": "この辞書は若いので、かばんに入らない。", "explanation": "ここは〈厚い〉の意味。辞書の厚みを『若い』では表せない。『厚い』が正しい。"}, {"text": "このロープは若いので、重い荷物も運べる。", "explanation": "ここは〈強い〉の意味。ロープの丈夫さを『若い』で言うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は年のわりに考え方がとても若く。", "corrected_sentence": "祖父は年のわりに考え方がとても若い。", "error_description": "述語の活用形の誤り。『若く』は連用形で、文末では終止形『若い』にする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "若い", "is_correct": true, "explanation": "連体形。『若いころ』で名詞『ころ』を修飾する正しい形。"}, {"text": "若く", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、『若くころ』は成り立たない。"}, {"text": "若かろう", "is_correct": false, "explanation": "推量の形。『若かろうころ』では文が続かない。"}, {"text": "若ければ", "is_correct": false, "explanation": "仮定形。『若ければころ』では文が続かない。"}], "correct_form": "若い", "base_form": "若い", "form_label": "連体形", "sentence_index": 1, "explanations": {"若い": "連体形。『若いころ』で名詞『ころ』を修飾する正しい形。", "若く": "連用形。名詞を直接修飾できず、『若くころ』は成り立たない。", "若かろう": "推量の形。『若かろうころ』では文が続かない。", "若ければ": "仮定形。『若ければころ』では文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は若いに見えるので、いつも年を聞かれる。", "corrected_sentence": "彼女は若く見えるので、いつも年を聞かれる。", "error_description": "活用の誤り。『若い』に『に』は続かない。『見える』を修飾するには連用形『若く』にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "若い", "is_correct": true, "explanation": "基本形。「平均年齢が若いため」で、現在の状態を理由として示す。"}, {"text": "若ければ", "is_correct": false, "explanation": "仮定形。『平均年齢が若ければため』のように理由の『ため』に続かず、文が成り立たない。"}, {"text": "若くない", "is_correct": false, "explanation": "否定形。「若くないため」では意味が逆になり、企画が次々に出る理由と合わない。"}, {"text": "若き", "is_correct": false, "explanation": "文語の連体形。名詞の前にしか置けず、「若きため」は成り立たない。"}], "correct_form": "若い", "base_form": "若い", "form_label": "基本形", "sentence_index": 7, "explanations": {"若い": "基本形。「平均年齢が若いため」で、現在の状態を理由として示す。", "若ければ": "仮定形。『平均年齢が若ければため』のように理由の『ため』に続かず、文が成り立たない。", "若くない": "否定形。「若くないため」では意味が逆になり、企画が次々に出る理由と合わない。", "若き": "文語の連体形。名詞の前にしか置けず、「若きため」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『夜明けの空』の『の』。夜明けを空の修飾語にする正しい形。"}, {"text": "を", "is_correct": false, "explanation": "対象の『を』。『夜明けを空は』では文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。『夜明けへ空は』は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』。『夜明けが空は』では主題の関係が崩れる。"}], "correct_answer": "の", "explanations": {"の": "『夜明けの空』の『の』。夜明けを空の修飾語にする正しい形。", "を": "対象の『を』。『夜明けを空は』では文が成立しない。", "へ": "方向の『へ』。『夜明けへ空は』は意味が通らない。", "が": "主格の『が』。『夜明けが空は』では主題の関係が崩れる。"}, "error_tags": {"を": "対象格", "へ": "方向", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『夜明けの光』の『の』。夜明けを光の修飾語にする正しい形。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の『で』。『夜明けで光が』は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "対象の『を』。『夜明けを光が差して』は『差す』の項と合わず、文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』。『夜明けが光が差して』と主語が二つ並び、文が不自然になる。"}], "correct_answer": "の", "explanations": {"の": "『夜明けの光』の『の』。夜明けを光の修飾語にする正しい形。", "で": "場所・手段の『で』。『夜明けで光が』は意味が通らない。", "を": "対象の『を』。『夜明けを光が差して』は『差す』の項と合わず、文が成立しない。", "が": "主格の『が』。『夜明けが光が差して』と主語が二つ並び、文が不自然になる。"}, "error_tags": {"で": "場所・手段", "を": "対象格", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "夜が明けること。朝になって空が明るくなること。", "primary_collocate": null, "pronunciation": "よあけ", "ipa": "jo.a.ke", "syllable_count": 3, "sentences": [{"text": "夜明けに、鳥の声で目がさめました。", "target_word": "夜明け", "complexity_tier": "T2", "furigana": "夜明[よあ]けに、鳥[とり]の声[こえ]で目[め]がさめました。", "sentence_source": "generated"}, {"text": "夜明けの空は、ピンク色でとてもきれいでした。", "target_word": "夜明け", "complexity_tier": "T2", "furigana": "夜明[よあ]けの空[そら]は、ピンク色[いろ]でとてもきれいでした。", "sentence_source": "generated"}, {"text": "夜明けが来る前に、わたしたちは山をのぼり始めた。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夜明[よあ]けが来[く]る前[まえ]に、わたしたちは山[やま]をのぼり始[はじ]めた。", "sentence_source": "generated"}, {"text": "冬は夜明けがおそいので、朝七時でもまだ暗い。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "冬[ふゆ]は夜明[よあ]けがおそいので、朝[あさ]七時[しちじ]でもまだ暗[くら]い。", "sentence_source": "generated"}, {"text": "夜明けとともに、町はだんだん明るくなっていった。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夜明[よあ]けとともに、町[まち]はだんだん明[あか]るくなっていった。", "sentence_source": "generated"}, {"text": "兄は夜明けに家を出て、一番電車で空港へ向かった。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "兄[あに]は夜明[よあ]けに家[いえ]を出[で]て、一番[いちばん]電車[でんしゃ]で空港[くうこう]へ向[む]かった。", "sentence_source": "generated"}, {"text": "夜明けまで友だちと話して、そのまま学校へ行った。", "target_word": "夜明け", "complexity_tier": "T2", "furigana": "夜明[よあ]けまで友[とも]だちと話[はな]して、そのまま学校[がっこう]へ行[い]った。", "sentence_source": "generated"}, {"text": "海から夜明けの光が差してくると、船の上の人々は歓声を上げた。", "target_word": "夜明け", "complexity_tier": "T4", "furigana": "海[うみ]から夜明[よあ]けの光[ひかり]が差[さ]してくると、船[ふね]の上[うえ]の人々[ひとびと]は歓声[かんせい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "夏は夜明けが早く、四時半ごろには外が明るくなる。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夏[なつ]は夜明[よあ]けが早[はや]く、四時半[よじはん]ごろには外[そと]が明[あか]るくなる。", "sentence_source": "generated"}, {"text": "夜明けの海辺で、父と一緒に釣りをした。", "target_word": "夜明け", "complexity_tier": "T2", "furigana": "夜明[よあ]けの海辺[うみべ]で、父[ちち]と一緒[いっしょ]に釣[つ]りをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜明け", "label": "基本形"}, {"form": "夜明け前", "label": "複合形"}], "register": "中立", "sense_fingerprint": "夜が明けて空が明るくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜明け", "is_correct": true, "explanation": "『夜明けに』の『夜明け』。夜が明けて空が明るくなる時刻を指し、目が覚める場面に合う。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "日が沈む時間帯。鳥の声で目が覚める場面とは合わない。"}, {"text": "真夜中", "is_correct": false, "explanation": "夜中の一番深い時間。鳥の声で目が覚める場面には合わない。"}, {"text": "正午", "is_correct": false, "explanation": "昼の十二時。目が覚める場面とは時間帯が合わない。"}], "explanations": {"夜明け": "『夜明けに』の『夜明け』。夜が明けて空が明るくなる時刻を指し、目が覚める場面に合う。", "夕暮れ": "日が沈む時間帯。鳥の声で目が覚める場面とは合わない。", "真夜中": "夜中の一番深い時間。鳥の声で目が覚める場面には合わない。", "正午": "昼の十二時。目が覚める場面とは時間帯が合わない。"}, "sentence_index": 0, "correct_answer": "夜明け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明けになると、街灯が点き始めた。", "explanation": "ここは〈夕暮れ〉の意味。街灯が点くのは日没後で、夜明けの時刻には合わない。"}, {"text": "夜明けは午前二時に訪れた。", "explanation": "ここは〈深夜〉の意味。夜明けは空が明るくなる朝の時刻で、午前二時のような深夜の時間帯とは合わない。"}, {"text": "夜明けになると、鳥は巣に帰っていく。", "explanation": "ここは〈夕方〉の意味。鳥が巣に帰るのは夕方で、夜明けは鳥が巣から出ていく時刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜明け", "is_correct": true, "explanation": "『夜明けまで』の『夜明け』。夜通し話して、そのまま朝に学校へ行く流れに合う。"}, {"text": "昼過ぎ", "is_correct": false, "explanation": "昼過ぎまで話して学校へ直行する流れは不自然で、夜通しの話を表せない。"}, {"text": "夕方", "is_correct": false, "explanation": "夕方まで話して、そのまま学校へ行く流れは成り立たない。"}, {"text": "日暮れ", "is_correct": false, "explanation": "日暮れまで話して学校へ行く流れは不自然で、朝の登校と合わない。"}], "explanations": {"夜明け": "『夜明けまで』の『夜明け』。夜通し話して、そのまま朝に学校へ行く流れに合う。", "昼過ぎ": "昼過ぎまで話して学校へ直行する流れは不自然で、夜通しの話を表せない。", "夕方": "夕方まで話して、そのまま学校へ行く流れは成り立たない。", "日暮れ": "日暮れまで話して学校へ行く流れは不自然で、朝の登校と合わない。"}, "sentence_index": 6, "correct_answer": "夜明け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けになると、港は一気に暗くなっていく。", "explanation": "ここは〈日没〉の意味。夜明けは空が明るくなる時刻で、港が一気に暗くなる描写は日没に合う。"}, {"text": "夜明けになると、海は真っ黒に沈んでいった。", "explanation": "ここは〈夜〉の意味。夜明けは空が明るくなる時刻で、真っ黒に沈む描写とは合わない。"}, {"text": "夜明けになると、鳥の声が少しずつ消えていった。", "explanation": "ここは〈夕暮れ〉の意味。夜明けは鳥の声が増えていく時刻で、消えていく描写とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜明けを、窓の外で鳥が鳴き始めた。", "corrected_sentence": "夜明けに、窓の外で鳥が鳴き始めた。", "error_description": "時点を表す助詞の誤り。『夜明け』という時点は『に』で示す。『を』では文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52207, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは夜明けが待って、山頂へ向かった。", "corrected_sentence": "私たちは夜明けを待って、山頂へ向かった。", "error_description": "目的語の助詞の誤り。『待つ』の対象は『を』で示す。『夜明けが待って』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『夜明けの空』の『の』。夜明けを空の修飾語にする正しい形。"}, {"text": "を", "is_correct": false, "explanation": "対象の『を』。『夜明けを空は』では文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の『で』。『夜明けで空は』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。『夜明けへ空は』は文が成立しない。"}], "correct_answer": "の", "explanations": {"の": "『夜明けの空』の『の』。夜明けを空の修飾語にする正しい形。", "を": "対象の『を』。『夜明けを空は』では文が成立しない。", "で": "場所・手段の『で』。『夜明けで空は』は意味が通らない。", "へ": "方向の『へ』。『夜明けへ空は』は文が成立しない。"}, "error_tags": {"を": "対象格", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "『夜明けまで』の『まで』。継続の終点を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』。『夜明けが降り続き』は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の『と』。『夜明けと降り続き』は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "対象の『を』。『雨は夜明けを降り続き』は『降り続く』と合わず、文が成立しない。"}], "correct_answer": "まで", "explanations": {"まで": "『夜明けまで』の『まで』。継続の終点を示す正しい形。", "が": "主格の『が』。『夜明けが降り続き』は成り立たない。", "と": "並列・共同の『と』。『夜明けと降り続き』は意味が通らない。", "を": "対象の『を』。『雨は夜明けを降り続き』は『降り続く』と合わず、文が成立しない。"}, "error_tags": {"が": "主格", "と": "並列・共同", "を": "対象格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "夜が明け始める時刻。夜が明けて、空が明るくなること。また、その時刻。", "primary_collocate": null, "pronunciation": "よあけ", "ipa": "jo.a.ke", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明けの凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "夜明け", "complexity_tier": "T5", "furigana": "修業[しゅぎょう]の途上[とじょう]にある若[わか]きパン職人[しょくにん]は、夜明[よあ]けの凛[りん]とした空気[くうき]が張[は]り詰[つ]めるアトリエにて、野生[やせい]の酵母[こうぼ]が織[お]りなす微細[びさい]かつ劇的[げきてき]な化学[かがく]反応[はんのう]と黙々[もくもく]と格闘[かくとう]していた。", "sentence_source": "generated"}, {"text": "夜明けの空は、東のほうからゆっくり明るくなっていった。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夜明[よあ]けの空[そら]は、東[ひがし]のほうからゆっくり明[あか]るくなっていった。", "sentence_source": "generated"}, {"text": "山の上で夜明けを待ち、初日の出を見た。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で夜明[よあ]けを待[ま]ち、初日[はつひ]の出[で]を見[み]た。", "sentence_source": "generated"}, {"text": "夜明けが近づくにつれて、鳥の声が聞こえ始めた。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夜明[よあ]けが近[ちか]づくにつれて、鳥[とり]の声[こえ]が聞[き]こえ始[はじ]めた。", "sentence_source": "generated"}, {"text": "漁師たちは夜明けとともに船を出し、昼前に港へ戻ってくる。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "漁師[りょうし]たちは夜明[よあ]けとともに船[ふね]を出[だ]し、昼前[ひるまえ]に港[みなと]へ戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "徹夜で勉強していたら、いつの間にか夜明けになっていた。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "徹夜[てつや]で勉強[べんきょう]していたら、いつの間[ま]にか夜明[よあ]けになっていた。", "sentence_source": "generated"}, {"text": "夜明けの町は静かで、新聞を配るバイクの音だけが響いていた。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "夜明[よあ]けの町[まち]は静[しず]かで、新聞[しんぶん]を配[くば]るバイクの音[おと]だけが響[ひび]いていた。", "sentence_source": "generated"}, {"text": "雨は夜明けまで降り続き、朝には止んだ。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "雨[あめ]は夜明[よあ]けまで降[ふ]り続[つづ]き、朝[あさ]には止[や]んだ。", "sentence_source": "generated"}, {"text": "夜明けが来る前がいちばん暗いと言うが、その後の空の変化は美しい。", "target_word": "夜明け", "complexity_tier": "T4", "furigana": "夜明[よあ]けが来[く]る前[まえ]がいちばん暗[くら]いと言[い]うが、その後[ご]の空[そら]の変化[へんか]は美[うつく]しい。", "sentence_source": "generated"}, {"text": "彼らは夜明けに出発する予定だったので、前の晩は早く寝た。", "target_word": "夜明け", "complexity_tier": "T3", "furigana": "彼[かれ]らは夜明[よあ]けに出発[しゅっぱつ]する予定[よてい]だったので、前[まえ]の晩[ばん]は早[はや]く寝[ね]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜明け", "label": "基本形"}, {"form": "夜明け前", "label": "複合形"}], "register": "中立", "sense_fingerprint": "夜が明け始める時刻・明け方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 張り詰める (Zipf 1.07)','sentence 7 above tier T3: contains vocabulary far above tier T3: 降り続き (Zipf 1.58)']::text[], 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜明け", "is_correct": true, "explanation": "『夜明けの凛とした空気』の『夜明け』。夜が明け始める時刻を指し、張り詰めた明け方の空気に合う。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "夕方の時間帯。張り詰めた明け方の空気の描写とは時間帯が合わない。"}, {"text": "日没", "is_correct": false, "explanation": "日が沈む時刻。夜明け前の凛とした空気の文脈に合わない。"}, {"text": "深夜", "is_correct": false, "explanation": "夜中の時間帯。夜明け前の空気を描く文脈と合わない。"}], "explanations": {"夜明け": "『夜明けの凛とした空気』の『夜明け』。夜が明け始める時刻を指し、張り詰めた明け方の空気に合う。", "夕暮れ": "夕方の時間帯。張り詰めた明け方の空気の描写とは時間帯が合わない。", "日没": "日が沈む時刻。夜明け前の凛とした空気の文脈に合わない。", "深夜": "夜中の時間帯。夜明け前の空気を描く文脈と合わない。"}, "sentence_index": 0, "correct_answer": "夜明け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明けの空は、オレンジ色に染まりながら沈んでいった。", "explanation": "ここは〈夕暮れ〉の意味。日が沈む時間帯は『夜明け』ではなく『夕暮れ』で言う。"}, {"text": "夜明けになると、街はオレンジ色の西日に包まれた。", "explanation": "ここは〈夕焼け〉の意味。夜明けは東の空が明るくなる時刻で、西日に染まる夕焼けの情景とは合わない。"}, {"text": "夜明けの空は、ゆっくり暗くなっていった。", "explanation": "ここは〈日の入り〉の意味。夜明けは空が明るくなる時刻で、暗くなる描写とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜明け", "is_correct": true, "explanation": "『夜明けの町』の『夜明け』。朝の静けさと新聞配達のバイクの描写に合う。"}, {"text": "真夜中", "is_correct": false, "explanation": "夜中の一番深い時間。新聞配達のバイクが走る朝の町とは時間帯が違う。"}, {"text": "昼下がり", "is_correct": false, "explanation": "昼過ぎの時間帯。朝の静けさや新聞配達の描写と合わない。"}, {"text": "正午", "is_correct": false, "explanation": "昼の十二時。朝の町の描写とは合わない。"}], "explanations": {"夜明け": "『夜明けの町』の『夜明け』。朝の静けさと新聞配達のバイクの描写に合う。", "真夜中": "夜中の一番深い時間。新聞配達のバイクが走る朝の町とは時間帯が違う。", "昼下がり": "昼過ぎの時間帯。朝の静けさや新聞配達の描写と合わない。", "正午": "昼の十二時。朝の町の描写とは合わない。"}, "sentence_index": 6, "correct_answer": "夜明け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けになると、通りはだんだん暗くなっていった。", "explanation": "ここは〈夜〉の意味。夜明けは明るくなっていく時刻で、暗くなる描写とは合わない。"}, {"text": "夜明けが西の空を赤く染めていた。", "explanation": "ここは〈夕焼け〉の意味。夜明けは東の空が明るくなる時刻で、西の空の夕焼けには使わない。"}, {"text": "夜明けの空は、西のほうからゆっくり暗くなっていった。", "explanation": "ここは〈日没〉の意味。夜明けは空が明るくなる時刻で、日が沈む描写とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜明けの、空が少しずつ明るくなった。", "corrected_sentence": "夜明けに、空が少しずつ明るくなった。", "error_description": "時点を表す助詞の誤り。『夜明け』の後に『の』を置くと文が途中で切れてしまう。時点は『に』で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨は夜明けに降り続き、昼前には止んだ。", "corrected_sentence": "雨は夜明けまで降り続き、昼前には止んだ。", "error_description": "継続の終点を示す助詞の誤り。『降り続く』の範囲は『まで』で示す。『夜明けに』では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
