INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「休む」の目的語を示す。「修業を休まなかった」は練習を怠らなかったという意味で自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「修業と一日も休まなかった」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「修業へ一日も休まなかった」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、「修業より一日も休まなかった」では比べる相手がなく文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「休む」の目的語を示す。「修業を休まなかった」は練習を怠らなかったという意味で自然。", "と": "「と」は並列や引用を示し、「修業と一日も休まなかった」では文が成り立たない。", "へ": "「へ」は方向を示し、「修業へ一日も休まなかった」は意味が通らない。", "より": "「より」は比較を示し、「修業より一日も休まなかった」では比べる相手がなく文が崩れる。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを上手にできるようになるために、長い間、練習をすること。", "primary_collocate": null, "pronunciation": "しゅぎょう", "ipa": "ɕɯɡʲoː", "syllable_count": 3, "sentences": [{"text": "ピアノが上手になるには、毎日の修業が欠かせない。", "target_word": "修業", "complexity_tier": "T3", "furigana": "ピアノが上手[じょうず]になるには、毎日[まいにち]の修業[しゅぎょう]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "書道の腕を上げたくて、三年間、先生のもとで修業を続けた。", "target_word": "修業", "complexity_tier": "T3", "furigana": "書道[しょどう]の腕[うで]を上[あ]げたくて、三年間[さんねんかん]、先生[せんせい]のもとで修業[しゅぎょう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は一流の料理人になるために、毎晩遅くまで包丁の修業に励んでいる。", "target_word": "修業", "complexity_tier": "T3", "furigana": "彼[かれ]は一流[いちりゅう]の料理人[りょうりにん]になるために、毎晩[まいばん]遅[おそ]くまで包丁[ほうちょう]の修業[しゅぎょう]に励[はげ]んでいる。", "sentence_source": "generated"}, {"text": "剣道の修業は長い道のりで、すぐに強くなれるものではない。", "target_word": "修業", "complexity_tier": "T3", "furigana": "剣道[けんどう]の修業[しゅぎょう]は長[なが]い道[みち]のりで、すぐに強[つよ]くなれるものではない。", "sentence_source": "generated"}, {"text": "落語家を目指す彼は、師匠の家に住み込んで修業をしている。", "target_word": "修業", "complexity_tier": "T3", "furigana": "落語家[らくごか]を目指[めざ]す彼[かれ]は、師匠[ししょう]の家[いえ]に住[す]み込[こ]んで修業[しゅぎょう]をしている。", "sentence_source": "generated"}, {"text": "修業を重ねるうちに、難しかった技も自然にできるようになった。", "target_word": "修業", "complexity_tier": "T3", "furigana": "修業[しゅぎょう]を重[かさ]ねるうちに、難[むずか]しかった技[わざ]も自然[しぜん]にできるようになった。", "sentence_source": "generated"}, {"text": "私はまだ修業の身なので、人に教えるのは早すぎる。", "target_word": "修業", "complexity_tier": "T3", "furigana": "私[わたし]はまだ修業[しゅぎょう]の身[み]なので、人[ひと]に教[おし]えるのは早[はや]すぎる。", "sentence_source": "generated"}, {"text": "彼女は歌がうまくなるまで、地道な修業を一日も休まなかった。", "target_word": "修業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌[うた]がうまくなるまで、地道[じみち]な修業[しゅぎょう]を一日[いちにち]も休[やす]まなかった。", "sentence_source": "generated"}, {"text": "茶道の修業を始めたころは、正座だけで足がしびれて大変だった。", "target_word": "修業", "complexity_tier": "T3", "furigana": "茶道[さどう]の修業[しゅぎょう]を始[はじ]めたころは、正座[せいざ]だけで足[あし]がしびれて大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "もっと上達したいなら、基本を繰り返す修業が大切だ。", "target_word": "修業", "complexity_tier": "T3", "furigana": "もっと上達[じょうたつ]したいなら、基本[きほん]を繰[く]り返[かえ]す修業[しゅぎょう]が大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "修業", "label": "基本形"}, {"form": "修業する", "label": "サ変動詞形"}, {"form": "修業した", "label": "夕形"}], "register": "中立", "sense_fingerprint": "上達するために長い間練習を続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渋滞", "is_correct": false, "explanation": "「毎日の渋滞が欠かせない」は意味が通らず、ピアノの上達とは結びつかない。"}, {"text": "修業", "is_correct": true, "explanation": "上達のために長く練習を続けることを表し、「毎日の」「欠かせない」と合う。"}, {"text": "納品", "is_correct": false, "explanation": "納品は品物を届けることで、ピアノの上達を述べる文には合わない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、練習の継続を表す文脈には当てはまらない。"}], "explanations": {"渋滞": "「毎日の渋滞が欠かせない」は意味が通らず、ピアノの上達とは結びつかない。", "修業": "上達のために長く練習を続けることを表し、「毎日の」「欠かせない」と合う。", "納品": "納品は品物を届けることで、ピアノの上達を述べる文には合わない。", "停電": "停電は電気が止まることで、練習の継続を表す文脈には当てはまらない。"}, "sentence_index": 0, "correct_answer": "修業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の前日は、部屋の修業を一時間だけして早めに寝ることにしている。", "explanation": "ここは〈掃除〉の意味。修業は上達のための長い練習で、部屋を片づける意味では使わない。"}, {"text": "先生に作文の修業を頼んで、誤字を直してもらった。", "explanation": "ここは〈修正〉の意味。修業は上達のために練習を続けることで、文章を直す意味はない。"}, {"text": "新入社員は入社後、三日間の修業を受けてから現場に出る。", "explanation": "ここは〈研修〉の意味。修業は長い期間にわたる上達のための練習で、短期の社内研修には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会議", "is_correct": false, "explanation": "「まだ会議の身なので」は意味が通らず、修業の立場を表す文に合わない。"}, {"text": "出勤", "is_correct": false, "explanation": "「まだ出勤の身」は意味が通らず、まだ学んでいる立場を表せない。"}, {"text": "修業", "is_correct": true, "explanation": "まだ一人前ではなく学んでいる立場を表し、「人に教えるのは早すぎる」と合う。"}, {"text": "欠勤", "is_correct": false, "explanation": "欠勤は仕事を休むことで、学びの立場を表す「身」の語とは結びつかない。"}], "explanations": {"会議": "「まだ会議の身なので」は意味が通らず、修業の立場を表す文に合わない。", "出勤": "「まだ出勤の身」は意味が通らず、まだ学んでいる立場を表せない。", "修業": "まだ一人前ではなく学んでいる立場を表し、「人に教えるのは早すぎる」と合う。", "欠勤": "欠勤は仕事を休むことで、学びの立場を表す「身」の語とは結びつかない。"}, "sentence_index": 6, "correct_answer": "修業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、公園を一時間修業している。", "explanation": "ここは〈散歩〉の意味。修業は上達のための練習で、歩いて楽しむ行為には使わない。"}, {"text": "壊れた絵画を、専門家が一週間かけて修業した。", "explanation": "ここは〈修復〉の意味。修業は上達のために練習を続けることで、絵を直す意味はない。"}, {"text": "明日の朝、新幹線で修業する予定だ。", "explanation": "ここは〈出発〉の意味。修業は練習を続けることで、移動を始める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日、ギターの修業で励んでいる。", "corrected_sentence": "彼は毎日、ギターの修業に励んでいる。", "error_description": "誤: 「修業で励んでいる」／正: 「修業に励んでいる」。「励む」は対象を「に」で示すため、「で」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は三年間、剣道の修業を磨き続けた。", "corrected_sentence": "彼は三年間、剣道の修業を続けた。", "error_description": "誤: 「修業を磨き続けた」／正: 「修業を続けた」。「磨く」は技や腕に使い、「修業」には「続ける」が合う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩む", "is_correct": true, "explanation": "緊張が解けて引き締まりがなくなるという意味で、張り詰めるの対義語として辞書に載る。"}, {"text": "広がる", "is_correct": false, "explanation": "広がるは範囲が大きくなることで、張り詰めるの対義語ではない。"}, {"text": "集まる", "is_correct": false, "explanation": "集まるは人や物が一つにまとまることで、張り詰めるの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休息の状態を表し、張り詰めるの対義語として辞書に載る語ではない。"}], "correct_answer": "緩む", "explanations": {"緩む": "緊張が解けて引き締まりがなくなるという意味で、張り詰めるの対義語として辞書に載る。", "広がる": "広がるは範囲が大きくなることで、張り詰めるの対義語ではない。", "集まる": "集まるは人や物が一つにまとまることで、張り詰めるの対義語ではない。", "眠る": "眠るは休息の状態を表し、張り詰めるの対義語として辞書に載る語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「張り詰めていた」の主語（神経）を示し、「神経が張り詰めていた」と自然につながる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「神経と張り詰めていた」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「神経へ張り詰めていた」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、「神経より張り詰めていた」では比べる相手がなく文が崩れる。"}], "correct_answer": "が", "explanations": {"が": "「張り詰めていた」の主語（神経）を示し、「神経が張り詰めていた」と自然につながる。", "と": "「と」は並列や引用を示し、「神経と張り詰めていた」では文が成り立たない。", "へ": "「へ」は方向を示し、「神経へ張り詰めていた」は意味が通らない。", "より": "「より」は比較を示し、「神経より張り詰めていた」では比べる相手がなく文が崩れる。"}, "error_tags": {"が": "主語", "と": "並列・引用", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩む", "is_correct": true, "explanation": "緊張が解けて引き締まりがなくなるという意味で、張り詰めるの対義語として辞書に載る。"}, {"text": "戻る", "is_correct": false, "explanation": "戻るは元の場所や状態に返ることで、張り詰めるの対義語ではない。"}, {"text": "沈む", "is_correct": false, "explanation": "沈むは下へ入り込むことで、張り詰めるの対義語ではない。"}, {"text": "届く", "is_correct": false, "explanation": "届くは物や知らせが目的地に着くことで、張り詰めるの対義語ではない。"}], "correct_answer": "緩む", "explanations": {"緩む": "緊張が解けて引き締まりがなくなるという意味で、張り詰めるの対義語として辞書に載る。", "戻る": "戻るは元の場所や状態に返ることで、張り詰めるの対義語ではない。", "沈む": "沈むは下へ入り込むことで、張り詰めるの対義語ではない。", "届く": "届くは物や知らせが目的地に着くことで、張り詰めるの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "心や空気がとても強くて、ぴんと張ったようになること。", "primary_collocate": null, "pronunciation": "はりつめる", "ipa": "haɾitsɯmeɾɯ", "syllable_count": 5, "sentences": [{"text": "大事な試合の前は、いつも心が張り詰めてしまう。", "target_word": "張り詰めて", "complexity_tier": "T3", "furigana": "大事[だいじ]な試合[しあい]の前[まえ]は、いつも心[こころ]が張[は]り詰[つ]めてしまう。", "sentence_source": "generated"}, {"text": "部屋に入ると、張り詰めた空気が肌で感じられた。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "部屋[へや]に入[はい]ると、張[は]り詰[つ]めた空気[くうき]が肌[はだ]で感[かん]じられた。", "sentence_source": "generated"}, {"text": "先生が黙って全員の顔を見回すと、教室の空気が張り詰めた。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "先生[せんせい]が黙[だま]って全員[ぜんいん]の顔[かお]を見回[みまわ]すと、教室[きょうしつ]の空気[くうき]が張[は]り詰[つ]めた。", "sentence_source": "generated"}, {"text": "毎日張り詰めた気持ちで働いていたので、休みの日は一日中寝ていた。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "毎日[まいにち]張[は]り詰[つ]めた気持[きも]ちで働[はたら]いていたので、休[やす]みの日[ひ]は一日中[いちにちじゅう]寝[ね]ていた。", "sentence_source": "generated"}, {"text": "二人の間には、今にも口論が始まりそうな張り詰めた空気があった。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "二人[ふたり]の間[あいだ]には、今[いま]にも口論[こうろん]が始[はじ]まりそうな張[は]り詰[つ]めた空気[くうき]があった。", "sentence_source": "generated"}, {"text": "発表を待つ間、家族みんなの心が張り詰めていた。", "target_word": "張り詰めて", "complexity_tier": "T3", "furigana": "発表[はっぴょう]を待[ま]つ間[あいだ]、家族[かぞく]みんなの心[こころ]が張[は]り詰[つ]めていた。", "sentence_source": "generated"}, {"text": "張り詰めた雰囲気の中で、試験官は静かに問題用紙を配り始めた。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "張[は]り詰[つ]めた雰囲気[ふんいき]の中[なか]で、試験官[しけんかん]は静[しず]かに問題用紙[もんだいようし]を配[くば]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "長い間神経が張り詰めていたせいで、肩がすっかりこってしまった。", "target_word": "張り詰めて", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]神経[しんけい]が張[は]り詰[つ]めていたせいで、肩[かた]がすっかりこってしまった。", "sentence_source": "generated"}, {"text": "犯人が動いた瞬間、現場の空気がぴんと張り詰めた。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "犯人[はんにん]が動[うご]いた瞬間[しゅんかん]、現場[げんば]の空気[くうき]がぴんと張[は]り詰[つ]めた。", "sentence_source": "generated"}, {"text": "張り詰めた気持ちをほぐすために、彼は温かいお茶をゆっくり飲んだ。", "target_word": "張り詰めた", "complexity_tier": "T3", "furigana": "張[は]り詰[つ]めた気持[きも]ちをほぐすために、彼[かれ]は温[あたた]かいお茶[ちゃ]をゆっくり飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "張り詰める", "label": "辞書形"}, {"form": "張り詰めた", "label": "夕形"}, {"form": "張り詰めて", "label": "テ形"}, {"form": "張り詰めない", "label": "ナイ形"}, {"form": "張り詰めている", "label": "継続形"}], "register": "中立", "sense_fingerprint": "心や空気がぴんと強く張ったように緊張した状態になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "張り詰めて", "is_correct": true, "explanation": "大事な試合の前に心が引き締まってしまうという状態を表し、文脈と合う。"}, {"text": "縛って", "is_correct": false, "explanation": "「縛る」は物をくくる動作で、「心が縛ってしまう」は主語と合わない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は他動詞で、「心が磨いてしまう」は主語と合わない。"}, {"text": "蒸発して", "is_correct": false, "explanation": "蒸発は液体が気体になることで、心の緊張を表す文とは結びつかない。"}], "explanations": {"張り詰めて": "大事な試合の前に心が引き締まってしまうという状態を表し、文脈と合う。", "縛って": "「縛る」は物をくくる動作で、「心が縛ってしまう」は主語と合わない。", "磨いて": "「磨く」は他動詞で、「心が磨いてしまう」は主語と合わない。", "蒸発して": "蒸発は液体が気体になることで、心の緊張を表す文とは結びつかない。"}, "sentence_index": 0, "correct_answer": "張り詰めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "掲示板に告知の紙を張り詰めた。", "explanation": "ここは〈貼る〉の意味。張り詰めるは心や空気が引き締まることで、紙を貼る意味はない。"}, {"text": "嫌な思い出が心に張り詰めた。", "explanation": "ここは〈残る〉の意味。張り詰めるは緊張で引き締まることで、思い出が残る意味はない。"}, {"text": "夜通し雨が張り詰めた。", "explanation": "ここは〈降る〉の意味。張り詰めるは引き締まった状態を表すので、雨が降る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "張り詰めた", "is_correct": true, "explanation": "試験前の緊張した雰囲気を表し、「雰囲気の中で」と自然につながる。"}, {"text": "焼け落ちた", "is_correct": false, "explanation": "焼け落ちるは建物などが火で崩れることで、雰囲気を表す文には合わない。"}, {"text": "干からびた", "is_correct": false, "explanation": "干からびるは水分が失われることで、教室の雰囲気を表す語としては不自然。"}, {"text": "割れた", "is_correct": false, "explanation": "割れるは物が砕けることで、張り詰めた雰囲気の文脈には合わない。"}], "explanations": {"張り詰めた": "試験前の緊張した雰囲気を表し、「雰囲気の中で」と自然につながる。", "焼け落ちた": "焼け落ちるは建物などが火で崩れることで、雰囲気を表す文には合わない。", "干からびた": "干からびるは水分が失われることで、教室の雰囲気を表す語としては不自然。", "割れた": "割れるは物が砕けることで、張り詰めた雰囲気の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "張り詰めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靴紐をぎゅっと張り詰めて結んだ。", "explanation": "ここは〈締める〉の意味。締めるは物を強く縛る動作で、張り詰めるは状態を表す語なので使えない。"}, {"text": "庭の桜が一斉に張り詰めた。", "explanation": "ここは〈咲く〉の意味。張り詰めるは心や空気の引き締まりで、花が咲く意味では使わない。"}, {"text": "お茶がすっかり張り詰めてしまった。", "explanation": "ここは〈冷める〉の意味。張り詰めるは緊張による引き締まりで、お茶の温度が下がる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議室の空気を張り詰めて、誰も話せなかった。", "corrected_sentence": "会議室の空気が張り詰めて、誰も話せなかった。", "error_description": "誤: 「空気を張り詰めて」／正: 「空気が張り詰めて」。「張り詰める」は自動詞で、主語に「が」を取るため「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "張り詰めた", "is_correct": true, "explanation": "夕形で名詞「空気」を修飾し、前から続く張り詰めた状態を表す。"}, {"text": "張り詰めて", "is_correct": false, "explanation": "テ形は名詞を直接修飾できず、「張り詰めて空気」は成り立たない。"}, {"text": "張り詰めよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「張り詰めよう空気」は成り立たない。"}, {"text": "張り詰めます", "is_correct": false, "explanation": "丁寧体は名詞を修飾できず、「張り詰めます空気」は誤り。"}], "correct_form": "張り詰めた", "base_form": "張り詰める", "form_label": "夕形", "sentence_index": 1, "explanations": {"張り詰めた": "夕形で名詞「空気」を修飾し、前から続く張り詰めた状態を表す。", "張り詰めて": "テ形は名詞を直接修飾できず、「張り詰めて空気」は成り立たない。", "張り詰めよう": "意志形は名詞を修飾できず、「張り詰めよう空気」は成り立たない。", "張り詰めます": "丁寧体は名詞を修飾できず、「張り詰めます空気」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52213, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室の空気がずっと張り詰めらなかった。", "corrected_sentence": "教室の空気がずっと張り詰めなかった。", "error_description": "誤: 「張り詰めらなかった」／正: 「張り詰めなかった」。「張り詰める」に「られる」は付かず、否定過去形は「張り詰めなかった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "張り詰めて", "is_correct": true, "explanation": "「張り詰めていた」の一部で、神経が張った状態の継続を表す。"}, {"text": "張り詰めよう", "is_correct": false, "explanation": "意志形になり、「せいで」の原因として続く過去の状態の描写と合わない。"}, {"text": "張り詰めれば", "is_correct": false, "explanation": "仮定形は条件を表し、「せいで」で結ばれる原因の述べ方と合わない。"}, {"text": "張り詰めさせて", "is_correct": false, "explanation": "使役形では別の誰かに張らせる意味になり、主語の神経が張り詰めた文と合わない。"}], "correct_form": "張り詰めて", "base_form": "張り詰める", "form_label": "テ形", "sentence_index": 7, "explanations": {"張り詰めて": "「張り詰めていた」の一部で、神経が張った状態の継続を表す。", "張り詰めよう": "意志形になり、「せいで」の原因として続く過去の状態の描写と合わない。", "張り詰めれば": "仮定形は条件を表し、「せいで」で結ばれる原因の述べ方と合わない。", "張り詰めさせて": "使役形では別の誰かに張らせる意味になり、主語の神経が張り詰めた文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
