INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52221, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「しばしば」「よく」という意味で、ある事がらが例外はあるものの起こりがちであることを表す言葉です。", "primary_collocate": null, "pronunciation": "おうおう", "ipa": "oːoː", "syllable_count": 4, "sentences": [{"text": "急いでいるときは、往々にして忘れ物をする。", "target_word": "往々", "complexity_tier": "T3", "furigana": "急[いそ]いでいるときは、往々[おうおう]にして忘[わす]れ物[もの]をする。", "sentence_source": "generated"}, {"text": "初心者は往々にして、基本を軽く見がちだ。", "target_word": "往々", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]は往々[おうおう]にして、基本[きほん]を軽[かる]く見[み]がちだ。", "sentence_source": "generated"}, {"text": "有名な店でも、味が落ちることは往々にしてある。", "target_word": "往々", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な店[みせ]でも、味[あじ]が落[お]ちることは往々[おうおう]にしてある。", "sentence_source": "generated"}, {"text": "天気予報は、往々にして外れることがある。", "target_word": "往々", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]は、往々[おうおう]にして外[はず]れることがある。", "sentence_source": "generated"}, {"text": "人は自分のミスに、往々にして気づかないものだ。", "target_word": "往々", "complexity_tier": "T3", "furigana": "人[ひと]は自分[じぶん]のミスに、往々[おうおう]にして気[き]づかないものだ。", "sentence_source": "generated"}, {"text": "安い品物は、往々にしてすぐ壊れてしまう。", "target_word": "往々", "complexity_tier": "T3", "furigana": "安[やす]い品物[しなもの]は、往々[おうおう]にしてすぐ壊[こわ]れてしまう。", "sentence_source": "generated"}, {"text": "親切のつもりの言葉が、往々にして相手を傷つける。", "target_word": "往々", "complexity_tier": "T3", "furigana": "親切[しんせつ]のつもりの言葉[ことば]が、往々[おうおう]にして相手[あいて]を傷[きず]つける。", "sentence_source": "generated"}, {"text": "夜中に書いた手紙は、往々にして読み返すと恥ずかしい。", "target_word": "往々", "complexity_tier": "T3", "furigana": "夜中[よなか]に書[か]いた手紙[てがみ]は、往々[おうおう]にして読[よ]み返[かえ]すと恥[は]ずかしい。", "sentence_source": "generated"}, {"text": "若いうちは、往々にして失敗から学ぶものだ。", "target_word": "往々", "complexity_tier": "T3", "furigana": "若[わか]いうちは、往々[おうおう]にして失敗[しっぱい]から学[まな]ぶものだ。", "sentence_source": "generated"}, {"text": "疲れていると、往々にして小さなことで怒ってしまう。", "target_word": "往々", "complexity_tier": "T3", "furigana": "疲[つか]れていると、往々[おうおう]にして小[ちい]さなことで怒[おこ]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "往々", "label": "基本形（副詞）"}, {"form": "往々にして", "label": "慣用形"}], "register": "formal", "sense_fingerprint": "ある事がらがしばしば起こりがちであることを表す（往々にして）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往々", "is_correct": true, "explanation": "「往々にして」は「よく〜しがちだ」の意味で、「忘れ物をする」と自然につながる。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は否定の述語と呼応するので、肯定の「忘れ物をする」には続かない。"}, {"text": "一切", "is_correct": false, "explanation": "「一切」も否定と呼応する副詞で、肯定文の空欄には入らない。"}, {"text": "滅多に", "is_correct": false, "explanation": "「滅多に」は「〜ない」を伴う語で、「忘れ物をする」と肯定で続けると文が成り立たない。"}], "explanations": {"往々": "「往々にして」は「よく〜しがちだ」の意味で、「忘れ物をする」と自然につながる。", "決して": "「決して」は否定の述語と呼応するので、肯定の「忘れ物をする」には続かない。", "一切": "「一切」も否定と呼応する副詞で、肯定文の空欄には入らない。", "滅多に": "「滅多に」は「〜ない」を伴う語で、「忘れ物をする」と肯定で続けると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "往々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の試合は、往々にして勝った。", "explanation": "ここは〈一度きり〉（一回だけ起こる）の意味と混同した例。〈往々〉は繰り返し起こりがちな傾向を表すので、昨日の一試合の結果には合わない。"}, {"text": "明日は、往々にして来てください。", "explanation": "〈往々〉は傾向を述べる語で、相手への依頼や命令には使えない。〈必ず〉と混同した例。"}, {"text": "私の誕生日は、往々にして三月十日だ。", "explanation": "ここは〈常に〉（例外なく決まっている）の意味と混同した例。〈往々〉は多くの場合の傾向なので、生まれた日のように変わらない事実には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往々", "is_correct": true, "explanation": "「往々にして」は「よく〜しがちだ」の意味で、「相手を傷つける」と自然につながる。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は否定と呼応する副詞で、肯定の「相手を傷つける」とは続かない。"}, {"text": "一向に", "is_correct": false, "explanation": "「一向に」は「〜ない」を伴う副詞で、肯定の文には入らない。"}, {"text": "断じて", "is_correct": false, "explanation": "「断じて」は「〜ない」と呼応するので、肯定の「傷つける」に合わない。"}], "explanations": {"往々": "「往々にして」は「よく〜しがちだ」の意味で、「相手を傷つける」と自然につながる。", "少しも": "「少しも」は否定と呼応する副詞で、肯定の「相手を傷つける」とは続かない。", "一向に": "「一向に」は「〜ない」を伴う副詞で、肯定の文には入らない。", "断じて": "「断じて」は「〜ない」と呼応するので、肯定の「傷つける」に合わない。"}, "sentence_index": 6, "correct_answer": "往々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この工事は、往々にして一度で終わった。", "explanation": "ここは〈単発〉（一回きりの出来事）の意味と混同した例。〈往々〉は繰り返し起こりがちな傾向なので、一度で終わった工事の説明には合わない。"}, {"text": "借りた本は、往々にしてお返しします。", "explanation": "〈往々〉は傾向を述べる語で、〈必ず〉のような約束の表現には使えない。"}, {"text": "この薬は、往々にして百パーセント効く。", "explanation": "ここは〈絶対に〉（例外なく確かに）の意味と混同した例。〈往々〉は多くの場合の傾向なので、確実な効果を保証する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、往々をして電車が遅れる。", "corrected_sentence": "雨の日は、往々にして電車が遅れる。", "error_description": "「往々にして」という決まった形の「に」が「を」になっている。「往々を」は成り立たず、正しくは「往々にして」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人は、往々に都合の悪いことを忘れる。", "corrected_sentence": "人は、往々にして都合の悪いことを忘れる。", "error_description": "「往々にして」の「して」が抜けている。「往々に」だけでは決まった形にならず、正しくは「往々にして」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "特有の対義語。ほかの人にも見られる性質を表し、特有と反対になる。"}, {"text": "無関係", "is_correct": false, "explanation": "関わりがないという意味で、性質の広さを表す対義語ではない。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に害を与える意味で、特有の対義語ではない。"}, {"text": "不要", "is_correct": false, "explanation": "要らないという意味で、特有とは対になる関係ではない。"}], "correct_answer": "共通", "explanations": {"共通": "特有の対義語。ほかの人にも見られる性質を表し、特有と反対になる。", "無関係": "関わりがないという意味で、性質の広さを表す対義語ではない。", "迷惑": "人に害を与える意味で、特有の対義語ではない。", "不要": "要らないという意味で、特有とは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。"}, {"text": "不便", "is_correct": false, "explanation": "使いにくさを表す語で、特有の対義語ではない。"}, {"text": "無謀", "is_correct": false, "explanation": "向こう見ずの意味で、性質の広さを表す対義語ではない。"}, {"text": "過剰", "is_correct": false, "explanation": "程度が多すぎる意味で、特有の対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。", "不便": "使いにくさを表す語で、特有の対義語ではない。", "無謀": "向こう見ずの意味で、性質の広さを表す対義語ではない。", "過剰": "程度が多すぎる意味で、特有の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "そのものだけが持っている、ほかにはない特徴のこと。", "primary_collocate": null, "pronunciation": "とくゆう", "ipa": "tokɯjɯː", "syllable_count": 4, "sentences": [{"text": "京都の冬には、底冷えという特有の寒さがある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "京都[きょうと]の冬[ふゆ]には、底冷[そこび]えという特有[とくゆう]の寒[さむ]さがある。", "sentence_source": "generated"}, {"text": "外国語を学ぶと、その言語特有の考え方に気づくことがある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "外国語[がいこくご]を学[まな]ぶと、その言語[げんご]特有[とくゆう]の考[かんが]え方[かた]に気[き]づくことがある。", "sentence_source": "generated"}, {"text": "このカレーはスパイスの特有の香りが食欲をそそる。", "target_word": "特有", "complexity_tier": "T3", "furigana": "このカレーはスパイスの特有[とくゆう]の香[かお]りが食欲[しょくよく]をそそる。", "sentence_source": "generated"}, {"text": "緊張したときに早口になるのは、彼特有のくせだ。", "target_word": "特有", "complexity_tier": "T3", "furigana": "緊張[きんちょう]したときに早口[はやくち]になるのは、彼[かれ]特有[とくゆう]のくせだ。", "sentence_source": "generated"}, {"text": "雪国特有の知恵として、家の屋根を急な形に作る習慣がある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "雪国[ゆきぐに]特有[とくゆう]の知恵[ちえ]として、家[いえ]の屋根[やね]を急[きゅう]な形[かたち]に作[つく]る習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "深海の生き物には、暗い環境に特有の体のつくりを持つものが多い。", "target_word": "特有", "complexity_tier": "T3", "furigana": "深海[しんかい]の生[い]き物[もの]には、暗[くら]い環境[かんきょう]に特有[とくゆう]の体[からだ]のつくりを持[も]つものが多[おお]い。", "sentence_source": "generated"}, {"text": "日本語特有の表現は、そのまま外国語に訳しにくい。", "target_word": "特有", "complexity_tier": "T3", "furigana": "日本語[にほんご]特有[とくゆう]の表現[ひょうげん]は、そのまま外国語[がいこくご]に訳[やく]しにくい。", "sentence_source": "generated"}, {"text": "祖母の漬け物には、家庭ごとに特有の味がある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "祖母[そぼ]の漬[つ]け物[もの]には、家庭[かてい]ごとに特有[とくゆう]の味[あじ]がある。", "sentence_source": "generated"}, {"text": "寺の鐘の音は、静かな夜に特有の響きを持って聞こえた。", "target_word": "特有", "complexity_tier": "T3", "furigana": "寺[てら]の鐘[かね]の音[おと]は、静[しず]かな夜[よる]に特有[とくゆう]の響[ひび]きを持[も]って聞[き]こえた。", "sentence_source": "generated"}, {"text": "若者特有の言葉づかいを、年配の人は理解できないことが多い。", "target_word": "特有", "complexity_tier": "T3", "furigana": "若者[わかもの]特有[とくゆう]の言葉[ことば]づかいを、年配[ねんぱい]の人[ひと]は理解[りかい]できないことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特有", "label": "語幹"}, {"form": "特有の", "label": "連体形"}, {"form": "特有で", "label": "連用形"}, {"form": "特有だ", "label": "終止形"}], "register": "中立", "sense_fingerprint": "そのものだけが持つ、ほかには見られない特徴を表す。「〜特有の＋名詞」の形が基本。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 底冷え (Zipf 1.48)']::text[], 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "「底冷えという特有の寒さ」で、京都の冬だけの寒さを表し文脈に合う。"}, {"text": "無関係", "is_correct": false, "explanation": "「無関係の寒さ」は意味が通らず、底冷えの説明と合わない。"}, {"text": "迷惑", "is_correct": false, "explanation": "「迷惑な寒さ」は人に害を与える意味で、寒さの特徴を表せない。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な寒さ」は要らないという意味で、文の説明と合わない。"}], "explanations": {"特有": "「底冷えという特有の寒さ」で、京都の冬だけの寒さを表し文脈に合う。", "無関係": "「無関係の寒さ」は意味が通らず、底冷えの説明と合わない。", "迷惑": "「迷惑な寒さ」は人に害を与える意味で、寒さの特徴を表せない。", "不要": "「不要な寒さ」は要らないという意味で、文の説明と合わない。"}, "sentence_index": 0, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この祭りは、どの町にも特有のものとして行われている。", "explanation": "ここは〈共通〉の意味。特有はほかにはない性質なので、どの町でも行われる行事には使わない。"}, {"text": "連絡は、特有の担当者だけに伝えられた。", "explanation": "ここは〈特定〉の意味。特有は性質を表すので、特定の人を選び出す場面には使わない。"}, {"text": "この料理は、どの家庭にもあるありふれた特有の味だ。", "explanation": "ここは〈一般的〉の意味。特有はほかにない特徴を指すので、どの家庭にもある味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "「日本語特有の表現」で、日本語だけに見られる性質を表し文脈に合う。"}, {"text": "過剰", "is_correct": false, "explanation": "「過剰な表現」は多すぎる意味で、訳しにくさの説明と結びつかない。"}, {"text": "乱暴", "is_correct": false, "explanation": "「乱暴な表現」は荒っぽい意味で、表現の性質を表せない。"}, {"text": "無謀", "is_correct": false, "explanation": "「無謀な表現」は向こう見ずの意味で、文の内容と合わない。"}], "explanations": {"特有": "「日本語特有の表現」で、日本語だけに見られる性質を表し文脈に合う。", "過剰": "「過剰な表現」は多すぎる意味で、訳しにくさの説明と結びつかない。", "乱暴": "「乱暴な表現」は荒っぽい意味で、表現の性質を表せない。", "無謀": "「無謀な表現」は向こう見ずの意味で、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若者にも年配の人にも同様に特有の言葉づかいが見られる。", "explanation": "ここは〈共通〉の意味。特有は他にない性質を表すので、両方に当てはまる場面には使わない。"}, {"text": "若者の言葉づかいは、特有名詞として辞書に載せるべきだ。", "explanation": "ここは〈固有〉の意味。個別の名前を表す語は固有名詞で、特有名詞とは言わない。"}, {"text": "若者の言葉づかいは、どの世代にも特有のものとして同じように使われている。", "explanation": "ここは〈一般的〉の意味。特有はほかにない特徴を指すので、どの世代にも使われる言葉には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの夜には、町特有に太鼓の音が響く。", "corrected_sentence": "祭りの夜には、町特有の太鼓の音が響く。", "error_description": "「特有」は名詞を修飾するときに「特有の」の形を取る。「特有に」は誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "特有", "is_correct": true, "explanation": "「その言語特有の考え方」で、名詞を修飾する語幹の形。"}, {"text": "特有な", "is_correct": false, "explanation": "「特有な」は後ろの「の」と続かず、この位置では合わない。"}, {"text": "特有に", "is_correct": false, "explanation": "連用形は「の」の前に置けず、名詞修飾の位置に合わない。"}, {"text": "特有で", "is_correct": false, "explanation": "「で」は中止の形で、後ろに「の考え方」が続く位置では成り立たない。"}], "correct_form": "特有", "base_form": "特有", "form_label": "語幹", "sentence_index": 1, "explanations": {"特有": "「その言語特有の考え方」で、名詞を修飾する語幹の形。", "特有な": "「特有な」は後ろの「の」と続かず、この位置では合わない。", "特有に": "連用形は「の」の前に置けず、名詞修飾の位置に合わない。", "特有で": "「で」は中止の形で、後ろに「の考え方」が続く位置では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52227, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏祭りの屋台は、地方特有味が豊かだ。", "corrected_sentence": "夏祭りの屋台は、地方特有の味が豊かだ。", "error_description": "「特有」が名詞「味」を修飾するには「特有の」が必要で、「の」が欠けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "特有", "is_correct": true, "explanation": "「家庭ごとに特有の味」で、名詞「味」を修飾する語幹の形。"}, {"text": "特有だ", "is_correct": false, "explanation": "終止形は名詞の前に直接つかず、「の味」と続かないので、この位置では成り立たない。"}, {"text": "特有である", "is_correct": false, "explanation": "断定の形は名詞を修飾する位置に置けず、「の味」と続けられない。"}, {"text": "特有だろう", "is_correct": false, "explanation": "推量の形は名詞修飾の位置に入らず、「の味」と続けると文として成り立たない。"}], "correct_form": "特有", "base_form": "特有", "form_label": "語幹", "sentence_index": 7, "explanations": {"特有": "「家庭ごとに特有の味」で、名詞「味」を修飾する語幹の形。", "特有だ": "終止形は名詞の前に直接つかず、「の味」と続かないので、この位置では成り立たない。", "特有である": "断定の形は名詞を修飾する位置に置けず、「の味」と続けられない。", "特有だろう": "推量の形は名詞修飾の位置に入らず、「の味」と続けると文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。"}, {"text": "過剰", "is_correct": false, "explanation": "程度が多すぎる意味で、特有の対義語ではない。"}, {"text": "不要", "is_correct": false, "explanation": "要らないという意味で、特有とは対になる関係ではない。"}, {"text": "無関係", "is_correct": false, "explanation": "関わりがないという意味で、性質の広さを表す対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。", "過剰": "程度が多すぎる意味で、特有の対義語ではない。", "不要": "要らないという意味で、特有とは対になる関係ではない。", "無関係": "関わりがないという意味で、性質の広さを表す対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。"}, {"text": "不便", "is_correct": false, "explanation": "使いにくさを表す語で、特有の対義語ではない。"}, {"text": "無謀", "is_correct": false, "explanation": "向こう見ずの意味で、性質の広さを表す対義語ではない。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に害を与える意味で、特有の対義語ではない。"}], "correct_answer": "共通", "explanations": {"共通": "特有の対義語。ほかのものにも見られる性質を表し、特有と反対になる。", "不便": "使いにくさを表す語で、特有の対義語ではない。", "無謀": "向こう見ずの意味で、性質の広さを表す対義語ではない。", "迷惑": "人に害を与える意味で、特有の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかのものにはない、そのものだけが持つ特別な性質や特徴。", "primary_collocate": null, "pronunciation": "とくゆう", "ipa": "tokɯjɯː", "syllable_count": 4, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "特有", "complexity_tier": "T4", "furigana": "現代[げんだい]の商業的[しょうぎょうてき]なベーキングにおいては往々[おうおう]にして画一的[かくいつてき]な効率性[こうりつせい]が優先[ゆうせん]されがちであるが、彼[かれ]が真[しん]に渇望[かつぼう]するのは、サワードウ特有[とくゆう]の繊細[せんさい]かつ複雑[ふくざつ]な酸味[さんみ]と、穀物[こくもつ]本来[ほんらい]が秘[ひ]める深[ふか]い旨[うま]みの極致[きょくち]である。", "sentence_source": "mined"}, {"text": "日本の夏特有の蒸し暑さで、毎年この時期は体がだるくなる。", "target_word": "特有", "complexity_tier": "T3", "furigana": "日本[にほん]の夏[なつ]特有[とくゆう]の蒸[む]し暑[あつ]さで、毎年[まいとし]この時期[じき]は体[からだ]がだるくなる。", "sentence_source": "generated"}, {"text": "この地方特有の方言は、他の地域の人にはなかなか聞き取れない。", "target_word": "特有", "complexity_tier": "T3", "furigana": "この地方[ちほう]特有[とくゆう]の方言[ほうげん]は、他[ほか]の地域[ちいき]の人[ひと]にはなかなか聞[き]き取[と]れない。", "sentence_source": "generated"}, {"text": "古い木造の家には、木の香りが混ざった特有のにおいがある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "古[ふる]い木造[もくぞう]の家[いえ]には、木[き]の香[かお]りが混[ま]ざった特有[とくゆう]のにおいがある。", "sentence_source": "generated"}, {"text": "猫特有のしぐさがかわいくて、飼い主はつい写真を撮ってしまう。", "target_word": "特有", "complexity_tier": "T3", "furigana": "猫[ねこ]特有[とくゆう]のしぐさがかわいくて、飼[か]い主[ぬし]はつい写真[しゃしん]を撮[と]ってしまう。", "sentence_source": "generated"}, {"text": "子どもの病気には、その年齢に特有の症状がいくつかある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "子[こ]どもの病気[びょうき]には、その年齢[ねんれい]に特有[とくゆう]の症状[しょうじょう]がいくつかある。", "sentence_source": "generated"}, {"text": "彼の文章には、他の作家にはまねできない特有のリズムがある。", "target_word": "特有", "complexity_tier": "T3", "furigana": "彼[かれ]の文章[ぶんしょう]には、他[ほか]の作家[さっか]にはまねできない特有[とくゆう]のリズムがある。", "sentence_source": "generated"}, {"text": "高山植物は、寒く風の強い環境に特有の姿をしている。", "target_word": "特有", "complexity_tier": "T3", "furigana": "高山[こうざん]植物[しょくぶつ]は、寒[さむ]く風[かぜ]の強[つよ]い環境[かんきょう]に特有[とくゆう]の姿[すがた]をしている。", "sentence_source": "generated"}, {"text": "海辺の町特有の潮の香りを感じると、子どものころを思い出す。", "target_word": "特有", "complexity_tier": "T3", "furigana": "海辺[うみべ]の町[まち]特有[とくゆう]の潮[しお]の香[かお]りを感[かん]じると、子[こ]どものころを思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "この病気は高齢者に特有というわけではなく、若い人にも起こる。", "target_word": "特有", "complexity_tier": "T3", "furigana": "この病気[びょうき]は高齢者[こうれいしゃ]に特有[とくゆう]というわけではなく、若[わか]い人[ひと]にも起[お]こる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特有", "label": "語幹"}, {"form": "特有の", "label": "連体形"}, {"form": "特有で", "label": "連用形"}, {"form": "特有だ", "label": "終止形"}], "register": "中立", "sense_fingerprint": "あるものや場所、集団だけに見られる固有の性質や特徴を表す。「〜特有の＋名詞」の形で使うことが多い。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24)']::text[], 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "「サワードウ特有の」で、そのパンだけが持つ酸味を表し、文脈に合う。"}, {"text": "平凡", "is_correct": false, "explanation": "「平凡な酸味」は特別さがない意味で、「繊細かつ複雑な」と矛盾する。"}, {"text": "過剰", "is_correct": false, "explanation": "「過剰な酸味」は度合いが多すぎる意味で、「繊細」と合わない。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な酸味」は要らないという意味で、「真に渇望する」文脈と逆になる。"}], "explanations": {"特有": "「サワードウ特有の」で、そのパンだけが持つ酸味を表し、文脈に合う。", "平凡": "「平凡な酸味」は特別さがない意味で、「繊細かつ複雑な」と矛盾する。", "過剰": "「過剰な酸味」は度合いが多すぎる意味で、「繊細」と合わない。", "不要": "「不要な酸味」は要らないという意味で、「真に渇望する」文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この調味料は、どの家庭の台所にも特有のものとして置かれている。", "explanation": "ここは〈共通〉の意味。特有は「そのものだけが持つ」ことを表すので、どの家庭にもある調味料には合わない。"}, {"text": "会議の日程は、特有の出席者にだけ伝えられた。", "explanation": "ここは〈特定〉の意味。特有は性質の独自さを表すので、人を限定する場面には使わない。"}, {"text": "その作家の文章は、どこにでもある平凡な特有の言い回しだ。", "explanation": "ここは〈一般的〉の意味。特有はほかにない特徴を指すので、どこにでもある言い回しには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "「まねできない特有のリズム」で、その作家だけの性質を表し文脈に合う。"}, {"text": "迷惑", "is_correct": false, "explanation": "「迷惑なリズム」は人に害を与える意味で、文脈と合わない。"}, {"text": "不便", "is_correct": false, "explanation": "「不便なリズム」は使いにくさを表し、文章への評価と合わない。"}, {"text": "無謀", "is_correct": false, "explanation": "「無謀なリズム」は向こう見ずの意味で、リズムには結びつかない。"}], "explanations": {"特有": "「まねできない特有のリズム」で、その作家だけの性質を表し文脈に合う。", "迷惑": "「迷惑なリズム」は人に害を与える意味で、文脈と合わない。", "不便": "「不便なリズム」は使いにくさを表し、文章への評価と合わない。", "無謀": "「無謀なリズム」は向こう見ずの意味で、リズムには結びつかない。"}, "sentence_index": 6, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この病気は高齢者にも若い人にも同様に特有のものとして見られる。", "explanation": "ここは〈共通〉の意味。特有は他にない性質を表すので、両方に当てはまる場面には使わない。"}, {"text": "東京は特有名詞として辞書に載っている。", "explanation": "ここは〈固有〉の意味。個別の名前を表す語は固有名詞で、特有名詞とは言わない。"}, {"text": "この病気は、どこにでもあるありきたりな特有の症状だ。", "explanation": "ここは〈一般的〉の意味。特有はほかにない特徴を指すので、どこにでもある症状には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沖縄特有に三線の音色は、耳に残りやすい。", "corrected_sentence": "沖縄特有の三線の音色は、耳に残りやすい。", "error_description": "「特有」は名詞を修飾するときに「特有の」の形を取る。「特有に」は誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "特有", "is_correct": true, "explanation": "「夏特有の蒸し暑さ」で、名詞を修飾する語幹の形。"}, {"text": "特有な", "is_correct": false, "explanation": "「特有な」は後ろの「の」と続かず、この位置では合わない。"}, {"text": "特有に", "is_correct": false, "explanation": "連用形は「の」の前に置けず、名詞修飾の位置に合わない。"}, {"text": "特有で", "is_correct": false, "explanation": "「で」は中止の形で、後ろに「の蒸し暑さ」が続く位置では成り立たない。"}], "correct_form": "特有", "base_form": "特有", "form_label": "語幹", "sentence_index": 1, "explanations": {"特有": "「夏特有の蒸し暑さ」で、名詞を修飾する語幹の形。", "特有な": "「特有な」は後ろの「の」と続かず、この位置では合わない。", "特有に": "連用形は「の」の前に置けず、名詞修飾の位置に合わない。", "特有で": "「で」は中止の形で、後ろに「の蒸し暑さ」が続く位置では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52228, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海の生き物は、深い水圧に特有姿をしている。", "corrected_sentence": "海の生き物は、深い水圧に特有の姿をしている。", "error_description": "「特有」が名詞「姿」を修飾するには「特有の」が必要で、「の」が欠けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "特有", "is_correct": true, "explanation": "「環境に特有の姿」で、名詞「姿」を修飾する語幹の形。"}, {"text": "特有だ", "is_correct": false, "explanation": "終止形は名詞の前に直接つかず、「の姿」と続かないので、この位置では成り立たない。"}, {"text": "特有である", "is_correct": false, "explanation": "断定の形は名詞を修飾する位置に置けず、「の姿」と続けられない。"}, {"text": "特有だろう", "is_correct": false, "explanation": "推量の形は名詞修飾の位置に入らず、「の姿」と続けると文として成り立たない。"}], "correct_form": "特有", "base_form": "特有", "form_label": "語幹", "sentence_index": 7, "explanations": {"特有": "「環境に特有の姿」で、名詞「姿」を修飾する語幹の形。", "特有だ": "終止形は名詞の前に直接つかず、「の姿」と続かないので、この位置では成り立たない。", "特有である": "断定の形は名詞を修飾する位置に置けず、「の姿」と続けられない。", "特有だろう": "推量の形は名詞修飾の位置に入らず、「の姿」と続けると文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「画一の教育」で、「画一」が「教育」を修飾する「の」。"}, {"text": "に", "is_correct": false, "explanation": "格助詞「に」だが、「画一に教育では」と続けると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す格助詞「へ」で、「画一へ教育では」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "対象を表す「を」だが、「画一を教育では」と続けると動詞がなく文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「画一の教育」で、「画一」が「教育」を修飾する「の」。", "に": "格助詞「に」だが、「画一に教育では」と続けると文が成り立たない。", "へ": "方向を表す格助詞「へ」で、「画一へ教育では」は意味が通らない。", "を": "対象を表す「を」だが、「画一を教育では」と続けると動詞がなく文が成り立たない。"}, "error_tags": {"に": "方向や相手を表す格助詞だが、「画一に教育では」と続けると文が成り立たない", "へ": "方向を表す格助詞で、「画一へ教育では」は意味が通らない", "を": "対象を表す格助詞だが、「画一を教育では」は動詞がなく文が成り立たない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多様", "is_correct": true, "explanation": "「多様」は様々であることで、みんな同じという〈画一〉の反対の意味を表す。"}, {"text": "統一", "is_correct": false, "explanation": "〈統一〉は一つにまとめることで、〈画一〉と近い意味の語であり反対語ではない。"}, {"text": "均一", "is_correct": false, "explanation": "〈均一〉は同じであることを表し、〈画一〉の仲間の語で反対語ではない。"}, {"text": "標準", "is_correct": false, "explanation": "〈標準〉は基準となる形を表し、〈画一〉とはつながるが反対語ではない。"}], "correct_answer": "多様", "explanations": {"多様": "「多様」は様々であることで、みんな同じという〈画一〉の反対の意味を表す。", "統一": "〈統一〉は一つにまとめることで、〈画一〉と近い意味の語であり反対語ではない。", "均一": "〈均一〉は同じであることを表し、〈画一〉の仲間の語で反対語ではない。", "標準": "〈標準〉は基準となる形を表し、〈画一〉とはつながるが反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「求める」の対象を示す「を」で、「画一を求めすぎる」と自然につながる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す格助詞「と」だが、「画一と求めすぎる」は動詞の対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「画一へ求めすぎる」は求める先として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」で、「画一より求めすぎる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「求める」の対象を示す「を」で、「画一を求めすぎる」と自然につながる。", "と": "並列や相手を表す格助詞「と」だが、「画一と求めすぎる」は動詞の対象として成り立たない。", "へ": "方向を表す「へ」で、「画一へ求めすぎる」は求める先として不自然。", "より": "比較を表す「より」で、「画一より求めすぎる」は意味が通らない。"}, "error_tags": {"と": "並列や相手を表す格助詞だが、「画一と求めすぎる」は動詞の対象として成り立たない", "より": "比較を表す助詞で、「画一より求めすぎる」は意味が通らない", "へ": "方向を表す格助詞だが、「画一へ求めすぎる」は求める対象として不自然"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多様", "is_correct": true, "explanation": "「多様」は様々であることで、みんな同じという〈画一〉の反対の意味を表す。"}, {"text": "同一", "is_correct": false, "explanation": "〈同一〉は同じであることを表し、〈画一〉と近い意味の語で反対語ではない。"}, {"text": "規格", "is_correct": false, "explanation": "〈規格〉は決められた基準を表し、〈画一〉とつながるが反対語ではない。"}, {"text": "定型", "is_correct": false, "explanation": "〈定型〉は決まった形を表し、〈画一〉の仲間の語で反対語ではない。"}], "correct_answer": "多様", "explanations": {"多様": "「多様」は様々であることで、みんな同じという〈画一〉の反対の意味を表す。", "同一": "〈同一〉は同じであることを表し、〈画一〉と近い意味の語で反対語ではない。", "規格": "〈規格〉は決められた基準を表し、〈画一〉とつながるが反対語ではない。", "定型": "〈定型〉は決まった形を表し、〈画一〉の仲間の語で反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_error