INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんな同じであること。", "primary_collocate": null, "pronunciation": "かくいつ", "ipa": "kakɯitsɯ", "syllable_count": 4, "sentences": [{"text": "制服による画一を、この学校は見直すことにした。", "target_word": "画一", "complexity_tier": "T3", "furigana": "制服[せいふく]による画一[かくいつ]を、この学校[がっこう]は見直[みなお]すことにした。", "sentence_source": "generated"}, {"text": "画一の教育では、一人ひとりの才能は伸びにくい。", "target_word": "画一", "complexity_tier": "T3", "furigana": "画一[かくいつ]の教育[きょういく]では、一人[ひとり]ひとりの才能[さいのう]は伸[の]びにくい。", "sentence_source": "generated"}, {"text": "彼は画一を嫌い、いつも自分らしい服を選ぶ。", "target_word": "画一", "complexity_tier": "T3", "furigana": "彼[かれ]は画一[かくいつ]を嫌[きら]い、いつも自分[じぶん]らしい服[ふく]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "どの駅前も同じ店ばかりで、街づくりの画一が問題になっている。", "target_word": "画一", "complexity_tier": "T3", "furigana": "どの駅前[えきまえ]も同[おな]じ店[みせ]ばかりで、街[まち]づくりの画一[かくいつ]が問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "画一を重んじる会社では、新しい意見が出にくい。", "target_word": "画一", "complexity_tier": "T3", "furigana": "画一[かくいつ]を重[おも]んじる会社[かいしゃ]では、新[あたら]しい意見[いけん]が出[で]にくい。", "sentence_source": "generated"}, {"text": "画一より個性を大切にする教え方が、広がっている。", "target_word": "画一", "complexity_tier": "T3", "furigana": "画一[かくいつ]より個性[こせい]を大切[たいせつ]にする教[おし]え方[かた]が、広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "同じ形の家が並ぶ画一の風景に、少し退屈した。", "target_word": "画一", "complexity_tier": "T3", "furigana": "同[おな]じ形[かたち]の家[いえ]が並[なら]ぶ画一[かくいつ]の風景[ふうけい]に、少[すこ]し退屈[たいくつ]した。", "sentence_source": "generated"}, {"text": "画一を求めすぎると、子どもの自由な発想が失われる。", "target_word": "画一", "complexity_tier": "T3", "furigana": "画一[かくいつ]を求[もと]めすぎると、子[こ]どもの自由[じゆう]な発想[はっそう]が失[うしな]われる。", "sentence_source": "generated"}, {"text": "店ごとの特色がなく、画一のサービスだった。", "target_word": "画一", "complexity_tier": "T3", "furigana": "店[みせ]ごとの特色[とくしょく]がなく、画一[かくいつ]のサービスだった。", "sentence_source": "generated"}, {"text": "画一を避けて、メニューを店ごとに変えている。", "target_word": "画一", "complexity_tier": "T3", "furigana": "画一[かくいつ]を避[さ]けて、メニューを店[みせ]ごとに変[か]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "画一", "label": "基本形"}], "register": "formal", "sense_fingerprint": "個性や違いがなく、すべてが同じ形・内容にそろっていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "画一", "is_correct": true, "explanation": "「制服による画一」は制服で同じ形にそろえることを指し、「見直す」と合う。"}, {"text": "拍手", "is_correct": false, "explanation": "「制服による拍手」は意味が通らず、「見直す」の対象にならない。"}, {"text": "軽量", "is_correct": false, "explanation": "「制服による軽量」は制服の重さの話になり、「見直す」と結びつかない。"}, {"text": "雑踏", "is_correct": false, "explanation": "「雑踏」は人が混み合う場所を指し、制服の影響としては成立しない。"}], "explanations": {"画一": "「制服による画一」は制服で同じ形にそろえることを指し、「見直す」と合う。", "拍手": "「制服による拍手」は意味が通らず、「見直す」の対象にならない。", "軽量": "「制服による軽量」は制服の重さの話になり、「見直す」と結びつかない。", "雑踏": "「雑踏」は人が混み合う場所を指し、制服の影響としては成立しない。"}, "sentence_index": 0, "correct_answer": "画一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この一枚きりの絵は、画一だ。", "explanation": "〈画一〉は多くのものが同じ形にそろうことを指す。一つの作品には使わず、〈単純〉と混同した例。"}, {"text": "一人ひとりの画一を大切にする教育が広がっている。", "explanation": "ここは〈個別〉（それぞれ別々であること）の意味と混同した例。〈画一〉は皆が同じである状態を指すので、一人ひとりの違いを重んじる文には合わない。"}, {"text": "この画一は鮮明で、細部までよく見える。", "explanation": "ここは〈画像〉（写真や絵などの像）の意味と混同した例。〈画一〉は多くのものが同じ形にそろうことを指すので、像を表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画一", "is_correct": true, "explanation": "「同じ形の家が並ぶ画一の風景」は同じであることを指し、文脈に合う。"}, {"text": "多彩", "is_correct": false, "explanation": "「多彩」は色や形が豊かなことで、同じ形の家並みとは反対。「多彩の」と続けるのも誤り。"}, {"text": "雑然", "is_correct": false, "explanation": "「雑然」は散らかった様子で、同じ形の家が並ぶ風景には合わない。"}, {"text": "華美", "is_correct": false, "explanation": "「華美」は派手で飾り立てた様子で、同じ形の家が並ぶ風景には合わない。"}], "explanations": {"画一": "「同じ形の家が並ぶ画一の風景」は同じであることを指し、文脈に合う。", "多彩": "「多彩」は色や形が豊かなことで、同じ形の家並みとは反対。「多彩の」と続けるのも誤り。", "雑然": "「雑然」は散らかった様子で、同じ形の家が並ぶ風景には合わない。", "華美": "「華美」は派手で飾り立てた様子で、同じ形の家が並ぶ風景には合わない。"}, "sentence_index": 6, "correct_answer": "画一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は昨日と画一のシャツを着ていた。", "explanation": "〈同一〉の意味で使うのは誤り。〈画一〉は多くのものが同じ形にそろうことで、一着の服が同じかどうかには使わない。"}, {"text": "自由な服装を画一に決めて、みんなで楽しむ。", "explanation": "ここは〈統一〉（一定の方針で揃えること）の意味と混同した例。〈画一〉は個性を失わせる否定的な響きがあり、自由を尊重する場面には合わない。"}, {"text": "この料理は味が画一で、食べるたびに驚くほど違う。", "explanation": "ここは〈多様〉（さまざまであること）の意味と混同した例。〈画一〉は同じであることなので、食べるたびに味が変わるという説明とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校則による画一に、もう一度見直すべきだ。", "corrected_sentence": "校則による画一を、もう一度見直すべきだ。", "error_description": "「見直す」は対象を「を」で取るので、「画一」に続く「に」が誤り。正しくは「画一を見直す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全国チェーンでは、店の画一を食べている。", "corrected_sentence": "全国チェーンでは、店の画一を進めている。", "error_description": "「画一」は「進める」「広げる」のような動詞と組むので、「食べる」とは組み合わない。正しくは「画一を進めている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
