INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52231, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物の、いい味のこと。", "primary_collocate": null, "pronunciation": "うまみ", "ipa": "ɯmami", "syllable_count": 3, "sentences": [{"text": "このスープは、肉の旨みがたっぷり出ている。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "このスープは、肉[にく]の旨[うま]みがたっぷり出[で]ている。", "sentence_source": "generated"}, {"text": "魚は焼きすぎると、旨みが逃げてしまう。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "魚[さかな]は焼[や]きすぎると、旨[うま]みが逃[に]げてしまう。", "sentence_source": "generated"}, {"text": "しいたけからは、よい旨みが出る。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "しいたけからは、よい旨[うま]みが出[で]る。", "sentence_source": "generated"}, {"text": "昆布でだしをとると、料理に旨みが加わる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "昆布[こんぶ]でだしをとると、料理[りょうり]に旨[うま]みが加[くわ]わる。", "sentence_source": "generated"}, {"text": "このラーメンは、旨みが濃くて何度でも食べたくなる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "このラーメンは、旨[うま]みが濃[こ]くて何度[なんど]でも食[た]べたくなる。", "sentence_source": "generated"}, {"text": "新鮮な野菜は旨みがあるので、調味料が少なくても十分おいしい。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "新鮮[しんせん]な野菜[やさい]は旨[うま]みがあるので、調味料[ちょうみりょう]が少[すく]なくても十分[じゅうぶん]おいしい。", "sentence_source": "generated"}, {"text": "トマトを煮込むと、旨みがぎゅっと集まる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "トマトを煮込[にこ]むと、旨[うま]みがぎゅっと集[あつ]まる。", "sentence_source": "generated"}, {"text": "母の味噌汁には、不思議な旨みがある。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "母[はは]の味噌汁[みそしる]には、不思議[ふしぎ]な旨[うま]みがある。", "sentence_source": "generated"}, {"text": "干した魚は、日に当てると旨みが増す。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "干[ほ]した魚[さかな]は、日[ひ]に当[あ]てると旨[うま]みが増[ま]す。", "sentence_source": "generated"}, {"text": "この牛肉は脂が少なく、赤身の旨みを楽しめる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "この牛肉[ぎゅうにく]は脂[あぶら]が少[すく]なく、赤身[あかみ]の旨[うま]みを楽[たの]しめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨み", "label": "基本形"}, {"form": "旨い", "label": "形容詞形"}], "register": "neutral", "sense_fingerprint": "食べ物が持つ、おいしいと感じる良い味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52231, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旨み", "is_correct": true, "explanation": "「肉の旨み」は肉から出るおいしい味を指し、「たっぷり出ている」と合う。"}, {"text": "重さ", "is_correct": false, "explanation": "「肉の重さ」は出てくるものではないので、「たっぷり出ている」と合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "「硬さ」は肉の性質を表し、スープに「たっぷり出る」ものではない。"}, {"text": "大きさ", "is_correct": false, "explanation": "「大きさ」は形の性質を表し、「たっぷり出ている」とは続かない。"}], "explanations": {"旨み": "「肉の旨み」は肉から出るおいしい味を指し、「たっぷり出ている」と合う。", "重さ": "「肉の重さ」は出てくるものではないので、「たっぷり出ている」と合わない。", "硬さ": "「硬さ」は肉の性質を表し、スープに「たっぷり出る」ものではない。", "大きさ": "「大きさ」は形の性質を表し、「たっぷり出ている」とは続かない。"}, "sentence_index": 0, "correct_answer": "旨み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この肉は、旨みがとてもやわらかい。", "explanation": "〈食感〉の話で使うのは誤り。〈旨み〉は味のよさを指すので、やわらかさの説明には合わない。"}, {"text": "このコーヒーは、旨みが部屋中に広がる。", "explanation": "〈香り〉の話で使うのは誤り。〈旨み〉は食べ物の味わいで、部屋に広がるものではない。"}, {"text": "この絵は、旨みが鮮やかだ。", "explanation": "〈色・見た目〉に使うのは誤り。〈旨み〉は味の語なので、絵の鮮やかさとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52231, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旨み", "is_correct": true, "explanation": "「旨みがぎゅっと集まる」は味が凝縮することを表し、「煮込むと」と合う。"}, {"text": "色", "is_correct": false, "explanation": "「色がぎゅっと集まる」は意味が通らず、煮込みの説明に合わない。"}, {"text": "形", "is_correct": false, "explanation": "「形がぎゅっと集まる」は不自然で、煮込む料理の説明には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段がぎゅっと集まる」は意味をなさず、煮込みの文脈に合わない。"}], "explanations": {"旨み": "「旨みがぎゅっと集まる」は味が凝縮することを表し、「煮込むと」と合う。", "色": "「色がぎゅっと集まる」は意味が通らず、煮込みの説明に合わない。", "形": "「形がぎゅっと集まる」は不自然で、煮込む料理の説明には合わない。", "値段": "「値段がぎゅっと集まる」は意味をなさず、煮込みの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "旨み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は、旨みが苦くて飲めない。", "explanation": "〈苦味〉と混同した例。〈旨み〉は好ましい味の要素なので、苦さを表す文脈には合わない。"}, {"text": "この弁当は旨みが大きくて、満腹になる。", "explanation": "〈量〉の意味で使うのは誤り。〈旨み〉は味のよさを表し、大きさや量を表さない。"}, {"text": "このピアノは、旨みが澄んでいて響きが美しい。", "explanation": "〈音色〉の話で使うのは誤り。〈旨み〉は食べ物の味わいを指すので、音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52231, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鶏ガラは長く煮すぎると、旨みを抜けてしまう。", "corrected_sentence": "鶏ガラは長く煮すぎると、旨みが抜けてしまう。", "error_description": "「抜ける」は自動詞で、主語を「が」で示す。「旨みを抜ける」は他動詞の「を」を誤って使った誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52231, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干し貝柱を戻すと、旨いがよく出る。", "corrected_sentence": "干し貝柱を戻すと、旨みがよく出る。", "error_description": "「旨み」を形容詞の「旨い」にしてしまっている。「旨い」は名詞の代わりに「が」の後に続けられず、「旨みが出る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
