INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物や飲み物に含まれる、うまいと感じる味。特に、肉や魚、野菜などから出る、こくのあるおいしさ。", "primary_collocate": null, "pronunciation": "うまみ", "ipa": "ɯmami", "syllable_count": 3, "sentences": [{"text": "煮干しや鰹節からは、深い旨みのあるだしが取れる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "煮干[にぼ]しや鰹節[かつおぶし]からは、深[ふか]い旨[うま]みのあるだしが取[と]れる。", "sentence_source": "generated"}, {"text": "熟成させた肉は、旨みが強くなって味に厚みが出る。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]させた肉[にく]は、旨[うま]みが強[つよ]くなって味[あじ]に厚[あつ]みが出[で]る。", "sentence_source": "generated"}, {"text": "トマトに含まれるグルタミン酸が、料理に旨みを与える。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "トマトに含[ふく]まれるグルタミン酸[さん]が、料理[りょうり]に旨[うま]みを与[あた]える。", "sentence_source": "generated"}, {"text": "貝類の旨みが溶け出したスープは、飲むと体が温まる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "貝類[かいるい]の旨[うま]みが溶[と]け出[だ]したスープは、飲[の]むと体[からだ]が温[あたた]まる。", "sentence_source": "generated"}, {"text": "干ししいたけを水で戻した汁は、旨みが濃く煮物に使える。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "干[ほ]ししいたけを水[みず]で戻[もど]した汁[しる]は、旨[うま]みが濃[こ]く煮物[にもの]に使[つか]える。", "sentence_source": "generated"}, {"text": "日本料理では、だしの旨みを料理の土台にする。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "日本料理[にほんりょうり]では、だしの旨[うま]みを料理[りょうり]の土台[どだい]にする。", "sentence_source": "generated"}, {"text": "チーズや生ハムには、発酵や熟成によって生まれた旨みがある。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "チーズや生[なま]ハムには、発酵[はっこう]や熟成[じゅくせい]によって生[う]まれた旨[うま]みがある。", "sentence_source": "generated"}, {"text": "野菜をじっくり炒めると、甘みだけでなく旨みも出てくる。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "野菜[やさい]をじっくり炒[いた]めると、甘[あま]みだけでなく旨[うま]みも出[で]てくる。", "sentence_source": "generated"}, {"text": "鶏肉を骨ごと煮ると、骨からも旨みが出る。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "鶏肉[とりにく]を骨[ほね]ごと煮[に]ると、骨[ほね]からも旨[うま]みが出[で]る。", "sentence_source": "generated"}, {"text": "昆布と鰹節を合わせると、旨みが何倍にも強くなるそうだ。", "target_word": "旨み", "complexity_tier": "T3", "furigana": "昆布[こんぶ]と鰹節[かつおぶし]を合[あ]わせると、旨[うま]みが何倍[なんばい]にも強[つよ]くなるそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨み", "label": "基本形"}, {"form": "旨い", "label": "形容詞形"}], "register": "neutral", "sense_fingerprint": "肉・魚・野菜などから出る、こくのある深いおいしさ（うま味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '154265da-feaf-448d-b4be-5107c88812b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旨み", "is_correct": true, "explanation": "「深い旨みのあるだし」は食べ物のこくのあるおいしさを持つだしを指し、文脈に合う。"}, {"text": "手触り", "is_correct": false, "explanation": "「深い手触りのあるだし」は意味が通らず、だしの説明に合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "「深い硬さのあるだし」は味の説明にならず、文脈に合わない。"}, {"text": "形状", "is_correct": false, "explanation": "「深い形状のあるだし」は不自然で、だしの良さを表さない。"}], "explanations": {"旨み": "「深い旨みのあるだし」は食べ物のこくのあるおいしさを持つだしを指し、文脈に合う。", "手触り": "「深い手触りのあるだし」は意味が通らず、だしの説明に合わない。", "硬さ": "「深い硬さのあるだし」は味の説明にならず、文脈に合わない。", "形状": "「深い形状のあるだし」は不自然で、だしの良さを表さない。"}, "sentence_index": 0, "correct_answer": "旨み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コーヒーを淹れると、旨みが部屋いっぱいに立ち上る。", "explanation": "〈香り〉が立ち上るという表現に〈旨み〉を入れた誤り。旨みは味の要素で、立ち上るのは香り。"}, {"text": "この布は旨みがなめらかで、よく伸びる。", "explanation": "ここは〈手触り〉（布の肌ざわりや伸び具合）の意味と混同した例。〈旨み〉は食べ物の味を指すので、布の質感を表す文には合わない。"}, {"text": "この鍋の旨みは重くて持ちにくい。", "explanation": "〈重さ〉の話で使うのは誤り。〈旨み〉は味の語で、物の重さを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旨み", "is_correct": true, "explanation": "「生まれた旨みがある」は発酵や熟成で生じたこくのある味を指し、文脈に合う。"}, {"text": "電圧", "is_correct": false, "explanation": "「生まれた電圧」は食品の説明に合わず、文脈に合わない。"}, {"text": "磁気", "is_correct": false, "explanation": "「生まれた磁気」は食品の性質ではなく、発酵の説明には合わない。"}, {"text": "重量", "is_correct": false, "explanation": "「生まれた重量がある」は意味が通らず、発酵食品の説明にならない。"}], "explanations": {"旨み": "「生まれた旨みがある」は発酵や熟成で生じたこくのある味を指し、文脈に合う。", "電圧": "「生まれた電圧」は食品の説明に合わず、文脈に合わない。", "磁気": "「生まれた磁気」は食品の性質ではなく、発酵の説明には合わない。", "重量": "「生まれた重量がある」は意味が通らず、発酵食品の説明にならない。"}, "sentence_index": 6, "correct_answer": "旨み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この汁は旨みが苦く、飲むと口が渋くなる。", "explanation": "〈苦味〉と混同した例。〈旨み〉は好ましい味の要素なので、苦さや渋さの説明には使わない。"}, {"text": "この楽器は、旨みが澄んで響きがきれいだ。", "explanation": "〈音色〉の話で使うのは誤り。〈旨み〉は食べ物の味わいを指すので、音には使えない。"}, {"text": "鍋の火を強めると、旨みの温度が上がる。", "explanation": "ここは〈熱さ〉（物や料理の熱の程度）の意味と混同した例。〈旨み〉は味のよさを指すので、火加減で上がるような熱さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鶏ガラは水から煮ると、旨みをよく出る。", "corrected_sentence": "鶏ガラは水から煮ると、旨みがよく出る。", "error_description": "「出る」は自動詞で、主語を「が」で示す。「旨みを出る」は他動詞の「を」を誤って使った誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昆布は水につけると、旨いがじわじわ出る。", "corrected_sentence": "昆布は水につけると、旨みがじわじわ出る。", "error_description": "「旨み」を形容詞の「旨い」にしてしまっている。「旨い」は名詞の代わりに「が」の後に続けられず、「旨みが出る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd13b941f-7a75-4964-a7e6-f3e1d81fb16c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
