INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「極致に達し」で、到達する先を示す正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「極致で達し」は手段を表す形になり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は、ここでは「達し」と続かず意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、到達する先を示す位置には合わない。"}], "correct_answer": "に", "explanations": {"に": "「極致に達し」で、到達する先を示す正しい助詞。", "で": "「極致で達し」は手段を表す形になり、文が成り立たない。", "と": "並列の「と」は、ここでは「達し」と続かず意味が通らない。", "から": "起点の「から」は、到達する先を示す位置には合わない。"}, "error_tags": {"で": "手段", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の程度が最も高いところ。", "primary_collocate": null, "pronunciation": "きょくち", "ipa": "kʲokɯtɕi", "syllable_count": 3, "sentences": [{"text": "彼女のダンスは、表現力の極致と言ってもいいほど見事だった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のダンスは、表現力[ひょうげんりょく]の極致[きょくち]と言[い]ってもいいほど見事[みごと]だった。", "sentence_source": "generated"}, {"text": "三つ星の店で食べたデザートは、甘さの極致だった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "三[みっ]つ星[ぼし]の店[みせ]で食[た]べたデザートは、甘[あま]さの極致[きょくち]だった。", "sentence_source": "generated"}, {"text": "悲しみの極致にいた彼女は、涙も出なくなった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "悲[かな]しみの極致[きょくち]にいた彼女[かのじょ]は、涙[なみだ]も出[で]なくなった。", "sentence_source": "generated"}, {"text": "この映画の最後の場面は、緊張の極致だった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "この映画[えいが]の最後[さいご]の場面[ばめん]は、緊張[きんちょう]の極致[きょくち]だった。", "sentence_source": "generated"}, {"text": "昔の名人の演奏は、芸の極致として今も語り継がれている。", "target_word": "極致", "complexity_tier": "T3", "furigana": "昔[むかし]の名人[めいじん]の演奏[えんそう]は、芸[げい]の極致[きょくち]として今[いま]も語[かた]り継[つ]がれている。", "sentence_source": "generated"}, {"text": "長い待ち時間のあとで食べた温かいラーメンは、幸せの極致だった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "長[なが]い待[ま]ち時間[じかん]のあとで食[た]べた温[あたた]かいラーメンは、幸[しあわ]せの極致[きょくち]だった。", "sentence_source": "generated"}, {"text": "このホテルの部屋は、快適さの極致で、一度泊まると離れたくない。", "target_word": "極致", "complexity_tier": "T3", "furigana": "このホテルの部屋[へや]は、快適[かいてき]さの極致[きょくち]で、一度[いちど]泊[と]まると離[はな]れたくない。", "sentence_source": "generated"}, {"text": "彼の絶望は極致に達し、何も手につかなかった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "彼[かれ]の絶望[ぜつぼう]は極致[きょくち]に達[たっ]し、何[なに]も手[て]につかなかった。", "sentence_source": "generated"}, {"text": "満開の桜が夜空に浮かぶ光景は、美の極致だった。", "target_word": "極致", "complexity_tier": "T3", "furigana": "満開[まんかい]の桜[さくら]が夜空[よぞら]に浮[う]かぶ光景[こうけい]は、美[び]の極致[きょくち]だった。", "sentence_source": "generated"}, {"text": "冬の露天風呂は、くつろぎの極致だと私は思う。", "target_word": "極致", "complexity_tier": "T3", "furigana": "冬[ふゆ]の露天[ろてん]風呂[ぶろ]は、くつろぎの極致[きょくち]だと私[わたし]は思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "極致", "label": "基本形"}, {"form": "極致の", "label": "連体形"}, {"form": "極致に", "label": "格助詞「に」付き"}, {"form": "極致だ", "label": "終止形"}], "register": "やや硬い", "sense_fingerprint": "ある物事の中で、これ以上ないほどすばらしい、あるいは程度が最も高いところ。「〜の極致」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "極致", "is_correct": true, "explanation": "「表現力の極致」で、表現力がこれ以上ない状態にあることを表し、文脈に合う。"}, {"text": "残金", "is_correct": false, "explanation": "「表現力の残金」は残ったお金の意味で、ダンスの評価と合わない。"}, {"text": "義務", "is_correct": false, "explanation": "「表現力の義務」は意味が通らず、ダンスの評価と合わない。"}, {"text": "残骸", "is_correct": false, "explanation": "「表現力の残骸」は壊れたものを指し、見事さの説明と合わない。"}], "explanations": {"極致": "「表現力の極致」で、表現力がこれ以上ない状態にあることを表し、文脈に合う。", "残金": "「表現力の残金」は残ったお金の意味で、ダンスの評価と合わない。", "義務": "「表現力の義務」は意味が通らず、ダンスの評価と合わない。", "残骸": "「表現力の残骸」は壊れたものを指し、見事さの説明と合わない。"}, "sentence_index": 0, "correct_answer": "極致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "登山家は山の極致に立ち、雲海を見下ろした。", "explanation": "ここは〈頂上〉の意味。極致は程度の高さを表す抽象語で、山の頂には使わない。"}, {"text": "彼は剣道の極致を理由に、稽古を休んだ。", "explanation": "ここは〈言い訳〉の意味。極致はいちばんすごい状態を表すので、休む理由として使う場面には合わない。"}, {"text": "机の極致に、コップが置いてあった。", "explanation": "ここは〈端〉の意味。極致は最高の程度を表す語で、場所の縁を指す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "極致", "is_correct": true, "explanation": "「快適さの極致」で、部屋の快適さがこれ以上ない状態にあることを表し、文脈に合う。"}, {"text": "混乱", "is_correct": false, "explanation": "「快適さの混乱」は意味が通らず、部屋の評価と合わない。"}, {"text": "節約", "is_correct": false, "explanation": "「快適さの節約」は意味が通らず、部屋の評価と合わない。"}, {"text": "欠点", "is_correct": false, "explanation": "「快適さの欠点」は意味が逆で、部屋を褒める文脈と合わない。"}], "explanations": {"極致": "「快適さの極致」で、部屋の快適さがこれ以上ない状態にあることを表し、文脈に合う。", "混乱": "「快適さの混乱」は意味が通らず、部屋の評価と合わない。", "節約": "「快適さの節約」は意味が通らず、部屋の評価と合わない。", "欠点": "「快適さの欠点」は意味が逆で、部屋を褒める文脈と合わない。"}, "sentence_index": 6, "correct_answer": "極致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅人は山の極致に宿を取り、翌朝出発した。", "explanation": "ここは〈ふもと〉の意味。極致は抽象的な程度を表すので、場所には使わない。"}, {"text": "レストランの極致で、デザートがついてきた。", "explanation": "ここは〈おまけ〉の意味。極致は最高の程度を表すので、添えられる付録ではない。"}, {"text": "会場の極致が、演奏を邪魔した。", "explanation": "ここは〈雑音〉の意味。極致は最高の程度を表すので、騒がしい音の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その試合は、盛り上がりの極致を終わった。", "corrected_sentence": "その試合は、盛り上がりの極致で終わった。", "error_description": "「終わる」は場面を示す「で」と結ぶ。「極致を終わった」の「を」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52233, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この映画の結末は、感動の極致で言ってもいいほどだった。", "corrected_sentence": "この映画の結末は、感動の極致と言ってもいいほどだった。", "error_description": "「言う」は引用の「と」と結ぶ。「極致で」の「で」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
