INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52235, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほんの少しだけ、ちがうこと。", "primary_collocate": null, "pronunciation": "びみょう", "ipa": "bimʲoː", "syllable_count": 3, "sentences": [{"text": "双子の兄弟は、声が微妙に違う。", "target_word": "微妙", "complexity_tier": "T2", "furigana": "双子[ふたご]の兄弟[きょうだい]は、声[こえ]が微妙[びみょう]に違[ちが]う。", "sentence_source": "generated"}, {"text": "このふたつの青は、微妙に濃さが違う。", "target_word": "微妙", "complexity_tier": "T2", "furigana": "このふたつの青[あお]は、微妙[びみょう]に濃[こ]さが違[ちが]う。", "sentence_source": "generated"}, {"text": "左の絵と右の絵には、微妙な違いが三つある。", "target_word": "微妙", "complexity_tier": "T2", "furigana": "左[ひだり]の絵[え]と右[みぎ]の絵[え]には、微妙[びみょう]な違[ちが]いが三[みっ]つある。", "sentence_source": "generated"}, {"text": "昨日と今日では、風の冷たさが微妙に違う。", "target_word": "微妙", "complexity_tier": "T2", "furigana": "昨日[きのう]と今日[きょう]では、風[かぜ]の冷[つめ]たさが微妙[びみょう]に違[ちが]う。", "sentence_source": "generated"}, {"text": "同じ名前のお菓子でも、店によって味が微妙に違う。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "同[おな]じ名前[なまえ]のお菓子[かし]でも、店[みせ]によって味[あじ]が微妙[びみょう]に違[ちが]う。", "sentence_source": "generated"}, {"text": "写真を二枚並べると、角度が微妙にずれているのがわかった。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "写真[しゃしん]を二枚[にまい]並[なら]べると、角度[かくど]が微妙[びみょう]にずれているのがわかった。", "sentence_source": "generated"}, {"text": "姉と私は顔がそっくりだが、目の形だけは微妙に違う。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "姉[あね]と私[わたし]は顔[かお]がそっくりだが、目[め]の形[かたち]だけは微妙[びみょう]に違[ちが]う。", "sentence_source": "generated"}, {"text": "新しい靴は、前のものより大きさが微妙に小さい。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]は、前[まえ]のものより大[おお]きさが微妙[びみょう]に小[ちい]さい。", "sentence_source": "generated"}, {"text": "地図と実際の道は微妙に違っていて、少し迷った。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "地図[ちず]と実際[じっさい]の道[みち]は微妙[びみょう]に違[ちが]っていて、少[すこ]し迷[まよ]った。", "sentence_source": "generated"}, {"text": "辞書の説明と先生の説明には、微妙な違いがあった。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "辞書[じしょ]の説明[せつめい]と先生[せんせい]の説明[せつめい]には、微妙[びみょう]な違[ちが]いがあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微妙", "label": "語幹"}, {"form": "微妙な", "label": "連体形"}, {"form": "微妙に", "label": "連用形"}, {"form": "微妙だ", "label": "終止形"}], "register": "標準", "sense_fingerprint": "二つのものがほんの少しだけ違うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52235, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "「声が微妙に違う」で、ほんの少しの違いを表す意味に合う。"}, {"text": "堂々", "is_correct": false, "explanation": "立派で威厳がある様子。「に違う」とは続かない。"}, {"text": "寛大", "is_correct": false, "explanation": "心が広く許す様子。違いを表す語として続かない。"}, {"text": "冷静", "is_correct": false, "explanation": "落ち着いている様子。声の違いを表す語として続かない。"}], "explanations": {"微妙": "「声が微妙に違う」で、ほんの少しの違いを表す意味に合う。", "堂々": "立派で威厳がある様子。「に違う」とは続かない。", "寛大": "心が広く許す様子。違いを表す語として続かない。", "冷静": "落ち着いている様子。声の違いを表す語として続かない。"}, "sentence_index": 0, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の身長は、微妙に十センチも違う。", "explanation": "ここは〈大きな差〉の意味。身長の十センチ差は大きな差で、〈微妙〉は使わない。"}, {"text": "試験の点数は、微妙に百点も違った。", "explanation": "ここは〈大差〉の意味。百点の開きは大差であり、〈微妙〉は合わない。"}, {"text": "山の標高は、微妙に千メートルも違う。", "explanation": "ここは〈明らかな差〉の意味。千メートルの開きは明らかな差で、〈微妙〉とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52235, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "「目の形だけは微妙に違う」で、ほんの少しの違いを表す意味に合う。"}, {"text": "熱心", "is_correct": false, "explanation": "物事に打ち込む様子。「に違う」と続けても意味が成り立たない。"}, {"text": "豪快", "is_correct": false, "explanation": "大胆で勢いのある様子。違いの程度を表す語として合わない。"}, {"text": "無遠慮", "is_correct": false, "explanation": "遠慮のない様子。目の形の違いを表す語として続かない。"}], "explanations": {"微妙": "「目の形だけは微妙に違う」で、ほんの少しの違いを表す意味に合う。", "熱心": "物事に打ち込む様子。「に違う」と続けても意味が成り立たない。", "豪快": "大胆で勢いのある様子。違いの程度を表す語として合わない。", "無遠慮": "遠慮のない様子。目の形の違いを表す語として続かない。"}, "sentence_index": 6, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの都市の人口は、微妙に百万人も違う。", "explanation": "ここは〈大差〉の意味。百万人の開きは大差で、〈微妙〉は使わない。"}, {"text": "両チームの得点は、微妙に大差で開いた。", "explanation": "ここは〈歴然〉の意味。大差で開いた点差は歴然としていて、〈微妙〉の違いの小ささとは合わない。"}, {"text": "彼の声は、友人と比べて微妙に桁違いに大きい。", "explanation": "ここは〈格段〉の意味。格段の差を〈微妙〉で表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの靴の大きさには、微妙の差がある。", "corrected_sentence": "二つの靴の大きさには、微妙な差がある。", "error_description": "「微妙」は形容動詞なので、名詞「差」を修飾するには「な」が必要。「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微妙に", "is_correct": true, "explanation": "連用形。「濃さが違う」を修飾する形。"}, {"text": "微妙で", "is_correct": false, "explanation": "て形。名詞を直接修飾できず、「微妙で濃さが違う」は文として成り立たない。"}, {"text": "微妙だ", "is_correct": false, "explanation": "終止形。文の述語になる形で、ここでは「違う」を修飾しない。"}, {"text": "微妙", "is_correct": false, "explanation": "語幹。単独では動詞を修飾する形になれない。"}], "correct_form": "微妙に", "base_form": "微妙", "form_label": "連用形", "sentence_index": 1, "explanations": {"微妙に": "連用形。「濃さが違う」を修飾する形。", "微妙で": "て形。名詞を直接修飾できず、「微妙で濃さが違う」は文として成り立たない。", "微妙だ": "終止形。文の述語になる形で、ここでは「違う」を修飾しない。", "微妙": "語幹。単独では動詞を修飾する形になれない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52235, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "双子の姉妹は、声の高さだけが微妙を違う。", "corrected_sentence": "双子の姉妹は、声の高さだけが微妙に違う。", "error_description": "「微妙に違う」は連用形で違いを修飾する形。「微妙を違う」は「を」が誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微妙に", "is_correct": true, "explanation": "連用形。「小さい」を修飾して程度を示す形。"}, {"text": "微妙だった", "is_correct": false, "explanation": "過去形。「小さい」を修飾する連用形にはならない。"}, {"text": "微妙さ", "is_correct": false, "explanation": "名詞化した形。「小さい」を修飾できない。"}, {"text": "微妙ではない", "is_correct": false, "explanation": "否定の形。「小さい」を修飾する連用形としては使えない。"}], "correct_form": "微妙に", "base_form": "微妙", "form_label": "連用形", "sentence_index": 7, "explanations": {"微妙に": "連用形。「小さい」を修飾して程度を示す形。", "微妙だった": "過去形。「小さい」を修飾する連用形にはならない。", "微妙さ": "名詞化した形。「小さい」を修飾できない。", "微妙ではない": "否定の形。「小さい」を修飾する連用形としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
