INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52236, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "はっきりとはわからないほど、わずかな違いや変化があること。また、その様子。", "primary_collocate": null, "pronunciation": "びみょう", "ipa": "bimʲoː", "syllable_count": 3, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "微妙", "complexity_tier": "T5", "furigana": "指先[ゆびさき]を通[つう]じて伝[つた]わる生地[きじ]の微妙[びみょう]な弾力[だんりょく]や発酵[はっこう]の進行具合[しんこうぐあい]を唯一[ゆいいつ]の羅針盤[らしんばん]とし、彼[かれ]は温度[おんど]と湿度[しつど]という変数[へんすう]を緻密[ちみつ]に制御[せいぎょ]することで、微生物[びせいぶつ]という目[め]に見[み]えぬパートナーとの静[しず]かなる対話[たいわ]を試[こころ]みる。", "sentence_source": "mined"}, {"text": "二つの色は似ているが、よく見ると微妙な違いがある。", "target_word": "微妙", "complexity_tier": "T2", "furigana": "二[ふた]つの色[いろ]は似[に]ているが、よく見[み]ると微妙[びみょう]な違[ちが]いがある。", "sentence_source": "generated"}, {"text": "同じ曲でも、歌う人によって微妙に雰囲気が変わる。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "同[おな]じ曲[きょく]でも、歌[うた]う人[ひと]によって微妙[びみょう]に雰囲気[ふんいき]が変[か]わる。", "sentence_source": "generated"}, {"text": "音の高さの微妙な差を、彼女の耳は聞き分けた。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "音[おと]の高[たか]さの微妙[びみょう]な差[さ]を、彼女[かのじょ]の耳[みみ]は聞[き]き分[わ]けた。", "sentence_source": "generated"}, {"text": "鏡を見ても気づかないほど、顔の左右は微妙に違っている。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "鏡[かがみ]を見[み]ても気[き]づかないほど、顔[かお]の左右[さゆう]は微妙[びみょう]に違[ちが]っている。", "sentence_source": "generated"}, {"text": "職人は塩の量を微妙に変えて、味の変化を確かめた。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "職人[しょくにん]は塩[しお]の量[りょう]を微妙[びみょう]に変[か]えて、味[あじ]の変化[へんか]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "天気予報はいつも当たるわけではなく、空気の微妙な変化を読むのは難しい。", "target_word": "微妙", "complexity_tier": "T4", "furigana": "天気予報[てんきよほう]はいつも当[あ]たるわけではなく、空気[くうき]の微妙[びみょう]な変化[へんか]を読[よ]むのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "この二つの言葉は意味が近く、微妙なニュアンスの違いを説明するのは簡単ではない。", "target_word": "微妙", "complexity_tier": "T4", "furigana": "この二[ふた]つの言葉[ことば]は意味[いみ]が近[ちか]く、微妙[びみょう]なニュアンスの違[ちが]いを説明[せつめい]するのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "先生は、生徒の表情の微妙な変化を見逃さなかった。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の表情[ひょうじょう]の微妙[びみょう]な変化[へんか]を見逃[みのが]さなかった。", "sentence_source": "generated"}, {"text": "温度が一度上がっただけで、パンの焼き上がりが微妙に違ってくる。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "温度[おんど]が一度[いちど]上[あ]がっただけで、パンの焼[や]き上[あ]がりが微妙[びみょう]に違[ちが]ってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "微妙", "label": "語幹"}, {"form": "微妙な", "label": "連体形"}, {"form": "微妙に", "label": "連用形"}, {"form": "微妙だ", "label": "終止形"}], "register": "標準", "sense_fingerprint": "見分けにくいほど小さな違いや変化があるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 羅針盤 (Zipf 3.09), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52)']::text[], 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "「微妙な弾力」で、わずかな違いや感触を表す意味に合う。"}, {"text": "大胆", "is_correct": false, "explanation": "思い切って行う様子を表す。弾力の細かさには合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "荒っぽく扱う様子を表す。生地の感触を表す語ではない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活な性格を表す。生地の弾力には使わない。"}], "explanations": {"微妙": "「微妙な弾力」で、わずかな違いや感触を表す意味に合う。", "大胆": "思い切って行う様子を表す。弾力の細かさには合わない。", "乱暴": "荒っぽく扱う様子を表す。生地の感触を表す語ではない。", "陽気": "明るく快活な性格を表す。生地の弾力には使わない。"}, "sentence_index": 0, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの山は、標高が微妙に三千メートルも違う。", "explanation": "ここは〈大差〉の意味。三千メートルの開きは大差で、〈微妙〉は使わない。"}, {"text": "夜中の雷は、微妙に天地を揺るがすほどの音で鳴り響いた。", "explanation": "ここは〈激しさ〉の意味。天地を揺るがす激しさは〈微妙〉のわずかさと合わない。"}, {"text": "彼はライバルとの差を、微妙に大きく広げた。", "explanation": "ここは〈大幅〉の意味。差を大幅に広げる規模の変化には〈微妙〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "「空気の微妙な変化」で、わずかな変化を表す意味に合う。"}, {"text": "低俗", "is_correct": false, "explanation": "品が低いという意味。空気の変化には使わない。"}, {"text": "豪快", "is_correct": false, "explanation": "豪快で大胆な様子を表す。わずかな変化には合わない。"}, {"text": "無遠慮", "is_correct": false, "explanation": "遠慮がない様子を表す。空気の変化を修飾しない。"}], "explanations": {"微妙": "「空気の微妙な変化」で、わずかな変化を表す意味に合う。", "低俗": "品が低いという意味。空気の変化には使わない。", "豪快": "豪快で大胆な様子を表す。わずかな変化には合わない。", "無遠慮": "遠慮がない様子を表す。空気の変化を修飾しない。"}, "sentence_index": 6, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その試合は、点差が微妙に開いて圧勝した。", "explanation": "ここは〈圧倒的〉の意味。圧勝するほどの大差を〈微妙〉で表すことはできない。"}, {"text": "彼は足を滑らせ、微妙に全治一年のけがをした。", "explanation": "ここは〈重傷〉の意味。全治一年の大けがは〈微妙〉のわずかさと合わない。"}, {"text": "地震の被害は、微妙に県全域を覆うほどだった。", "explanation": "ここは〈甚大〉の意味。県全域に及ぶ被害は〈微妙〉のわずかさと合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つのコップの高さには、微妙の差がある。", "corrected_sentence": "二つのコップの高さには、微妙な差がある。", "error_description": "「微妙」は形容動詞なので、名詞を修飾するには「な」が必要。「の」は誤りで、「な」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微妙な", "is_correct": true, "explanation": "連体形。「違い」を修飾して名詞を直接つなぐ形。"}, {"text": "微妙だ", "is_correct": false, "explanation": "終止形。名詞を直接修飾できず、ここでは文が続かない。"}, {"text": "微妙さ", "is_correct": false, "explanation": "名詞化した形。「違い」を直接修飾できず、「微妙さ違い」は成り立たない。"}, {"text": "微妙", "is_correct": false, "explanation": "語幹。単独では名詞を修飾できず、文の中で形が決まらない。"}], "correct_form": "微妙な", "base_form": "微妙", "form_label": "連体形", "sentence_index": 1, "explanations": {"微妙な": "連体形。「違い」を修飾して名詞を直接つなぐ形。", "微妙だ": "終止形。名詞を直接修飾できず、ここでは文が続かない。", "微妙さ": "名詞化した形。「違い」を直接修飾できず、「微妙さ違い」は成り立たない。", "微妙": "語幹。単独では名詞を修飾できず、文の中で形が決まらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52236, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この二枚の布は、一見同じだが、触ると手触りが微妙を違う。", "corrected_sentence": "この二枚の布は、一見同じだが、触ると手触りが微妙に違う。", "error_description": "「微妙に違う」は連用形で違いを修飾する形。「微妙を違う」は「を」が誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "微妙な", "is_correct": true, "explanation": "連体形。「ニュアンスの違い」を修飾する形。"}, {"text": "微妙に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「違い」は直接修飾できない。"}, {"text": "微妙で", "is_correct": false, "explanation": "中止形。文を続ける形で、名詞を修飾できず「違い」につながらない。"}, {"text": "微妙だった", "is_correct": false, "explanation": "過去形。名詞を直接修飾できず、ここでは述語としても成り立たない。"}], "correct_form": "微妙な", "base_form": "微妙", "form_label": "連体形", "sentence_index": 7, "explanations": {"微妙な": "連体形。「ニュアンスの違い」を修飾する形。", "微妙に": "連用形。動詞や形容詞を修飾する形で、名詞「違い」は直接修飾できない。", "微妙で": "中止形。文を続ける形で、名詞を修飾できず「違い」につながらない。", "微妙だった": "過去形。名詞を直接修飾できず、ここでは述語としても成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「母の具合は」で話題の主題を示す。「母の具合はどうですか」の正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「母の具合をどうですか」は、状態を尋ねる文に目的語を置く形で不自然。"}, {"text": "に", "is_correct": false, "explanation": "「母の具合にどうですか」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「母の具合でどうですか」は、手段や場所の意味にもならず不自然。"}], "correct_answer": "は", "explanations": {"は": "「母の具合は」で話題の主題を示す。「母の具合はどうですか」の正しい助詞。", "を": "「母の具合をどうですか」は、状態を尋ねる文に目的語を置く形で不自然。", "に": "「母の具合にどうですか」は文として成り立たない。", "で": "「母の具合でどうですか」は、手段や場所の意味にもならず不自然。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ねじの具合がおかしくて」で、具合の主語を示す。正しい助詞。"}, {"text": "の", "is_correct": false, "explanation": "「ねじの具合のおかしくて」は文として成り立たず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「ねじの具合へおかしくて」は方向を表す形で、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「ねじの具合とおかしくて」は並列を表す形で、状態を述べる文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「ねじの具合がおかしくて」で、具合の主語を示す。正しい助詞。", "の": "「ねじの具合のおかしくて」は文として成り立たず、不自然。", "へ": "「ねじの具合へおかしくて」は方向を表す形で、意味が通らない。", "と": "「ねじの具合とおかしくて」は並列を表す形で、状態を述べる文に合わない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体や物事の状態、調子のこと。", "primary_collocate": null, "pronunciation": "ぐあい", "ipa": "ɡɯai", "syllable_count": 3, "sentences": [{"text": "おなかが痛くて具合が悪いので、学校を休みました。", "target_word": "具合", "complexity_tier": "T2", "furigana": "おなかが痛[いた]くて具合[ぐあい]が悪[わる]いので、学校[がっこう]を休[やす]みました。", "sentence_source": "generated"}, {"text": "母の具合はどうですか。もう熱は下がりました。", "target_word": "具合", "complexity_tier": "T2", "furigana": "母[はは]の具合[ぐあい]はどうですか。もう熱[ねつ]は下[さ]がりました。", "sentence_source": "generated"}, {"text": "パソコンの具合が悪いので、店に持っていった。", "target_word": "具合", "complexity_tier": "T2", "furigana": "パソコンの具合[ぐあい]が悪[わる]いので、店[みせ]に持[も]っていった。", "sentence_source": "generated"}, {"text": "昨日より具合がいいので、今日は散歩に行けそうだ。", "target_word": "具合", "complexity_tier": "T3", "furigana": "昨日[きのう]より具合[ぐあい]がいいので、今日[きょう]は散歩[さんぽ]に行[い]けそうだ。", "sentence_source": "generated"}, {"text": "車の具合を見てもらうために、修理工場へ行った。", "target_word": "具合", "complexity_tier": "T3", "furigana": "車[くるま]の具合[ぐあい]を見[み]てもらうために、修理工場[しゅうりこうじょう]へ行[い]った。", "sentence_source": "generated"}, {"text": "彼は顔色が悪く、具合が悪そうだった。", "target_word": "具合", "complexity_tier": "T3", "furigana": "彼[かれ]は顔色[かおいろ]が悪[わる]く、具合[ぐあい]が悪[わる]そうだった。", "sentence_source": "generated"}, {"text": "足の具合はどうですか。まだ少し痛みますか。", "target_word": "具合", "complexity_tier": "T2", "furigana": "足[あし]の具合[ぐあい]はどうですか。まだ少[すこ]し痛[いた]みますか。", "sentence_source": "generated"}, {"text": "この時計は、ねじの具合がおかしくて、時間が合わない。", "target_word": "具合", "complexity_tier": "T3", "furigana": "この時計[とけい]は、ねじの具合[ぐあい]がおかしくて、時間[じかん]が合[あ]わない。", "sentence_source": "generated"}, {"text": "具合が悪くなったら、すぐに先生に言ってください。", "target_word": "具合", "complexity_tier": "T2", "furigana": "具合[ぐあい]が悪[わる]くなったら、すぐに先生[せんせい]に言[い]ってください。", "sentence_source": "generated"}, {"text": "犬の具合が心配で、夜中に何度も様子を見に行った。", "target_word": "具合", "complexity_tier": "T3", "furigana": "犬[いぬ]の具合[ぐあい]が心配[しんぱい]で、夜中[よなか]に何度[なんど]も様子[ようす]を見[み]に行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "具合", "label": "基本形"}], "register": "標準", "sense_fingerprint": "体や物の調子のよしあし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具合", "is_correct": true, "explanation": "「具合が悪い」で、体の調子が悪いことを表す。この文脈の正解。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息が悪い」は意味をなさず、体の調子を表せない。"}, {"text": "足音", "is_correct": false, "explanation": "「足音が悪い」は不自然で、体の状態を表す語ではない。"}, {"text": "鼻声", "is_correct": false, "explanation": "「鼻声が悪い」は体の状態を指すとしても、おなかの痛みと結びつかない。"}], "explanations": {"具合": "「具合が悪い」で、体の調子が悪いことを表す。この文脈の正解。", "寝息": "「寝息が悪い」は意味をなさず、体の調子を表せない。", "足音": "「足音が悪い」は不自然で、体の状態を表す語ではない。", "鼻声": "「鼻声が悪い」は体の状態を指すとしても、おなかの痛みと結びつかない。"}, "sentence_index": 0, "correct_answer": "具合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の出発の予定は、まだ具合を決めていない。", "explanation": "ここは〈予定〉の意味。具合は状態を指すので、日時や計画を決める意味では使えない。"}, {"text": "この店は具合が厚く、ずっと客が絶えない。", "explanation": "ここは〈信用〉の意味。具合は状態を表すので、信頼の厚さを表す「厚い」とは合わない。"}, {"text": "彼は具合が温かく、みんなに好かれる。", "explanation": "ここは〈人柄〉の意味。具合は状態を表すので、人の性格を表す「温かい」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具合", "is_correct": true, "explanation": "「足の具合はどうですか」で、足の状態を尋ねる。この文脈の正解。"}, {"text": "指輪", "is_correct": false, "explanation": "「足の指輪」は意味をなさず、足の状態を尋ねる文に合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "「足の靴下」は不自然で、足の状態を表す語ではない。"}, {"text": "天井", "is_correct": false, "explanation": "「足の天井」は意味をなさず、痛みの話題に合わない。"}], "explanations": {"具合": "「足の具合はどうですか」で、足の状態を尋ねる。この文脈の正解。", "指輪": "「足の指輪」は意味をなさず、足の状態を尋ねる文に合わない。", "靴下": "「足の靴下」は不自然で、足の状態を表す語ではない。", "天井": "「足の天井」は意味をなさず、痛みの話題に合わない。"}, "sentence_index": 6, "correct_answer": "具合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は会議でリーダーの具合を果たした。", "explanation": "ここは〈役割〉の意味。具合は状態を表すので、任務を果たすという意味では使わない。"}, {"text": "彼は具合がとても鋭く、音の違いにすぐ気づく。", "explanation": "ここは〈感覚〉の意味。具合は状態を指すので、感覚の鋭さを表す語ではない。"}, {"text": "この土地の具合は彼だ。", "explanation": "ここは〈持ち主〉の意味。具合は物事の状態を指し、所有する人を表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母の具合をよくなったので、安心した。", "corrected_sentence": "母の具合がよくなったので、安心した。", "error_description": "「具合」は「よくなった」の主語なので「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52241, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "犬の具合に心配で、朝から何度も病院に電話した。", "corrected_sentence": "犬の具合が心配で、朝から何度も病院に電話した。", "error_description": "「心配だ」は「が心配」の形で使うので「に」は誤り。「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「唯一の方法」で、名詞「唯一」と「方法」を連体修飾でつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「唯一を方法」は文として続かない。「を」は目的語を示すので、ここでは使えない。"}, {"text": "で", "is_correct": false, "explanation": "「唯一で方法」は成り立たない。「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置。"}, {"text": "へ", "is_correct": false, "explanation": "「唯一へ方法」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "「唯一の方法」で、名詞「唯一」と「方法」を連体修飾でつなぐ。", "を": "「唯一を方法」は文として続かない。「を」は目的語を示すので、ここでは使えない。", "で": "「唯一で方法」は成り立たない。「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置。", "へ": "「唯一へ方法」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
