INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たった一つのこと。", "primary_collocate": null, "pronunciation": "ゆいいつ", "ipa": "jɯiitsɯ", "syllable_count": 4, "sentences": [{"text": "彼女は私が相談できる唯一の友人です。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]が相談[そうだん]できる唯一[ゆいいつ]の友人[ゆうじん]です。", "sentence_source": "generated"}, {"text": "この島に行く唯一の方法は、船に乗ることだ。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "この島[しま]に行[い]く唯一[ゆいいつ]の方法[ほうほう]は、船[ふね]に乗[の]ることだ。", "sentence_source": "generated"}, {"text": "唯一の欠点は、値段が高いことです。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "唯一[ゆいいつ]の欠点[けってん]は、値段[ねだん]が高[たか]いことです。", "sentence_source": "generated"}, {"text": "彼はチームの中で唯一の経験者だったので、みんなに頼りにされた。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "彼[かれ]はチームの中[なか]で唯一[ゆいいつ]の経験者[けいけんしゃ]だったので、みんなに頼[たよ]りにされた。", "sentence_source": "generated"}, {"text": "この町に唯一残った映画館が来月閉まる。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "この町[まち]に唯一[ゆいいつ]残[のこ]った映画館[えいがかん]が来月[らいげつ]閉[し]まる。", "sentence_source": "generated"}, {"text": "母の写真は、私にとって唯一の宝物だ。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "母[はは]の写真[しゃしん]は、私[わたし]にとって唯一[ゆいいつ]の宝物[たからもの]だ。", "sentence_source": "generated"}, {"text": "唯一の出口がふさがれていて、外に出られなかった。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "唯一[ゆいいつ]の出口[でぐち]がふさがれていて、外[そと]に出[で]られなかった。", "sentence_source": "generated"}, {"text": "山の上にある小さな店が、この村で唯一の食料品店です。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]にある小[ちい]さな店[みせ]が、この村[むら]で唯一[ゆいいつ]の食料品店[しょくりょうひんてん]です。", "sentence_source": "generated"}, {"text": "勝つための唯一のチャンスを、彼は逃さなかった。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "勝[か]つための唯一[ゆいいつ]のチャンスを、彼[かれ]は逃[のが]さなかった。", "sentence_source": "generated"}, {"text": "唯一の心配は、明日の天気だ。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "唯一[ゆいいつ]の心配[しんぱい]は、明日[あした]の天気[てんき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯一", "label": "基本形"}, {"form": "唯一の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "ほかに同じものがなく、たった一つしかないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唯一", "is_correct": true, "explanation": "「相談できる唯一の友人」で、ほかにいない一人を表す。ここに入る語。"}, {"text": "天気", "is_correct": false, "explanation": "「相談できる天気の友人」とは意味が通らない。天気は気象の状態を指す。"}, {"text": "記録", "is_correct": false, "explanation": "記録は記した事柄なので、「友人」を修飾できない。"}, {"text": "出口", "is_correct": false, "explanation": "出口は場所の出入り口なので、人の「友人」を修飾できない。"}], "explanations": {"唯一": "「相談できる唯一の友人」で、ほかにいない一人を表す。ここに入る語。", "天気": "「相談できる天気の友人」とは意味が通らない。天気は気象の状態を指す。", "記録": "記録は記した事柄なので、「友人」を修飾できない。", "出口": "出口は場所の出入り口なので、人の「友人」を修飾できない。"}, "sentence_index": 0, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教室には唯一の生徒が三十人いる。", "explanation": "ここは〈全員〉や〈たくさん〉の意味になるはず。「唯一」は〈ただ一つ〉なので、三十人という複数の人数とは合わない。"}, {"text": "彼は宿題を唯一やった。", "explanation": "ここは〈全部〉の意味。「唯一」は名詞で、動詞を修飾して〈全部〉を表す使い方はしない。"}, {"text": "私は唯一朝ごはんを食べる。", "explanation": "ここは〈大抵〉の意味。「唯一」は〈ただ一つ〉の名詞なので、頻度を表す副詞の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唯一", "is_correct": true, "explanation": "「唯一の出口がふさがれていて」で、出口がひとつしかないことを表す。ここに入る語。"}, {"text": "理由", "is_correct": false, "explanation": "「理由の出口」は意味が通らない。理由は原因や訳を指す。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙の出口」は成り立たない。手紙は文章を送るものなので、出口を修飾しない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫の出口」は意味が通らない。冷蔵庫は家電で、出口の所有を表さない。"}], "explanations": {"唯一": "「唯一の出口がふさがれていて」で、出口がひとつしかないことを表す。ここに入る語。", "理由": "「理由の出口」は意味が通らない。理由は原因や訳を指す。", "手紙": "「手紙の出口」は成り立たない。手紙は文章を送るものなので、出口を修飾しない。", "冷蔵庫": "「冷蔵庫の出口」は意味が通らない。冷蔵庫は家電で、出口の所有を表さない。"}, "sentence_index": 6, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ほかにも唯一の心配が三つある。", "explanation": "ここは〈心配事のすべて〉の意味になるはず。「唯一」は〈ただ一つ〉なので、三つという数と矛盾する。"}, {"text": "私は唯一の友人たちと旅行に出かけた。", "explanation": "ここは〈複数の友人〉の意味。「唯一」は〈ただ一つ〉なので、「たち」で複数を表す語とは合わない。"}, {"text": "彼は唯一、旅をするのが好きだ。", "explanation": "ここは〈とても〉や〈特に〉の意味になるはず。「唯一」は〈ただ一つ〉の名詞なので、程度の副詞の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私には、相談できる唯一に友人がいる。", "corrected_sentence": "私には、相談できる唯一の友人がいる。", "error_description": "誤りは「唯一」の後の助詞。名詞「唯一」が「友人」を修飾するので、連体修飾の「の」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前には唯一に書店が残っている。", "corrected_sentence": "駅前には唯一の書店が残っている。", "error_description": "誤りは「唯一」の後の助詞。「唯一」が「書店」を修飾するので、連体修飾の「の」が必要。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す〈は〉。「農家の営為は」で、後ろの「左右される」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、受け身の文の主語には使えない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置や相手を示すので、主語を表す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すため、主語を示すことはできない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す〈は〉。「農家の営為は」で、後ろの「左右される」の主語になる。", "を": "〈を〉は目的語に付くので、受け身の文の主語には使えない。", "に": "〈に〉は位置や相手を示すので、主語を表す位置には入らない。", "へ": "〈へ〉は方向を示すため、主語を示すことはできない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「小さな営為でも」の〈で〉。〜でも（たとえ〜でも）の形で譲歩を表す。"}, {"text": "が", "is_correct": false, "explanation": "「小さな営為が」は主語の形になり、「〜でも」の譲歩の形にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、「小さな営為をでも」の形にはならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ形。「小さな営為のでも」は譲歩の文にならず不自然。"}], "correct_answer": "で", "explanations": {"で": "「小さな営為でも」の〈で〉。〜でも（たとえ〜でも）の形で譲歩を表す。", "が": "「小さな営為が」は主語の形になり、「〜でも」の譲歩の形にならず不自然。", "を": "〈を〉は目的語に付くので、「小さな営為をでも」の形にはならず不自然。", "の": "「の」は名詞をつなぐ形。「小さな営為のでも」は譲歩の文にならず不自然。"}, "error_tags": {"が": "主語", "の": "連体", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをするための仕事や活動のこと。", "primary_collocate": null, "pronunciation": "えいい", "ipa": "eii", "syllable_count": 3, "sentences": [{"text": "毎日の営為が、町の暮らしを支えている。", "target_word": "営為", "complexity_tier": "T3", "furigana": "毎日[まいにち]の営為[えいい]が、町[まち]の暮[く]らしを支[ささ]えている。", "sentence_source": "generated"}, {"text": "農家の営為は、天気に大きく左右される。", "target_word": "営為", "complexity_tier": "T3", "furigana": "農家[のうか]の営為[えいい]は、天気[てんき]に大[おお]きく左右[さゆう]される。", "sentence_source": "generated"}, {"text": "人々の営為によって、荒れた土地が畑になった。", "target_word": "営為", "complexity_tier": "T3", "furigana": "人々[ひとびと]の営為[えいい]によって、荒[あ]れた土地[とち]が畑[はたけ]になった。", "sentence_source": "generated"}, {"text": "この本には、昔の人の営為が書かれている。", "target_word": "営為", "complexity_tier": "T3", "furigana": "この本[ほん]には、昔[むかし]の人[ひと]の営為[えいい]が書[か]かれている。", "sentence_source": "generated"}, {"text": "魚をとることも、人間の大切な営為の一つだ。", "target_word": "営為", "complexity_tier": "T3", "furigana": "魚[さかな]をとることも、人間[にんげん]の大切[たいせつ]な営為[えいい]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "長い営為の結果、美しい庭ができあがった。", "target_word": "営為", "complexity_tier": "T3", "furigana": "長[なが]い営為[えいい]の結果[けっか]、美[うつく]しい庭[にわ]ができあがった。", "sentence_source": "generated"}, {"text": "彼は研究という営為に一生をささげた。", "target_word": "営為", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]という営為[えいい]に一生[いっしょう]をささげた。", "sentence_source": "generated"}, {"text": "小さな営為でも、続ければ大きな力になる。", "target_word": "営為", "complexity_tier": "T3", "furigana": "小[ちい]さな営為[えいい]でも、続[つづ]ければ大[おお]きな力[ちから]になる。", "sentence_source": "generated"}, {"text": "祭りの準備は、町の人々の営為そのものだった。", "target_word": "営為", "complexity_tier": "T3", "furigana": "祭[まつ]りの準備[じゅんび]は、町[まち]の人々[ひとびと]の営為[えいい]そのものだった。", "sentence_source": "generated"}, {"text": "自然を守る営為は、これからも続けなければならない。", "target_word": "営為", "complexity_tier": "T3", "furigana": "自然[しぜん]を守[まも]る営為[えいい]は、これからも続[つづ]けなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "営為", "label": "基本形"}], "register": "formal", "sense_fingerprint": "何かをするための仕事や活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "営為", "is_correct": true, "explanation": "ここは〈仕事や活動〉の意味。日々の仕事が町の暮らしを支えるという文脈に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は一時的な外出で、毎日町の暮らしを支える主語にはならない。"}, {"text": "休暇", "is_correct": false, "explanation": "休暇は仕事を離れる期間なので、暮らしを支える働きとは合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは自然現象で、町の暮らしを支える行為の主語にはならない。"}], "explanations": {"営為": "ここは〈仕事や活動〉の意味。日々の仕事が町の暮らしを支えるという文脈に合う。", "旅行": "旅行は一時的な外出で、毎日町の暮らしを支える主語にはならない。", "休暇": "休暇は仕事を離れる期間なので、暮らしを支える働きとは合わない。", "夕焼け": "夕焼けは自然現象で、町の暮らしを支える行為の主語にはならない。"}, "sentence_index": 0, "correct_answer": "営為"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "罪を認めたのは、彼の誠実な営為だった。", "explanation": "ここは〈行為〉の意味。ひとつの行いを指す〈行為〉で、営為は継続的な仕事や活動を指すので合わない。"}, {"text": "壁の落書きは、いたずらな子どもの営為だ。", "explanation": "ここは〈仕業〉の意味。いたずらなどを誰がしたかには〈仕業〉を使う。営為はそうした用途では使わないので合わない。"}, {"text": "その発見は、ただの偶然の営為だった。", "explanation": "ここは〈偶然〉の意味。思いがけず起きたことは〈偶然〉で、営為は人が何かをするための仕事や活動を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "営為", "is_correct": true, "explanation": "ここは〈仕事や活動〉の意味。一生をささげる対象として、研究という活動を指す。"}, {"text": "試合", "is_correct": false, "explanation": "試合は勝敗を競う場なので、「研究という〜」の言い換えとして成り立たない。"}, {"text": "余暇", "is_correct": false, "explanation": "余暇は仕事以外の時間で、一生をささげる対象にはならない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は気軽な動作なので、「研究という」に続けると意味が合わない。"}], "explanations": {"営為": "ここは〈仕事や活動〉の意味。一生をささげる対象として、研究という活動を指す。", "試合": "試合は勝敗を競う場なので、「研究という〜」の言い換えとして成り立たない。", "余暇": "余暇は仕事以外の時間で、一生をささげる対象にはならない。", "散歩": "散歩は気軽な動作なので、「研究という」に続けると意味が合わない。"}, "sentence_index": 6, "correct_answer": "営為"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その突然の営為は、周囲を驚かせた。", "explanation": "ここは〈行動〉の意味。とっさの振る舞いは〈行動〉で、営為は続けて取り組む仕事や活動を指すので合わない。"}, {"text": "彼の怠慢は、長く続いた営為だった。", "explanation": "ここは〈怠慢〉の意味。なすべきことを怠る態度は〈怠慢〉で、営為は何かをするための仕事や活動を指すので合わない。"}, {"text": "あの失言は、取り返しのつかない営為だった。", "explanation": "ここは〈過ち〉の意味。誤った言動は〈過ち〉で、営為は目的をもって取り組む活動を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の営為を町の暮らしを支えていることを、誰も疑わない。", "corrected_sentence": "毎日の営為が町の暮らしを支えていることを、誰も疑わない。", "error_description": "誤りは営為の後の助詞。〈支える〉の主語は営為なので〈が〉が正しく、〈を〉では営為が目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52245, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は茶道という営為と、生涯を注いできた。", "corrected_sentence": "彼女は茶道という営為に、生涯を注いできた。", "error_description": "誤りは営為の後の助詞。〈注ぐ〉は注ぐ先を〈に〉で示すため、〈と〉では文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す〈が〉。「長年の営為が〜を支えてきた」で、営為を主語にする。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、営為が主語になる文では使えない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置や相手を示すので、「支えてきた」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すため、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す〈が〉。「長年の営為が〜を支えてきた」で、営為を主語にする。", "を": "〈を〉は目的語に付くので、営為が主語になる文では使えない。", "に": "〈に〉は位置や相手を示すので、「支えてきた」の主語にはならない。", "へ": "〈へ〉は方向を示すため、主語の位置には入らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〜には、の形で主題を示す〈に〉。「建築という営為には」で、話題の範囲を示す。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くため、「欠かせない」の主題を示す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、主題を表す文脈では使えない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体修飾なので、営為に続けて文の主題を示すことはできない。"}], "correct_answer": "に", "explanations": {"に": "〜には、の形で主題を示す〈に〉。「建築という営為には」で、話題の範囲を示す。", "を": "〈を〉は目的語に付くため、「欠かせない」の主題を示す位置には入らない。", "へ": "〈へ〉は方向を示すので、主題を表す文脈では使えない。", "の": "〈の〉は連体修飾なので、営為に続けて文の主題を示すことはできない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある目的のために行う一連の作業や活動。特に、創造的または技術的な取り組み。", "primary_collocate": null, "pronunciation": "えいい", "ipa": "eii", "syllable_count": 3, "sentences": [{"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "営為", "complexity_tier": "T5", "furigana": "静謐[せいひつ]な工房[こうぼう]において、作[つく]り手[て]は野生[やせい]酵母[こうぼ]と乳酸菌[にゅうさんきん]の共生[きょうせい]するサワードウの種起[たねお]こしから営為[えいい]を開始[かいし]する。", "sentence_source": "mined"}, {"text": "職人たちの長年の営為が、この伝統工芸を今日まで支えてきた。", "target_word": "営為", "complexity_tier": "T4", "furigana": "職人[しょくにん]たちの長年[ながねん]の営為[えいい]が、この伝統[でんとう]工芸[こうげい]を今日[きょう]まで支[ささ]えてきた。", "sentence_source": "generated"}, {"text": "研究者にとって、実験を重ねることは日々の営為にほかならない。", "target_word": "営為", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]にとって、実験[じっけん]を重[かさ]ねることは日々[ひび]の営為[えいい]にほかならない。", "sentence_source": "generated"}, {"text": "遺跡から出土した道具には、古代の人々の営為の跡が残されている。", "target_word": "営為", "complexity_tier": "T4", "furigana": "遺跡[いせき]から出土[しゅつど]した道具[どうぐ]には、古代[こだい]の人々[ひとびと]の営為[えいい]の跡[あと]が残[のこ]されている。", "sentence_source": "generated"}, {"text": "彼女は寝食を忘れて、創作の営為に打ち込んだ。", "target_word": "営為", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は寝食[しんしょく]を忘[わす]れて、創作[そうさく]の営為[えいい]に打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "こうした地道な営為の積み重ねが、やがて大きな成果を生んだ。", "target_word": "営為", "complexity_tier": "T4", "furigana": "こうした地道[じみち]な営為[えいい]の積[つ]み重[かさ]ねが、やがて大[おお]きな成果[せいか]を生[う]んだ。", "sentence_source": "generated"}, {"text": "この棚田は、自然の力ではなく人間の営為によって築かれた。", "target_word": "営為", "complexity_tier": "T4", "furigana": "この棚田[たなだ]は、自然[しぜん]の力[ちから]ではなく人間[にんげん]の営為[えいい]によって築[きず]かれた。", "sentence_source": "generated"}, {"text": "建築という営為には、技術と美意識の両方が欠かせない。", "target_word": "営為", "complexity_tier": "T4", "furigana": "建築[けんちく]という営為[えいい]には、技術[ぎじゅつ]と美意識[びいしき]の両方[りょうほう]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "長い営為の末に、ようやく新しい製法が確立された。", "target_word": "営為", "complexity_tier": "T4", "furigana": "長[なが]い営為[えいい]の末[すえ]に、ようやく新[あたら]しい製法[せいほう]が確立[かくりつ]された。", "sentence_source": "generated"}, {"text": "農業は自然と向き合う営為であり、天候に大きく左右される。", "target_word": "営為", "complexity_tier": "T4", "furigana": "農業[のうぎょう]は自然[しぜん]と向[む]き合[あ]う営為[えいい]であり、天候[てんこう]に大[おお]きく左右[さゆう]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "営為", "label": "基本形"}], "register": "formal", "sense_fingerprint": "目的をもって行う創造的・技術的な一連の活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "営為", "is_correct": true, "explanation": "ここは〈取り組み・活動〉の意味。種起こしから始まる一連の作業を指し、「開始する」の目的語として合う。"}, {"text": "酵母", "is_correct": false, "explanation": "酵母は微生物そのもので、「開始する」の対象にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは自然現象で、「〜を開始する」の対象にはならない。"}, {"text": "乳酸菌", "is_correct": false, "explanation": "乳酸菌は生き物の名で、作業の開始対象にはならず文が成り立たない。"}], "explanations": {"営為": "ここは〈取り組み・活動〉の意味。種起こしから始まる一連の作業を指し、「開始する」の目的語として合う。", "酵母": "酵母は微生物そのもので、「開始する」の対象にはならない。", "夕焼け": "夕焼けは自然現象で、「〜を開始する」の対象にはならない。", "乳酸菌": "乳酸菌は生き物の名で、作業の開始対象にはならず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "営為"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その場で手を貸したのは、とっさの親切な営為だった。", "explanation": "ここは〈行為〉の意味。一度きりの親切は〈行為〉で、営為は目的をもって続ける創造・技術的な取り組みを指すので合わない。"}, {"text": "花瓶が割れていたのは、いたずら好きの猫の営為だろう。", "explanation": "ここは〈仕業〉の意味。いたずらや不始末を誰がしたかには〈仕業〉を使う。営為は建設的な取り組みに使うので合わない。"}, {"text": "この居酒屋は夜の営為が長く、午前二時まで開いている。", "explanation": "ここは〈営業〉の意味。店を開けて商いをする時間や活動は〈営業〉で、営為は目的をもつ創造・技術的な取り組みを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "営為", "is_correct": true, "explanation": "ここは〈人の取り組み・働き〉の意味。自然の力と対比して、人が長く手をかけた営みを指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時の区切りで、「人間の〜によって築かれた」の手段にはならない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は自然現象なので、人間の働きとして築いたという文脈に合わない。"}, {"text": "土地", "is_correct": false, "explanation": "土地は築く対象であり、「人間の土地によって築かれた」は文として不自然。"}], "explanations": {"営為": "ここは〈人の取り組み・働き〉の意味。自然の力と対比して、人が長く手をかけた営みを指す。", "季節": "季節は時の区切りで、「人間の〜によって築かれた」の手段にはならない。", "天候": "天候は自然現象なので、人間の働きとして築いたという文脈に合わない。", "土地": "土地は築く対象であり、「人間の土地によって築かれた」は文として不自然。"}, "sentence_index": 6, "correct_answer": "営為"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その突然の営為は、周囲を驚かせた。", "explanation": "ここは〈行動〉の意味。とっさの大胆な振る舞いは〈行動〉で、営為は長く続く目的的な取り組みを指すので合わない。"}, {"text": "あの役所の不正は、組織ぐるみの営為だった。", "explanation": "ここは〈所業〉の意味。悪事や不正をした振る舞いは〈所業〉で、営為は目的をもつ創造・技術的な取り組みを指すので合わない。"}, {"text": "その過ちは、深く反省すべき営為だ。", "explanation": "ここは〈過ち〉の意味。誤った行いは〈過ち〉で、営為は目的をもって取り組む活動を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は長年の営為に成果を、一冊の本にまとめた。", "corrected_sentence": "彼女は長年の営為の成果を、一冊の本にまとめた。", "error_description": "誤りは営為の後の助詞。〈成果〉を修飾するには連体修飾の〈の〉が正しく、〈に〉では成果を位置や相手として結べない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い営為を受け継ぐで、今の職人は製法を守っている。", "corrected_sentence": "古い営為を受け継いで、今の職人は製法を守っている。", "error_description": "誤りは〈受け継ぐ〉の接続形。「〜て」を作るには〈受け継いで〉が正しく、辞書形に〈で〉を続けることはできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
