INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52247, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "しずかなこと。とても静かなこと。", "primary_collocate": null, "pronunciation": "せいひつ", "ipa": "seːçitsɯ", "syllable_count": 4, "sentences": [{"text": "雪が降った朝、町は静謐に包まれていた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]った朝[あさ]、町[まち]は静謐[せいひつ]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "古い寺には、人の声さえ吸い込まれるような静謐がある。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "古[ふる]い寺[てら]には、人[ひと]の声[こえ]さえ吸[す]い込[こ]まれるような静謐[せいひつ]がある。", "sentence_source": "generated"}, {"text": "静謐な図書館の中では、ページをめくる音だけが聞こえた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "静謐[せいひつ]な図書館[としょかん]の中[なか]では、ページをめくる音[おと]だけが聞[き]こえた。", "sentence_source": "generated"}, {"text": "夜明け前の湖は、風もなく静謐だった。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "夜明[よあ]け前[まえ]の湖[みずうみ]は、風[かぜ]もなく静謐[せいひつ]だった。", "sentence_source": "generated"}, {"text": "彼は静謐を破る大きな音に、思わず顔を上げた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "彼[かれ]は静謐[せいひつ]を破[やぶ]る大[おお]きな音[おと]に、思[おも]わず顔[かお]を上[あ]げた。", "sentence_source": "generated"}, {"text": "森の奥の静謐な空気の中で、私は深く息をした。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]の静謐[せいひつ]な空気[くうき]の中[なか]で、私[わたし]は深[ふか]く息[いき]をした。", "sentence_source": "generated"}, {"text": "祈りの時間、聖堂は完全な静謐に満ちていた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "祈[いの]りの時間[じかん]、聖堂[せいどう]は完全[かんぜん]な静謐[せいひつ]に満[み]ちていた。", "sentence_source": "generated"}, {"text": "都会の騒音から離れ、山荘で静謐な時を過ごした。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "都会[とかい]の騒音[そうおん]から離[はな]れ、山荘[さんそう]で静謐[せいひつ]な時[とき]を過[す]ごした。", "sentence_source": "generated"}, {"text": "試合のあと、スタジアムには不思議な静謐が戻ってきた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "試合[しあい]のあと、スタジアムには不思議[ふしぎ]な静謐[せいひつ]が戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "病室の静謐を守るため、看護師は足音を立てずに歩いた。", "target_word": "静謐", "complexity_tier": "T3", "furigana": "病室[びょうしつ]の静謐[せいひつ]を守[まも]るため、看護師[かんごし]は足音[あしおと]を立[た]てずに歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静謐", "label": "基本形"}, {"form": "静謐な", "label": "連体形"}, {"form": "静謐に", "label": "連用形"}, {"form": "静謐だ", "label": "終止形"}], "register": "literary", "sense_fingerprint": "物音一つなく、深く落ち着いて静かな様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52247, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静謐", "is_correct": true, "explanation": "「静謐に包まれていた」は物音のない深い静けさを表し、雪の朝の町の様子に合う。"}, {"text": "騒然", "is_correct": false, "explanation": "「騒然」はざわついて騒がしい様子で、雪の朝の静けさと逆の意味になる。「騒然に」は形も合わない。"}, {"text": "雑然", "is_correct": false, "explanation": "「雑然」は物が散らかって乱れた様子を表すので、静けさを述べる文には合わない。"}, {"text": "殷賑", "is_correct": false, "explanation": "「殷賑」は人や物で賑わうことを表すので、雪の朝の静かな町には合わない。"}], "explanations": {"静謐": "「静謐に包まれていた」は物音のない深い静けさを表し、雪の朝の町の様子に合う。", "騒然": "「騒然」はざわついて騒がしい様子で、雪の朝の静けさと逆の意味になる。「騒然に」は形も合わない。", "雑然": "「雑然」は物が散らかって乱れた様子を表すので、静けさを述べる文には合わない。", "殷賑": "「殷賑」は人や物で賑わうことを表すので、雪の朝の静かな町には合わない。"}, "sentence_index": 0, "correct_answer": "静謐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の前に、どうか静謐にお願いします。", "explanation": "ここは〈静粛〉の意味。会場で話し声を止めるよう頼むときは静粛にと言う。静謐は場の深い静けさを指すので、この依頼には合わない。"}, {"text": "ドアノブに触ると静謐が走った。", "explanation": "ここは〈静電気〉の意味。ドアノブで感じる電気は静電気と言う。静謐は静けさを表すので、電気の話には使えない。"}, {"text": "この金細工は、静謐なほど細い線まで揃っている。", "explanation": "ここは〈精緻〉の意味。細部まで細かく緻密に作られた様子は精緻と言う。静謐は静けさを表すので、ものの細かな作りには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52247, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静謐", "is_correct": true, "explanation": "「完全な静謐に満ちていた」は祈りの場の深い静けさを表し、文脈に合う。"}, {"text": "悠然", "is_correct": false, "explanation": "「悠然」はゆったり落ち着いた様子を表す語で、「完全な悠然に満ちていた」とは言えない。「悠然と」の形になる。"}, {"text": "朦朧", "is_correct": false, "explanation": "「朦朧」は意識がぼんやりした状態を指すので、聖堂の静けさを表す語としては合わない。"}, {"text": "雑多", "is_correct": false, "explanation": "「雑多」は種類が入り混じっていることを表すので、静けさを述べる文には合わない。"}], "explanations": {"静謐": "「完全な静謐に満ちていた」は祈りの場の深い静けさを表し、文脈に合う。", "悠然": "「悠然」はゆったり落ち着いた様子を表す語で、「完全な悠然に満ちていた」とは言えない。「悠然と」の形になる。", "朦朧": "「朦朧」は意識がぼんやりした状態を指すので、聖堂の静けさを表す語としては合わない。", "雑多": "「雑多」は種類が入り混じっていることを表すので、静けさを述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "静謐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会議で最後まで静謐を通した。", "explanation": "ここは〈沈黙〉の意味。黙り通す態度は沈黙を通すと言う。静謐は場の静けさを指すので、人の態度には合わない。"}, {"text": "この台所は静謐なほど清潔に保たれている。", "explanation": "ここは〈清潔〉の意味。汚れがなく衛生的な様子は清潔と言う。静謐は静けさを表すので、掃除の行き届いた状態には使えない。"}, {"text": "腕の静謐が浮き出ている。", "explanation": "ここは〈静脈〉の意味。血液が流れる血管は静脈と言う。静謐は静けさを表すので、体の部位には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52247, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の森は、鳥の声一つない静謐を包まれていた。", "corrected_sentence": "夜の森は、鳥の声一つない静謐に包まれていた。", "error_description": "「包まれる」は「〜に包まれる」と「に」を取る。「静謐を包まれていた」は助詞が誤りで、正しくは「静謐に包まれていた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "静謐", "is_correct": true, "explanation": "「静謐がある」と後に名詞として続く基本形で、この文の形と一致する。"}, {"text": "静謐で", "is_correct": false, "explanation": "中止の「で」は名詞に直接つかないので、「静謐で がある」は成り立たない。"}, {"text": "静謐だった", "is_correct": false, "explanation": "過去の断定の形は文末に来るもので、名詞の前には置けない。"}, {"text": "静謐であった", "is_correct": false, "explanation": "文語的な過去の断定の形で、名詞の前に直接つなぐことができない。"}], "correct_form": "静謐", "base_form": "静謐", "form_label": "基本形（名詞的用法）", "sentence_index": 1, "explanations": {"静謐": "「静謐がある」と後に名詞として続く基本形で、この文の形と一致する。", "静謐で": "中止の「で」は名詞に直接つかないので、「静謐で がある」は成り立たない。", "静謐だった": "過去の断定の形は文末に来るもので、名詞の前には置けない。", "静謐であった": "文語的な過去の断定の形で、名詞の前に直接つなぐことができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52247, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕暮れの丘は、風の音さえ消えるほどの静謐だ空気に包まれている。", "corrected_sentence": "夕暮れの丘は、風の音さえ消えるほどの静謐な空気に包まれている。", "error_description": "形容動詞「静謐」は終止形「だ」のままでは名詞を修飾できない。連体形「な」を使い、正しくは「静謐な空気」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "静謐な", "is_correct": true, "explanation": "連体形の「な」で、後ろの名詞「時」を修飾する形になり、この文と一致する。"}, {"text": "静謐に", "is_correct": false, "explanation": "連用形の「に」は動詞や形容詞を修飾するもので、名詞の「時」にはつながらない。"}, {"text": "静謐だ", "is_correct": false, "explanation": "終止形で言い切りになるため、後ろの名詞「時」を修飾できない。"}, {"text": "静謐である", "is_correct": false, "explanation": "断定の形で、名詞を修飾する形としては使えず、「時」に続かない。"}], "correct_form": "静謐な", "base_form": "静謐", "form_label": "連体形", "sentence_index": 7, "explanations": {"静謐な": "連体形の「な」で、後ろの名詞「時」を修飾する形になり、この文と一致する。", "静謐に": "連用形の「に」は動詞や形容詞を修飾するもので、名詞の「時」にはつながらない。", "静謐だ": "終止形で言い切りになるため、後ろの名詞「時」を修飾できない。", "静謐である": "断定の形で、名詞を修飾する形としては使えず、「時」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す〈が〉。「作り手が見えるパンは」で、見える対象の持ち主として作り手を示す。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、「見える」の主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や共同を示すが、「作り手と見えるパン」は「見える」の相手にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す〈が〉。「作り手が見えるパンは」で、見える対象の持ち主として作り手を示す。", "を": "〈を〉は目的語に付くので、「見える」の主語を示せない。", "と": "〈と〉は並列や共同を示すが、「作り手と見えるパン」は「見える」の相手にならず不自然。", "で": "〈で〉は手段や場所を示すので、主語の位置には入らない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〜になる、の〈に〉。変化の結果を示し、作り手と「になる」を結びつける。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すため、「になる」と結ぶことはできない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、「になる」の補語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、「になる」の補語としては成り立たない。"}], "correct_answer": "に", "explanations": {"に": "〜になる、の〈に〉。変化の結果を示し、作り手と「になる」を結びつける。", "を": "〈を〉は目的語を示すため、「になる」と結ぶことはできない。", "が": "〈が〉は主語を示すので、「になる」の補語にはならない。", "で": "〈で〉は手段や場所を示すので、「になる」の補語としては成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをつくる人。", "primary_collocate": null, "pronunciation": "つくりて", "ipa": "t͡sɯkɯɾite", "syllable_count": 4, "sentences": [{"text": "この料理の作り手は、近所の小さな店の主人です。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "この料理[りょうり]の作[つく]り手[て]は、近所[きんじょ]の小[ちい]さな店[みせ]の主人[しゅじん]です。", "sentence_source": "generated"}, {"text": "作り手が見えるパンは、安心して食べられます。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]が見[み]えるパンは、安心[あんしん]して食[た]べられます。", "sentence_source": "generated"}, {"text": "おもちゃの作り手に、お礼の手紙を書きました。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "おもちゃの作[つく]り手[て]に、お礼[れい]の手紙[てがみ]を書[か]きました。", "sentence_source": "generated"}, {"text": "作り手によって、同じ形のカップでも味わいが違います。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]によって、同[おな]じ形[かたち]のカップでも味[あじ]わいが違[ちが]います。", "sentence_source": "generated"}, {"text": "このセーターの作り手は、私の祖母です。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "このセーターの作[つく]り手[て]は、私[わたし]の祖母[そぼ]です。", "sentence_source": "generated"}, {"text": "市場で、野菜の作り手と話しました。", "target_word": "作り手", "complexity_tier": "T2", "furigana": "市場[いちば]で、野菜[やさい]の作[つく]り手[て]と話[はな]しました。", "sentence_source": "generated"}, {"text": "作り手の名前が、箱の裏に書いてあります。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]の名前[なまえ]が、箱[はこ]の裏[うら]に書[か]いてあります。", "sentence_source": "generated"}, {"text": "私の夢は、絵本の作り手になることです。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "私[わたし]の夢[ゆめ]は、絵本[えほん]の作[つく]り手[て]になることです。", "sentence_source": "generated"}, {"text": "作り手の工夫が、この道具のあちこちに見られます。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]の工夫[くふう]が、この道具[どうぐ]のあちこちに見[み]られます。", "sentence_source": "generated"}, {"text": "買う人と作り手がつながる市が、毎月開かれます。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "買[か]う人[ひと]と作[つく]り手[て]がつながる市[いち]が、毎月[まいつき]開[ひら]かれます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作り手", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものをつくる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作り手", "is_correct": true, "explanation": "ここは〈ものをつくる人〉の意味。料理を作った人として、店の主人を指す文の主語に合う。"}, {"text": "味", "is_correct": false, "explanation": "味は料理の性質で、「〜は近所の小さな店の主人です」の主語にはならない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は料理の素材で、人を指す主語として文が成り立たない。"}, {"text": "器", "is_correct": false, "explanation": "器は料理を盛る道具なので、店の主人という人を指す文には合わない。"}], "explanations": {"作り手": "ここは〈ものをつくる人〉の意味。料理を作った人として、店の主人を指す文の主語に合う。", "味": "味は料理の性質で、「〜は近所の小さな店の主人です」の主語にはならない。", "材料": "材料は料理の素材で、人を指す主語として文が成り立たない。", "器": "器は料理を盛る道具なので、店の主人という人を指す文には合わない。"}, "sentence_index": 0, "correct_answer": "作り手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋の作り手は、軽くて丈夫で、手にすっとなじむ。", "explanation": "ここは〈作品〉の意味。完成した品物そのものの出来は〈作品〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "この鍋の作り手は、鉄と油だけでできている。", "explanation": "ここは〈材料〉の意味。物をつくるもとになるものは〈材料〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "この鍋の作り手は、三百年前から変わらない手順のことだ。", "explanation": "ここは〈製法〉の意味。作るやり方や手順は〈製法〉で、作り手は物をつくる人を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作り手", "is_correct": true, "explanation": "ここは〈ものをつくる人〉の意味。箱に名前を書く人として、の前に来る語に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は自然の状態で、名前が書かれる対象にはならない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は名前を持たないものなので、「の名前が箱の裏に」と続けると不自然。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を指し、名前が箱に書かれるという文には合わない。"}], "explanations": {"作り手": "ここは〈ものをつくる人〉の意味。箱に名前を書く人として、の前に来る語に合う。", "天気": "天気は自然の状態で、名前が書かれる対象にはならない。", "空気": "空気は名前を持たないものなので、「の名前が箱の裏に」と続けると不自然。", "季節": "季節は時期を指し、名前が箱に書かれるという文には合わない。"}, "sentence_index": 6, "correct_answer": "作り手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の作り手は、薄い紙で包まれて届いた。", "explanation": "ここは〈包み〉の意味。中身を包む紙や箱は〈包み〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "この器の作り手は、先月より千円安くなった。", "explanation": "ここは〈値段〉の意味。品物に付く金額は〈値段〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "このテーブルを頼んだのは、遠くの作り手です。", "explanation": "ここは〈注文主〉の意味。品物を依頼する側は注文主で、作り手は製作する側なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作り手を、値段を決める前に材料を選び直した。", "corrected_sentence": "作り手は、値段を決める前に材料を選び直した。", "error_description": "誤りは作り手の後の助詞。主語を示すのは〈は〉で、〈を〉では作り手に対応する動詞がなく文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52253, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作り手を感謝の手紙を送りました。", "corrected_sentence": "作り手に感謝の手紙を送りました。", "error_description": "誤りは作り手の後の助詞。〈送る〉は受け取る相手を〈に〉で示すため、〈を〉では作り手が送られる物になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す〈は〉。「作り手は〜焼き続けている」で話題の人物を示す。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、焼き続ける動作の主体を示せない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は相手や場所を示すため、主語の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、主語を表すことはできない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す〈は〉。「作り手は〜焼き続けている」で話題の人物を示す。", "を": "〈を〉は目的語に付くので、焼き続ける動作の主体を示せない。", "に": "〈に〉は相手や場所を示すため、主語の位置には入らない。", "で": "〈で〉は手段や場所を示すので、主語を表すことはできない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す〈が〉。「作り手が丁寧に仕上げた」で、仕上げる動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語に付くので、仕上げる主体を示すことはできない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は相手や位置を示すため、仕上げる主体を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す〈が〉。「作り手が丁寧に仕上げた」で、仕上げる動作の主体を示す。", "を": "〈を〉は目的語に付くので、仕上げる主体を示すことはできない。", "に": "〈に〉は相手や位置を示すため、仕上げる主体を表せない。", "へ": "〈へ〉は方向を示すので、主語の位置には入らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを作る人のこと。特に、手作業で物を作る職人や芸術家を指す。", "primary_collocate": null, "pronunciation": "つくりて", "ipa": "t͡sɯkɯɾite", "syllable_count": 4, "sentences": [{"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "作り手", "complexity_tier": "T5", "furigana": "静謐[せいひつ]な工房[こうぼう]において、作[つく]り手[て]は野生[やせい]酵母[こうぼ]と乳酸菌[にゅうさんきん]の共生[きょうせい]するサワードウの種起[たねお]こしから営為[えいい]を開始[かいし]する。", "sentence_source": "mined"}, {"text": "この器の作り手は、三十年以上も同じ窯で焼き続けている。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "この器[うつわ]の作[つく]り手[て]は、三十年[さんじゅうねん]以上[いじょう]も同[おな]じ窯[かま]で焼[や]き続[つづ]けている。", "sentence_source": "generated"}, {"text": "作り手の顔が見える野菜は、安心して買える。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]の顔[かお]が見[み]える野菜[やさい]は、安心[あんしん]して買[か]える。", "sentence_source": "generated"}, {"text": "使い手の声を聞いて、作り手は形を少しずつ改良した。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "使[つか]い手[て]の声[こえ]を聞[き]いて、作[つく]り手[て]は形[かたち]を少[すこ]しずつ改良[かいりょう]した。", "sentence_source": "generated"}, {"text": "人気の作り手が、百貨店で個展を開くことになった。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "人気[にんき]の作[つく]り手[て]が、百貨店[ひゃっかてん]で個展[こてん]を開[ひら]くことになった。", "sentence_source": "generated"}, {"text": "作り手の思いが伝わる品は、値段が高くてもよく売れる。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]の思[おも]いが伝[つた]わる品[しな]は、値段[ねだん]が高[たか]くてもよく売[う]れる。", "sentence_source": "generated"}, {"text": "この織物の作り手は高齢で、後継者を探している。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "この織物[おりもの]の作[つく]り手[て]は高齢[こうれい]で、後継者[こうけいしゃ]を探[さが]している。", "sentence_source": "generated"}, {"text": "作り手が丁寧に仕上げた木のおもちゃは、子どもにも人気だ。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "作[つく]り手[て]が丁寧[ていねい]に仕上[しあ]げた木[き]のおもちゃは、子[こ]どもにも人気[にんき]だ。", "sentence_source": "generated"}, {"text": "展示会では、作り手本人が作品の説明をしてくれた。", "target_word": "作り手", "complexity_tier": "T3", "furigana": "展示会[てんじかい]では、作[つく]り手[て]本人[ほんにん]が作品[さくひん]の説明[せつめい]をしてくれた。", "sentence_source": "generated"}, {"text": "若い作り手たちが、古い技法を現代風に生かしている。", "target_word": "作り手", "complexity_tier": "T4", "furigana": "若[わか]い作[つく]り手[て]たちが、古[ふる]い技法[ぎほう]を現代風[げんだいふう]に生[い]かしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作り手", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "手作業で物を作る職人や芸術家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 営為 (Zipf 1.88)']::text[], 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作り手", "is_correct": true, "explanation": "ここは〈物を作る人〉の意味。工房で種起こしから作業を始める主体として主語に合う。"}, {"text": "器", "is_correct": false, "explanation": "器は作られる物で、「営為を開始する」の主語にはならない。"}, {"text": "酵母", "is_correct": false, "explanation": "酵母は生き物で、人の作業を開始する主語としては不自然。"}, {"text": "乳酸菌", "is_correct": false, "explanation": "乳酸菌は微生物の名で、作業を開始する主体にはならない。"}], "explanations": {"作り手": "ここは〈物を作る人〉の意味。工房で種起こしから作業を始める主体として主語に合う。", "器": "器は作られる物で、「営為を開始する」の主語にはならない。", "酵母": "酵母は生き物で、人の作業を開始する主語としては不自然。", "乳酸菌": "乳酸菌は微生物の名で、作業を開始する主体にはならない。"}, "sentence_index": 0, "correct_answer": "作り手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この作り手は、軽くて丈夫で、手にすっとなじむ。", "explanation": "ここは〈作品〉の意味。完成した品物そのものの出来を指すのは〈作品〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "この作り手は、鉄と油だけでできている。", "explanation": "ここは〈材料〉の意味。物をつくるもとになるものは〈材料〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "この作り手は、三百年前から変わらない、ゆっくりした手順だ。", "explanation": "ここは〈製法〉の意味。作るやり方や手順は〈製法〉で、作り手は物をつくる人を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作り手", "is_correct": true, "explanation": "ここは〈物を作る人〉の意味。織物を作ってきた高齢の人として、後継者を探す主語に合う。"}, {"text": "糸", "is_correct": false, "explanation": "糸は素材で、高齢で後継者を探す主語にはならない。"}, {"text": "客", "is_correct": false, "explanation": "客は買いに来る人を指し、この織物の後継者探しの主語とは合わない。"}, {"text": "旅人", "is_correct": false, "explanation": "旅人は一時的に訪れる人で、この織物の後継者を探す文脈に合わない。"}], "explanations": {"作り手": "ここは〈物を作る人〉の意味。織物を作ってきた高齢の人として、後継者を探す主語に合う。", "糸": "糸は素材で、高齢で後継者を探す主語にはならない。", "客": "客は買いに来る人を指し、この織物の後継者探しの主語とは合わない。", "旅人": "旅人は一時的に訪れる人で、この織物の後継者を探す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "作り手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の作り手は、薄い紙で丁寧に包まれて届いた。", "explanation": "ここは〈包み〉の意味。中身を包む紙や箱は〈包み〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "このお皿の作り手は、先月より千円安くなった。", "explanation": "ここは〈値段〉の意味。品物に付く金額は〈値段〉で、作り手は物をつくる人を指すので合わない。"}, {"text": "このお皿を頼んだのは、遠方に住む作り手の方だ。", "explanation": "ここは〈注文主〉の意味。品物を頼む側は注文主で、作り手は製作する側なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この器の作り手に思いが、形に表れている。", "corrected_sentence": "この器の作り手の思いが、形に表れている。", "error_description": "誤りは作り手の後の助詞。〈思い〉を修飾するには連体修飾の〈の〉が正しく、〈に〉では思いを修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作り手を丁寧に仕上げた木の器は、長く使える。", "corrected_sentence": "作り手が丁寧に仕上げた木の器は、長く使える。", "error_description": "誤りは作り手の後の助詞。〈仕上げた〉の主語は作り手なので〈が〉が正しく、〈を〉では作り手が仕上げられる対象になり意味が逆になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
