INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長さをはかる単位で、1メートルの1000分の1を表す。数字のあとにつけて使う。", "primary_collocate": null, "pronunciation": "みり", "ipa": "miɾi", "syllable_count": 2, "sentences": [{"text": "昨日は大雨で、一日に80ミリも雨が降りました。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "昨日[きのう]は大雨[おおあめ]で、一日[いちにち]に80ミリも雨[あめ]が降[ふ]りました。", "sentence_source": "generated"}, {"text": "このネジは直径が5ミリなので、細いドライバーが必要です。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "このネジは直径[ちょっけい]が5ミリなので、細[ほそ]いドライバーが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "彼は1ミリも動かずに、じっと鳥を見つめていた。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "彼[かれ]は1ミリも動[うご]かずに、じっと鳥[とり]を見[み]つめていた。", "sentence_source": "generated"}, {"text": "ズボンが少し長いので、すそを5ミリ短くしてもらった。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "ズボンが少[すこ]し長[なが]いので、すそを5ミリ短[みじか]くしてもらった。", "sentence_source": "generated"}, {"text": "彼女の爪は、1か月で3ミリくらいのびる。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の爪[つめ]は、1か月[げつ]で3ミリくらいのびる。", "sentence_source": "generated"}, {"text": "このスマホは、厚さがわずか7ミリしかなく、とてもうすい。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "このスマホは、厚[あつ]さがわずか7ミリしかなく、とてもうすい。", "sentence_source": "generated"}, {"text": "ほんの1ミリの差で、ボールはゴールの外へ出た。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "ほんの1ミリの差[さ]で、ボールはゴールの外[そと]へ出[で]た。", "sentence_source": "generated"}, {"text": "この雨量計は、1時間に降った雨が何ミリかを教えてくれる。", "target_word": "ミリ", "complexity_tier": "T4", "furigana": "この雨量計[うりょうけい]は、1時間[じかん]に降[ふ]った雨[あめ]が何[なん]ミリかを教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "その虫は体長が2ミリほどしかなく、目を近づけないと見えません。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "その虫[むし]は体長[たいちょう]が2ミリほどしかなく、目[め]を近[ちか]づけないと見[み]えません。", "sentence_source": "generated"}, {"text": "机の脚の長さが1ミリ違うだけで、机はがたがたゆれる。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "机[つくえ]の脚[あし]の長[なが]さが1ミリ違[ちが]うだけで、机[つくえ]はがたがたゆれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミリ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "数字のあとにつけて、ごく小さな長さや雨量を言う語(5ミリ・1ミリも動かない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミリ", "is_correct": true, "explanation": "ミリメートルの「ミリ」。雨量を表すのに使い、「一日に80ミリの雨」という文に合う。"}, {"text": "センチ", "is_correct": false, "explanation": "センチは長さの単位だが、雨量はミリで表すのが普通。「80センチも雨が降る」は文として合わない。"}, {"text": "グラム", "is_correct": false, "explanation": "グラムは重さの単位。雨が降った量を表す文脈には使えない。"}, {"text": "キロ", "is_correct": false, "explanation": "キロは1000倍を表す接頭語。一日の雨量が80キロという数値は現実的でなく、雨量の表し方とも合わない。"}], "explanations": {"ミリ": "ミリメートルの「ミリ」。雨量を表すのに使い、「一日に80ミリの雨」という文に合う。", "センチ": "センチは長さの単位だが、雨量はミリで表すのが普通。「80センチも雨が降る」は文として合わない。", "グラム": "グラムは重さの単位。雨が降った量を表す文脈には使えない。", "キロ": "キロは1000倍を表す接頭語。一日の雨量が80キロという数値は現実的でなく、雨量の表し方とも合わない。"}, "sentence_index": 0, "correct_answer": "ミリ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物は、重さが3ミリだ。", "explanation": "ここは重さの「グラム」の意味。ミリだけでは重さを表せず、「ミリグラム」のように単位と組み合わせて使う。"}, {"text": "降水確率は80ミリだ。", "explanation": "ここは確率の「パーセント」の意味。ミリは雨量の単位で、確率には使わない。"}, {"text": "コップの牛乳を3ミリ飲んだ。", "explanation": "ここは容量の「ミリリットル」の意味。ミリだけでは飲み物の量を表せず、長さの意味のミリでも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミリ", "is_correct": true, "explanation": "長さの「ミリ」。ボールがゴールの外に出るほどの、ほんの小さな差を表す。"}, {"text": "カラット", "is_correct": false, "explanation": "カラットは宝石の重さの単位。ボールの位置の差には合わない。"}, {"text": "ワット", "is_correct": false, "explanation": "ワットは電力の単位。長さや位置の差を表す文脈には使えない。"}, {"text": "ヘルツ", "is_correct": false, "explanation": "ヘルツは周波数の単位。ボールの位置の差を言うには使えない。"}], "explanations": {"ミリ": "長さの「ミリ」。ボールがゴールの外に出るほどの、ほんの小さな差を表す。", "カラット": "カラットは宝石の重さの単位。ボールの位置の差には合わない。", "ワット": "ワットは電力の単位。長さや位置の差を表す文脈には使えない。", "ヘルツ": "ヘルツは周波数の単位。ボールの位置の差を言うには使えない。"}, "sentence_index": 6, "correct_answer": "ミリ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "東京から大阪までは、道のりが500ミリほどある。", "explanation": "ここは「キロ」の意味。ミリは数ミリから数センチの長さに使い、都市間の距離には使わない。"}, {"text": "彼はテストで3ミリ点を取った。", "explanation": "ここは「得点」の意味。ミリは長さの単位なので、点数を数えるのには使わない。"}, {"text": "彼は1ミリ年上なので、先輩と呼ばれる。", "explanation": "ここは年齢の差（歳の差）の意味。年齢の差は「歳」で表し、ミリは長さの単位にしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ほんの1ミリに差で、人形が棚から落ちた。", "corrected_sentence": "ほんの1ミリの差で、人形が棚から落ちた。", "error_description": "誤: 「1ミリに差」（に）。正: 「1ミリの差」（の）。「ミリの差」の形で、名詞を修飾する「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ズボンのすそを5ミリ短くなってもらった。", "corrected_sentence": "ズボンのすそを5ミリ短くしてもらった。", "error_description": "誤: 「短くなってもらった」（なる）。正: 「短くしてもらった」（する）。「〜してもらう」は他動詞の「する」で受ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
