INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52256, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「ミリ」は、基本の単位の1000分の1を表す接頭語です。例えば、1メートルの1000分の1が1ミリメートルです。", "primary_collocate": null, "pronunciation": "みり", "ipa": "miɾi", "syllable_count": 2, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "ミリ", "complexity_tier": "T5", "furigana": "水温[すいおん]と室温[しつおん]をミリ単位[たんい]で制御[せいぎょ]し、小麦粉[こむぎこ]と水[みず]のみを混[ま]ぜ合[あ]わせる行為[こうい]は、単[たん]なる調理[ちょうり]の域[いき]を超[こ]え、微生物[びせいぶつ]の生態系[せいたいけい]を育[はぐく]む科学的[かがくてき]な実験[じっけん]とも呼応[こおう]する。", "sentence_source": "mined"}, {"text": "この定規には、ミリ単位の細かい目盛りがあるので、小さな部品の長さも測れる。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "この定規[じょうぎ]には、ミリ単位[たんい]の細[こま]かい目盛[めも]りがあるので、小[ちい]さな部品[ぶひん]の長[なが]さも測[はか]れる。", "sentence_source": "generated"}, {"text": "薬の量はミリグラム単位で決まっているため、少し間違えるだけでも危険だ。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "薬[くすり]の量[りょう]はミリグラム単位[たんい]で決[き]まっているため、少[すこ]し間違[まちが]えるだけでも危険[きけん]だ。", "sentence_source": "generated"}, {"text": "レシピに牛乳200ミリリットルと書いてあったので、計量カップで量って鍋に入れた。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "レシピに牛乳[ぎゅうにゅう]200ミリリットルと書[か]いてあったので、計量[けいりょう]カップで量[はか]って鍋[なべ]に入[い]れた。", "sentence_source": "generated"}, {"text": "1ミリ秒は1000分の1秒なので、人間の目ではその間の変化は見えない。", "target_word": "ミリ", "complexity_tier": "T4", "furigana": "1ミリ秒[びょう]は1000分[ぶん]の1秒[びょう]なので、人間[にんげん]の目[め]ではその間[あいだ]の変化[へんか]は見[み]えない。", "sentence_source": "generated"}, {"text": "この部品は、ミリ単位でずれると機械が動かなくなるほど精密に作られている。", "target_word": "ミリ", "complexity_tier": "T4", "furigana": "この部品[ぶひん]は、ミリ単位[たんい]でずれると機械[きかい]が動[うご]かなくなるほど精密[せいみつ]に作[つく]られている。", "sentence_source": "generated"}, {"text": "この装置は、通信の遅れをミリ秒単位で記録している。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "この装置[そうち]は、通信[つうしん]の遅[おく]れをミリ秒[びょう]単位[たんい]で記録[きろく]している。", "sentence_source": "generated"}, {"text": "大工さんは板の厚さをミリ単位で測り、すき間のない棚を作った。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "大工[だいく]さんは板[いた]の厚[あつ]さをミリ単位[たんい]で測[はか]り、すき間[ま]のない棚[たな]を作[つく]った。", "sentence_source": "generated"}, {"text": "病院では、子どもの飲み薬を1ミリリットル単位で量って渡してくれる。", "target_word": "ミリ", "complexity_tier": "T3", "furigana": "病院[びょういん]では、子[こ]どもの飲[の]み薬[ぐすり]を1ミリリットル単位[たんい]で量[はか]って渡[わた]してくれる。", "sentence_source": "generated"}, {"text": "1グラムの1000分の1を、ミリグラムと呼ぶ。", "target_word": "ミリ", "complexity_tier": "T2", "furigana": "1グラムの1000分[ぶん]の1を、ミリグラムと呼[よ]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミリ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "単位の前につく接頭語。基本単位の1000分の1を表す(ミリ単位・ミリ秒・ミリグラム・ミリリットル)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 混ぜ合わ (Zipf 2.89), 育む (Zipf 3.02), 呼応 (Zipf 3.02)']::text[], '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52256, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミリ", "is_correct": true, "explanation": "基本単位の1000分の1を表す接頭語で、水温と室温を細かく制御するという文脈に合う。"}, {"text": "キロ", "is_correct": false, "explanation": "キロは1000倍を表す接頭語。水温や室温を制御する精度としては大きすぎ、文の内容と合わない。"}, {"text": "センチ", "is_correct": false, "explanation": "センチは100分の1の単位で、水温の細かな制御を言うには粗い。「ミリ単位」の精密さと矛盾する。"}, {"text": "メガ", "is_correct": false, "explanation": "メガは100万倍を表す接頭語。水温の制御にこの単位は使わず、文の意味に合わない。"}], "explanations": {"ミリ": "基本単位の1000分の1を表す接頭語で、水温と室温を細かく制御するという文脈に合う。", "キロ": "キロは1000倍を表す接頭語。水温や室温を制御する精度としては大きすぎ、文の内容と合わない。", "センチ": "センチは100分の1の単位で、水温の細かな制御を言うには粗い。「ミリ単位」の精密さと矛盾する。", "メガ": "メガは100万倍を表す接頭語。水温の制御にこの単位は使わず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "ミリ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場には3ミリもの人が集まった。", "explanation": "ここは「千」の意味のつもりで使われている。ミリは1000分の1を表す接頭語で、人の数には使えない。"}, {"text": "成功率は30ミリだった。", "explanation": "ここは「パーセント」の意味。ミリは割合を表す語ではないので、%の代わりにはならない。"}, {"text": "この荷物の重さは5ミリメートルだ。", "explanation": "ここは重さの「グラム」の意味。ミリメートルは長さの単位なので、重さには使えない。重さはミリグラムで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52256, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミリ", "is_correct": true, "explanation": "ミリ秒（1000分の1秒）の「ミリ」。通信の遅れは秒の細かい単位で測るので、ここに入る。"}, {"text": "デシ", "is_correct": false, "explanation": "デシは10分の1の接頭語。「デシ秒」という単位は一般に使わず、通信の遅れを記録する文脈に合わない。"}, {"text": "ギガ", "is_correct": false, "explanation": "ギガは10億倍の接頭語。通信の遅れを記録する単位としては大きすぎ、「ギガ秒」も使われない。"}, {"text": "メガ", "is_correct": false, "explanation": "メガは100万倍を表す接頭語。時間の記録に「メガ秒」は使われず、文の意味に合わない。"}], "explanations": {"ミリ": "ミリ秒（1000分の1秒）の「ミリ」。通信の遅れは秒の細かい単位で測るので、ここに入る。", "デシ": "デシは10分の1の接頭語。「デシ秒」という単位は一般に使わず、通信の遅れを記録する文脈に合わない。", "ギガ": "ギガは10億倍の接頭語。通信の遅れを記録する単位としては大きすぎ、「ギガ秒」も使われない。", "メガ": "メガは100万倍を表す接頭語。時間の記録に「メガ秒」は使われず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "ミリ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "1グラムの100分の1を、ミリグラムと呼ぶ。", "explanation": "ここは100分の1（センチ）の位取りと取り違えている。ミリは1000分の1を表すので合わない。"}, {"text": "1グラムの1000倍を、ミリグラムと呼ぶ。", "explanation": "1000倍を表すのはキロ（キログラム）。ミリは1000分の1を表す接頭語なので、この意味では使えない。"}, {"text": "1グラムの100万分の1を、ミリグラムと呼ぶ。", "explanation": "ここは100万分の1（マイクロ）の意味。100万分の1はマイクログラムで表し、ミリは1000分の1を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52256, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は板の厚さをミリ単位を測って、棚を作った。", "corrected_sentence": "父は板の厚さをミリ単位で測って、棚を作った。", "error_description": "誤: 「ミリ単位を測る」（を）。正: 「ミリ単位で測る」（で）。「〜単位で測る」の形で、手段を表す「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52256, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "そのセンサーは、信号の遅れをミリグラム単位で記録している。", "corrected_sentence": "そのセンサーは、信号の遅れをミリ秒単位で記録している。", "error_description": "誤: 「ミリグラム」（重さの単位）。正: 「ミリ秒」（時間の単位）。時間の遅れを重さの単位で記録することはできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「パートナーになって」で、なる対象を表す。正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「パートナーをになって」は文として成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「パートナーでになって」は、手段や場所の意味にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「パートナーのになって」は連体修飾にならず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「パートナーになって」で、なる対象を表す。正しい助詞。", "を": "「パートナーをになって」は文として成り立たず、不自然。", "で": "「パートナーでになって」は、手段や場所の意味にもならない。", "の": "「パートナーのになって」は連体修飾にならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「最初のパートナーが休んだ」で、休む主語を示す。正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「最初のパートナーへ休んだ」は方向の形で、休むという動作に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「最初のパートナーから休んだ」は起点の意味になり、文の流れに合わない。"}, {"text": "より", "is_correct": false, "explanation": "「最初のパートナーより休んだ」は比較の形で、休む主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「最初のパートナーが休んだ」で、休む主語を示す。正しい助詞。", "へ": "「最初のパートナーへ休んだ」は方向の形で、休むという動作に合わない。", "から": "「最初のパートナーから休んだ」は起点の意味になり、文の流れに合わない。", "より": "「最初のパートナーより休んだ」は比較の形で、休む主語にならない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いっしょに何かをする人。", "primary_collocate": null, "pronunciation": "ぱーとなー", "ipa": "paːtonaː", "syllable_count": 5, "sentences": [{"text": "今日のテニスの試合では、田中さんがぼくのパートナーです。", "target_word": "パートナー", "complexity_tier": "T2", "furigana": "今日[きょう]のテニスの試合[しあい]では、田中[たなか]さんがぼくのパートナーです。", "sentence_source": "generated"}, {"text": "授業で、隣の人とパートナーになって会話を練習した。", "target_word": "パートナー", "complexity_tier": "T2", "furigana": "授業[じゅぎょう]で、隣[となり]の人[ひと]とパートナーになって会話[かいわ]を練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "ダンスのパートナーと、毎週土曜日に練習している。", "target_word": "パートナー", "complexity_tier": "T2", "furigana": "ダンスのパートナーと、毎週[まいしゅう]土曜日[どようび]に練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "旅行のパートナーは、いつも同じ友達だ。", "target_word": "パートナー", "complexity_tier": "T2", "furigana": "旅行[りょこう]のパートナーは、いつも同[おな]じ友達[ともだち]だ。", "sentence_source": "generated"}, {"text": "先生は「パートナーと二人で相談してください」と言った。", "target_word": "パートナー", "complexity_tier": "T2", "furigana": "先生[せんせい]は「パートナーと二人[ふたり]で相談[そうだん]してください」と言[い]った。", "sentence_source": "generated"}, {"text": "水泳の練習では、パートナーが私の泳ぎを見てくれる。", "target_word": "パートナー", "complexity_tier": "T3", "furigana": "水泳[すいえい]の練習[れんしゅう]では、パートナーが私[わたし]の泳[およ]ぎを見[み]てくれる。", "sentence_source": "generated"}, {"text": "卓球のダブルスでは、パートナーとの息が大切だ。", "target_word": "パートナー", "complexity_tier": "T3", "furigana": "卓球[たっきゅう]のダブルスでは、パートナーとの息[いき]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "最初のパートナーが休んだので、新しい人と組んだ。", "target_word": "パートナー", "complexity_tier": "T3", "furigana": "最初[さいしょ]のパートナーが休[やす]んだので、新[あたら]しい人[ひと]と組[く]んだ。", "sentence_source": "generated"}, {"text": "私の新しいパートナーは、いつも明るくて頼りになる。", "target_word": "パートナー", "complexity_tier": "T3", "furigana": "私[わたし]の新[あたら]しいパートナーは、いつも明[あか]るくて頼[たよ]りになる。", "sentence_source": "generated"}, {"text": "ゲームの中で、友達をパートナーにして敵と戦った。", "target_word": "パートナー", "complexity_tier": "T3", "furigana": "ゲームの中[なか]で、友達[ともだち]をパートナーにして敵[てき]と戦[たたか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パートナー", "label": "基本形"}], "register": "標準", "sense_fingerprint": "いっしょに何かをする相手の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パートナー", "is_correct": true, "explanation": "「ぼくのパートナーです」で、試合で組む相手を表す。この文脈の正解。"}, {"text": "審判", "is_correct": false, "explanation": "「ぼくの審判です」は意味が通らず、一緒に組む相手ではない。"}, {"text": "観客", "is_correct": false, "explanation": "「ぼくの観客です」は不自然で、試合で組む関係を表せない。"}, {"text": "得点", "is_correct": false, "explanation": "「ぼくの得点です」は意味をなさず、人を指せない。"}], "explanations": {"パートナー": "「ぼくのパートナーです」で、試合で組む相手を表す。この文脈の正解。", "審判": "「ぼくの審判です」は意味が通らず、一緒に組む相手ではない。", "観客": "「ぼくの観客です」は不自然で、試合で組む関係を表せない。", "得点": "「ぼくの得点です」は意味をなさず、人を指せない。"}, "sentence_index": 0, "correct_answer": "パートナー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合では、ライバルとしてパートナーに勝つ作戦を立てた。", "explanation": "ここは〈対戦相手〉の意味。パートナーは共に行動する相手で、勝つ対象にはならない。"}, {"text": "パートナーの季節になって、桜が咲き始めた。", "explanation": "ここは〈季節〉の意味。パートナーは人を指す語で、春や夏といった季節は表せない。"}, {"text": "夏休みは、パートナーという町でキャンプをした。", "explanation": "ここは〈地名〉の意味。パートナーは人を指す語で、場所の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パートナー", "is_correct": true, "explanation": "「パートナーとの息が大切だ」で、ダブルスで組む相手を表す。この文脈の正解。"}, {"text": "天気", "is_correct": false, "explanation": "「天気との息が大切だ」は意味をなさず、一緒に組む相手にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書との息が大切だ」は不自然で、試合で組む関係を表せない。"}, {"text": "信号", "is_correct": false, "explanation": "「信号との息が大切だ」は意味が通らず、人との息を表せない。"}], "explanations": {"パートナー": "「パートナーとの息が大切だ」で、ダブルスで組む相手を表す。この文脈の正解。", "天気": "「天気との息が大切だ」は意味をなさず、一緒に組む相手にならない。", "教科書": "「教科書との息が大切だ」は不自然で、試合で組む関係を表せない。", "信号": "「信号との息が大切だ」は意味が通らず、人との息を表せない。"}, "sentence_index": 6, "correct_answer": "パートナー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、パートナーを箸代わりにして朝食を食べる。", "explanation": "ここは〈道具〉の意味。パートナーは人を指すので、箸の代わりに使う物とはならない。"}, {"text": "会議はパートナーの三時に始まった。", "explanation": "ここは〈時刻〉の意味。パートナーは人を指す語で、時間を示す使い方はしない。"}, {"text": "明日のパートナーは、雨が降るらしい。", "explanation": "ここは〈天気〉の意味。パートナーは人を指す語で、天候の話題には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は毎週土曜日、ダンスのパートナーに練習している。", "corrected_sentence": "彼女は毎週土曜日、ダンスのパートナーと練習している。", "error_description": "「練習する」は一緒に行う相手を「と」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合では、弟をパートナーで二人で戦った。", "corrected_sentence": "試合では、弟をパートナーにして二人で戦った。", "error_description": "「パートナーにする」の「に」が必要。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「焼き上げると」の「と」。焼いた結果おいしくなるという条件を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」だが、「焼き上げるを」は後続の文と繋がらない。"}, {"text": "に", "is_correct": false, "explanation": "場所や時点を示す「に」で、動詞の終止形の後には置けない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」だが、動詞の終止形に直接は付かない。"}], "correct_answer": "と", "explanations": {"と": "「焼き上げると」の「と」。焼いた結果おいしくなるという条件を示す。", "を": "目的語を示す「を」だが、「焼き上げるを」は後続の文と繋がらない。", "に": "場所や時点を示す「に」で、動詞の終止形の後には置けない。", "で": "手段を示す「で」だが、動詞の終止形に直接は付かない。"}, "error_tags": {"を": "目的語", "に": "場所・時点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「焼き上げると」の「と」。焼いた結果いい匂いがしてきたという条件を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、焼き上げるの後には続かない。"}, {"text": "の", "is_correct": false, "explanation": "名詞に付く「の」で、動詞の終止形の後では文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「焼き上げるに」は動詞の終止形に「に」が続かず、文として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「焼き上げると」の「と」。焼いた結果いい匂いがしてきたという条件を示す。", "へ": "方向を示す「へ」で、焼き上げるの後には続かない。", "の": "名詞に付く「の」で、動詞の終止形の後では文が崩れる。", "に": "「焼き上げるに」は動詞の終止形に「に」が続かず、文として成り立たない。"}, "error_tags": {"へ": "方向", "の": "連体・名詞化", "に": "場所・時点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たべものに ひを つかって あつく して、たべられるように すること。", "primary_collocate": null, "pronunciation": "やきあげる", "ipa": "jakiaɡeɾɯ", "syllable_count": 5, "sentences": [{"text": "母はオーブンでパンを焼き上げました。", "target_word": "焼き上げました", "complexity_tier": "T3", "furigana": "母[はは]はオーブンでパンを焼[や]き上[あ]げました。", "sentence_source": "generated"}, {"text": "ピザは石の窯で焼き上げると、おいしくなります。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "ピザは石[いし]の窯[かま]で焼[や]き上[あ]げると、おいしくなります。", "sentence_source": "generated"}, {"text": "魚を焼き上げてから、皿にのせてください。", "target_word": "焼き上げて", "complexity_tier": "T3", "furigana": "魚[さかな]を焼[や]き上[あ]げてから、皿[さら]にのせてください。", "sentence_source": "generated"}, {"text": "日曜日に、父がクッキーを焼き上げました。", "target_word": "焼き上げました", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、父[ちち]がクッキーを焼[や]き上[あ]げました。", "sentence_source": "generated"}, {"text": "肉を強い火で焼き上げれば、中までしっかり熱くなります。", "target_word": "焼き上げれば", "complexity_tier": "T3", "furigana": "肉[にく]を強[つよ]い火[ひ]で焼[や]き上[あ]げれば、中[なか]までしっかり熱[あつ]くなります。", "sentence_source": "generated"}, {"text": "この店では、注文を受けてからパンを焼き上げます。", "target_word": "焼き上げます", "complexity_tier": "T3", "furigana": "この店[みせ]では、注文[ちゅうもん]を受[う]けてからパンを焼[や]き上[あ]げます。", "sentence_source": "generated"}, {"text": "子どもたちは、ホットケーキを上手に焼き上げた。", "target_word": "焼き上げた", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ホットケーキを上手[じょうず]に焼[や]き上[あ]げた。", "sentence_source": "generated"}, {"text": "三十分かけてケーキを焼き上げると、いい匂いがしてきた。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "三十分[さんじゅっぷん]かけてケーキを焼[や]き上[あ]げると、いい匂[にお]いがしてきた。", "sentence_source": "generated"}, {"text": "魚が生のままでは食べられないので、よく焼き上げる。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "魚[さかな]が生[なま]のままでは食[た]べられないので、よく焼[や]き上[あ]げる。", "sentence_source": "generated"}, {"text": "朝、おばあさんは大きなさつまいもを焼き上げた。", "target_word": "焼き上げた", "complexity_tier": "T3", "furigana": "朝[あさ]、おばあさんは大[おお]きなさつまいもを焼[や]き上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焼き上げます", "label": "丁寧形"}, {"form": "焼き上げて", "label": "て形"}, {"form": "焼き上げた", "label": "た形"}, {"form": "焼き上げない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "食べ物に火を通して、食べられる状態に焼いて仕上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼き上げました", "is_correct": true, "explanation": "丁寧な過去形で、文末に置いて「パンを焼いて仕上げた」という事実を述べる。"}, {"text": "焼き上げ", "is_correct": false, "explanation": "語幹だけでは文末に置けず、文が完結しない。"}, {"text": "焼き上げて", "is_correct": false, "explanation": "「て形」は文末で完結しない。"}, {"text": "焼き上げれば", "is_correct": false, "explanation": "仮定形は文末で完結せず、文が成立しない。"}], "explanations": {"焼き上げました": "丁寧な過去形で、文末に置いて「パンを焼いて仕上げた」という事実を述べる。", "焼き上げ": "語幹だけでは文末に置けず、文が完結しない。", "焼き上げて": "「て形」は文末で完結しない。", "焼き上げれば": "仮定形は文末で完結せず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "焼き上げました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裏庭の枯れ草を焼き上げて、きれいにした。", "explanation": "〈焼き払う〉の意味で使っているが、焼き上げるは食べ物などを火で仕上げる語なので、枯れ草を燃やす意味にはならない。"}, {"text": "ゼリーを焼き上げて、冷蔵庫で固めた。", "explanation": "〈冷却して凝固させる〉の意味で使っているが、焼き上げるは火を通して仕上げる語なので、ゼリーを冷やして凝固させる操作には使えない。"}, {"text": "洗濯物を焼き上げて、ベランダに干した。", "explanation": "〈乾燥させる〉の意味で使っているが、焼き上げるは火で仕上げる語なので、洗濯物を乾かす操作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焼き上げた", "is_correct": true, "explanation": "「子どもたちは、ホットケーキを上手に焼き上げた」で、焼いて完成させたという意味に合う。"}, {"text": "眠らせた", "is_correct": false, "explanation": "ホットケーキを眠らせるという言い方は、料理の文脈では意味が通らない。"}, {"text": "踏みつけた", "is_correct": false, "explanation": "ホットケーキを踏みつけるのは「上手に」と噛み合わず、料理の文脈に合わない。"}, {"text": "叩き割った", "is_correct": false, "explanation": "「上手に叩き割る」は料理の仕上げの文脈に合わない。"}], "explanations": {"焼き上げた": "「子どもたちは、ホットケーキを上手に焼き上げた」で、焼いて完成させたという意味に合う。", "眠らせた": "ホットケーキを眠らせるという言い方は、料理の文脈では意味が通らない。", "踏みつけた": "ホットケーキを踏みつけるのは「上手に」と噛み合わず、料理の文脈に合わない。", "叩き割った": "「上手に叩き割る」は料理の仕上げの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "焼き上げた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お粥を焼き上げて、少し冷ました。", "explanation": "〈冷却する〉の意味で使っているが、焼き上げるは火を通して仕上げる語なので、熱いものを冷やす操作には使えない。"}, {"text": "哺乳瓶を焼き上げて、消毒した。", "explanation": "〈煮沸する〉の意味で使っているが、焼き上げるは食べ物などを火で仕上げる語なので、器具を煮て消毒する操作には使えない。"}, {"text": "バターを焼き上げて、鍋に入れた。", "explanation": "〈溶かす〉の意味で使っているが、焼き上げるは火で仕上げる語なので、バターを液状にする操作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は毎朝、囲炉裏で干し魚を焼き上げから、畑に出かけます。", "corrected_sentence": "祖母は毎朝、囲炉裏で干し魚を焼き上げてから、畑に出かけます。", "error_description": "「焼き上げ」の後の「て」が抜けて「焼き上げから」になっている。「焼き上げてから」の「て」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "焼き上げる", "is_correct": true, "explanation": "終止形で、「と」に続けて条件を示す。「焼き上げると」の形に合う。"}, {"text": "焼き上げ", "is_correct": false, "explanation": "未然形（語幹）で、「と」の前には置けない。"}, {"text": "焼き上げて", "is_correct": false, "explanation": "「て形」で、「と」に続かない。"}, {"text": "焼き上げれば", "is_correct": false, "explanation": "仮定形で、「と」を重ねると二重になり不自然。"}], "correct_form": "焼き上げる", "base_form": "焼き上げる", "form_label": "終止形", "sentence_index": 1, "explanations": {"焼き上げる": "終止形で、「と」に続けて条件を示す。「焼き上げると」の形に合う。", "焼き上げ": "未然形（語幹）で、「と」の前には置けない。", "焼き上げて": "「て形」で、「と」に続かない。", "焼き上げれば": "仮定形で、「と」を重ねると二重になり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52259, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は休日に、アップルパイを上手に焼き上げだ。", "corrected_sentence": "姉は休日に、アップルパイを上手に焼き上げた。", "error_description": "「焼き上げた」の過去形「た」が「だ」になっている。「焼き上げだ」は文として成り立たず、正しくは「焼き上げた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "焼き上げる", "is_correct": true, "explanation": "終止形で、「と」に続けて条件を示す。「焼き上げると」の形に合う。"}, {"text": "焼き上げられ", "is_correct": false, "explanation": "受身の連用形で、「と」に続けると文が崩れる。"}, {"text": "焼き上げさせ", "is_correct": false, "explanation": "使役の連用形で、「と」に続くと主語との関係が崩れ不自然。"}, {"text": "焼き上げなければ", "is_correct": false, "explanation": "「なければ」の形で、「と」の前には置けない。"}], "correct_form": "焼き上げる", "base_form": "焼き上げる", "form_label": "終止形", "sentence_index": 7, "explanations": {"焼き上げる": "終止形で、「と」に続けて条件を示す。「焼き上げると」の形に合う。", "焼き上げられ": "受身の連用形で、「と」に続けると文が崩れる。", "焼き上げさせ": "使役の連用形で、「と」に続くと主語との関係が崩れ不自然。", "焼き上げなければ": "「なければ」の形で、「と」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「焼き上げてから」の「から」。動作の後に続く順序を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、「焼き上げて」の後に置くと文が続かない。"}, {"text": "と", "is_correct": false, "explanation": "「焼き上げてと」は並列・引用の形にならず、後の文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞に付くもので、動詞の「て形」の後では文が崩れる。"}], "correct_answer": "から", "explanations": {"から": "「焼き上げてから」の「から」。動作の後に続く順序を示す。", "が": "主語を示す「が」で、「焼き上げて」の後に置くと文が続かない。", "と": "「焼き上げてと」は並列・引用の形にならず、後の文が成立しない。", "の": "「の」は名詞に付くもので、動詞の「て形」の後では文が崩れる。"}, "error_tags": {"が": "主格", "と": "引用・並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「パンを焼き上げ」の「を」。焼く対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「パンに焼き上げ」は対象を示す格として不自然で、「なければならない」にもつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「パンで焼き上げ」は手段・場所の「で」だが、焼く対象を示せず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は焼き上げの対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「パンを焼き上げ」の「を」。焼く対象を示す。", "に": "「パンに焼き上げ」は対象を示す格として不自然で、「なければならない」にもつながらない。", "で": "「パンで焼き上げ」は手段・場所の「で」だが、焼く対象を示せず文が成立しない。", "へ": "方向を示す「へ」は焼き上げの対象にならない。"}, "error_tags": {"に": "時点・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "（パンや魚などを）焼いて、十分に火を通して食べられる状態にする。また、完成させる。", "primary_collocate": null, "pronunciation": "やきあげる", "ipa": "jakiaɡeɾɯ", "syllable_count": 5, "sentences": [{"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "焼き上げる", "complexity_tier": "T5", "furigana": "単[たん]なるパンを焼[や]き上[あ]げるという行為[こうい]の域[いき]を超[こ]え、そこには古[いにしえ]の製法[せいほう]への畏敬[いけい]の念[ねん]と、素材[そざい]の潜在能力[せんざいのうりょく]を限界[げんかい]まで引[ひ]き出[だ]そうとする職人[しょくにん]としての揺[ゆ]るぎない覚悟[かくご]が、静[しず]かに宿[やど]っていたのである。", "sentence_source": "mined"}, {"text": "母は毎朝、オーブンでパンを焼き上げてから、家族を起こします。", "target_word": "焼き上げて", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、オーブンでパンを焼[や]き上[あ]げてから、家族[かぞく]を起[お]こします。", "sentence_source": "generated"}, {"text": "このケーキは低い温度でじっくり焼き上げるので、中までふんわりしています。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "このケーキは低[ひく]い温度[おんど]でじっくり焼[や]き上[あ]げるので、中[なか]までふんわりしています。", "sentence_source": "generated"}, {"text": "職人は炭火で魚を焼き上げ、熱いうちにお客さんに出した。", "target_word": "焼き上げ", "complexity_tier": "T3", "furigana": "職人[しょくにん]は炭火[すみび]で魚[さかな]を焼[や]き上[あ]げ、熱[あつ]いうちにお客[きゃく]さんに出[だ]した。", "sentence_source": "generated"}, {"text": "陶芸家は窯で三日かけて皿を焼き上げた。", "target_word": "焼き上げた", "complexity_tier": "T3", "furigana": "陶芸家[とうげいか]は窯[かま]で三日[みっか]かけて皿[さら]を焼[や]き上[あ]げた。", "sentence_source": "generated"}, {"text": "生地が厚いので、四十分かけて焼き上げる必要がある。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "生地[きじ]が厚[あつ]いので、四十分[よんじゅっぷん]かけて焼[や]き上[あ]げる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "弟が焼き上げたクッキーは、少し焦げていたが、とてもおいしかった。", "target_word": "焼き上げた", "complexity_tier": "T3", "furigana": "弟[おとうと]が焼[や]き上[あ]げたクッキーは、少[すこ]し焦[こ]げていたが、とてもおいしかった。", "sentence_source": "generated"}, {"text": "パン屋では朝六時までに全部のパンを焼き上げなければならない。", "target_word": "焼き上げ", "complexity_tier": "T3", "furigana": "パン屋[や]では朝[あさ]六時[ろくじ]までに全部[ぜんぶ]のパンを焼[や]き上[あ]げなければならない。", "sentence_source": "generated"}, {"text": "ローストビーフは、オーブンで三十分かけて焼き上げるのがこつだ。", "target_word": "焼き上げる", "complexity_tier": "T3", "furigana": "ローストビーフは、オーブンで三十分[さんじっぷん]かけて焼[や]き上[あ]げるのがこつだ。", "sentence_source": "generated"}, {"text": "彼女は誕生日のために、大きなパイを焼き上げて友達を驚かせた。", "target_word": "焼き上げて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誕生日[たんじょうび]のために、大[おお]きなパイを焼[や]き上[あ]げて友達[ともだち]を驚[おどろ]かせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焼き上げます", "label": "丁寧形"}, {"form": "焼き上げて", "label": "て形"}, {"form": "焼き上げた", "label": "た形"}, {"form": "焼き上げない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "パンや魚などを火で十分に焼いて仕上げる、または焼き物などを焼いて完成させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼き上げる", "is_correct": true, "explanation": "「パンを焼き上げるという行為」として、焼いて仕上げる行為を表し、文の意味に合う。"}, {"text": "踏みつける", "is_correct": false, "explanation": "パンを踏みつけるのは乱暴な扱いで、古の製法への畏敬の念と噛み合わない。"}, {"text": "折り曲げる", "is_correct": false, "explanation": "パンを折り曲げるのは製法の行為とは無関係で、「行為の域を超える」という文脈に合わない。"}, {"text": "眠らせる", "is_correct": false, "explanation": "パンを眠らせるという言い方は、製法の行為を指す文脈では成り立たない。"}], "explanations": {"焼き上げる": "「パンを焼き上げるという行為」として、焼いて仕上げる行為を表し、文の意味に合う。", "踏みつける": "パンを踏みつけるのは乱暴な扱いで、古の製法への畏敬の念と噛み合わない。", "折り曲げる": "パンを折り曲げるのは製法の行為とは無関係で、「行為の域を超える」という文脈に合わない。", "眠らせる": "パンを眠らせるという言い方は、製法の行為を指す文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "焼き上げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火事で隣の家を焼き上げてしまった。", "explanation": "〈焼失させる〉の意味で使っているが、焼き上げるは食べ物などを火で仕上げる語なので、家を焼くことには使えない。"}, {"text": "ガスコンロで火を焼き上げて、鍋を温めた。", "explanation": "〈点火する〉の意味で使っているが、焼き上げるは食べ物などを火で仕上げる語なので、火をつける操作には使えない。"}, {"text": "鍋でスープを焼き上げて、とろみを出した。", "explanation": "〈煮詰める〉の意味で使っているが、焼き上げるは火で焼いて仕上げる語なので、汁を煮て水分を減らす操作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焼き上げた", "is_correct": true, "explanation": "「弟が焼き上げたクッキー」として、焼いて完成させたクッキーを修飾する形で文に合う。"}, {"text": "焼き上げます", "is_correct": false, "explanation": "「ます形」は名詞を修飾できず、「弟が〜クッキー」の形に入らない。"}, {"text": "焼き上げましょう", "is_correct": false, "explanation": "意志・勧誘の丁寧形で、名詞を修飾できない。"}, {"text": "焼き上げません", "is_correct": false, "explanation": "否定の丁寧形で、名詞を修飾する形として使えない。"}], "explanations": {"焼き上げた": "「弟が焼き上げたクッキー」として、焼いて完成させたクッキーを修飾する形で文に合う。", "焼き上げます": "「ます形」は名詞を修飾できず、「弟が〜クッキー」の形に入らない。", "焼き上げましょう": "意志・勧誘の丁寧形で、名詞を修飾できない。", "焼き上げません": "否定の丁寧形で、名詞を修飾する形として使えない。"}, "sentence_index": 6, "correct_answer": "焼き上げた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その景色を目に焼き上げた。", "explanation": "〈焼き付ける〉の意味で使っているが、焼き上げるは火を通して仕上げる語なので、景色を記憶に刻む表現にはならない。"}, {"text": "チョコを焼き上げて、ケーキに塗った。", "explanation": "〈溶かす〉の意味で使っているが、焼き上げるは材料を火で仕上げる語なので、チョコを液状にする操作には使えない。"}, {"text": "シャーベットを焼き上げて、冷凍庫に入れた。", "explanation": "〈凍らせる〉の意味で使っているが、焼き上げるは火で仕上げる語なので、冷やして固める操作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は朝早く、かまどで魚に焼き上げてから、畑へ出かけます。", "corrected_sentence": "祖父は朝早く、かまどで魚を焼き上げてから、畑へ出かけます。", "error_description": "「焼き上げる」の対象を示す「を」が「に」になっている。正しくは「魚を焼き上げる」で、対象には「を」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "焼き上げて", "is_correct": true, "explanation": "「てから」の前に来る「て形」。動作の順序を示すので文に合う。"}, {"text": "焼き上げれば", "is_correct": false, "explanation": "仮定形で、「から」に続かない。「焼き上げれば〜から」は文が成立しない。"}, {"text": "焼き上げよう", "is_correct": false, "explanation": "意志形で、「から」の前には置けない。"}, {"text": "焼き上げろ", "is_correct": false, "explanation": "命令形で、文中の「から」の前には置けない。命令の文になってしまう。"}], "correct_form": "焼き上げて", "base_form": "焼き上げる", "form_label": "て形", "sentence_index": 1, "explanations": {"焼き上げて": "「てから」の前に来る「て形」。動作の順序を示すので文に合う。", "焼き上げれば": "仮定形で、「から」に続かない。「焼き上げれば〜から」は文が成立しない。", "焼き上げよう": "意志形で、「から」の前には置けない。", "焼き上げろ": "命令形で、文中の「から」の前には置けない。命令の文になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は週末、大きなケーキを焼き上げれ、家族にふるまった。", "corrected_sentence": "妹は週末、大きなケーキを焼き上げて、家族にふるまった。", "error_description": "「焼き上げて」の「て形」が「焼き上げれ」になっている。「焼き上げれ」は仮定形の不完全な形で、正しくは「焼き上げて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "焼き上げ", "is_correct": true, "explanation": "「なければ」の前に来る未然形。「焼き上げなければならない」の形に合う。"}, {"text": "焼き上げる", "is_correct": false, "explanation": "終止形で、「なければ」の前には置けない。"}, {"text": "焼き上げた", "is_correct": false, "explanation": "過去の形で、「なければ」には続かない。"}, {"text": "焼き上げない", "is_correct": false, "explanation": "ない形で、「なければ」の前に置くと「なければなければ」のように二重になり不自然。"}], "correct_form": "焼き上げ", "base_form": "焼き上げる", "form_label": "未然形", "sentence_index": 7, "explanations": {"焼き上げ": "「なければ」の前に来る未然形。「焼き上げなければならない」の形に合う。", "焼き上げる": "終止形で、「なければ」の前には置けない。", "焼き上げた": "過去の形で、「なければ」には続かない。", "焼き上げない": "ない形で、「なければ」の前に置くと「なければなければ」のように二重になり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
