INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52261, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かくて、きれいな感じのこと。", "primary_collocate": null, "pronunciation": "せんさい", "ipa": "seɴsai", "syllable_count": 4, "sentences": [{"text": "このレース模様はとても繊細で、まるで雪の結晶のようだ。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "このレース模様[もよう]はとても繊細[せんさい]で、まるで雪[ゆき]の結晶[けっしょう]のようだ。", "sentence_source": "generated"}, {"text": "繊細な細工のガラスの器が、店の棚に並んでいる。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な細工[さいく]のガラスの器[うつわ]が、店[みせ]の棚[たな]に並[なら]んでいる。", "sentence_source": "generated"}, {"text": "祖母の着物には、繊細な刺繍がほどこされている。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "祖母[そぼ]の着物[きもの]には、繊細[せんさい]な刺繍[ししゅう]がほどこされている。", "sentence_source": "generated"}, {"text": "繊細な線で描かれた絵は、遠くから見ても美しい。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な線[せん]で描[えが]かれた絵[え]は、遠[とお]くから見[み]ても美[うつく]しい。", "sentence_source": "generated"}, {"text": "京都の工芸品は、繊細な作りで世界中に知られている。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "京都[きょうと]の工芸品[こうげいひん]は、繊細[せんさい]な作[つく]りで世界中[せかいじゅう]に知[し]られている。", "sentence_source": "generated"}, {"text": "彼女の指輪は繊細なデザインで、小さな花の形をしている。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の指輪[ゆびわ]は繊細[せんさい]なデザインで、小[ちい]さな花[はな]の形[かたち]をしている。", "sentence_source": "generated"}, {"text": "髪飾りの繊細な模様に、思わず見とれてしまった。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "髪飾[かみかざ]りの繊細[せんさい]な模様[もよう]に、思[おも]わず見[み]とれてしまった。", "sentence_source": "generated"}, {"text": "この紙は繊細な透かし模様が入っていて、光にかざすときれいだ。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "この紙[かみ]は繊細[せんさい]な透[す]かし模様[もよう]が入[はい]っていて、光[ひかり]にかざすときれいだ。", "sentence_source": "generated"}, {"text": "繊細な飾りのついたケーキは、食べるのがもったいない。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な飾[かざ]りのついたケーキは、食[た]べるのがもったいない。", "sentence_source": "generated"}, {"text": "繊細な彫刻の入った木箱を、旅先で買って帰った。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な彫刻[ちょうこく]の入[はい]った木箱[きばこ]を、旅先[たびさき]で買[か]って帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繊細だ", "label": "断定形"}, {"form": "繊細な", "label": "連体形"}, {"form": "繊細に", "label": "連用形"}, {"form": "繊細で", "label": "て形"}], "register": "中立", "sense_fingerprint": "模様や細工などが細かく、美しい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繊細", "is_correct": true, "explanation": "「とても繊細で」として、細かく美しい模様の様子を表し、雪の結晶にたとえる文に合う。"}, {"text": "粗雑", "is_correct": false, "explanation": "「とても粗雑で」は、細かく美しいレース模様の描写と矛盾する。"}, {"text": "無骨", "is_correct": false, "explanation": "無骨な模様は、細かく美しい模様の描写とは逆で合わない。"}, {"text": "粗末", "is_correct": false, "explanation": "粗末では、雪の結晶にたとえる美しさと矛盾する。"}], "explanations": {"繊細": "「とても繊細で」として、細かく美しい模様の様子を表し、雪の結晶にたとえる文に合う。", "粗雑": "「とても粗雑で」は、細かく美しいレース模様の描写と矛盾する。", "無骨": "無骨な模様は、細かく美しい模様の描写とは逆で合わない。", "粗末": "粗末では、雪の結晶にたとえる美しさと矛盾する。"}, "sentence_index": 0, "correct_answer": "繊細"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この城の繊細な石垣は、角ばった大きな岩を荒々しく積んで造られている。", "explanation": "〈無骨〉の意味で使っているが、繊細は細かく美しい細工を表すので、荒々しく無造作な造りには使えない。"}, {"text": "繊細な荒れ地が地平線まで広がり、草木は一本もない。", "explanation": "〈荒涼〉の意味で使っているが、繊細は細かく美しい様子を表すので、草木のない荒れ果てた景色には使えない。"}, {"text": "繊細な作りのボール紙の箱は、すぐにつぶれてしまう。", "explanation": "〈粗末〉の意味で使っているが、繊細は細かく美しい作りを表すので、安っぽく粗末な造りには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繊細", "is_correct": true, "explanation": "「髪飾りの繊細な模様」として、細かく美しい模様を表し、見とれる文脈に合う。"}, {"text": "硬質", "is_correct": false, "explanation": "硬質な模様では、細かく美しい髪飾りの印象と合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "乱暴な模様は、細やかな髪飾りの描写と逆で合わない。"}, {"text": "鈍重", "is_correct": false, "explanation": "鈍重な模様は、思わず見とれる細かさと合わない。"}], "explanations": {"繊細": "「髪飾りの繊細な模様」として、細かく美しい模様を表し、見とれる文脈に合う。", "硬質": "硬質な模様では、細かく美しい髪飾りの印象と合わない。", "乱暴": "乱暴な模様は、細やかな髪飾りの描写と逆で合わない。", "鈍重": "鈍重な模様は、思わず見とれる細かさと合わない。"}, "sentence_index": 6, "correct_answer": "繊細"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "繊細な大地震で、街の建物が大きく揺れた。", "explanation": "〈大規模な〉の意味で使っているが、繊細は細かく美しい様子を表し、規模の大きい災害には使わない。"}, {"text": "繊細な大型トラックで、荷物を運んだ。", "explanation": "〈大型〉の意味で使っているが、繊細は細かく美しい細工を表し、車両の大きさには使わない。"}, {"text": "繊細な拳で、相手を一撃で倒した。", "explanation": "〈力強い〉の意味で使っているが、繊細は細かく美しい様子を表すので、力強い動きには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この扇子には、繊細の透かし彫りが施されている。", "corrected_sentence": "この扇子には、繊細な透かし彫りが施されている。", "error_description": "「繊細」の後の「な」が「の」になっている。形容動詞の連体形「な」が必要で、正しくは「繊細な透かし彫り」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繊細", "is_correct": true, "explanation": "語幹で、後ろに「な」を付けて「繊細な細工」の形になる。文に合う。"}, {"text": "繊細だ", "is_correct": false, "explanation": "断定形で、「な」の前に置くと「だな」となり文が崩れる。"}, {"text": "繊細に", "is_correct": false, "explanation": "連用形で、「な」の前には続かない。"}, {"text": "繊細で", "is_correct": false, "explanation": "て形で、「な」の前には続かない。"}], "correct_form": "繊細", "base_form": "繊細", "form_label": "語幹（〜な）", "sentence_index": 1, "explanations": {"繊細": "語幹で、後ろに「な」を付けて「繊細な細工」の形になる。文に合う。", "繊細だ": "断定形で、「な」の前に置くと「だな」となり文が崩れる。", "繊細に": "連用形で、「な」の前には続かない。", "繊細で": "て形で、「な」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人の作った木の皿には、繊細を線の模様が刻まれている。", "corrected_sentence": "友人の作った木の皿には、繊細な線の模様が刻まれている。", "error_description": "「繊細」の後に「を」が付いている。名詞を修飾するには連体形「な」が必要で、正しくは「繊細な線の模様」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繊細", "is_correct": true, "explanation": "語幹で、後ろに「な」を付けて「繊細な透かし模様」の形になる。文に合う。"}, {"text": "繊細な", "is_correct": false, "explanation": "連体形で、後ろに「な」を重ねると「なな」になり不自然。"}, {"text": "繊細だった", "is_correct": false, "explanation": "過去の断定形で、「な」の前には続かない。"}, {"text": "繊細である", "is_correct": false, "explanation": "断定の書き言葉で、「な」の前には続かない。"}], "correct_form": "繊細", "base_form": "繊細", "form_label": "語幹（〜な）", "sentence_index": 7, "explanations": {"繊細": "語幹で、後ろに「な」を付けて「繊細な透かし模様」の形になる。文に合う。", "繊細な": "連体形で、後ろに「な」を重ねると「なな」になり不自然。", "繊細だった": "過去の断定形で、「な」の前には続かない。", "繊細である": "断定の書き言葉で、「な」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
