INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52262, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かくて、微妙な感じがすること。人の気持ちが細やかで、敏感なこと。", "primary_collocate": null, "pronunciation": "せんさい", "ipa": "seɴsai", "syllable_count": 4, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "繊細", "complexity_tier": "T5", "furigana": "現代[げんだい]の商業的[しょうぎょうてき]なベーキングにおいては往々[おうおう]にして画一的[かくいつてき]な効率性[こうりつせい]が優先[ゆうせん]されがちであるが、彼[かれ]が真[しん]に渇望[かつぼう]するのは、サワードウ特有[とくゆう]の繊細[せんさい]かつ複雑[ふくざつ]な酸味[さんみ]と、穀物[こくもつ]本来[ほんらい]が秘[ひ]める深[ふか]い旨[うま]みの極致[きょくち]である。", "sentence_source": "mined"}, {"text": "彼女は繊細な性格で、友達の小さな表情の変化にもすぐ気づく。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は繊細[せんさい]な性格[せいかく]で、友達[ともだち]の小[ちい]さな表情[ひょうじょう]の変化[へんか]にもすぐ気[き]づく。", "sentence_source": "generated"}, {"text": "この料理は味付けが繊細で、素材の香りを大切にしている。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "この料理[りょうり]は味付[あじつ]けが繊細[せんさい]で、素材[そざい]の香[かお]りを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "繊細な色の違いを見分けるには、長い経験が必要だ。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な色[いろ]の違[ちが]いを見分[みわ]けるには、長[なが]い経験[けいけん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は繊細なので、きつい言い方をされるとすぐに落ち込んでしまう。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "彼[かれ]は繊細[せんさい]なので、きつい言[い]い方[かた]をされるとすぐに落[お]ち込[こ]んでしまう。", "sentence_source": "generated"}, {"text": "画家は繊細なタッチで、朝の光のやわらかさを描き出した。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "画家[がか]は繊細[せんさい]なタッチで、朝[あさ]の光[ひかり]のやわらかさを描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "繊細な心を持つ人には、周りの人がそっと気を配ることが大切だ。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "繊細[せんさい]な心[こころ]を持[も]つ人[ひと]には、周[まわ]りの人[ひと]がそっと気[き]を配[くば]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "このワインは繊細な味わいなので、強い料理とは合わせにくい。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "このワインは繊細[せんさい]な味[あじ]わいなので、強[つよ]い料理[りょうり]とは合[あ]わせにくい。", "sentence_source": "generated"}, {"text": "時計の中は繊細な部品でできているため、乱暴に扱ってはいけない。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "時計[とけい]の中[なか]は繊細[せんさい]な部品[ぶひん]でできているため、乱暴[らんぼう]に扱[あつか]ってはいけない。", "sentence_source": "generated"}, {"text": "音楽家は、繊細な音の強弱で観客の心をつかんだ。", "target_word": "繊細", "complexity_tier": "T3", "furigana": "音楽家[おんがくか]は、繊細[せんさい]な音[おと]の強弱[きょうじゃく]で観客[かんきゃく]の心[こころ]をつかんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繊細だ", "label": "断定形"}, {"form": "繊細な", "label": "連体形"}, {"form": "繊細に", "label": "連用形"}, {"form": "繊細で", "label": "て形"}], "register": "中立", "sense_fingerprint": "細かく微妙であること、また人の感情が細やかで敏感であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24)']::text[], 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繊細", "is_correct": true, "explanation": "「繊細かつ複雑な酸味」として、細やかで微妙な味わいを表し、文の意味に合う。"}, {"text": "大雑把", "is_correct": false, "explanation": "「大雑把かつ複雑な酸味」は細やかな味わいを表す文脈と矛盾する。"}, {"text": "単調", "is_correct": false, "explanation": "「単調かつ複雑」は意味が矛盾し、味わいの細かさを表せない。"}, {"text": "無骨", "is_correct": false, "explanation": "無骨な酸味は細やかさとは逆の印象で、ここでは文脈に合わない。"}], "explanations": {"繊細": "「繊細かつ複雑な酸味」として、細やかで微妙な味わいを表し、文の意味に合う。", "大雑把": "「大雑把かつ複雑な酸味」は細やかな味わいを表す文脈と矛盾する。", "単調": "「単調かつ複雑」は意味が矛盾し、味わいの細かさを表せない。", "無骨": "無骨な酸味は細やかさとは逆の印象で、ここでは文脈に合わない。"}, "sentence_index": 0, "correct_answer": "繊細"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は繊細な大男で、ラグビーの試合で大活躍した。", "explanation": "〈大柄〉の意味で使っているが、繊細は細かさや細やかさを表し、体の大きさには使わない。"}, {"text": "繊細な台風が近づき、各地で大きな被害が出た。", "explanation": "〈強烈〉の意味で使っているが、繊細は細かさや細やかさを表し、台風の激しさには使わない。"}, {"text": "繊細な突風で、古い扉が吹き飛ばされた。", "explanation": "〈強風〉の意味で使っているが、繊細は細かく細やかな様子を表すので、突風の激しさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繊細", "is_correct": true, "explanation": "「繊細な心を持つ人」として、細やかで敏感な心を表し、文の意味に合う。"}, {"text": "平坦", "is_correct": false, "explanation": "平坦な心では、人の気持ちの細やかさを表せず文脈に合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈な心は、そっと気を配る細やかさとは合わない。"}, {"text": "硬質", "is_correct": false, "explanation": "硬質な心は、人の気持ちへの敏感さという意味と合わない。"}], "explanations": {"繊細": "「繊細な心を持つ人」として、細やかで敏感な心を表し、文の意味に合う。", "平坦": "平坦な心では、人の気持ちの細やかさを表せず文脈に合わない。", "頑丈": "頑丈な心は、そっと気を配る細やかさとは合わない。", "硬質": "硬質な心は、人の気持ちへの敏感さという意味と合わない。"}, "sentence_index": 6, "correct_answer": "繊細"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "繊細な量の水が、一気に部屋へ流れ込んだ。", "explanation": "〈大量〉の意味で使っているが、繊細は細かく微妙な感じを表すので、水の量の多さには使えない。"}, {"text": "繊細な豪雨で、川の水位が一気に上がった。", "explanation": "〈豪雨〉の意味で使っているが、繊細は細かさや細やかさを表し、激しい雨の勢いには使わない。"}, {"text": "繊細な大岩が、ゆっくりと山の斜面を転がり落ちた。", "explanation": "〈巨大〉の意味で使っているが、繊細は細かく微妙な感じを表すので、大きく重い岩の様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は繊細だ感覚で、音のわずかな違いを聞き分ける。", "corrected_sentence": "彼は繊細な感覚で、音のわずかな違いを聞き分ける。", "error_description": "「繊細」の後の「な」が「だ」になっている。名詞の前では連体形「な」が必要で、正しくは「繊細な感覚」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繊細", "is_correct": true, "explanation": "語幹で、後ろに「な」を付けて名詞を修飾する。「繊細な性格」の形に合う。"}, {"text": "繊細だ", "is_correct": false, "explanation": "断定形で、「な」の前に置くと「だな」となり文が崩れる。"}, {"text": "繊細に", "is_correct": false, "explanation": "連用形で、「な」の前には続かない。"}, {"text": "繊細で", "is_correct": false, "explanation": "て形で、「な」の前には続かない。"}], "correct_form": "繊細", "base_form": "繊細", "form_label": "語幹（〜な）", "sentence_index": 1, "explanations": {"繊細": "語幹で、後ろに「な」を付けて名詞を修飾する。「繊細な性格」の形に合う。", "繊細だ": "断定形で、「な」の前に置くと「だな」となり文が崩れる。", "繊細に": "連用形で、「な」の前には続かない。", "繊細で": "て形で、「な」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の指先は繊細ので、小さな刺繍も丁寧に仕上げる。", "corrected_sentence": "彼女の指先は繊細で、小さな刺繍も丁寧に仕上げる。", "error_description": "「繊細で」の「で」の後に「の」が入って誤った形になっている。正しくは「繊細で」（て形）で、ここでは「の」を付けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繊細", "is_correct": true, "explanation": "語幹で、後ろに「な」を付けて「繊細な味わい」の形になる。文に合う。"}, {"text": "繊細な", "is_correct": false, "explanation": "連体形で、後ろに「な」を重ねると「なな」になり不自然。"}, {"text": "繊細だった", "is_correct": false, "explanation": "過去の断定形で、「な」の前には続かない。"}, {"text": "繊細である", "is_correct": false, "explanation": "断定の書き言葉で、「な」の前には続かない。"}], "correct_form": "繊細", "base_form": "繊細", "form_label": "語幹（〜な）", "sentence_index": 7, "explanations": {"繊細": "語幹で、後ろに「な」を付けて「繊細な味わい」の形になる。文に合う。", "繊細な": "連体形で、後ろに「な」を重ねると「なな」になり不自然。", "繊細だった": "過去の断定形で、「な」の前には続かない。", "繊細である": "断定の書き言葉で、「な」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『水温が高すぎると』で、高さを述べる主語になる。"}, {"text": "を", "is_correct": false, "explanation": "『高すぎる』は形容詞なので、『水温を高すぎる』は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は対象や方向を示すため、『水温に高すぎる』とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段を示すため、『水温で高すぎると』は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『水温が高すぎると』で、高さを述べる主語になる。", "を": "『高すぎる』は形容詞なので、『水温を高すぎる』は成り立たない。", "に": "『に』は対象や方向を示すため、『水温に高すぎる』とは続かない。", "で": "『で』は手段を示すため、『水温で高すぎると』は文が成り立たない。"}, "error_tags": {"を": "目的語（形容詞に付く）", "に": "対象・方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『水温が熱すぎないか』で、熱さを述べる主語になる。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾に使うため、『水温の熱すぎないか』は文の骨組みに合わない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すため、『水温から熱すぎないか』は主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『水温へ熱すぎないか』は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『水温が熱すぎないか』で、熱さを述べる主語になる。", "の": "『の』は名詞修飾に使うため、『水温の熱すぎないか』は文の骨組みに合わない。", "から": "『から』は起点を示すため、『水温から熱すぎないか』は主語の位置に合わない。", "へ": "『へ』は方向を示すため、『水温へ熱すぎないか』は成り立たない。"}, "error_tags": {"の": "名詞修飾", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "水の温度のことです。水がどれだけあたたかいか、つめたいかを表します。", "primary_collocate": null, "pronunciation": "すいおん", "ipa": "sɯioɴ", "syllable_count": 4, "sentences": [{"text": "プールの水が冷たすぎないか、先生が水温を測ってくれた。", "target_word": "水温", "complexity_tier": "T3", "furigana": "プールの水[みず]が冷[つめ]たすぎないか、先生[せんせい]が水温[すいおん]を測[はか]ってくれた。", "sentence_source": "generated"}, {"text": "水温が高すぎると、お風呂に長く入れません。", "target_word": "水温", "complexity_tier": "T3", "furigana": "水温[すいおん]が高[たか]すぎると、お風呂[ふろ]に長[なが]く入[はい]れません。", "sentence_source": "generated"}, {"text": "今朝の川は水温がとても低くて、手を入れると痛いほどだった。", "target_word": "水温", "complexity_tier": "T3", "furigana": "今朝[けさ]の川[かわ]は水温[すいおん]がとても低[ひく]くて、手[て]を入[い]れると痛[いた]いほどだった。", "sentence_source": "generated"}, {"text": "魚は水温の変化にとても弱い生き物だ。", "target_word": "水温", "complexity_tier": "T3", "furigana": "魚[さかな]は水温[すいおん]の変化[へんか]にとても弱[よわ]い生[い]き物[もの]だ。", "sentence_source": "generated"}, {"text": "夏の海は水温が高いので、泳いでいても寒くない。", "target_word": "水温", "complexity_tier": "T3", "furigana": "夏[なつ]の海[うみ]は水温[すいおん]が高[たか]いので、泳[およ]いでいても寒[さむ]くない。", "sentence_source": "generated"}, {"text": "水槽に温度計を入れて、水温を読み取った。", "target_word": "水温", "complexity_tier": "T3", "furigana": "水槽[すいそう]に温度計[おんどけい]を入[い]れて、水温[すいおん]を読[よ]み取[と]った。", "sentence_source": "generated"}, {"text": "水温が下がる冬は、池の鯉があまり動かなくなる。", "target_word": "水温", "complexity_tier": "T3", "furigana": "水温[すいおん]が下[さ]がる冬[ふゆ]は、池[いけ]の鯉[こい]があまり動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "赤ちゃんをお風呂に入れる前に、水温が熱すぎないか確かめた。", "target_word": "水温", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんをお風呂[ふろ]に入[い]れる前[まえ]に、水温[すいおん]が熱[あつ]すぎないか確[たし]かめた。", "sentence_source": "generated"}, {"text": "天気のよい日でも、湖の水温は思ったより低い。", "target_word": "水温", "complexity_tier": "T3", "furigana": "天気[てんき]のよい日[ひ]でも、湖[みずうみ]の水温[すいおん]は思[おも]ったより低[ひく]い。", "sentence_source": "generated"}, {"text": "魚が元気に育つよう、毎日水温を記録している。", "target_word": "水温", "complexity_tier": "T3", "furigana": "魚[さかな]が元気[げんき]に育[そだ]つよう、毎日[まいにち]水温[すいおん]を記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水温", "label": "基本形"}], "register": "標準", "sense_fingerprint": "水があたたかいか冷たいかの程度(水温が高い・低い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水温", "is_correct": true, "explanation": "先生が測る対象として、水の温度を表す水温が入る。"}, {"text": "色", "is_correct": false, "explanation": "色は目で見て判断するもので、温度計で測る対象ではない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いのことで、測ってくれたという文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は舌で感じるもので、冷たさを確かめる検査の対象にはならない。"}], "explanations": {"水温": "先生が測る対象として、水の温度を表す水温が入る。", "色": "色は目で見て判断するもので、温度計で測る対象ではない。", "香り": "香りは匂いのことで、測ってくれたという文脈に合わない。", "味": "味は舌で感じるもので、冷たさを確かめる検査の対象にはならない。"}, "sentence_index": 0, "correct_answer": "水温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪で、子どもの水温が三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。水温は水の温度で、人の体温には使わない。"}, {"text": "大雨で川の水温が三メートルまで増えた。", "explanation": "ここは〈水位〉の意味。水温は温度なので、水の高さが増えるとは言わない。"}, {"text": "工場の排水で、川の水温が悪化した。", "explanation": "ここは〈水質〉の意味。水温は温度なので、悪化して水の良し悪しが変わるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水温", "is_correct": true, "explanation": "『水温が下がる冬』で、冬の水の温度が下がることを示す語になる。"}, {"text": "池", "is_correct": false, "explanation": "池は場所を表すので、『池が下がる』という言い方は成り立たない。"}, {"text": "鯉", "is_correct": false, "explanation": "鯉は生き物で、『鯉が下がる』は温度の変化を表さない。"}, {"text": "餌", "is_correct": false, "explanation": "餌は食べ物で、『餌が下がる』は冬の温度変化の文脈に合わない。"}], "explanations": {"水温": "『水温が下がる冬』で、冬の水の温度が下がることを示す語になる。", "池": "池は場所を表すので、『池が下がる』という言い方は成り立たない。", "鯉": "鯉は生き物で、『鯉が下がる』は温度の変化を表さない。", "餌": "餌は食べ物で、『餌が下がる』は冬の温度変化の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "水温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は水温が氷点下まで下がり、霜がおりた。", "explanation": "ここは〈気温〉の意味。霜は空気の冷え込みで生じるため、水の温度には使わない。"}, {"text": "台風の影響で、池の水温が十倍に増えた。", "explanation": "ここは〈水量〉の意味。水温は温度なので、十倍に増えるという量の変化は表せない。"}, {"text": "夏は水温が長く、影が濃くなる。", "explanation": "ここは〈日照時間〉の意味。水温は温度を表すので、長さの語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖の水温を低いので、朝は霧が出やすい。", "corrected_sentence": "湖の水温が低いので、朝は霧が出やすい。", "error_description": "『水温』に付く助詞は主語を示す『が』。『を』では『低い』の主語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52263, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い夜は水温が下がりので、池の魚が動かなくなる。", "corrected_sentence": "寒い夜は水温が下がるので、池の魚が動かなくなる。", "error_description": "『下がる』は『ので』の前で辞書形を使う。『下がりので』は動詞の活用形が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『水温が』で、急に変わる主体を示す主語になる。"}, {"text": "を", "is_correct": false, "explanation": "『変わる』は自動詞なので『水温を』は目的語として続かない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すため、『水温で変わらない』は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すため、『水温から変わらない』は主語の位置に合わない。"}], "correct_answer": "が", "explanations": {"が": "『水温が』で、急に変わる主体を示す主語になる。", "を": "『変わる』は自動詞なので『水温を』は目的語として続かない。", "で": "『で』は手段や場所を示すため、『水温で変わらない』は成り立たない。", "から": "『から』は起点を示すため、『水温から変わらない』は主語の位置に合わない。"}, "error_tags": {"を": "目的語（自動詞に付く）", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『下げる』は他動詞なので、目的語の『水温を』になる。"}, {"text": "が", "is_correct": false, "explanation": "『下げる』は他動詞のため、『水温が下げる』は主語として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は対象や方向を示すため、『水温に下げる』とは続かない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾に使うため、『水温の下げるために』は文の骨組みに合わない。"}], "correct_answer": "を", "explanations": {"を": "『下げる』は他動詞なので、目的語の『水温を』になる。", "が": "『下げる』は他動詞のため、『水温が下げる』は主語として成り立たない。", "に": "『に』は対象や方向を示すため、『水温に下げる』とは続かない。", "の": "『の』は名詞修飾に使うため、『水温の下げるために』は文の骨組みに合わない。"}, "error_tags": {"が": "主語（他動詞に付く）", "に": "対象・方向", "の": "名詞修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "水の温度。特に、水の熱さや冷たさの程度を数値で表したもの。", "primary_collocate": null, "pronunciation": "すいおん", "ipa": "sɯioɴ", "syllable_count": 4, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "水温", "complexity_tier": "T5", "furigana": "水温[すいおん]と室温[しつおん]をミリ単位[たんい]で制御[せいぎょ]し、小麦粉[こむぎこ]と水[みず]のみを混[ま]ぜ合[あ]わせる行為[こうい]は、単[たん]なる調理[ちょうり]の域[いき]を超[こ]え、微生物[びせいぶつ]の生態系[せいたいけい]を育[はぐく]む科学的[かがくてき]な実験[じっけん]とも呼応[こおう]する。", "sentence_source": "mined"}, {"text": "魚を飼うときは、水温が急に変わらないよう、ヒーターで調節します。", "target_word": "水温", "complexity_tier": "T3", "furigana": "魚[さかな]を飼[か]うときは、水温[すいおん]が急[きゅう]に変[か]わらないよう、ヒーターで調節[ちょうせつ]します。", "sentence_source": "generated"}, {"text": "川の水温が低い春先は、まだ泳ぐのに向いていません。", "target_word": "水温", "complexity_tier": "T3", "furigana": "川[かわ]の水温[すいおん]が低[ひく]い春先[はるさき]は、まだ泳[およ]ぐのに向[む]いていません。", "sentence_source": "generated"}, {"text": "温度計で水温を測ると、お風呂は42度だった。", "target_word": "水温", "complexity_tier": "T3", "furigana": "温度計[おんどけい]で水温[すいおん]を測[はか]ると、お風呂[ふろ]は42度[ど]だった。", "sentence_source": "generated"}, {"text": "海の水温が上がると、台風が強くなりやすいといわれる。", "target_word": "水温", "complexity_tier": "T4", "furigana": "海[うみ]の水温[すいおん]が上[あ]がると、台風[たいふう]が強[つよ]くなりやすいといわれる。", "sentence_source": "generated"}, {"text": "水温が25度を超えると、この魚は元気に動き回る。", "target_word": "水温", "complexity_tier": "T3", "furigana": "水温[すいおん]が25度[ど]を超[こ]えると、この魚[さかな]は元気[げんき]に動[うご]き回[まわ]る。", "sentence_source": "generated"}, {"text": "パンの生地を作るときは、水温が高すぎると発酵が進みすぎてしまう。", "target_word": "水温", "complexity_tier": "T4", "furigana": "パンの生地[きじ]を作[つく]るときは、水温[すいおん]が高[たか]すぎると発酵[はっこう]が進[すす]みすぎてしまう。", "sentence_source": "generated"}, {"text": "熱すぎる温泉は、水温を下げるために水をたして入る。", "target_word": "水温", "complexity_tier": "T3", "furigana": "熱[あつ]すぎる温泉[おんせん]は、水温[すいおん]を下[さ]げるために水[みず]をたして入[はい]る。", "sentence_source": "generated"}, {"text": "冬は水温が下がるので、金魚はほとんどえさを食べなくなる。", "target_word": "水温", "complexity_tier": "T3", "furigana": "冬[ふゆ]は水温[すいおん]が下[さ]がるので、金魚[きんぎょ]はほとんどえさを食[た]べなくなる。", "sentence_source": "generated"}, {"text": "プールの水温は毎朝測って、記録ノートに書いている。", "target_word": "水温", "complexity_tier": "T3", "furigana": "プールの水温[すいおん]は毎朝[まいあさ]測[はか]って、記録[きろく]ノートに書[か]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水温", "label": "基本形"}], "register": "標準", "sense_fingerprint": "水の温度を数値で表したもの(水温が上がる・水温を測る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水温", "is_correct": true, "explanation": "室温と並べて温度を制御する文脈で、水の温度を表す水温が入る。"}, {"text": "水質", "is_correct": false, "explanation": "水質は水の性質を指し、温度の室温と並べると文脈が崩れる。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履くもので、室温と並べて温度を制御する対象にはならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の湿り気を表し、水の温度を扱う文脈に合わない。"}], "explanations": {"水温": "室温と並べて温度を制御する文脈で、水の温度を表す水温が入る。", "水質": "水質は水の性質を指し、温度の室温と並べると文脈が崩れる。", "靴": "靴は履くもので、室温と並べて温度を制御する対象にはならない。", "湿度": "湿度は空気の湿り気を表し、水の温度を扱う文脈に合わない。"}, "sentence_index": 0, "correct_answer": "水温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱があって、子どもの水温が三十八度もあった。", "explanation": "ここは〈体温〉の意味。水温は水の温度を指し、人の体温には使わない。"}, {"text": "大雨で川の水温が三メートルまで上がった。", "explanation": "ここは〈水位〉の意味。水温は温度なので、川の水面の高さには使えない。"}, {"text": "工場の排水で、川の水温が悪化した。", "explanation": "ここは〈水質〉の意味。水温は温度を表すので、悪化して良し悪しが変わるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水温", "is_correct": true, "explanation": "水の温度を指し、『高すぎると発酵が進みすぎる』という条件の主語になる。"}, {"text": "糖度", "is_correct": false, "explanation": "糖度は糖の濃さを指し、水の温度を条件にする文脈とは結びつかない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、高すぎると発酵が進むという温度の条件にはならない。"}, {"text": "生地", "is_correct": false, "explanation": "生地は作る対象そのもので、温度の条件として『高すぎる』とは言わない。"}], "explanations": {"水温": "水の温度を指し、『高すぎると発酵が進みすぎる』という条件の主語になる。", "糖度": "糖度は糖の濃さを指し、水の温度を条件にする文脈とは結びつかない。", "時計": "時計は時刻を示す道具で、高すぎると発酵が進むという温度の条件にはならない。", "生地": "生地は作る対象そのもので、温度の条件として『高すぎる』とは言わない。"}, "sentence_index": 6, "correct_answer": "水温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の水温は三十五度まで上がり、熱中症に注意しよう。", "explanation": "ここは〈気温〉の意味。水温は水の温度で、空気の暑さには使わない。"}, {"text": "大雨で川の水温が急に増え、橋が流された。", "explanation": "ここは〈水量〉の意味。水温は温度なので、量が増えるとは言わない。"}, {"text": "夏は水温が長く、洗濯物がよく乾く。", "explanation": "ここは〈日照時間〉の意味。水温は温度を表すので、長さを表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の池は水温を高いので、魚がよく泳ぐ。", "corrected_sentence": "夏の池は水温が高いので、魚がよく泳ぐ。", "error_description": "『水温』に付く助詞は主語を示す『が』。『を』は他動詞の目的語に付くので、形容詞『高い』の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52264, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パンの生地は水温が低くと、発酵がゆっくり進む。", "corrected_sentence": "パンの生地は水温が低いと、発酵がゆっくり進む。", "error_description": "『低い』の仮定形は『低いと』。『低くと』は形容詞の活用形が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新しい", "is_correct": true, "explanation": "「古い（昔からの）」の対義語で、時間的に新しいことを表す。"}, {"text": "大きい", "is_correct": false, "explanation": "形容詞だが、「古い」の対義語ではない。"}, {"text": "明るい", "is_correct": false, "explanation": "「暗い」の対義語で、「古い」とは対にならない。"}, {"text": "遠い", "is_correct": false, "explanation": "「近い」の対義語で、「古い」とは対にならない。"}], "correct_answer": "新しい", "explanations": {"新しい": "「古い（昔からの）」の対義語で、時間的に新しいことを表す。", "大きい": "形容詞だが、「古い」の対義語ではない。", "明るい": "「暗い」の対義語で、「古い」とは対にならない。", "遠い": "「近い」の対義語で、「古い」とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
