INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "むかしのこと", "primary_collocate": null, "pronunciation": "ふるい", "ipa": "ɸɯɾɯi", "syllable_count": 3, "sentences": [{"text": "祖母は古い出来事を、昨日のことのように話してくれる。", "target_word": "古い", "complexity_tier": "T3", "furigana": "祖母[そぼ]は古[ふる]い出来事[できごと]を、昨日[きのう]のことのように話[はな]してくれる。", "sentence_source": "generated"}, {"text": "この町には、古いことを知る人がもうほとんどいない。", "target_word": "古い", "complexity_tier": "T3", "furigana": "この町[まち]には、古[ふる]いことを知[し]る人[ひと]がもうほとんどいない。", "sentence_source": "generated"}, {"text": "古いことは忘れたと、祖父はいつも笑って言う。", "target_word": "古い", "complexity_tier": "T3", "furigana": "古[ふる]いことは忘[わす]れたと、祖父[そふ]はいつも笑[わら]って言[い]う。", "sentence_source": "generated"}, {"text": "古い話を蒸し返すのは、もうやめにしよう。", "target_word": "古い", "complexity_tier": "T3", "furigana": "古[ふる]い話[はなし]を蒸[む]し返[かえ]すのは、もうやめにしよう。", "sentence_source": "generated"}, {"text": "古い記録によると、この村が生まれたのは千年以上前らしい。", "target_word": "古い", "complexity_tier": "T3", "furigana": "古[ふる]い記録[きろく]によると、この村[むら]が生[う]まれたのは千年[せんねん]以上前[いじょうまえ]らしい。", "sentence_source": "generated"}, {"text": "彼は古い恨みを、今でも根に持っている。", "target_word": "古い", "complexity_tier": "T3", "furigana": "彼[かれ]は古[ふる]い恨[うら]みを、今[いま]でも根[ね]に持[も]っている。", "sentence_source": "generated"}, {"text": "古い慣習が、いまも村に残っている。", "target_word": "古い", "complexity_tier": "T3", "furigana": "古[ふる]い慣習[かんしゅう]が、いまも村[むら]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "古いことほど、記録が残りにくい。", "target_word": "古い", "complexity_tier": "T3", "furigana": "古[ふる]いことほど、記録[きろく]が残[のこ]りにくい。", "sentence_source": "generated"}, {"text": "祖父は古い思い出を、ときどき静かに語ってくれる。", "target_word": "古い", "complexity_tier": "T3", "furigana": "祖父[そふ]は古[ふる]い思[おも]い出[で]を、ときどき静[しず]かに語[かた]ってくれる。", "sentence_source": "generated"}, {"text": "昔から伝わる古い話を、祖母が教えてくれました。", "target_word": "古い", "complexity_tier": "T3", "furigana": "昔[むかし]から伝[つた]わる古[ふる]い話[はなし]を、祖母[そぼ]が教[おし]えてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "古い", "label": "終止形"}, {"form": "古くて", "label": "て形"}, {"form": "古かった", "label": "た形"}, {"form": "古く", "label": "連用形"}], "register": "中立", "sense_fingerprint": "昔のものや、昔からあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古い", "is_correct": true, "explanation": "「古い出来事」で、昔の出来事を表す連体修飾として正しい。"}, {"text": "古く", "is_correct": false, "explanation": "連用形は名詞を修飾できず、「古く出来事を」は不自然。"}, {"text": "古くて", "is_correct": false, "explanation": "て形は連体修飾に使えず、文が続かない。"}, {"text": "古さ", "is_correct": false, "explanation": "名詞の「古さ」では「古さ出来事」となり意味が通らない。"}], "explanations": {"古い": "「古い出来事」で、昔の出来事を表す連体修飾として正しい。", "古く": "連用形は名詞を修飾できず、「古く出来事を」は不自然。", "古くて": "て形は連体修飾に使えず、文が続かない。", "古さ": "名詞の「古さ」では「古さ出来事」となり意味が通らない。"}, "sentence_index": 0, "correct_answer": "古い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝の古いことを、昼にもう一度話してくれた。", "explanation": "ここは〈今朝あったこと〉の意味。〈古いこと〉は昔からあったことを指すので、今朝のことには使えない。"}, {"text": "来週の古いことを、今日すでに振り返った。", "explanation": "ここは〈来週のこと〉の意味。〈古いこと〉は昔からあったことを指すので、来週のことには使えない。"}, {"text": "先週の古い出来事を、今になって話題にする。", "explanation": "ここは〈少し前の出来事〉の意味。〈古いこと〉は昔からあったことを指すので、先週の出来事には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古い", "is_correct": true, "explanation": "「古い慣習」で、昔からあるものを修飾する連体形として文意に合う。"}, {"text": "古風", "is_correct": false, "explanation": "形容動詞の語幹で、「古風慣習」と直接続けられず不自然。"}, {"text": "古株", "is_correct": false, "explanation": "名詞で、「古株慣習」は成り立たない。"}, {"text": "古書", "is_correct": false, "explanation": "名詞の「古書」は慣習を修飾できず、文が続かない。"}], "explanations": {"古い": "「古い慣習」で、昔からあるものを修飾する連体形として文意に合う。", "古風": "形容動詞の語幹で、「古風慣習」と直接続けられず不自然。", "古株": "名詞で、「古株慣習」は成り立たない。", "古書": "名詞の「古書」は慣習を修飾できず、文が続かない。"}, "sentence_index": 6, "correct_answer": "古い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明後日の古い記録を、今日のうちに確認した。", "explanation": "ここは〈以前の記録〉の意味。だが〈古いこと〉は昔からあったことを指すので、明後日の記録には使えない。"}, {"text": "来月の古い話を、今朝の会議で持ち出した。", "explanation": "ここは〈前から続く話〉の意味。〈古い話〉は昔からあった話を指すので、来月の話には使えない。"}, {"text": "来週の古い約束を、そろそろ果たそう。", "explanation": "ここは〈長年の約束〉の意味。〈古いこと〉は昔からあったことを指すので、来週の約束には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は古く話を、今も覚えている。", "corrected_sentence": "祖父は古い話を、今も覚えている。", "error_description": "名詞「話」を修飾するには連体形「古い」が必要。連用形「古く」では修飾できず、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "古い", "is_correct": true, "explanation": "「古いこと」の「こと」を修飾する連体形で、文が成り立つ。"}, {"text": "古く", "is_correct": false, "explanation": "連用形は「古くことを」となり、名詞を修飾できない。"}, {"text": "古ければ", "is_correct": false, "explanation": "仮定形の「古ければ」は直後に「こと」を続けられず、文が成り立たない。"}, {"text": "古くて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「古くてことを」は不自然。"}], "correct_form": "古い", "base_form": "古い", "form_label": "連体形", "sentence_index": 1, "explanations": {"古い": "「古いこと」の「こと」を修飾する連体形で、文が成り立つ。", "古く": "連用形は「古くことを」となり、名詞を修飾できない。", "古ければ": "仮定形の「古ければ」は直後に「こと」を続けられず、文が成り立たない。", "古くて": "て形は名詞を修飾できず、「古くてことを」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52265, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いの記録に、この村の名前が残っている。", "corrected_sentence": "古い記録に、この村の名前が残っている。", "error_description": "「古い」は連体形で「記録」を直接修飾するため、「の」は入れない。「古いの記録」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "古い", "is_correct": true, "explanation": "「古いこと」の「こと」を修飾する連体形で、「古いことほど」と文が成り立つ。"}, {"text": "古さ", "is_correct": false, "explanation": "名詞の「古さ」は「古さことほど」と続かず、文が成り立たない。"}, {"text": "古がり", "is_correct": false, "explanation": "名詞形の「古がり」は「古がりことほど」と続けられず、文が成り立たない。"}, {"text": "古めかし", "is_correct": false, "explanation": "形容詞「古めかしい」の語幹で、単独では「こと」を修飾できず文が成り立たない。"}], "correct_form": "古い", "base_form": "古い", "form_label": "連体形", "sentence_index": 7, "explanations": {"古い": "「古いこと」の「こと」を修飾する連体形で、「古いことほど」と文が成り立つ。", "古さ": "名詞の「古さ」は「古さことほど」と続かず、文が成り立たない。", "古がり": "名詞形の「古がり」は「古がりことほど」と続けられず、文が成り立たない。", "古めかし": "形容詞「古めかしい」の語幹で、単独では「こと」を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「製法が簡単なので」の主語を示す「が」で、述語「簡単」と対応する。"}, {"text": "を", "is_correct": false, "explanation": "「製法を簡単」は目的語を示すが、「簡単」と続かず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「製法に簡単」は述語と対応せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、「製法で簡単」は主語にならず意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「製法が簡単なので」の主語を示す「が」で、述語「簡単」と対応する。", "を": "「製法を簡単」は目的語を示すが、「簡単」と続かず文が成り立たない。", "に": "「製法に簡単」は述語と対応せず、文が成り立たない。", "で": "手段を表すが、「製法で簡単」は主語にならず意味が通らない。"}, "error_tags": {"を": "目的語の誤用", "に": "位置の誤用", "で": "手段の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「製法を図で示しながら」の「を」で、示す対象を表し文意に合う。"}, {"text": "に", "is_correct": false, "explanation": "示す対象は「を」で示すため、「製法に図で示す」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では示す対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の意味になり、示す対象を表さないため不自然。"}], "correct_answer": "を", "explanations": {"を": "「製法を図で示しながら」の「を」で、示す対象を表し文意に合う。", "に": "示す対象は「を」で示すため、「製法に図で示す」は成り立たない。", "へ": "方向を示す「へ」では示す対象にならない。", "と": "並列の意味になり、示す対象を表さないため不自然。"}, "error_tags": {"に": "対象の誤用", "へ": "方向の誤用", "と": "並列の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをつくるやりかた。", "primary_collocate": null, "pronunciation": "せいほう", "ipa": "seːhoː", "syllable_count": 4, "sentences": [{"text": "店主はラーメンのスープの製法を、弟子に少しずつ教えた。", "target_word": "製法", "complexity_tier": "T3", "furigana": "店主[てんしゅ]はラーメンのスープの製法[せいほう]を、弟子[でし]に少[すこ]しずつ教[おし]えた。", "sentence_source": "generated"}, {"text": "このクッキーは製法が簡単なので、子どもでも作れる。", "target_word": "製法", "complexity_tier": "T3", "furigana": "このクッキーは製法[せいほう]が簡単[かんたん]なので、子[こ]どもでも作[つく]れる。", "sentence_source": "generated"}, {"text": "特許を取ったのは、製品そのものではなく、その製法である。", "target_word": "製法", "complexity_tier": "T3", "furigana": "特許[とっきょ]を取[と]ったのは、製品[せいひん]そのものではなく、その製法[せいほう]である。", "sentence_source": "generated"}, {"text": "会社は新しい製法を開発して、コストを半分に減らした。", "target_word": "製法", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい製法[せいほう]を開発[かいはつ]して、コストを半分[はんぶん]に減[へ]らした。", "sentence_source": "generated"}, {"text": "製法の違いによって、緑茶と紅茶は別のお茶になる。", "target_word": "製法", "complexity_tier": "T3", "furigana": "製法[せいほう]の違[ちが]いによって、緑茶[りょくちゃ]と紅茶[こうちゃ]は別[べつ]のお茶[ちゃ]になる。", "sentence_source": "generated"}, {"text": "レシピ本には材料だけでなく、製法も詳しく書かれている。", "target_word": "製法", "complexity_tier": "T3", "furigana": "レシピ本[ぼん]には材料[ざいりょう]だけでなく、製法[せいほう]も詳[くわ]しく書[か]かれている。", "sentence_source": "generated"}, {"text": "同じ名前のハムでも、メーカーごとに製法が異なる。", "target_word": "製法", "complexity_tier": "T3", "furigana": "同[おな]じ名前[なまえ]のハムでも、メーカーごとに製法[せいほう]が異[こと]なる。", "sentence_source": "generated"}, {"text": "先生は、ガラスの製法を図で示しながら授業を進めた。", "target_word": "製法", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ガラスの製法[せいほう]を図[ず]で示[しめ]しながら授業[じゅぎょう]を進[すす]めた。", "sentence_source": "generated"}, {"text": "古い文書から、昔の石鹸の製法が明らかになった。", "target_word": "製法", "complexity_tier": "T3", "furigana": "古[ふる]い文書[ぶんしょ]から、昔[むかし]の石鹸[せっけん]の製法[せいほう]が明[あき]らかになった。", "sentence_source": "generated"}, {"text": "製法を公開していないので、他の会社はまねできない。", "target_word": "製法", "complexity_tier": "T3", "furigana": "製法[せいほう]を公開[こうかい]していないので、他[ほか]の会社[かいしゃ]はまねできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製法", "label": "基本形"}], "register": "中立（やや書き言葉寄り）", "sense_fingerprint": "ものを作るやり方一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "製法", "is_correct": true, "explanation": "「スープの製法」で、ものを作るやり方を指し文意に合う。"}, {"text": "製鉄", "is_correct": false, "explanation": "鉄を作る工程で、ラーメンのスープの文脈には合わない。"}, {"text": "製紙", "is_correct": false, "explanation": "紙を作る工程で、ラーメンの文脈には合わない。"}, {"text": "製鋼", "is_correct": false, "explanation": "鋼を作る工程で、ラーメンの文脈には合わない。"}], "explanations": {"製法": "「スープの製法」で、ものを作るやり方を指し文意に合う。", "製鉄": "鉄を作る工程で、ラーメンのスープの文脈には合わない。", "製紙": "紙を作る工程で、ラーメンの文脈には合わない。", "製鋼": "鋼を作る工程で、ラーメンの文脈には合わない。"}, "sentence_index": 0, "correct_answer": "製法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新しい製法を発売して、売り上げを伸ばした。", "explanation": "ここは〈製品〉の意味。発売するのは製品で、作り方の製法ではない。"}, {"text": "この会社は製法の担当を部署ごとに分け、毎日報告させている。", "explanation": "ここは〈担当部署〉の意味。製法は作り方を指すので、部署に割り振る対象にはならない。"}, {"text": "彼女は製法がとても速く、一日で仕事を終えてしまう。", "explanation": "製法は作り方を指す語で、人の仕事の速さを言うのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "製法", "is_correct": true, "explanation": "「メーカーごとに製法が異なる」で、作り方を指す語として文意に合う。"}, {"text": "製鉱", "is_correct": false, "explanation": "鉱石を精製する工程で、ハムの文脈には合わない。"}, {"text": "製綿", "is_correct": false, "explanation": "綿を作る工程で、ハムの文脈には合わない。"}, {"text": "製薬", "is_correct": false, "explanation": "薬を作る工程で、ハムの文脈には合わない。"}], "explanations": {"製法": "「メーカーごとに製法が異なる」で、作り方を指す語として文意に合う。", "製鉱": "鉱石を精製する工程で、ハムの文脈には合わない。", "製綿": "綿を作る工程で、ハムの文脈には合わない。", "製薬": "薬を作る工程で、ハムの文脈には合わない。"}, "sentence_index": 6, "correct_answer": "製法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は製法の鍋を火にかけて、ゆっくり温めておく。", "explanation": "ここは〈道具〉の意味。製法は作り方を指し、火にかける道具を言う語ではない。"}, {"text": "製法が高いので、学生でも気軽に買えない。", "explanation": "製法は作り方を指す語で、値段の高さを言う語としては使わない。"}, {"text": "製法の売れ行きが好調で、店は大忙しだ。", "explanation": "製法は売れるものではなく、製品の売れ行きを言う語として使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場では、新しい製法を製品を作っている。", "corrected_sentence": "この工場では、新しい製法で製品を作っている。", "error_description": "「製法で」は手段を示す。「製法を」と目的語を二つ重ねると、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52267, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ製法を破ることで、味が毎回そろう。", "corrected_sentence": "同じ製法を守ることで、味が毎回そろう。", "error_description": "製法は「守る」と結びつく。「破る」では味がそろう理由にならず、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「同情の念から」で、同情の気持ちを寄付の理由として示す。文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは寄付の理由なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す助詞で、理由を表す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、ここでは理由を表さないので合わない。"}], "correct_answer": "から", "explanations": {"から": "「同情の念から」で、同情の気持ちを寄付の理由として示す。文の意味に合う。", "を": "「を」は目的語を示すが、ここは寄付の理由なので合わない。", "へ": "「へ」は方向を示す助詞で、理由を表す文には合わない。", "と": "「と」は並列や相手を示すが、ここでは理由を表さないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「感謝の念」で、感謝を内容とする念であることを示す連体修飾の「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「感謝が念」は名詞同士をつながない。「が」は主語を示す助詞なので、名詞を修飾する位置には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「感謝を念」は目的語を示す助詞で、名詞を修飾できないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「感謝に念」は相手や場所を示す助詞で、名詞を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「感謝の念」で、感謝を内容とする念であることを示す連体修飾の「の」が入る。", "が": "「感謝が念」は名詞同士をつながない。「が」は主語を示す助詞なので、名詞を修飾する位置には合わない。", "を": "「感謝を念」は目的語を示す助詞で、名詞を修飾できないので合わない。", "に": "「感謝に念」は相手や場所を示す助詞で、名詞を修飾する位置には入らない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "相手・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で、大切なものに対して感じる、深い思いやりの気持ちのこと。", "primary_collocate": null, "pronunciation": "ねん", "ipa": "neɴ", "syllable_count": 2, "sentences": [{"text": "先生に対する感謝の念は、今も変わりません。", "target_word": "念", "complexity_tier": "T3", "furigana": "先生[せんせい]に対[たい]する感謝[かんしゃ]の念[ねん]は、今[いま]も変[か]わりません。", "sentence_source": "generated"}, {"text": "被災した人々への同情の念から、多くの人が寄付をした。", "target_word": "念", "complexity_tier": "T3", "furigana": "被災[ひさい]した人々[ひとびと]への同情[どうじょう]の念[ねん]から、多[おお]くの人[ひと]が寄付[きふ]をした。", "sentence_source": "generated"}, {"text": "彼は亡くなった友への追悼の念を、短い手紙に込めた。", "target_word": "念", "complexity_tier": "T3", "furigana": "彼[かれ]は亡[な]くなった友[とも]への追悼[ついとう]の念[ねん]を、短[みじか]い手紙[てがみ]に込[こ]めた。", "sentence_source": "generated"}, {"text": "長年支えてくれた家族に、深い感謝の念を抱いている。", "target_word": "念", "complexity_tier": "T3", "furigana": "長年[ながねん]支[ささ]えてくれた家族[かぞく]に、深[ふか]い感謝[かんしゃ]の念[ねん]を抱[いだ]いている。", "sentence_source": "generated"}, {"text": "自然に対する愛着の念が、この村の暮らしを守ってきた。", "target_word": "念", "complexity_tier": "T3", "furigana": "自然[しぜん]に対[たい]する愛着[あいちゃく]の念[ねん]が、この村[むら]の暮[く]らしを守[まも]ってきた。", "sentence_source": "generated"}, {"text": "母への尊敬の念は、年を重ねるほど強くなる。", "target_word": "念", "complexity_tier": "T3", "furigana": "母[はは]への尊敬[そんけい]の念[ねん]は、年[とし]を重[かさ]ねるほど強[つよ]くなる。", "sentence_source": "generated"}, {"text": "失敗した部下を責めず、励ます彼に、みんなは敬愛の念を覚えた。", "target_word": "念", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した部下[ぶか]を責[せ]めず、励[はげ]ます彼[かれ]に、みんなは敬愛[けいあい]の念[ねん]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "彼女は忘れ物を届けてくれた人に、感謝の念を伝えたいと思った。", "target_word": "念", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は忘[わす]れ物[もの]を届[とど]けてくれた人[ひと]に、感謝[かんしゃ]の念[ねん]を伝[つた]えたいと思[おも]った。", "sentence_source": "generated"}, {"text": "古い建物を修理する職人たちは、先人への敬いの念を忘れない。", "target_word": "念", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]を修理[しゅうり]する職人[しょくにん]たちは、先人[せんじん]への敬[うやま]いの念[ねん]を忘[わす]れない。", "sentence_source": "generated"}, {"text": "動物たちへの慈しみの念が、彼を獣医の道に進ませた。", "target_word": "念", "complexity_tier": "T3", "furigana": "動物[どうぶつ]たちへの慈[いつく]しみの念[ねん]が、彼[かれ]を獣医[じゅうい]の道[みち]に進[すす]ませた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "念", "label": "基本形"}], "register": "formal", "sense_fingerprint": "感謝や敬意など、心の中に抱く思い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "「感謝の念」は、感謝する気持ちを表す。この文で意味が通る唯一の語。"}, {"text": "紙", "is_correct": false, "explanation": "「感謝の紙」は意味をなさない。"}, {"text": "地図", "is_correct": false, "explanation": "「感謝の地図」は文脈に合わない。"}, {"text": "階段", "is_correct": false, "explanation": "「感謝の階段」は成り立たない。"}], "explanations": {"念": "「感謝の念」は、感謝する気持ちを表す。この文で意味が通る唯一の語。", "紙": "「感謝の紙」は意味をなさない。", "地図": "「感謝の地図」は文脈に合わない。", "階段": "「感謝の階段」は成り立たない。"}, "sentence_index": 0, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その件は念に置いて、慎重に考えておいた。", "explanation": "ここは〈念頭に置く〉の意味（心に留める）。念は深い思いやりの気持ちを指し、「心に留める」の意味はないので、〈念頭〉と取り違えた誤用で合わない。"}, {"text": "彼は長年受けた念を、仕事で返した。", "explanation": "ここは〈恩〉の意味。恩は受けて返すものだが、念は相手に向ける気持ちで、受け取って返すものではないので合わない。"}, {"text": "彼は鋭い念で危険を察知した。", "explanation": "ここは〈勘〉の意味。勘は直感で察知する働きだが、念は気持ちを指すので、察知の手段としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "念", "is_correct": true, "explanation": "「敬愛の念」は、尊敬し慕う気持ちを表す。この文で意味が通る唯一の語。"}, {"text": "紙", "is_correct": false, "explanation": "「敬愛の紙」は意味をなさない。"}, {"text": "橋", "is_correct": false, "explanation": "「敬愛の橋」は文脈に合わない。"}, {"text": "駅", "is_correct": false, "explanation": "「敬愛の駅」は成り立たない。"}], "explanations": {"念": "「敬愛の念」は、尊敬し慕う気持ちを表す。この文で意味が通る唯一の語。", "紙": "「敬愛の紙」は意味をなさない。", "橋": "「敬愛の橋」は文脈に合わない。", "駅": "「敬愛の駅」は成り立たない。"}, "sentence_index": 6, "correct_answer": "念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寺の僧は、亡き人のために念を唱え続けた。", "explanation": "ここは〈念仏〉の意味（仏の名を唱える）。念は唱えるものとしては使わず、念仏を唱えるという言い方になるので合わない。"}, {"text": "彼は昔の約束を、念を果たして守った。", "explanation": "ここは〈義理〉の意味。義理は果たすものだが、念は果たすものではないので合わない。"}, {"text": "彼女は、あの人との楽しい日々を、念で語り合った。", "explanation": "ここは〈思い〉の意味（心に抱く気持ち）。念は深い思いやりの気持ちを指し、語り合う手段として「念で」とは使わないので、〈思い〉と取り違えた誤用で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "被災地の人々への同情の念を、ボランティアに参加した。", "corrected_sentence": "被災地の人々への同情の念から、ボランティアに参加した。", "error_description": "「念」の後に続く助詞は、理由を表す「から」が正しい。「を」は目的語を示す助詞なので、理由を述べる文脈では不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、支えてくれた友人への感謝の念が手紙に込めた。", "corrected_sentence": "彼女は、支えてくれた友人への感謝の念を手紙に込めた。", "error_description": "「込める」は目的語に「を」を取る。「念が込めた」では主語と述語が合わず、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中に潜在する」で、力が存在する場所を示す。文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「中を潜在する」は場所を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「中へ潜在する」は方向を示すが、ここは存在する場所なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「中と潜在する」は並列の意味になり、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「中に潜在する」で、力が存在する場所を示す。文の意味に合う。", "を": "「中を潜在する」は場所を示せず、不自然。", "へ": "「中へ潜在する」は方向を示すが、ここは存在する場所なので合わない。", "と": "「中と潜在する」は並列の意味になり、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顕在", "is_correct": true, "explanation": "「潜在」の対義語。表に現れて明らかな状態を指し、隠れた状態の「潜在」と対になる。"}, {"text": "公開", "is_correct": false, "explanation": "「公開」は「非公開」の対義語で、「潜在」とは対にならない。"}, {"text": "消滅", "is_correct": false, "explanation": "「消滅」は存在がなくなることで、「潜在」の対義語とは言えない。"}, {"text": "制作", "is_correct": false, "explanation": "「制作」は作ることを指し、「潜在」の反対語ではない。"}], "correct_answer": "顕在", "explanations": {"顕在": "「潜在」の対義語。表に現れて明らかな状態を指し、隠れた状態の「潜在」と対になる。", "公開": "「公開」は「非公開」の対義語で、「潜在」とは対にならない。", "消滅": "「消滅」は存在がなくなることで、「潜在」の対義語とは言えない。", "制作": "「制作」は作ることを指し、「潜在」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
