INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まだ見えないけれど、あとで出てくる力や可能性のこと。", "primary_collocate": null, "pronunciation": "せんざい", "ipa": "seɴzai", "syllable_count": 4, "sentences": [{"text": "この町には、まだ知られていない魅力が潜在している。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "この町[まち]には、まだ知[し]られていない魅力[みりょく]が潜在[せんざい]している。", "sentence_source": "generated"}, {"text": "彼の中に潜在する力は、試合の終盤になって初めて表に出た。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "彼[かれ]の中[なか]に潜在[せんざい]する力[ちから]は、試合[しあい]の終盤[しゅうばん]になって初[はじ]めて表[おもて]に出[で]た。", "sentence_source": "generated"}, {"text": "この地域の地下には、まだ開発されていない資源が潜在している。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "この地域[ちいき]の地下[ちか]には、まだ開発[かいはつ]されていない資源[しげん]が潜在[せんざい]している。", "sentence_source": "generated"}, {"text": "社会に潜在する問題を、調査で明らかにした。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "社会[しゃかい]に潜在[せんざい]する問題[もんだい]を、調査[ちょうさ]で明[あき]らかにした。", "sentence_source": "generated"}, {"text": "市場には、まだ形になっていない需要が潜在している。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "市場[しじょう]には、まだ形[かたち]になっていない需要[じゅよう]が潜在[せんざい]している。", "sentence_source": "generated"}, {"text": "子どもの才能は、周りの大人が気づかないまま潜在していることが多い。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "子[こ]どもの才能[さいのう]は、周[まわ]りの大人[おとな]が気[き]づかないまま潜在[せんざい]していることが多[おお]い。", "sentence_source": "generated"}, {"text": "潜在していた不満が、会議の場で一気に表に出た。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "潜在[せんざい]していた不満[ふまん]が、会議[かいぎ]の場[ば]で一気[いっき]に表[おもて]に出[で]た。", "sentence_source": "generated"}, {"text": "古い建物には危険が潜在しているので、中に入る前に点検が必要だ。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]には危険[きけん]が潜在[せんざい]しているので、中[なか]に入[はい]る前[まえ]に点検[てんけん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この会社には、世界で勝負できる力が潜在していると私は思う。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]には、世界[せかい]で勝負[しょうぶ]できる力[ちから]が潜在[せんざい]していると私[わたし]は思[おも]う。", "sentence_source": "generated"}, {"text": "見えないところに潜在する可能性を、彼は見逃さなかった。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "見[み]えないところに潜在[せんざい]する可能性[かのうせい]を、彼[かれ]は見逃[みのが]さなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜在", "label": "基本形"}, {"form": "潜在する", "label": "サ変動詞終止形"}, {"form": "潜在している", "label": "継続形"}, {"form": "潜在した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "表に出ずに内側に隠れて存在していること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "「魅力が潜在している」で、まだ表に出ていない状態を表す。この文で意味が通る語。"}, {"text": "寄付", "is_correct": false, "explanation": "「魅力が寄付している」は主語と動詞が合わず、不自然。"}, {"text": "解説", "is_correct": false, "explanation": "「魅力が解説している」は主語と動詞が合わず、不自然。"}, {"text": "公布", "is_correct": false, "explanation": "「公布」は法令などに使う語で、魅力の文には合わない。"}], "explanations": {"潜在": "「魅力が潜在している」で、まだ表に出ていない状態を表す。この文で意味が通る語。", "寄付": "「魅力が寄付している」は主語と動詞が合わず、不自然。", "解説": "「魅力が解説している」は主語と動詞が合わず、不自然。", "公布": "「公布」は法令などに使う語で、魅力の文には合わない。"}, "sentence_index": 0, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "潜水士は海の底まで深く潜在した。", "explanation": "ここは〈潜る〉の意味（水中に入る動作）。潜在は状態を表す語で、移動の意味はないので合わない。"}, {"text": "犯人は山中の小屋に三日間潜在していた。", "explanation": "ここは〈潜伏〉の意味（人が身を隠す）。潜在は人が隠れる意味では使わないので合わない。"}, {"text": "祖父は縁側で昼寝をして、そのまま潜在していた。", "explanation": "ここは〈眠る〉の意味。潜在は眠る意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "「潜在していた不満」で、表に出ずに内側にあった状態を表す。この文で意味が通る語。"}, {"text": "放映", "is_correct": false, "explanation": "「放映していた不満」は不自然で、文の意味に合わない。"}, {"text": "出品", "is_correct": false, "explanation": "「出品していた不満」は意味が通らない。"}, {"text": "解任", "is_correct": false, "explanation": "「解任していた不満」は文に合わない。"}], "explanations": {"潜在": "「潜在していた不満」で、表に出ずに内側にあった状態を表す。この文で意味が通る語。", "放映": "「放映していた不満」は不自然で、文の意味に合わない。", "出品": "「出品していた不満」は意味が通らない。", "解任": "「解任していた不満」は文に合わない。"}, "sentence_index": 6, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スパイが敵の基地に三日間潜在した。", "explanation": "ここは〈潜入〉の意味（敵地に忍び込む）。潜在は忍び込む意味はないので合わない。"}, {"text": "このワインは五年間じっくり潜在している。", "explanation": "ここは〈熟成〉の意味（寝かせて味を深める）。潜在は時間をかけて成熟する意味はないので合わない。"}, {"text": "箱の陰に猫が潜在している。", "explanation": "ここは〈潜む〉の意味（生き物が身を隠す）。潜在は生き物が隠れる様子には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山奥には、まだ誰も知らない温泉を潜在している。", "corrected_sentence": "山奥には、まだ誰も知らない温泉が潜在している。", "error_description": "「潜在」は自動詞なので、主語を「が」で示す。「を」を使うと目的語になり、潜在の用法に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の奥には、まだ発見されていない遺跡が潜在される。", "corrected_sentence": "森の奥には、まだ発見されていない遺跡が潜在している。", "error_description": "「潜在」は受け身にならない自動詞なので、「潜在される」は誤り。状態を表す「潜在している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『声が呼応して』で、応え合う主体である声を示す主語になる。"}, {"text": "を", "is_correct": false, "explanation": "『呼応する』は目的語を取らないため、『声を呼応して』は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾に使うため、『声の呼応して』は文の骨組みに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『声へ呼応して』は主語の位置に合わない。"}], "correct_answer": "が", "explanations": {"が": "『声が呼応して』で、応え合う主体である声を示す主語になる。", "を": "『呼応する』は目的語を取らないため、『声を呼応して』は成り立たない。", "の": "『の』は名詞修飾に使うため、『声の呼応して』は文の骨組みに合わない。", "へ": "『へ』は方向を示すため、『声へ呼応して』は主語の位置に合わない。"}, "error_tags": {"を": "目的語", "の": "名詞修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものが、おたがいにこたえあうように、つながること。", "primary_collocate": null, "pronunciation": "こおう", "ipa": "kooɯ", "syllable_count": 3, "sentences": [{"text": "森の中で、二羽の鳥の鳴き声が呼応していた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)で、二羽(にわ)の鳥(とり)の鳴(な)き声(ごえ)が呼応(こおう)していた。", "sentence_source": "generated"}, {"text": "歌い手とお客さんの声が呼応して、会場が一つになった。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "歌(うた)い手(て)とお客(きゃく)さんの声(こえ)が呼応(こおう)して、会場(かいじょう)が一(ひと)つになった。", "sentence_source": "generated"}, {"text": "兄が手を振ると、弟もそれに呼応して手を振り返した。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "兄(あに)が手(て)を振(ふ)ると、弟(おとうと)もそれに呼応(こおう)して手(て)を振(ふ)り返(かえ)した。", "sentence_source": "generated"}, {"text": "左右の塔が互いに呼応するように、同じ高さで建っている。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "左右(さゆう)の塔(とう)が互(たが)いに呼応(こおう)するように、同(おな)じ高(たか)さで建(た)っている。", "sentence_source": "generated"}, {"text": "この詩は、最初の行と最後の行が呼応している。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "この詩(し)は、最初(さいしょ)の行(ぎょう)と最後(さいご)の行(ぎょう)が呼応(こおう)している。", "sentence_source": "generated"}, {"text": "太鼓の音に呼応して、笛の音が響いた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "太鼓(たいこ)の音(おと)に呼応(こおう)して、笛(ふえ)の音(ね)が響(ひび)いた。", "sentence_source": "generated"}, {"text": "二つの村の祭りは、昔から呼応し合って行われてきた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "二(ふた)つの村(むら)の祭(まつ)りは、昔(むかし)から呼応(こおう)し合(あ)って行(おこな)われてきた。", "sentence_source": "generated"}, {"text": "先生の問いかけに、生徒たちが呼応して元気に答えた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "先生(せんせい)の問(と)いかけに、生徒(せいと)たちが呼応(こおう)して元気(げんき)に答(こた)えた。", "sentence_source": "generated"}, {"text": "二人のダンサーの動きが見事に呼応していた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "二人(ふたり)のダンサーの動(うご)きが見事(みごと)に呼応(こおう)していた。", "sentence_source": "generated"}, {"text": "遠くの犬の遠吠えに呼応して、近くの犬も吠え始めた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "遠(とお)くの犬(いぬ)の遠吠(とおぼ)えに呼応(こおう)して、近(ちか)くの犬(いぬ)も吠(ほ)え始(はじ)めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼応する", "label": "辞書形"}, {"form": "呼応して", "label": "て形"}, {"form": "呼応した", "label": "過去形"}, {"form": "呼応しない", "label": "否定形"}], "register": "neutral written (書き言葉、常体)", "sense_fingerprint": "二つのものが互いに応え合うように結びつく（スル名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼応", "is_correct": true, "explanation": "二羽の鳥の鳴き声が応え合っている様子を表し、『呼応していた』が入る。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は礼を述べる気持ちで、鳴き声の様子を表す『感謝していた』は合わない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べることで、鳴き声が『点検していた』とは言えない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、鳴き声が『散歩していた』とは言えない。"}], "explanations": {"呼応": "二羽の鳥の鳴き声が応え合っている様子を表し、『呼応していた』が入る。", "感謝": "感謝は礼を述べる気持ちで、鳴き声の様子を表す『感謝していた』は合わない。", "点検": "点検は調べることで、鳴き声が『点検していた』とは言えない。", "散歩": "散歩は歩くことで、鳴き声が『散歩していた』とは言えない。"}, "sentence_index": 0, "correct_answer": "呼応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い鍵を呼応させて、ドアをこじ開けた。", "explanation": "ここは〈こじ開ける〉の意味。呼応は二つのものが応じ合ってつながることで、鍵を無理に壊す動作には使わない。"}, {"text": "彼は一人で呼応しながら、窓を拭いていた。", "explanation": "ここは〈単独の作業〉の場面。呼応は相手と応え合うことなので、一人では成り立たない。"}, {"text": "ひとつの鐘が呼応して、夕方の空に鳴り響いた。", "explanation": "ここは〈自然に響く〉の意味。呼応は二つのものがおたがいに応え合うことで、一つだけで鳴る場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼応", "is_correct": true, "explanation": "『昔から呼応し合って』で、祭りが互いに応え合ってきたことを表す。"}, {"text": "居眠り", "is_correct": false, "explanation": "居眠りは眠ることで、『居眠りし合って』は祭りの文脈に合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "入浴は体を洗う行為で、祭りについて『入浴し合って』とは言えない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は品を買う行為で、祭りの行事を表す文脈に合わない。"}], "explanations": {"呼応": "『昔から呼応し合って』で、祭りが互いに応え合ってきたことを表す。", "居眠り": "居眠りは眠ることで、『居眠りし合って』は祭りの文脈に合わない。", "入浴": "入浴は体を洗う行為で、祭りについて『入浴し合って』とは言えない。", "買い物": "買い物は品を買う行為で、祭りの行事を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呼応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな地響きに呼応して、ペンギンが昼寝を始めた。", "explanation": "ここは〈無関係な動き〉の意味。呼応は二つのものが応じ合うことで、無関係な動物の行動には使わない。"}, {"text": "熱いものに触れると、手は呼応して離れた。", "explanation": "ここは〈反射〉の意味。呼応は互いに応じ合う関係で、一方的な反射的動作には使わない。"}, {"text": "作業のあと、ファイルは呼応して保存された。", "explanation": "ここは〈同期〉の意味。呼応はおたがいに応え合う関係で、ファイル一つの保存には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄の合図を呼応して、弟が立ち上がった。", "corrected_sentence": "兄の合図に呼応して、弟が立ち上がった。", "error_description": "『呼応する』は『に』で相手を示す。『を』は目的語に付くため、呼応の相手を示す形としては誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風の音に呼応だ、木々がざわめいた。", "corrected_sentence": "風の音に呼応して、木々がざわめいた。", "error_description": "『呼応する』の後に続く接続形は『呼応して』。『呼応だ』は文が続かず、活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『呼応する』は『に』で相手を示すため、『呼びかけに呼応して』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『呼応する』は目的語を取らないため、『呼びかけを呼応して』は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すため、『呼びかけが呼応して』は相手の示し方として合わない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞修飾に使うため、『呼びかけの呼応して』は文の骨組みに合わない。"}], "correct_answer": "に", "explanations": {"に": "『呼応する』は『に』で相手を示すため、『呼びかけに呼応して』が正しい。", "を": "『呼応する』は目的語を取らないため、『呼びかけを呼応して』は成り立たない。", "が": "『が』は主語を示すため、『呼びかけが呼応して』は相手の示し方として合わない。", "の": "『の』は名詞修飾に使うため、『呼びかけの呼応して』は文の骨組みに合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "名詞修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『音楽の盛り上がりと呼応して』で、呼応する相手を並べて示す。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すため、『音楽の盛り上がりで呼応して』は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『音楽の盛り上がりへ呼応して』とは続かない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すため、呼応の相手を示す形としては合わない。"}], "correct_answer": "と", "explanations": {"と": "『音楽の盛り上がりと呼応して』で、呼応する相手を並べて示す。", "で": "『で』は手段や場所を示すため、『音楽の盛り上がりで呼応して』は成り立たない。", "へ": "『へ』は方向を示すため、『音楽の盛り上がりへ呼応して』とは続かない。", "から": "『から』は起点を示すため、呼応の相手を示す形としては合わない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある事柄や動作が、別の事柄や動作と対応したり、影響し合ったりすること。", "primary_collocate": null, "pronunciation": "こおう", "ipa": "kooɯ", "syllable_count": 3, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "呼応", "complexity_tier": "T4", "furigana": "水温(すいおん)と室温(しつおん)をミリ単位(たんい)で制御(せいぎょ)し、小麦粉(こむぎこ)と水(みず)のみを混(ま)ぜ合(あ)わせる行為(こうい)は、単(たん)なる調理(ちょうり)の域(いき)を超(こ)え、微生物(びせいぶつ)の生態系(せいたいけい)を育(はぐく)む科学的(かがくてき)な実験(じっけん)とも呼応(こおう)する。", "sentence_source": "mined"}, {"text": "市長の呼びかけに呼応して、多くの住民が清掃活動に参加した。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "市長(しちょう)の呼(よ)びかけに呼応(こおう)して、多(おお)くの住民(じゅうみん)が清掃(せいそう)活動(かつどう)に参加(さんか)した。", "sentence_source": "generated"}, {"text": "株価の上昇は、景気回復の動きと呼応している。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "株価(かぶか)の上昇(じょうしょう)は、景気(けいき)回復(かいふく)の動(うご)きと呼応(こおう)している。", "sentence_source": "generated"}, {"text": "前半の伏線が、結末の場面と呼応する構成になっている。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "前半(ぜんはん)の伏線(ふくせん)が、結末(けつまつ)の場面(ばめん)と呼応(こおう)する構成(こうせい)になっている。", "sentence_source": "generated"}, {"text": "彼の発言に呼応するように、会場から拍手が起こった。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "彼(かれ)の発言(はつげん)に呼応(こおう)するように、会場(かいじょう)から拍手(はくしゅ)が起(お)こった。", "sentence_source": "generated"}, {"text": "気温の低下に呼応して、電力の使用量も増えた。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "気温(きおん)の低下(ていか)に呼応(こおう)して、電力(でんりょく)の使用量(しようりょう)も増(ふ)えた。", "sentence_source": "generated"}, {"text": "二つの政党が互いに呼応して、法案の成立を目指した。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "二(ふた)つの政党(せいとう)が互(たが)いに呼応(こおう)して、法案(ほうあん)の成立(せいりつ)を目指(めざ)した。", "sentence_source": "generated"}, {"text": "音楽の盛り上がりと呼応して、照明も明るくなった。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "音楽(おんがく)の盛(も)り上(あ)がりと呼応(こおう)して、照明(しょうめい)も明(あか)るくなった。", "sentence_source": "generated"}, {"text": "商品の値上げに呼応し、他社も価格を見直した。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "商品(しょうひん)の値上(ねあ)げに呼応(こおう)し、他社(たしゃ)も価格(かかく)を見直(みなお)した。", "sentence_source": "generated"}, {"text": "学生たちの運動は、全国の動きと呼応して広がった。", "target_word": "呼応", "complexity_tier": "T3", "furigana": "学生(がくせい)たちの運動(うんどう)は、全国(ぜんこく)の動(うご)きと呼応(こおう)して広(ひろ)がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼応する", "label": "辞書形"}, {"form": "呼応して", "label": "て形"}, {"form": "呼応した", "label": "過去形"}, {"form": "呼応しない", "label": "否定形"}], "register": "formal written (書き言葉)", "sense_fingerprint": "ある事柄・動作が別の事柄・動作と対応し影響し合う（スル名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼応", "is_correct": true, "explanation": "『実験とも呼応する』で、二つの事柄が応じ合う関係を表す語になる。"}, {"text": "相談", "is_correct": false, "explanation": "相談は話し合う行為で、『実験とも相談する』では文意が通らない。"}, {"text": "散策", "is_correct": false, "explanation": "散策は歩き回ることで、実験と結びついて『散策する』とは言えない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は礼を述べる気持ちで、実験を対象にした『感謝する』は文脈に合わない。"}], "explanations": {"呼応": "『実験とも呼応する』で、二つの事柄が応じ合う関係を表す語になる。", "相談": "相談は話し合う行為で、『実験とも相談する』では文意が通らない。", "散策": "散策は歩き回ることで、実験と結びついて『散策する』とは言えない。", "感謝": "感謝は礼を述べる気持ちで、実験を対象にした『感謝する』は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "呼応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬を飲むと、体が呼応して発疹が出た。", "explanation": "ここは〈反応〉の意味。呼応は互いに応え合う関係で、体の一方的な反応には使わない。"}, {"text": "彼は一人で呼応しながら、部屋の掃除を続けた。", "explanation": "ここは〈単独の作業〉の場面。呼応は相手と応え合うことなので、一人では成り立たない。"}, {"text": "彼の財布が呼応して、部屋のドアが開いた。", "explanation": "ここは〈無関係な偶然の一致〉の意味。呼応は互いに応じ合う関係で、無関係な二つの出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼応", "is_correct": true, "explanation": "『互いに呼応して』で、互いに応え合って法案の成立を目指す関係を表す。"}, {"text": "居眠り", "is_correct": false, "explanation": "居眠りは眠ることで、『互いに居眠りして』は意味が通らない。"}, {"text": "入浴", "is_correct": false, "explanation": "入浴は体を洗う行為で、政党の動きに対して『互いに入浴して』とは言えない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は品を買う行為で、『互いに買い物して』は法案の文脈に合わない。"}], "explanations": {"呼応": "『互いに呼応して』で、互いに応え合って法案の成立を目指す関係を表す。", "居眠り": "居眠りは眠ることで、『互いに居眠りして』は意味が通らない。", "入浴": "入浴は体を洗う行為で、政党の動きに対して『互いに入浴して』とは言えない。", "買い物": "買い物は品を買う行為で、『互いに買い物して』は法案の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呼応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一本のロウソクが呼応して、部屋の明かりが消えた。", "explanation": "ここは〈消灯〉の場面。呼応は複数のものがおたがいに応え合うことで、一本の火が単独で消える場合には使わない。"}, {"text": "熱いものに触れると、手は呼応して離れた。", "explanation": "ここは〈反射〉の意味。呼応は互いに応じ合う関係で、一方的な反射的動作には使わない。"}, {"text": "夜遅く、彼女の名を呼応して、窓を開けた。", "explanation": "ここは〈呼び出す〉の意味。呼応は対応・影響し合う関係で、名前を呼ぶ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ライブの盛り上がりを呼応して、観客が手を叩いた。", "corrected_sentence": "ライブの盛り上がりに呼応して、観客が手を叩いた。", "error_description": "『呼応する』は『に』で相手を示す。『を』は目的語に付くため、呼応の相手を示す形としては誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52274, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい法律の施行に呼応しで、役所の手続きが変わった。", "corrected_sentence": "新しい法律の施行に呼応して、役所の手続きが変わった。", "error_description": "『呼応する』のて形は『呼応して』。『呼応しで』は濁音化した誤った活用形になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「記憶を」は引き出す対象を示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「記憶が」は主語になり、引き出す対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「記憶と」は並列の相手を示し、引き出す対象は示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「記憶へ」は方向を示すが、引き出す対象は示さない。"}], "correct_answer": "を", "explanations": {"を": "「記憶を」は引き出す対象を示す目的語の格助詞。", "が": "「記憶が」は主語になり、引き出す対象にはならない。", "と": "「記憶と」は並列の相手を示し、引き出す対象は示さない。", "へ": "「記憶へ」は方向を示すが、引き出す対象は示さない。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「夢を」は引き出す対象を示す目的語の格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「夢に」は方向や相手を示し、引き出す対象は「を」で示す必要があるため合わない。"}, {"text": "の", "is_correct": false, "explanation": "「夢の」は名詞を修飾する形で、動詞に直接つながらず文の格関係が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「夢で」は手段や場所を示し、引き出す対象は示さないため合わない。"}], "correct_answer": "を", "explanations": {"を": "「夢を」は引き出す対象を示す目的語の格助詞。", "に": "「夢に」は方向や相手を示し、引き出す対象は「を」で示す必要があるため合わない。", "の": "「夢の」は名詞を修飾する形で、動詞に直接つながらず文の格関係が成立しない。", "で": "「夢で」は手段や場所を示し、引き出す対象は示さないため合わない。"}, "error_tags": {"に": "方向", "の": "連体修飾", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かくれたものを、うえにだすこと。", "primary_collocate": null, "pronunciation": "ひきだす", "ipa": "çikidasɯ", "syllable_count": 4, "sentences": [{"text": "彼女の優しい質問が、少年の隠していた悩みを引き出した。", "target_word": "引き出した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の優[やさ]しい質問[しつもん]が、少年[しょうねん]の隠[かく]していた悩[なや]みを引[ひ]き出[だ]した。", "sentence_source": "generated"}, {"text": "催眠療法では、忘れていた記憶を引き出すことがある。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "催眠[さいみん]療法[りょうほう]では、忘[わす]れていた記憶[きおく]を引[ひ]き出[だ]すことがある。", "sentence_source": "generated"}, {"text": "先生は生徒の中に隠れていた長所を引き出してくれた。", "target_word": "引き出して", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の中[なか]に隠[かく]れていた長所[ちょうしょ]を引[ひ]き出[だ]してくれた。", "sentence_source": "generated"}, {"text": "記者は、巧みな質問で大臣から本音を引き出した。", "target_word": "引き出した", "complexity_tier": "T3", "furigana": "記者[きしゃ]は、巧[たく]みな質問[しつもん]で大臣[だいじん]から本音[ほんね]を引[ひ]き出[だ]した。", "sentence_source": "generated"}, {"text": "絵を描くことで、心の奥にある気持ちを引き出せる。", "target_word": "引き出せる", "complexity_tier": "T3", "furigana": "絵[え]を描[えが]くことで、心[こころ]の奥[おく]にある気持[きも]ちを引[ひ]き出[だ]せる。", "sentence_source": "generated"}, {"text": "警察は、容疑者から事件の真実を引き出そうとした。", "target_word": "引き出そう", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、容疑者[ようぎしゃ]から事件[じけん]の真実[しんじつ]を引[ひ]き出[だ]そうとした。", "sentence_source": "generated"}, {"text": "彼女の演奏は、楽器の音色の奥にある美しさを引き出している。", "target_word": "引き出して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の演奏[えんそう]は、楽器[がっき]の音色[ねいろ]の奥[おく]にある美[うつく]しさを引[ひ]き出[だ]している。", "sentence_source": "generated"}, {"text": "友人との会話が、忘れていた夢を引き出してくれた。", "target_word": "引き出して", "complexity_tier": "T3", "furigana": "友人[ゆうじん]との会話[かいわ]が、忘[わす]れていた夢[ゆめ]を引[ひ]き出[だ]してくれた。", "sentence_source": "generated"}, {"text": "古い写真は、懐かしい思い出を引き出す。", "target_word": "引き出す", "complexity_tier": "T2", "furigana": "古[ふる]い写真[しゃしん]は、懐[なつ]かしい思[おも]い出[で]を引[ひ]き出[だ]す。", "sentence_source": "generated"}, {"text": "良い聞き手は、話し手の隠れた魅力を引き出せる。", "target_word": "引き出せる", "complexity_tier": "T3", "furigana": "良[よ]い聞[き]き手[て]は、話[はな]し手[て]の隠[かく]れた魅力[みりょく]を引[ひ]き出[だ]せる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引き出す", "label": "辞書形"}, {"form": "引き出さ", "label": "未然形"}, {"form": "引き出し", "label": "連用形"}, {"form": "引き出そう", "label": "意志形"}, {"form": "引き出して", "label": "て形"}, {"form": "引き出した", "label": "た形"}, {"form": "引き出せる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "奥や内に隠れていたものを表に出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引き出した", "is_correct": true, "explanation": "た形で、過去の出来事として文を言い切れる。質問が悩みを表に出した経緯を述べる。"}, {"text": "引き出して", "is_correct": false, "explanation": "て形は文を言い切れず、「悩みを引き出して。」で終わらない。"}, {"text": "引き出せ", "is_correct": false, "explanation": "命令形になり、「質問が悩みを引き出せ。」は出来事を述べる文に合わない。"}, {"text": "引き出さ", "is_correct": false, "explanation": "未然形は文を言い切れず、文末に置けない。"}], "explanations": {"引き出した": "た形で、過去の出来事として文を言い切れる。質問が悩みを表に出した経緯を述べる。", "引き出して": "て形は文を言い切れず、「悩みを引き出して。」で終わらない。", "引き出せ": "命令形になり、「質問が悩みを引き出せ。」は出来事を述べる文に合わない。", "引き出さ": "未然形は文を言い切れず、文末に置けない。"}, "sentence_index": 0, "correct_answer": "引き出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は難しい仕事を、途中で引き出した。", "explanation": "ここは〈投げ出す〉の意味。引き出すは隠れていたものを表に出す意味で、途中でやめて放り出す場合には使わない。"}, {"text": "彼は、本心を心の奥へ引き出した。", "explanation": "ここは〈押し込める〉の意味。引き出すは内から表へ出す意味で、内側へ閉じ込める方向には使わない。"}, {"text": "昨夜の大雨で、洪水が村の家々を引き出した。", "explanation": "ここは〈押し流す〉の意味。引き出すは取り出す意味で、水が勢いで運び去る場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引き出して", "is_correct": true, "explanation": "て形。「いる」に続けて「引き出している」となり、継続の状態を表す。"}, {"text": "引き出す", "is_correct": false, "explanation": "辞書形は「引き出すいる」となり、「いる」に続けられない。"}, {"text": "引き出し", "is_correct": false, "explanation": "連用形は「引き出しいる」となり、「いる」に続けられない。"}, {"text": "引き出さ", "is_correct": false, "explanation": "未然形は「引き出さいる」となり、「いる」に続けられない。"}], "explanations": {"引き出して": "て形。「いる」に続けて「引き出している」となり、継続の状態を表す。", "引き出す": "辞書形は「引き出すいる」となり、「いる」に続けられない。", "引き出し": "連用形は「引き出しいる」となり、「いる」に続けられない。", "引き出さ": "未然形は「引き出さいる」となり、「いる」に続けられない。"}, "sentence_index": 6, "correct_answer": "引き出して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は床の汚れを、ブラシで引き出した。", "explanation": "ここは〈取り除く〉の意味。引き出すは隠れたものを表に出す意味で、汚れを消し去る場合には使わない。"}, {"text": "彼は緩んだ体を、ぎゅっと引き出した。", "explanation": "ここは〈引き締める〉の意味。引き出すは隠れたものを表に出す意味で、たるんだ体を締める場合には使わない。"}, {"text": "老朽化した古い建物を、引き出した。", "explanation": "ここは〈取り壊す〉の意味。引き出すは内から外へ取り出す意味で、建物を壊して無くす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の優しい質問が、隠していた不安を引き出れた。", "corrected_sentence": "彼の優しい質問が、隠していた不安を引き出した。", "error_description": "「引き出す」の過去形は「引き出した」。「引き出れた」は存在しない誤った活用。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引き出す", "is_correct": true, "explanation": "辞書形（連体形）。「引き出すことがある」と、後ろの「こと」を修飾する形。"}, {"text": "引き出し", "is_correct": false, "explanation": "連用形は「引き出しことがある」と続けられず、名詞「こと」を修飾できない。"}, {"text": "引き出さ", "is_correct": false, "explanation": "未然形は「引き出さことがある」と続けられず、文が成立しない。"}, {"text": "引き出そう", "is_correct": false, "explanation": "意志形は「引き出そうことがある」となり、「こと」を修飾できない。"}], "correct_form": "引き出す", "base_form": "引き出す", "form_label": "連体形（辞書形）", "sentence_index": 1, "explanations": {"引き出す": "辞書形（連体形）。「引き出すことがある」と、後ろの「こと」を修飾する形。", "引き出し": "連用形は「引き出しことがある」と続けられず、名詞「こと」を修飾できない。", "引き出さ": "未然形は「引き出さことがある」と続けられず、文が成立しない。", "引き出そう": "意志形は「引き出そうことがある」となり、「こと」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52275, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その指揮者は、楽団の奥に眠る音色を引き出しる。", "corrected_sentence": "その指揮者は、楽団の奥に眠る音色を引き出している。", "error_description": "「引き出す」の継続形は「引き出している」。「引き出しる」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引き出して", "is_correct": true, "explanation": "て形。「てくれた」に続き、友人が夢を引き出してくれたという恩恵を表す。"}, {"text": "引き出した", "is_correct": false, "explanation": "た形は「くれた」に直接続かず、「引き出したくれた」は成立しない。"}, {"text": "引き出せる", "is_correct": false, "explanation": "可能形は「くれた」に続けられず、「引き出せるくれた」は文が成立しない。"}, {"text": "引き出さない", "is_correct": false, "explanation": "否定形は「くれた」に続けられず、「引き出さないくれた」は成立しない。"}], "correct_form": "引き出して", "base_form": "引き出す", "form_label": "て形", "sentence_index": 7, "explanations": {"引き出して": "て形。「てくれた」に続き、友人が夢を引き出してくれたという恩恵を表す。", "引き出した": "た形は「くれた」に直接続かず、「引き出したくれた」は成立しない。", "引き出せる": "可能形は「くれた」に続けられず、「引き出せるくれた」は文が成立しない。", "引き出さない": "否定形は「くれた」に続けられず、「引き出さないくれた」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
