INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「実力を」は引き出せた対象を示す目的語の格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「実力に」は対象を示せず、引き出せたという動作の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「実力の」は名詞に続く連体の助詞で、動詞「引き出せた」の直前に置くと文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "「実力より」は比較を表し、引き出せた対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「実力を」は引き出せた対象を示す目的語の格助詞。", "に": "「実力に」は対象を示せず、引き出せたという動作の目的語にならない。", "の": "「実力の」は名詞に続く連体の助詞で、動詞「引き出せた」の直前に置くと文が続かない。", "より": "「実力より」は比較を表し、引き出せた対象を示すことはできない。"}, "error_tags": {"に": "対象の誤用", "の": "連体の誤用", "より": "比較の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "（物や能力を）外に取り出すこと。特に、隠れた能力を十分に発揮させること。", "primary_collocate": null, "pronunciation": "ひきだす", "ipa": "çikidasɯ", "syllable_count": 4, "sentences": [{"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "引き出そう", "complexity_tier": "T4", "furigana": "単[ただ]なるパンを焼[や]き上[あ]げるという行為[こうい]の域[いき]を超[こ]え、そこには古[いにしえ]の製法[せいほう]への畏敬[いけい]の念[ねん]と、素材[そざい]の潜在能力[せんざいのうりょく]を限界[げんかい]まで引[ひ]き出[だ]そうとする職人[しょくにん]としての揺[ゆ]るぎない覚悟[かくご]が、静[しず]かに宿[やど]っていたのである。", "sentence_source": "mined"}, {"text": "良い監督は、選手の力を最大限に引き出す。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "良[よ]い監督[かんとく]は、選手[せんしゅ]の力[ちから]を最大限[さいだいげん]に引[ひ]き出[だ]す。", "sentence_source": "generated"}, {"text": "先生の励ましが、生徒の才能を引き出した。", "target_word": "引き出した", "complexity_tier": "T3", "furigana": "先生[せんせい]の励[はげ]ましが、生徒[せいと]の才能[さいのう]を引[ひ]き出[だ]した。", "sentence_source": "generated"}, {"text": "子どもの好奇心を引き出す絵本が、この店では人気だ。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "子[こ]どもの好奇心[こうきしん]を引[ひ]き出[だ]す絵本[えほん]が、この店[みせ]では人気[にんき]だ。", "sentence_source": "generated"}, {"text": "この調味料は、素材の甘みを引き出す効果がある。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "この調味料[ちょうみりょう]は、素材[そざい]の甘[あま]みを引[ひ]き出[だ]す効果[こうか]がある。", "sentence_source": "generated"}, {"text": "新人の才能を引き出すために、上司は難しい仕事を任せた。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "新人[しんじん]の才能[さいのう]を引[ひ]き出[だ]すために、上司[じょうし]は難[むずか]しい仕事[しごと]を任[まか]せた。", "sentence_source": "generated"}, {"text": "この教え方は、生徒のやる気を引き出すのがうまい。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "この教[おし]え方[かた]は、生徒[せいと]のやる気[き]を引[ひ]き出[だ]すのがうまい。", "sentence_source": "generated"}, {"text": "練習で眠っていた実力を引き出せたので、試合に勝てた。", "target_word": "引き出せた", "complexity_tier": "T3", "furigana": "練習[れんしゅう]で眠[ねむ]っていた実力[じつりょく]を引[ひ]き出[だ]せたので、試合[しあい]に勝[か]てた。", "sentence_source": "generated"}, {"text": "強火で焼くと、肉のうまみを引き出せます。", "target_word": "引き出せ", "complexity_tier": "T3", "furigana": "強火[つよび]で焼[や]くと、肉[にく]のうまみを引[ひ]き出[だ]せます。", "sentence_source": "generated"}, {"text": "彼の笑顔は、周りの人の優しさを引き出す不思議な力がある。", "target_word": "引き出す", "complexity_tier": "T3", "furigana": "彼[かれ]の笑顔[えがお]は、周[まわ]りの人[ひと]の優[やさ]しさを引[ひ]き出[だ]す不思議[ふしぎ]な力[ちから]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引き出す", "label": "辞書形"}, {"form": "引き出さ", "label": "未然形"}, {"form": "引き出し", "label": "連用形"}, {"form": "引き出そう", "label": "意志形"}, {"form": "引き出して", "label": "て形"}, {"form": "引き出した", "label": "た形"}, {"form": "引き出せる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "隠れた能力や良さを外に出して十分に発揮させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 焼き上げる (Zipf 2.14), 畏敬 (Zipf 2.76), 揺るぎない (Zipf 2.86), 宿っ (Zipf 3.16)']::text[], 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引き出そう", "is_correct": true, "explanation": "意志形。「〜そうとする」に続き、限界まで素材の力を引き出そうとする意図を表す。"}, {"text": "引き出した", "is_correct": false, "explanation": "た形は「〜そうとする」に続かず、「引き出したとする」では文が成立しない。"}, {"text": "引き出せる", "is_correct": false, "explanation": "可能形は「〜そうとする」の形に接続せず、目的を表す文型に合わない。"}, {"text": "引き出して", "is_correct": false, "explanation": "て形は「〜そうとする」の前に置けず、文を言い切れない。"}], "explanations": {"引き出そう": "意志形。「〜そうとする」に続き、限界まで素材の力を引き出そうとする意図を表す。", "引き出した": "た形は「〜そうとする」に続かず、「引き出したとする」では文が成立しない。", "引き出せる": "可能形は「〜そうとする」の形に接続せず、目的を表す文型に合わない。", "引き出して": "て形は「〜そうとする」の前に置けず、文を言い切れない。"}, "sentence_index": 0, "correct_answer": "引き出そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このオーブンは、毎日おいしいパンを引き出している。", "explanation": "ここは〈生み出す〉の意味。引き出すは内にあるものを外へ取り出す意味で、無いものを作る場合には使わない。"}, {"text": "彼は来た道を、ためらわず引き出した。", "explanation": "ここは〈引き返す〉の意味。引き出すは隠れたものを外に出す意味で、来た道を戻る場合には使わない。"}, {"text": "先生は宿題を忘れた生徒を、職員室へ引き出した。", "explanation": "ここは〈呼び出す〉の意味。引き出すは隠れたものを表に出す意味で、人を来させる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引き出す", "is_correct": true, "explanation": "辞書形に「のが」が続き、動作を名詞化した「引き出すのがうまい」となる。"}, {"text": "引き出そう", "is_correct": false, "explanation": "意志形は「引き出そうのがうまい」となり、名詞化できない。"}, {"text": "引き出して", "is_correct": false, "explanation": "て形は「引き出してのがうまい」となり、成立しない。"}, {"text": "引き出さ", "is_correct": false, "explanation": "未然形は単独で名詞化できず、「引き出さのがうまい」は成立しない。"}], "explanations": {"引き出す": "辞書形に「のが」が続き、動作を名詞化した「引き出すのがうまい」となる。", "引き出そう": "意志形は「引き出そうのがうまい」となり、名詞化できない。", "引き出して": "て形は「引き出してのがうまい」となり、成立しない。", "引き出さ": "未然形は単独で名詞化できず、「引き出さのがうまい」は成立しない。"}, "sentence_index": 6, "correct_answer": "引き出す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は先輩から、重要な役割を引き出した。", "explanation": "ここは〈引き受ける〉の意味。引き出すは隠れたものを外に出す意味で、仕事や役目を自分が受ける場合には使わない。"}, {"text": "彼は締め切りを、一日だけ引き出した。", "explanation": "ここは〈延ばす〉の意味。引き出すは隠れたものを外に出す意味で、期限を先へずらす場合には使わない。"}, {"text": "彼は船を、海の底へ引き出した。", "explanation": "ここは〈沈める〉の意味。引き出すは外へ取り出す意味で、底へ沈めることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この料理人は、食材の旨みに引き出す技術を持つ。", "corrected_sentence": "この料理人は、食材の旨みを引き出す技術を持つ。", "error_description": "引き出すの対象（目的語）は「を」で示す。「旨みに」は誤りで、正しくは「旨みを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引き出す", "is_correct": true, "explanation": "辞書形（終止形）。文を言い切る形で、習慣的な事実を述べる文に合う。"}, {"text": "引き出そう", "is_correct": false, "explanation": "意志形になると意志の文となり、事実を述べる文の述語に合わない。"}, {"text": "引き出し", "is_correct": false, "explanation": "連用形は文を言い切れず、「選手の力を最大限に引き出し。」では述語にならない。"}, {"text": "引き出して", "is_correct": false, "explanation": "て形は文を言い切れず、この位置では述語として成立しない。"}], "correct_form": "引き出す", "base_form": "引き出す", "form_label": "終止形（辞書形）", "sentence_index": 1, "explanations": {"引き出す": "辞書形（終止形）。文を言い切る形で、習慣的な事実を述べる文に合う。", "引き出そう": "意志形になると意志の文となり、事実を述べる文の述語に合わない。", "引き出し": "連用形は文を言い切れず、「選手の力を最大限に引き出し。」では述語にならない。", "引き出して": "て形は文を言い切れず、この位置では述語として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、眠っていた実力に引き出せたので、大会で優勝できた。", "corrected_sentence": "彼女は、眠っていた実力を引き出せたので、大会で優勝できた。", "error_description": "「引き出せた」の対象は「を」で示す。「実力に」は誤りで、正しくは「実力を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引き出せた", "is_correct": true, "explanation": "可能形の過去形。「実力を引き出せたので」で、能力を発揮できた結果を表す。"}, {"text": "引き出せなかった", "is_correct": false, "explanation": "可能形の否定過去で、実力を発揮できなかった意味になり、後の「試合に勝てた」と結果が合わない。"}, {"text": "引き出そう", "is_correct": false, "explanation": "意志形は「引き出そうので」と続かず、理由を述べる文が成立しない。"}, {"text": "引き出せ", "is_correct": false, "explanation": "命令・仮定の形で、「引き出せので」と続けられず、理由の文が成立しない。"}], "correct_form": "引き出せた", "base_form": "引き出す", "form_label": "可能形の過去形", "sentence_index": 7, "explanations": {"引き出せた": "可能形の過去形。「実力を引き出せたので」で、能力を発揮できた結果を表す。", "引き出せなかった": "可能形の否定過去で、実力を発揮できなかった意味になり、後の「試合に勝てた」と結果が合わない。", "引き出そう": "意志形は「引き出そうので」と続かず、理由を述べる文が成立しない。", "引き出せ": "命令・仮定の形で、「引き出せので」と続けられず、理由の文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「水飲みとトイレ」で、二つの対象を並べる「と」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「水飲みをトイレのために」は並列の形にならない。「を」は目的語を示すので、ここでは使えない。"}, {"text": "に", "is_correct": false, "explanation": "「水飲みにトイレのために」は成り立たない。「に」は場所や相手を示すので、この位置には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「水飲みへトイレ」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}], "correct_answer": "と", "explanations": {"と": "「水飲みとトイレ」で、二つの対象を並べる「と」が入る。", "を": "「水飲みをトイレのために」は並列の形にならない。「を」は目的語を示すので、ここでは使えない。", "に": "「水飲みにトイレのために」は成り立たない。「に」は場所や相手を示すので、この位置には合わない。", "へ": "「水飲みへトイレ」は意味が通らない。「へ」は方向を示すので、ここには入らない。"}, "error_tags": {"を": "目的語", "に": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水飲みをしておく」で、「水飲み」を行為の目的語として示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「水飲みがしておく」は主語と動詞が合わない。「が」では文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「水飲みにしておく」は成り立たない。「に」は時間や場所を示すので、ここでは使えない。"}, {"text": "から", "is_correct": false, "explanation": "「水飲みからしておく」は意味が通らない。「から」は起点を示すので、この位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「水飲みをしておく」で、「水飲み」を行為の目的語として示す「を」が入る。", "が": "「水飲みがしておく」は主語と動詞が合わない。「が」では文が成立しない。", "に": "「水飲みにしておく」は成り立たない。「に」は時間や場所を示すので、ここでは使えない。", "から": "「水飲みからしておく」は意味が通らない。「から」は起点を示すので、この位置には合わない。"}, "error_tags": {"が": "主語", "に": "時点", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水を飲むことです。", "primary_collocate": null, "pronunciation": "みずのみ", "ipa": "mizɯnomi", "syllable_count": 4, "sentences": [{"text": "走ったあとは、水飲みの量を少しずつ増やすのがよい。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "走[はし]ったあとは、水飲[みずの]みの量[りょう]を少[すこ]しずつ増[ふ]やすのがよい。", "sentence_source": "generated"}, {"text": "休憩時間は水飲みとトイレのために使ってください。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "休憩時間[きゅうけいじかん]は水飲[みずの]みとトイレのために使[つか]ってください。", "sentence_source": "generated"}, {"text": "部活では、十分ごとに短い水飲みの時間がある。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "部活[ぶかつ]では、十分[じゅっぷん]ごとに短[みじか]い水飲[みずの]みの時間[じかん]がある。", "sentence_source": "generated"}, {"text": "暑い日は、こまめな水飲みを忘れないようにしましょう。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、こまめな水飲[みずの]みを忘[わす]れないようにしましょう。", "sentence_source": "generated"}, {"text": "水飲みを控えると、のどがかわいて頭が痛くなる。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "水飲[みずの]みを控[ひか]えると、のどがかわいて頭[あたま]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "子どもたちは、水飲みのために木陰に集まった。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、水飲[みずの]みのために木陰[こかげ]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "試合の途中で水飲みが認められ、選手は一息ついた。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "試合[しあい]の途中[とちゅう]で水飲[みずの]みが認[みと]められ、選手[せんしゅ]は一息[ひといき]ついた。", "sentence_source": "generated"}, {"text": "先生は、授業が始まる前に水飲みをしておくように言った。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "先生[せんせい]は、授業[じゅぎょう]が始[はじ]まる前[まえ]に水飲[みずの]みをしておくように言[い]った。", "sentence_source": "generated"}, {"text": "長い散歩では、水飲みを何度か挟むと楽だ。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "長[なが]い散歩[さんぽ]では、水飲[みずの]みを何度[なんど]か挟[はさ]むと楽[らく]だ。", "sentence_source": "generated"}, {"text": "夜中の水飲みが多いのは、体の病気のしるしかもしれない。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "夜中[よなか]の水飲[みずの]みが多[おお]いのは、体[からだ]の病気[びょうき]のしるしかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水飲み", "label": "基本形"}, {"form": "水飲みの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "水を飲むという行為そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水飲み", "is_correct": true, "explanation": "「水飲みの量を少しずつ増やす」で、水を飲む行為の回数や量を表す。ここに入る語。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の量」は意味が通らない。天気は空の状態を指す。"}, {"text": "靴下", "is_correct": false, "explanation": "「靴下の量を増やす」は文脈に合わない。靴下は身につけるもので、水分補給の話題とは結びつかない。"}, {"text": "出口", "is_correct": false, "explanation": "「出口の量」は成り立たない。出口は場所なので、量を表す語と結びつかない。"}], "explanations": {"水飲み": "「水飲みの量を少しずつ増やす」で、水を飲む行為の回数や量を表す。ここに入る語。", "天気": "「天気の量」は意味が通らない。天気は空の状態を指す。", "靴下": "「靴下の量を増やす」は文脈に合わない。靴下は身につけるもので、水分補給の話題とは結びつかない。", "出口": "「出口の量」は成り立たない。出口は場所なので、量を表す語と結びつかない。"}, "sentence_index": 0, "correct_answer": "水飲み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池で水飲みをして遊んだ。", "explanation": "ここは〈水遊び〉の意味になるはず。「水飲み」は水を飲む行為なので、水の中で遊ぶ意味にはならず、この文には合わない。"}, {"text": "庭の花に毎朝、水飲みをしている。", "explanation": "ここは〈水やり〉の意味になるはず。「水飲み」は飲む行為なので、植物に水を与える意味では使わない。"}, {"text": "彼は毎朝、水飲みを浴びてから出かける。", "explanation": "ここは〈入浴〉の意味になるはず。「水飲み」は水を飲む行為なので、体に浴びる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水飲み", "is_correct": true, "explanation": "「試合の途中で水飲みが認められ」で、試合中に水を飲む行為が許されたことを表す。ここに入る語。"}, {"text": "雨", "is_correct": false, "explanation": "「雨が認められ」は意味が通らない。雨は自然現象で、認められる対象ではない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布が認められ」は文脈に合わない。財布は持ち物なので、試合中の行動の許可とは結びつかない。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車が認められ」は試合の文脈に合わない。自転車は乗り物なので、試合中の行為とは結びつかない。"}], "explanations": {"水飲み": "「試合の途中で水飲みが認められ」で、試合中に水を飲む行為が許されたことを表す。ここに入る語。", "雨": "「雨が認められ」は意味が通らない。雨は自然現象で、認められる対象ではない。", "財布": "「財布が認められ」は文脈に合わない。財布は持ち物なので、試合中の行動の許可とは結びつかない。", "自転車": "「自転車が認められ」は試合の文脈に合わない。自転車は乗り物なので、試合中の行為とは結びつかない。"}, "sentence_index": 6, "correct_answer": "水飲み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この果物は水飲みが多くて、みずみずしい。", "explanation": "ここは〈水分〉の意味になるはず。「水飲み」は水を飲む行為なので、果物に含まれる水分の量を表す語ではない。"}, {"text": "水飲みを食べて、おなかを満たした。", "explanation": "ここは〈食べ物〉の意味。行為の〈水飲み〉は水を飲むことなので、食べるものではない。"}, {"text": "彼は毎晩、水飲みを読んでから眠る。", "explanation": "ここは〈読書〉の意味になるはず。行為の〈水飲み〉は読むものではないので、読書の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中の水飲みで多いと、眠りが浅くなる。", "corrected_sentence": "夜中の水飲みが多いと、眠りが浅くなる。", "error_description": "誤りは「水飲み」の後の助詞。「水飲みが多い」と、主語を示す「が」が必要。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52279, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "レース中に水飲みを認められ、選手は一息ついた。", "corrected_sentence": "レース中に水飲みが認められ、選手は一息ついた。", "error_description": "誤りは「水飲み」の後の助詞。認められるのは「水飲み」なので、主語を示す「が」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「犬用の水飲みを新しいものに取りかえた」で、取りかえる対象の「水飲み」を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「水飲みが新しいものに取りかえた」は主語と目的語の関係が合わない。取りかえる側ではない。"}, {"text": "で", "is_correct": false, "explanation": "「水飲みで新しいものに取りかえた」は意味が通らない。「で」は手段を示すので、ここでは使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「水飲みへ新しいものに取りかえた」は成り立たない。「へ」は方向を示すので、ここには入らない。"}], "correct_answer": "を", "explanations": {"を": "「犬用の水飲みを新しいものに取りかえた」で、取りかえる対象の「水飲み」を示す「を」が入る。", "が": "「水飲みが新しいものに取りかえた」は主語と目的語の関係が合わない。取りかえる側ではない。", "で": "「水飲みで新しいものに取りかえた」は意味が通らない。「で」は手段を示すので、ここでは使えない。", "へ": "「水飲みへ新しいものに取りかえた」は成り立たない。「へ」は方向を示すので、ここには入らない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
