INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物や人が水を飲むための器や設備。", "primary_collocate": null, "pronunciation": "みずのみ", "ipa": "mizɯnomi", "syllable_count": 4, "sentences": [{"text": "庭の水飲みに、朝から小鳥が集まっている。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "庭[にわ]の水飲[みずの]みに、朝[あさ]から小鳥[ことり]が集[あつ]まっている。", "sentence_source": "generated"}, {"text": "犬用の水飲みを新しいものに取りかえた。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "犬用[いぬよう]の水飲[みずの]みを新[あたら]しいものに取[と]りかえた。", "sentence_source": "generated"}, {"text": "公園の水飲みは、夏になると子どもたちで混み合う。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "公園[こうえん]の水飲[みずの]みは、夏[なつ]になると子[こ]どもたちで混[こ]み合[あ]う。", "sentence_source": "generated"}, {"text": "ハムスターのケージに水飲みを取り付けた。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "ハムスターのケージに水飲[みずの]みを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "古い水飲みが割れてしまったので、陶器の物を買った。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "古[ふる]い水飲[みずの]みが割[わ]れてしまったので、陶器[とうき]の物[もの]を買[か]った。", "sentence_source": "generated"}, {"text": "猫は、台所の床に置かれた水飲みから静かに水を飲んでいた。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "猫[ねこ]は、台所[だいどころ]の床[ゆか]に置[お]かれた水飲[みずの]みから静[しず]かに水[みず]を飲[の]んでいた。", "sentence_source": "generated"}, {"text": "水飲みが空になっていたので、すぐに水を足した。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "水飲[みずの]みが空[から]になっていたので、すぐに水[みず]を足[た]した。", "sentence_source": "generated"}, {"text": "校庭の水飲みで、生徒たちが顔を洗っている。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "校庭[こうてい]の水飲[みずの]みで、生徒[せいと]たちが顔[かお]を洗[あら]っている。", "sentence_source": "generated"}, {"text": "旅行中も、ペットの水飲みを持ち歩くようにしている。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "旅行中[りょこうちゅう]も、ペットの水飲[みずの]みを持[も]ち歩[ある]くようにしている。", "sentence_source": "generated"}, {"text": "水飲みの水が凍らないように、冬は温かい場所に置く。", "target_word": "水飲み", "complexity_tier": "T3", "furigana": "水飲[みずの]みの水[みず]が凍[こお]らないように、冬[ふゆ]は温[あたた]かい場所[ばしょ]に置[お]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水飲み", "label": "基本形"}, {"form": "水飲みの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "動物や人が水を飲むための器や設備", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水飲み", "is_correct": true, "explanation": "「庭の水飲みに、朝から小鳥が集まっている」で、水を飲むための器を指す。ここに入る語。"}, {"text": "天気", "is_correct": false, "explanation": "「庭の天気に小鳥が集まる」は意味が通らない。天気は空の状態を指す。"}, {"text": "記録", "is_correct": false, "explanation": "「庭の記録に小鳥が集まる」は成り立たない。記録は記した事柄を指す。"}, {"text": "財布", "is_correct": false, "explanation": "「庭の財布に小鳥が集まる」は意味が通らない。財布は金銭を入れる物なので、庭には置かない。"}], "explanations": {"水飲み": "「庭の水飲みに、朝から小鳥が集まっている」で、水を飲むための器を指す。ここに入る語。", "天気": "「庭の天気に小鳥が集まる」は意味が通らない。天気は空の状態を指す。", "記録": "「庭の記録に小鳥が集まる」は成り立たない。記録は記した事柄を指す。", "財布": "「庭の財布に小鳥が集まる」は意味が通らない。財布は金銭を入れる物なので、庭には置かない。"}, "sentence_index": 0, "correct_answer": "水飲み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ハムスターが、ケージの水飲みを飲んだ。", "explanation": "ここは〈器の中の水〉を飲むという意味になるはず。「水飲み」は器や水を飲む行為を指すので、器そのものを飲むとは言えない。"}, {"text": "ハムスターを水飲みに寝かせた。", "explanation": "ここは〈寝床〉の意味になるはず。「水飲み」は水を飲むための器や場所で、寝かせる場所にはならない。"}, {"text": "夏の日は、水飲みを傘の代わりにさした。", "explanation": "ここは〈傘〉の意味になるはず。「水飲み」は水を飲むための器や場所で、雨や日差しを防ぐ道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水飲み", "is_correct": true, "explanation": "「水飲みが空になっていたので、すぐに水を足した」で、水を入れておく器を指す。ここに入る語。"}, {"text": "天井", "is_correct": false, "explanation": "「天井が空になっていた」は意味が通らない。天井は建物の上の面なので、水を足す対象にならない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便が空になっていた」は成り立たない。郵便は送る仕組みを指すので、水の量とは結びつかない。"}, {"text": "雷", "is_correct": false, "explanation": "「雷が空になっていた」は文脈に合わない。雷は自然現象なので、水を足す対象にはならない。"}], "explanations": {"水飲み": "「水飲みが空になっていたので、すぐに水を足した」で、水を入れておく器を指す。ここに入る語。", "天井": "「天井が空になっていた」は意味が通らない。天井は建物の上の面なので、水を足す対象にならない。", "郵便": "「郵便が空になっていた」は成り立たない。郵便は送る仕組みを指すので、水の量とは結びつかない。", "雷": "「雷が空になっていた」は文脈に合わない。雷は自然現象なので、水を足す対象にはならない。"}, "sentence_index": 6, "correct_answer": "水飲み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達と公園の水飲みで映画を見た。", "explanation": "ここは〈映画館〉の意味になるはず。「水飲み」は水を飲むための場所や道具なので、映画を見る場所にはならない。"}, {"text": "非常時に備えて、水飲みを食べ物として備蓄した。", "explanation": "ここは〈食料〉の意味。器の〈水飲み〉は食べ物ではないので、備蓄の対象にはならない。"}, {"text": "彼は毎晩、水飲みを読んでから眠る。", "explanation": "ここは〈読書〉の意味になるはず。器や場所の〈水飲み〉は読むものではないので、読書の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペットの水飲みで空になっていたので、すぐに水を足した。", "corrected_sentence": "ペットの水飲みが空になっていたので、すぐに水を足した。", "error_description": "誤りは「水飲み」の後の助詞。「空になる」の主語は「水飲み」なので、「が」が必要。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52280, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の水飲みを落ち葉が入った。", "corrected_sentence": "庭の水飲みに落ち葉が入った。", "error_description": "誤りは「水飲み」の後の助詞。「入る」の場所を示すので「に」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
