INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52281, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "心がしっかりしていて、変わらないこと。", "primary_collocate": null, "pronunciation": "ゆるぎない", "ipa": "jɯɾɯɡinai", "syllable_count": 5, "sentences": [{"text": "祖母は、どんな時も揺るぎない心で家族を守った。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、どんな時[とき]も揺[ゆ]るぎない心[こころ]で家族[かぞく]を守[まも]った。", "sentence_source": "generated"}, {"text": "周囲に反対されても、彼の気持ちは揺るぎない。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "周囲[しゅうい]に反対[はんたい]されても、彼[かれ]の気持[きも]ちは揺[ゆ]るぎない。", "sentence_source": "generated"}, {"text": "彼女には、医者になるという揺るぎない志がある。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "彼女[かのじょ]には、医者[いしゃ]になるという揺[ゆ]るぎない志[こころざし]がある。", "sentence_source": "generated"}, {"text": "揺るぎない態度で話す校長先生の言葉に、皆が安心した。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "揺[ゆ]るぎない態度[たいど]で話[はな]す校長[こうちょう]先生[せんせい]の言葉[ことば]に、皆[みな]が安心[あんしん]した。", "sentence_source": "generated"}, {"text": "長い旅を経て、僕の考えは揺るぎないものになった。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]を経[へ]て、僕[ぼく]の考[かんが]えは揺[ゆ]るぎないものになった。", "sentence_source": "generated"}, {"text": "彼は揺るぎない決意を胸に、壇上へ向かった。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "彼[かれ]は揺[ゆ]るぎない決意[けつい]を胸[むね]に、壇上[だんじょう]へ向[む]かった。", "sentence_source": "generated"}, {"text": "親友への信頼は、これからも揺るぎないだろう。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "親友[しんゆう]への信頼[しんらい]は、これからも揺[ゆ]るぎないだろう。", "sentence_source": "generated"}, {"text": "揺るぎない意志があれば、どんな困難も乗り越えられる。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "揺[ゆ]るぎない意志[いし]があれば、どんな困難[こんなん]も乗[の]り越[こ]えられる。", "sentence_source": "generated"}, {"text": "新人ながら、揺るぎない覚悟で大役に臨んだ。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "新人[しんじん]ながら、揺[ゆ]るぎない覚悟[かくご]で大役[たいやく]に臨[のぞ]んだ。", "sentence_source": "generated"}, {"text": "若いころに決めた目標を、彼は今も揺るぎない気持ちで追っている。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "若[わか]いころに決[き]めた目標[もくひょう]を、彼[かれ]は今[いま]も揺[ゆ]るぎない気持[きも]ちで追[お]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揺るぎない", "label": "終止形・連体形"}, {"form": "揺るぎなく", "label": "連用形"}, {"form": "揺るぎなくて", "label": "て形"}, {"form": "揺るぎなかった", "label": "過去形"}, {"form": "揺るぎなければ", "label": "仮定形"}], "register": "やや硬い（書き言葉寄り）", "sense_fingerprint": "心や気持ちがしっかりしていて変わらない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52281, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "連体形。「揺るぎない心」と後ろの名詞を修飾し、心が変わらない様子を表す。"}, {"text": "揺るぎなくて", "is_correct": false, "explanation": "て形は「心」を修飾できず、文が成立しない。"}, {"text": "揺るぎなければ", "is_correct": false, "explanation": "仮定形は「心」を修飾できず、文の流れに合わない。"}, {"text": "揺るぎなさ", "is_correct": false, "explanation": "名詞形は「揺るぎなさ心」では成立せず、「の」が必要になる。"}], "explanations": {"揺るぎない": "連体形。「揺るぎない心」と後ろの名詞を修飾し、心が変わらない様子を表す。", "揺るぎなくて": "て形は「心」を修飾できず、文が成立しない。", "揺るぎなければ": "仮定形は「心」を修飾できず、文の流れに合わない。", "揺るぎなさ": "名詞形は「揺るぎなさ心」では成立せず、「の」が必要になる。"}, "sentence_index": 0, "correct_answer": "揺るぎない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ひとりで留守番をした夜は、揺るぎない夜だった。", "explanation": "ここは〈心細い〉の意味。揺るぎないは心や信念がしっかりして変わらないことで、頼りなく不安な気持ちは表さない。"}, {"text": "彼は揺るぎない汗を流しながら、丘を登った。", "explanation": "ここは〈大量の〉の意味。揺るぎないは心や態度がしっかりして変わらないことで、汗の量には使わない。"}, {"text": "昨夜、揺るぎない地震が町を襲った。", "explanation": "ここは〈激しい〉の意味。揺るぎないは動じない心や態度を表し、揺れの強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52281, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "終止形に「だろう」が続き、「揺るぎないだろう」と推量を表す。"}, {"text": "揺るぎなく", "is_correct": false, "explanation": "連用形は「だろう」に続かず、「揺るぎなくだろう」は成立しない。"}, {"text": "揺るぎなくても", "is_correct": false, "explanation": "譲歩の形は「だろう」に続かず、文が成立しない。"}, {"text": "揺るぎなさそう", "is_correct": false, "explanation": "様態の形は「だろう」の前に置けず、文が成立しない。"}], "explanations": {"揺るぎない": "終止形に「だろう」が続き、「揺るぎないだろう」と推量を表す。", "揺るぎなく": "連用形は「だろう」に続かず、「揺るぎなくだろう」は成立しない。", "揺るぎなくても": "譲歩の形は「だろう」に続かず、文が成立しない。", "揺るぎなさそう": "様態の形は「だろう」の前に置けず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "揺るぎない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は揺るぎない寝癖を直そうと、一時間も鏡の前にいた。", "explanation": "ここは〈ぼさぼさの〉の意味。揺るぎないは心や態度の堅さを表し、髪の乱れには使わない。"}, {"text": "彼は揺るぎない靴を、一日中ぴかぴかに磨いた。", "explanation": "ここは〈ぴかぴかの〉の意味。揺るぎないは心や態度の堅さを表し、磨いて光る靴の状態には使わない。"}, {"text": "まぶしい夕焼けの中で、揺るぎないバスが遠ざかっていった。", "explanation": "ここは〈古びた〉の意味。揺るぎないは心や態度の堅さを表し、車両の古さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52281, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その先生は、揺るぎなさ方針で生徒を導いた。", "corrected_sentence": "その先生は、揺るぎない方針で生徒を導いた。", "error_description": "「揺るぎなさ」は名詞形で、名詞「方針」を直接修飾できない。形容詞の連体形「揺るぎない」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "終止形。「彼の気持ちは揺るぎない。」と述語として文を言い切る形。"}, {"text": "揺るぎなくて", "is_correct": false, "explanation": "て形は文を言い切れず、述語として成立しない。"}, {"text": "揺るぎなければ", "is_correct": false, "explanation": "仮定形は文を言い切れず、「気持ちは揺るぎなければ」では述語にならない。"}, {"text": "揺るぎなさ", "is_correct": false, "explanation": "名詞形は述語として言い切るには「だ」が必要で、この文に合わない。"}], "correct_form": "揺るぎない", "base_form": "揺るぎない", "form_label": "終止形", "sentence_index": 1, "explanations": {"揺るぎない": "終止形。「彼の気持ちは揺るぎない。」と述語として文を言い切る形。", "揺るぎなくて": "て形は文を言い切れず、述語として成立しない。", "揺るぎなければ": "仮定形は文を言い切れず、「気持ちは揺るぎなければ」では述語にならない。", "揺るぎなさ": "名詞形は述語として言い切るには「だ」が必要で、この文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52281, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その子は揺るぎないの気持ちで、練習に打ち込んでいる。", "corrected_sentence": "その子は揺るぎない気持ちで、練習に打ち込んでいる。", "error_description": "連体形「揺るぎない」の直後に「の」を付けるのは誤り。「揺るぎない気持ち」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "連体形。「揺るぎない意志」と名詞を修飾する形。"}, {"text": "揺るぎなくても", "is_correct": false, "explanation": "譲歩の形は「意志」を修飾できず、文が成立しない。"}, {"text": "揺るぎなかろう", "is_correct": false, "explanation": "文語の推量形は「意志」を修飾できず、文が成立しない。"}, {"text": "揺るぎなさそう", "is_correct": false, "explanation": "様態の形は「意志」を修飾できず、文が成立しない。"}], "correct_form": "揺るぎない", "base_form": "揺るぎない", "form_label": "連体形", "sentence_index": 7, "explanations": {"揺るぎない": "連体形。「揺るぎない意志」と名詞を修飾する形。", "揺るぎなくても": "譲歩の形は「意志」を修飾できず、文が成立しない。", "揺るぎなかろう": "文語の推量形は「意志」を修飾できず、文が成立しない。", "揺るぎなさそう": "様態の形は「意志」を修飾できず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
