INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52282, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何があっても動かない、しっかりとした様子。信念や態度が強く、揺れないこと。", "primary_collocate": null, "pronunciation": "ゆるぎない", "ipa": "jɯɾɯɡinai", "syllable_count": 5, "sentences": [{"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "揺るぎない", "complexity_tier": "T4", "furigana": "単[ただ]なるパンを焼[や]き上[あ]げるという行為[こうい]の域[いき]を超[こ]え、そこには古[いにしえ]の製法[せいほう]への畏敬[いけい]の念[ねん]と、素材[そざい]の潜在能力[せんざいのうりょく]を限界[げんかい]まで引[ひ]き出[だ]そうとする職人[しょくにん]としての揺[ゆ]るぎない覚悟[かくご]が、静[しず]かに宿[やど]っていたのである。", "sentence_source": "mined"}, {"text": "彼は揺るぎない自信を持って、舞台に立った。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "彼[かれ]は揺[ゆ]るぎない自信[じしん]を持[も]って、舞台[ぶたい]に立[た]った。", "sentence_source": "generated"}, {"text": "二人の間には、揺るぎない信頼がある。", "target_word": "揺るぎない", "complexity_tier": "T2", "furigana": "二人[ふたり]の間[あいだ]には、揺[ゆ]るぎない信頼[しんらい]がある。", "sentence_source": "generated"}, {"text": "長年の努力が、彼女の地位を揺るぎないものにした。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "長年[ながねん]の努力[どりょく]が、彼女[かのじょ]の地位[ちい]を揺[ゆ]るぎないものにした。", "sentence_source": "generated"}, {"text": "失敗しても夢をあきらめない、揺るぎない決意があった。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても夢[ゆめ]をあきらめない、揺[ゆ]るぎない決意[けつい]があった。", "sentence_source": "generated"}, {"text": "この会社は業界で揺るぎない地位を築いている。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は業界[ぎょうかい]で揺[ゆ]るぎない地位[ちい]を築[きず]いている。", "sentence_source": "generated"}, {"text": "証拠がそろい、彼の無実は揺るぎない事実となった。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "証拠[しょうこ]がそろい、彼[かれ]の無実[むじつ]は揺[ゆ]るぎない事実[じじつ]となった。", "sentence_source": "generated"}, {"text": "揺るぎない信念を持つ人は、周りの意見に流されない。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "揺[ゆ]るぎない信念[しんねん]を持[も]つ人[ひと]は、周[まわ]りの意見[いけん]に流[なが]されない。", "sentence_source": "generated"}, {"text": "優勝した今、チームの強さは揺るぎないと言える。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]した今[いま]、チームの強[つよ]さは揺[ゆ]るぎないと言[い]える。", "sentence_source": "generated"}, {"text": "母の揺るぎない愛情に支えられて、私は育った。", "target_word": "揺るぎない", "complexity_tier": "T3", "furigana": "母[はは]の揺[ゆ]るぎない愛情[あいじょう]に支[ささ]えられて、私[わたし]は育[そだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揺るぎない", "label": "終止形・連体形"}, {"form": "揺るぎなく", "label": "連用形"}, {"form": "揺るぎなくて", "label": "て形"}, {"form": "揺るぎなかった", "label": "過去形"}, {"form": "揺るぎなければ", "label": "仮定形"}], "register": "やや硬い（書き言葉寄り）", "sense_fingerprint": "信念・地位・態度などが何があっても動じず、しっかりしている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e1d971-3fc5-423b-a5a3-a36d95e5b57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "連体形。後ろの「覚悟」を修飾し、「職人としての揺るぎない覚悟」と続く。"}, {"text": "揺るぎなくて", "is_correct": false, "explanation": "て形は「覚悟」を修飾できず、名詞句が成立しない。"}, {"text": "揺るぎなければ", "is_correct": false, "explanation": "仮定形は「覚悟」を修飾できず、文の流れに合わない。"}, {"text": "揺るぎなさ", "is_correct": false, "explanation": "名詞形は「揺るぎなさ覚悟」では成立せず、「の」が必要になる。"}], "explanations": {"揺るぎない": "連体形。後ろの「覚悟」を修飾し、「職人としての揺るぎない覚悟」と続く。", "揺るぎなくて": "て形は「覚悟」を修飾できず、名詞句が成立しない。", "揺るぎなければ": "仮定形は「覚悟」を修飾できず、文の流れに合わない。", "揺るぎなさ": "名詞形は「揺るぎなさ覚悟」では成立せず、「の」が必要になる。"}, "sentence_index": 0, "correct_answer": "揺るぎない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その夜、窓の外では揺るぎない時間が静かに流れていた。", "explanation": "ここは〈ゆったりとした〉の意味。揺るぎないは信念や態度の堅さを表し、時間の流れには使わない。"}, {"text": "彼女は、揺るぎない涙を流し続けた。", "explanation": "ここは〈止めどない〉の意味。揺るぎないは心や態度の堅さを表し、涙の量や勢いには使わない。"}, {"text": "隣の部屋は、夜中ずっと揺るぎない。", "explanation": "ここは〈騒々しい〉の意味。揺るぎないは動じない心や態度に使い、物音の大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揺るぎない", "is_correct": true, "explanation": "連体形。「揺るぎない事実」と後ろの名詞を修飾し、「事実となった」と続く。"}, {"text": "揺るぎなくても", "is_correct": false, "explanation": "譲歩の形は「事実」を修飾できず、「揺るぎなくても事実となった」は文が成立しない。"}, {"text": "揺るぎなかろう", "is_correct": false, "explanation": "文語の推量形は名詞「事実」を修飾できず、文が成立しない。"}, {"text": "揺るぎなさそう", "is_correct": false, "explanation": "様態の形は「事実」を修飾できず、「揺るぎなさそう事実」は成立しない。"}], "explanations": {"揺るぎない": "連体形。「揺るぎない事実」と後ろの名詞を修飾し、「事実となった」と続く。", "揺るぎなくても": "譲歩の形は「事実」を修飾できず、「揺るぎなくても事実となった」は文が成立しない。", "揺るぎなかろう": "文語の推量形は名詞「事実」を修飾できず、文が成立しない。", "揺るぎなさそう": "様態の形は「事実」を修飾できず、「揺るぎなさそう事実」は成立しない。"}, "sentence_index": 6, "correct_answer": "揺るぎない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、揺るぎない服装で舞台に立った。", "explanation": "ここは〈派手な〉の意味。揺るぎないは信念や態度の堅さを表し、服装の華やかさには使わない。"}, {"text": "彼は、揺るぎない失敗で試験に落ちた。", "explanation": "ここは〈うっかりした〉の意味。揺るぎないは動かない心や態度を表し、不注意による失敗には使わない。"}, {"text": "彼は、揺るぎない卵をそっと割ってフライパンに落とした。", "explanation": "ここは〈もろい〉の意味。揺るぎないは動じずしっかりしている意味で、壊れやすさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca137c0f-b673-4f99-8a05-fbf2279db1c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
