INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52283, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかにはない、とくべつなこと。", "primary_collocate": null, "pronunciation": "どくとく", "ipa": "dokɯtokɯ", "syllable_count": 4, "sentences": [{"text": "この地方には独特の風習が残っている。", "target_word": "独特", "complexity_tier": "T3", "furigana": "この地方(ちほう)には独特(どくとく)の風習(ふうしゅう)が残(のこ)っている。", "sentence_source": "generated"}, {"text": "彼は独特な雰囲気を持っていて、すぐに目立つ。", "target_word": "独特", "complexity_tier": "T3", "furigana": "彼(かれ)は独特(どくとく)な雰囲気(ふんいき)を持(も)っていて、すぐに目立(めだ)つ。", "sentence_source": "generated"}, {"text": "古い町並みが独特の美しさを生んでいる。", "target_word": "独特", "complexity_tier": "T3", "furigana": "古(ふる)い町並(まちな)みが独特(どくとく)の美(うつく)しさを生(う)んでいる。", "sentence_source": "generated"}, {"text": "あの歌手の声は独特で、誰にもまねができない。", "target_word": "独特", "complexity_tier": "T3", "furigana": "あの歌手(かしゅ)の声(こえ)は独特(どくとく)で、誰(だれ)にもまねができない。", "sentence_source": "generated"}, {"text": "外国の料理は、日本とは違う独特の味付けだ。", "target_word": "独特", "complexity_tier": "T3", "furigana": "外国(がいこく)の料理(りょうり)は、日本(にほん)とは違(ちが)う独特(どくとく)の味付(あじつ)けだ。", "sentence_source": "generated"}, {"text": "この絵には、作者独特の色づかいが見られる。", "target_word": "独特", "complexity_tier": "T3", "furigana": "この絵(え)には、作者(さくしゃ)独特(どくとく)の色(いろ)づかいが見(み)られる。", "sentence_source": "generated"}, {"text": "彼女の笑い方は独特で、周りの人まで笑顔になる。", "target_word": "独特", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の笑(わら)い方(かた)は独特(どくとく)で、周(まわ)りの人(ひと)まで笑顔(えがお)になる。", "sentence_source": "generated"}, {"text": "民族衣装の独特な模様に、観光客が足を止めた。", "target_word": "独特", "complexity_tier": "T3", "furigana": "民族(みんぞく)衣装(いしょう)の独特(どくとく)な模様(もよう)に、観光客(かんこうきゃく)が足(あし)を止(と)めた。", "sentence_source": "generated"}, {"text": "この楽器は独特の音色を持っている。", "target_word": "独特", "complexity_tier": "T3", "furigana": "この楽器(がっき)は独特(どくとく)の音色(ねいろ)を持(も)っている。", "sentence_source": "generated"}, {"text": "雪国には、雪国独特の暮らしの知恵がある。", "target_word": "独特", "complexity_tier": "T3", "furigana": "雪国(ゆきぐに)には、雪国(ゆきぐに)独特(どくとく)の暮(く)らしの知恵(ちえ)がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独特だ", "label": "終止形"}, {"form": "独特な", "label": "連体形"}, {"form": "独特の", "label": "連体修飾（の）"}, {"form": "独特で", "label": "連用形"}], "register": "neutral (標準的な書き言葉)", "sense_fingerprint": "ほかのものにはない、そのものだけの特別さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 色づか (Zipf 1.64)']::text[], '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52283, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "「独特の風習」は、その地方にしかない特有の習わしを表し、文の意味に合う。"}, {"text": "明朗", "is_correct": false, "explanation": "明朗は明るくはっきりしたさまを表すので、風習の性質には合わない。"}, {"text": "頑強", "is_correct": false, "explanation": "頑強は丈夫で強いさまを表すので、習わしを表す語としては合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかは落ち着いたさまを表すので、「穏やかの風習」とは言えない。"}], "explanations": {"独特": "「独特の風習」は、その地方にしかない特有の習わしを表し、文の意味に合う。", "明朗": "明朗は明るくはっきりしたさまを表すので、風習の性質には合わない。", "頑強": "頑強は丈夫で強いさまを表すので、習わしを表す語としては合わない。", "穏やか": "穏やかは落ち着いたさまを表すので、「穏やかの風習」とは言えない。"}, "sentence_index": 0, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の演奏は独特で、どの楽団でも聴ける同じ曲目だった。", "explanation": "独特は他にない特有さを表すので、どの楽団でも同じ曲目という内容とは矛盾する。"}, {"text": "この部屋は独特で、どこの家にも同じものがある。", "explanation": "独特は他にない特有さを表すので、どこの家にも同じものがあるという内容とは矛盾する。"}, {"text": "この料理は独特で、どこの店でも同じ味がする。", "explanation": "独特は他にない特有さを表すので、どこの店でも同じ味だという内容とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52283, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "「独特で」は他にない特徴的な笑い方を表し、周りが笑顔になるという文脈に合う。"}, {"text": "厳格", "is_correct": false, "explanation": "厳格は規則を厳しく守るさまを表すので、笑い方の説明には合わない。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は物音がなく静かなさまを表すので、笑い方の性質には使わない。"}, {"text": "軽薄", "is_correct": false, "explanation": "軽薄は真剣さに欠けるさまを表すので、周りを笑顔にするという文脈とは意味が合わない。"}], "explanations": {"独特": "「独特で」は他にない特徴的な笑い方を表し、周りが笑顔になるという文脈に合う。", "厳格": "厳格は規則を厳しく守るさまを表すので、笑い方の説明には合わない。", "静粛": "静粛は物音がなく静かなさまを表すので、笑い方の性質には使わない。", "軽薄": "軽薄は真剣さに欠けるさまを表すので、周りを笑顔にするという文脈とは意味が合わない。"}, "sentence_index": 6, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の散歩で出会った鳥は独特で、町中どこでも見られる鳥だった。", "explanation": "独特は他にない特有さを表すので、町中どこでも見られるという内容とは矛盾する。"}, {"text": "この作品は独特で、千人も同じものを持っている。", "explanation": "独特は他にないことを表すので、千人が同じものを持つという内容とは矛盾する。"}, {"text": "この部品は独特で、どの製品にも同じように使われる。", "explanation": "独特は他と違う特有さを指すので、どの製品にも同じように使われるという内容とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52283, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この絵の色づかいは独特の、誰にも真似できない。", "corrected_sentence": "この絵の色づかいは独特で、誰にも真似できない。", "error_description": "「独特の」は名詞の前でしか使えず、文の途中で切ることはできない。文を続けるときは連用形「で」を使う。「独特の、」は誤りで、正しくは「独特で、」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "独特だ", "is_correct": false, "explanation": "終止形。名詞の前に直接置けないので、「雰囲気」を修飾できない。"}, {"text": "独特な", "is_correct": true, "explanation": "連体形。名詞「雰囲気」を修飾する形で、この文の答え。"}, {"text": "独特だろう", "is_correct": false, "explanation": "推量の形で言い切る形。名詞「雰囲気」の前には置けないので入らない。"}, {"text": "独特で", "is_correct": false, "explanation": "連用形。文を続ける形で、名詞の前に置いて修飾することはできない。"}], "correct_form": "独特な", "base_form": "独特だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"独特だ": "終止形。名詞の前に直接置けないので、「雰囲気」を修飾できない。", "独特な": "連体形。名詞「雰囲気」を修飾する形で、この文の答え。", "独特だろう": "推量の形で言い切る形。名詞「雰囲気」の前には置けないので入らない。", "独特で": "連用形。文を続ける形で、名詞の前に置いて修飾することはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52283, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村の祭りは独特くて、一度見る価値がある。", "corrected_sentence": "この村の祭りは独特で、一度見る価値がある。", "error_description": "独特は形容動詞なので「くて」は付かない。文を続けるときは連用形「で」を使う。「独特くて、」は誤りで、正しくは「独特で、」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "独特に", "is_correct": false, "explanation": "「に」で終わる副詞的な形。名詞「模様」を直接修飾できないので合わない。"}, {"text": "独特な", "is_correct": true, "explanation": "連体形。名詞「模様」を修飾する形で、この文の答え。"}, {"text": "独特だろう", "is_correct": false, "explanation": "推量の形で文を言い切る形。名詞「模様」の前には置けない。"}, {"text": "独特だったら", "is_correct": false, "explanation": "仮定の条件の形。名詞を修飾しないので、「模様」の前には入らない。"}], "correct_form": "独特な", "base_form": "独特だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"独特に": "「に」で終わる副詞的な形。名詞「模様」を直接修飾できないので合わない。", "独特な": "連体形。名詞「模様」を修飾する形で、この文の答え。", "独特だろう": "推量の形で文を言い切る形。名詞「模様」の前には置けない。", "独特だったら": "仮定の条件の形。名詞を修飾しないので、「模様」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
