INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52284, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他にはない、特有の性質を持っているさま。", "primary_collocate": null, "pronunciation": "どくとく", "ipa": "dokɯtokɯ", "syllable_count": 4, "sentences": [{"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "独特", "complexity_tier": "T4", "furigana": "数日(すうじつ)かけて培養(ばいよう)されたルヴァン種(しゅ)は、独特(どくとく)の酸味(さんみ)と芳醇(ほうじゅん)な香(かお)りを纏(まと)い、パンの骨格(こっかく)を形成(けいせい)する。", "sentence_source": "mined"}, {"text": "この店のカレーは独特の香りがあって、一度食べると忘れられない。", "target_word": "独特", "complexity_tier": "T3", "furigana": "この店(みせ)のカレーは独特(どくとく)の香(かお)りがあって、一度(いちど)食(た)べると忘(わす)れられない。", "sentence_source": "generated"}, {"text": "彼女は独特な感性を持ち、他の人と違う絵を描く。", "target_word": "独特", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は独特(どくとく)な感性(かんせい)を持(も)ち、他(ほか)の人(ひと)と違(ちが)う絵(え)を描(えが)く。", "sentence_source": "generated"}, {"text": "京都には、他の町にはない独特の雰囲気がある。", "target_word": "独特", "complexity_tier": "T3", "furigana": "京都(きょうと)には、他(ほか)の町(まち)にはない独特(どくとく)の雰囲気(ふんいき)がある。", "sentence_source": "generated"}, {"text": "沖縄の方言は独特で、他の地方の人にはなかなか分からない。", "target_word": "独特", "complexity_tier": "T3", "furigana": "沖縄(おきなわ)の方言(ほうげん)は独特(どくとく)で、他(ほか)の地方(ちほう)の人(ひと)にはなかなか分(わ)からない。", "sentence_source": "generated"}, {"text": "その作家は独特の文体で知られている。", "target_word": "独特", "complexity_tier": "T3", "furigana": "その作家(さっか)は独特(どくとく)の文体(ぶんたい)で知(し)られている。", "sentence_source": "generated"}, {"text": "この果物は独特な味がするので、好き嫌いが分かれる。", "target_word": "独特", "complexity_tier": "T3", "furigana": "この果物(くだもの)は独特(どくとく)な味(あじ)がするので、好(す)き嫌(きら)いが分(わ)かれる。", "sentence_source": "generated"}, {"text": "祖父は独特のリズムで太鼓をたたく。", "target_word": "独特", "complexity_tier": "T3", "furigana": "祖父(そふ)は独特(どくとく)のリズムで太鼓(たいこ)をたたく。", "sentence_source": "generated"}, {"text": "納豆の独特のにおいが苦手な外国人は多い。", "target_word": "独特", "complexity_tier": "T3", "furigana": "納豆(なっとう)の独特(どくとく)のにおいが苦手(にがて)な外国人(がいこくじん)は多(おお)い。", "sentence_source": "generated"}, {"text": "彼の話し方は独特で、一度聞くとすぐに彼だと分かる。", "target_word": "独特", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はな)し方(かた)は独特(どくとく)で、一度(いちど)聞(き)くとすぐに彼(かれ)だと分(わ)かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独特だ", "label": "終止形"}, {"form": "独特な", "label": "連体形"}, {"form": "独特の", "label": "連体修飾（の）"}, {"form": "独特で", "label": "連用形"}], "register": "neutral (標準的な書き言葉)", "sense_fingerprint": "そのものだけが持つ特有の性質があるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)']::text[], '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52284, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "「独特の」は他にない特徴を表し、酸味と香りの性質を説明できるので、この空欄に入る。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は壊れにくく丈夫なさまを表すので、酸味の性質を説明する語としては合わない。"}, {"text": "静か", "is_correct": false, "explanation": "静かは音や動きが穏やかなさまを表すので、味の特徴には使えない。"}, {"text": "明確", "is_correct": false, "explanation": "明確は内容がはっきりしているさまを表すので、「明確の酸味」とは言わない。"}], "explanations": {"独特": "「独特の」は他にない特徴を表し、酸味と香りの性質を説明できるので、この空欄に入る。", "頑丈": "頑丈は壊れにくく丈夫なさまを表すので、酸味の性質を説明する語としては合わない。", "静か": "静かは音や動きが穏やかなさまを表すので、味の特徴には使えない。", "明確": "明確は内容がはっきりしているさまを表すので、「明確の酸味」とは言わない。"}, "sentence_index": 0, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は独特の筋書きで、どの作品にもあるよくある展開ばかりだ。", "explanation": "独特は他にない特徴を指すので、よくある展開だという内容とは矛盾して合わない。"}, {"text": "この資料は独特で、どの先生の資料とも同じ内容だ。", "explanation": "独特は他にない特有さを表すので、どの資料とも同じ内容だという説明とは矛盾する。"}, {"text": "誰もが毎日口にする、独特の主食がある。", "explanation": "独特は他にない特有さを指すので、誰もが口にするという内容とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52284, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "「独特な味」は他にない特徴的な味を表し、好き嫌いが分かれる理由として自然につながる。"}, {"text": "華麗", "is_correct": false, "explanation": "華麗は美しく華やかなさまを表すので、味の説明には合わない。"}, {"text": "平穏", "is_correct": false, "explanation": "平穏は波立たず穏やかなさまを表すので、味の特徴を表さない。"}, {"text": "柔軟", "is_correct": false, "explanation": "柔軟は状況に応じて変えられるさまを表すので、味の性質には使わない。"}], "explanations": {"独特": "「独特な味」は他にない特徴的な味を表し、好き嫌いが分かれる理由として自然につながる。", "華麗": "華麗は美しく華やかなさまを表すので、味の説明には合わない。", "平穏": "平穏は波立たず穏やかなさまを表すので、味の特徴を表さない。", "柔軟": "柔軟は状況に応じて変えられるさまを表すので、味の性質には使わない。"}, "sentence_index": 6, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の散歩で出会った花は独特で、どこの庭にも咲いている花だった。", "explanation": "独特は他にない特有さを表すので、どこの庭にもあるという内容とは矛盾する。"}, {"text": "この二つの品は独特で、まったく変わらない品物だ。", "explanation": "独特は他にないことを表すので、まったく変わらない品物だという内容とは矛盾する。"}, {"text": "この規格は独特で、業界の誰もが同じように従う。", "explanation": "独特は他と違う特有さを指すので、誰もが同じように従うという内容とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52284, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の味は独特を、一度食べたら忘れられない。", "corrected_sentence": "この店の味は独特で、一度食べたら忘れられない。", "error_description": "独特は形状詞なので「を」は付かない。文を続けるときは連用形「で」を使う。「独特を」は誤りで、正しくは「独特で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "独特だ", "is_correct": false, "explanation": "終止形。名詞の前に直接置けないので、「香り」を修飾できない。"}, {"text": "独特だろう", "is_correct": false, "explanation": "推量の形で言い切る形。名詞「香り」の前には置けないので入らない。"}, {"text": "独特の", "is_correct": true, "explanation": "連体修飾の「の」。名詞「香り」を修飾する形として正しい。"}, {"text": "独特で", "is_correct": false, "explanation": "連用形。文を続ける形で、名詞の前に置いて修飾することはできない。"}], "correct_form": "独特の", "base_form": "独特だ", "form_label": "連体修飾（の）", "sentence_index": 1, "explanations": {"独特だ": "終止形。名詞の前に直接置けないので、「香り」を修飾できない。", "独特だろう": "推量の形で言い切る形。名詞「香り」の前には置けないので入らない。", "独特の": "連体修飾の「の」。名詞「香り」を修飾する形として正しい。", "独特で": "連用形。文を続ける形で、名詞の前に置いて修飾することはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52284, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の声は独特が、一度聞いたら忘れられない。", "corrected_sentence": "彼女の声は独特で、一度聞いたら忘れられない。", "error_description": "独特は形状詞なので主語を表す「が」は付けられない。述語として続けるときは「で」を使う。「独特が」は誤りで、正しくは「独特で」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "独特だし", "is_correct": false, "explanation": "接続の形で、名詞「リズム」の前に置いて修飾することはできない。"}, {"text": "独特なら", "is_correct": false, "explanation": "仮定の条件の形で、名詞「リズム」を直接修飾しないので入らない。"}, {"text": "独特の", "is_correct": true, "explanation": "連体修飾の「の」。名詞「リズム」を修飾する形として正しい。"}, {"text": "独特だったら", "is_correct": false, "explanation": "仮定の条件の形。名詞を修飾する形ではないので、「リズム」の前には入らない。"}], "correct_form": "独特の", "base_form": "独特だ", "form_label": "連体修飾（の）", "sentence_index": 7, "explanations": {"独特だし": "接続の形で、名詞「リズム」の前に置いて修飾することはできない。", "独特なら": "仮定の条件の形で、名詞「リズム」を直接修飾しないので入らない。", "独特の": "連体修飾の「の」。名詞「リズム」を修飾する形として正しい。", "独特だったら": "仮定の条件の形。名詞を修飾する形ではないので、「リズム」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
