INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "いいにおいのことです。", "primary_collocate": null, "pronunciation": "かおり", "ipa": "kaoɾi", "syllable_count": 3, "sentences": [{"text": "このせっけんは、花のいい香りがします。", "target_word": "香り", "complexity_tier": "T3", "furigana": "このせっけんは、花(はな)のいい香(かお)りがします。", "sentence_source": "generated"}, {"text": "朝、台所からコーヒーの香りがしてきました。", "target_word": "香り", "complexity_tier": "T3", "furigana": "朝(あさ)、台所(だいどころ)からコーヒーの香(かお)りがしてきました。", "sentence_source": "generated"}, {"text": "公園のバラは、とてもいい香りです。", "target_word": "香り", "complexity_tier": "T3", "furigana": "公園(こうえん)のバラは、とてもいい香(かお)りです。", "sentence_source": "generated"}, {"text": "母がパンを焼くと、家じゅうに香りが広がります。", "target_word": "香り", "complexity_tier": "T3", "furigana": "母(はは)がパンを焼(や)くと、家(いえ)じゅうに香(かお)りが広(ひろ)がります。", "sentence_source": "generated"}, {"text": "私はレモンの香りのお茶が好きです。", "target_word": "香り", "complexity_tier": "T3", "furigana": "私(わたし)はレモンの香(かお)りのお茶(ちゃ)が好(す)きです。", "sentence_source": "generated"}, {"text": "花屋に入ると、花の香りで気持ちがよくなりました。", "target_word": "香り", "complexity_tier": "T3", "furigana": "花屋(はなや)に入(はい)ると、花(はな)の香(かお)りで気持(きも)ちがよくなりました。", "sentence_source": "generated"}, {"text": "森を歩くと、木の香りがして、ほっとします。", "target_word": "香り", "complexity_tier": "T3", "furigana": "森(もり)を歩(ある)くと、木(き)の香(かお)りがして、ほっとします。", "sentence_source": "generated"}, {"text": "このシャンプーは、香りがやさしくて人気があります。", "target_word": "香り", "complexity_tier": "T3", "furigana": "このシャンプーは、香(かお)りがやさしくて人気(にんき)があります。", "sentence_source": "generated"}, {"text": "春には、庭に梅の香りが漂います。", "target_word": "香り", "complexity_tier": "T3", "furigana": "春(はる)には、庭(にわ)に梅(うめ)の香(かお)りが漂(ただよ)います。", "sentence_source": "generated"}, {"text": "店の前を通ると、焼き魚の香りがして、おなかがすきました。", "target_word": "香り", "complexity_tier": "T3", "furigana": "店(みせ)の前(まえ)を通(とお)ると、焼(や)き魚(ざかな)の香(かお)りがして、おなかがすきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "香り", "label": "基本形（名詞）"}], "register": "polite (丁寧体)", "sense_fingerprint": "花や食べ物などのいいにおい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52285, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香り", "is_correct": true, "explanation": "「花のいい香りがします」は、せっけんの心地よいにおいを表し、文に合う。"}, {"text": "音色", "is_correct": false, "explanation": "音色は聞いて感じる響きを指すので、においには使えない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は見た目の色合いを指すので、においを表さない。"}, {"text": "形", "is_correct": false, "explanation": "形は見た目の形状を指すので、においの説明には合わない。"}], "explanations": {"香り": "「花のいい香りがします」は、せっけんの心地よいにおいを表し、文に合う。", "音色": "音色は聞いて感じる響きを指すので、においには使えない。", "色彩": "色彩は見た目の色合いを指すので、においを表さない。", "形": "形は見た目の形状を指すので、においの説明には合わない。"}, "sentence_index": 0, "correct_answer": "香り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この石は香りが硬くて、ひびが入っている。", "explanation": "香りには硬さがないので、硬くてひびが入っているという説明には合わない。"}, {"text": "鐘の香りが広がります。", "explanation": "香りは嗅いで感じるもので、鐘の香りが広がるという表現は成り立たない。"}, {"text": "鍋の香りが熱くて、やけどしそうです。", "explanation": "香りには温度がないので、熱くてやけどしそうだという説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52285, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香り", "is_correct": true, "explanation": "「木の香りがして」は、森の中のにおいを表し、ほっとする文脈に合う。"}, {"text": "光", "is_correct": false, "explanation": "光は視覚で感じるもので、「木の光がして」とは言わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は感触や量を表すもので、木の性質を説明する語としては合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天候を表すので、木のにおいを説明する語としては合わない。"}], "explanations": {"香り": "「木の香りがして」は、森の中のにおいを表し、ほっとする文脈に合う。", "光": "光は視覚で感じるもので、「木の光がして」とは言わない。", "砂": "砂は感触や量を表すもので、木の性質を説明する語としては合わない。", "雨": "雨は天候を表すので、木のにおいを説明する語としては合わない。"}, "sentence_index": 6, "correct_answer": "香り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は香りが十キロあります。", "explanation": "香りには重さがないので、重さを数える文には使えない。"}, {"text": "この香りは丸くて、角がないのです。", "explanation": "香りには形がないので、丸くて角がないという説明には合わない。"}, {"text": "この部屋は香りが十畳です。", "explanation": "香りには広さがないので、大きさを示す文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52285, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はバラの香りを好きです。", "corrected_sentence": "私はバラの香りが好きです。", "error_description": "「好き」は「が」を取る形容動詞なので、「香りを」は誤り。正しくは「香りが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52285, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けると、お線香の香りに流れてきました。", "corrected_sentence": "窓を開けると、お線香の香りが流れてきました。", "error_description": "「流れる」は主語を「が」で示すので、「香りに」は誤り。正しくは「香りが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
