INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52286, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物が持つ、良い感じのにおい。嗅いで心地よいと感じられる気体の性質。", "primary_collocate": null, "pronunciation": "かおり", "ipa": "kaoɾi", "syllable_count": 3, "sentences": [{"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "香り", "complexity_tier": "T4", "furigana": "数日(すうじつ)かけて培養(ばいよう)されたルヴァン種(しゅ)は、独特(どくとく)の酸味(さんみ)と芳醇(ほうじゅん)な香(かお)りを纏(まと)い、パンの骨格(こっかく)を形成(けいせい)する。", "sentence_source": "mined"}, {"text": "庭のバラから甘い香りがただよってくる。", "target_word": "香り", "complexity_tier": "T3", "furigana": "庭(にわ)のバラから甘(あま)い香(かお)りがただよってくる。", "sentence_source": "generated"}, {"text": "焼きたてのパンの香りが、台所いっぱいに広がった。", "target_word": "香り", "complexity_tier": "T3", "furigana": "焼(や)きたてのパンの香(かお)りが、台所(だいどころ)いっぱいに広(ひろ)がった。", "sentence_source": "generated"}, {"text": "このお茶は、香りがよくて心が落ち着く。", "target_word": "香り", "complexity_tier": "T3", "furigana": "このお茶(ちゃ)は、香(かお)りがよくて心(こころ)が落(お)ち着(つ)く。", "sentence_source": "generated"}, {"text": "春になると、梅の香りが道ばたまで届く。", "target_word": "香り", "complexity_tier": "T3", "furigana": "春(はる)になると、梅(うめ)の香(かお)りが道(みち)ばたまで届(とど)く。", "sentence_source": "generated"}, {"text": "母は、お風呂に好きな花の香りの入浴剤を入れた。", "target_word": "香り", "complexity_tier": "T3", "furigana": "母(はは)は、お風呂(ふろ)に好(す)きな花(はな)の香(かお)りの入浴剤(にゅうよくざい)を入(い)れた。", "sentence_source": "generated"}, {"text": "コーヒー豆を挽くと、豊かな香りが立ちのぼる。", "target_word": "香り", "complexity_tier": "T3", "furigana": "コーヒー豆(まめ)を挽(ひ)くと、豊(ゆた)かな香(かお)りが立(た)ちのぼる。", "sentence_source": "generated"}, {"text": "森の中は、木の香りがして気持ちがいい。", "target_word": "香り", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)は、木(き)の香(かお)りがして気持(きも)ちがいい。", "sentence_source": "generated"}, {"text": "洗いたてのシャツから、石けんの香りがした。", "target_word": "香り", "complexity_tier": "T3", "furigana": "洗(あら)いたてのシャツから、石(せっ)けんの香(かお)りがした。", "sentence_source": "generated"}, {"text": "秋の夜、窓を開けると金木犀の香りが入ってきた。", "target_word": "香り", "complexity_tier": "T3", "furigana": "秋(あき)の夜(よる)、窓(まど)を開(あ)けると金木犀(きんもくせい)の香(かお)りが入(はい)ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "香り", "label": "基本形（名詞）"}], "register": "neutral (標準的な書き言葉)", "sense_fingerprint": "花・食べ物・飲み物などが放つ心地よいにおい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 培養 (Zipf 3.6), ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)','sentence 1 above tier T2: contains vocabulary far above tier T2: ただよっ (Zipf 1.83)','sentence 4 above tier T2: contains vocabulary far above tier T2: 道ばた (Zipf 2.25)','sentence 6 above tier T2: contains vocabulary far above tier T2: 挽く (Zipf 2.01), 立ちのぼる (Zipf 1.21)','sentence 8 above tier T2: contains vocabulary far above tier T2: 洗いたて (Zipf 1.5)','sentence 9 above tier T2: contains vocabulary far above tier T2: 金木犀 (Zipf 2.38)']::text[], '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52286, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香り", "is_correct": true, "explanation": "「芳醇な香りを纏い」は、パンの豊かなにおいを表し、文の意味に合う。"}, {"text": "光", "is_correct": false, "explanation": "光は視覚で感じるもので、「芳醇な光」とは言わない。"}, {"text": "音", "is_correct": false, "explanation": "音は聞いて感じるもので、芳醇という語とは結びつかない。"}, {"text": "熱", "is_correct": false, "explanation": "熱は温度を表すので、「芳醇な熱」という組み合わせは不自然で合わない。"}], "explanations": {"香り": "「芳醇な香りを纏い」は、パンの豊かなにおいを表し、文の意味に合う。", "光": "光は視覚で感じるもので、「芳醇な光」とは言わない。", "音": "音は聞いて感じるもので、芳醇という語とは結びつかない。", "熱": "熱は温度を表すので、「芳醇な熱」という組み合わせは不自然で合わない。"}, "sentence_index": 0, "correct_answer": "香り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この石の香りは冷たくて、手が凍りそうだ。", "explanation": "香りには温度がないので、冷たくて手が凍りそうだという説明には合わない。"}, {"text": "風の香りが聞こえた。", "explanation": "香りは嗅いで感じるもので、聞こえるものではないので合わない。"}, {"text": "夕日の香りが差し込んだ。", "explanation": "香りは嗅覚で感じるもので、差し込むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52286, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香り", "is_correct": true, "explanation": "「豊かな香りが立ちのぼる」は、コーヒーのにおいが広がる様子を表し、文の意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "色は立ちのぼるものではなく、「豊かな色」という文脈にも合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "歌声は立ちのぼるものではなく、コーヒーの場面には合わない。"}, {"text": "輝き", "is_correct": false, "explanation": "輝きは光の性質を指し、立ちのぼるという動きとは合わない。"}], "explanations": {"香り": "「豊かな香りが立ちのぼる」は、コーヒーのにおいが広がる様子を表し、文の意味に合う。", "色": "色は立ちのぼるものではなく、「豊かな色」という文脈にも合わない。", "歌声": "歌声は立ちのぼるものではなく、コーヒーの場面には合わない。", "輝き": "輝きは光の性質を指し、立ちのぼるという動きとは合わない。"}, "sentence_index": 6, "correct_answer": "香り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店の香りは四角くて、角ばった箱のようだ。", "explanation": "香りには形がないので、四角くて角ばった箱のようだという説明には合わない。"}, {"text": "この布は香りがなめらかだ。", "explanation": "香りには触れて感じる性質がないので、なめらかさの説明には合わない。"}, {"text": "この箱は香りが五キロある。", "explanation": "香りには重さがないので、五キロあるという説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52286, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭のバラは甘い香りに放っている。", "corrected_sentence": "庭のバラは甘い香りを放っている。", "error_description": "「放つ」は「を」を取る他動詞なので、「香りに」は誤り。正しくは「香りを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52286, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の香りで包まれて、心が落ち着いた。", "corrected_sentence": "森の香りに包まれて、心が落ち着いた。", "error_description": "「包まれる」は「に」を取るので、「香りで」は誤り。正しくは「香りに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。強い意志が主語として宿るという動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉。宿るは対象を取らない自動詞なので、意志を宿るとは言えない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の〈で〉。意志で宿るは意味が通らず、主語を示す位置に合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の〈と〉。意志と宿るは相手を伴う意味になり、文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。強い意志が主語として宿るという動作の主体を示す。", "を": "目的語の〈を〉。宿るは対象を取らない自動詞なので、意志を宿るとは言えない。", "で": "手段・場所の〈で〉。意志で宿るは意味が通らず、主語を示す位置に合わない。", "と": "共同・引用の〈と〉。意志と宿るは相手を伴う意味になり、文脈に合わない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。説得力が主語として宿るという動作の主体を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の〈へ〉。宿るは方向に向かう動きではないので、説得力へ宿るは意味が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉。説得力より宿るは比べる文になり、この文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の〈の〉。説得力の宿っているは名詞修飾として続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。説得力が主語として宿るという動作の主体を示す。", "へ": "方向の〈へ〉。宿るは方向に向かう動きではないので、説得力へ宿るは意味が成り立たない。", "より": "比較の〈より〉。説得力より宿るは比べる文になり、この文脈に合わない。", "の": "連体修飾の〈の〉。説得力の宿っているは名詞修飾として続かず、文が成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものの中に、こころやちからがあります。", "primary_collocate": null, "pronunciation": "やどる", "ipa": "jadoɾɯ", "syllable_count": 3, "sentences": [{"text": "この大木には、古くから神様が宿ると信じられている。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "この大木[たいぼく]には、古[ふる]くから神様[かみさま]が宿[やど]ると信[しん]じられている。", "sentence_source": "generated"}, {"text": "彼女の瞳には、強い意志が宿っていた。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の瞳[ひとみ]には、強[つよ]い意志[いし]が宿[やど]っていた。", "sentence_source": "generated"}, {"text": "使い込んだ道具には、職人の魂が宿る。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "使[つか]い込[こ]んだ道具[どうぐ]には、職人[しょくにん]の魂[たましい]が宿[やど]る。", "sentence_source": "generated"}, {"text": "小さな体にも、大きな力が宿っている。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "小[ちい]さな体[からだ]にも、大[おお]きな力[ちから]が宿[やど]っている。", "sentence_source": "generated"}, {"text": "この古い寺には、長い歴史の重みが宿っている。", "target_word": "宿っている", "complexity_tier": "T3", "furigana": "この古[ふる]い寺[てら]には、長[なが]い歴史[れきし]の重[おも]みが宿[やど]っている。", "sentence_source": "generated"}, {"text": "古い町並みには、人々の暮らしの温かさが宿っている。", "target_word": "宿っている", "complexity_tier": "T3", "furigana": "古[ふる]い町並[まちな]みには、人々[ひとびと]の暮[く]らしの温[あたた]かさが宿[やど]っている。", "sentence_source": "generated"}, {"text": "人形に心が宿るという話は、多くの国にある。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "人形[にんぎょう]に心[こころ]が宿[やど]るという話[はなし]は、多[おお]くの国[くに]にある。", "sentence_source": "generated"}, {"text": "彼の言葉には、不思議な説得力が宿っている。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]には、不思議[ふしぎ]な説得力[せっとくりょく]が宿[やど]っている。", "sentence_source": "generated"}, {"text": "古い鏡には、持ち主の思いが宿ると言われる。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "古[ふる]い鏡[かがみ]には、持[も]ち主[ぬし]の思[おも]いが宿[やど]ると言[い]われる。", "sentence_source": "generated"}, {"text": "子どもの笑顔に、未来への希望が宿っていた。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "子[こ]どもの笑顔[えがお]に、未来[みらい]への希望[きぼう]が宿[やど]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿る", "label": "終止形"}, {"form": "宿り", "label": "連用形"}, {"form": "宿った", "label": "過去形"}, {"form": "宿って", "label": "て形"}, {"form": "宿らない", "label": "否定形"}, {"form": "宿れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものの内部に心や力などが存在してとどまる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a4dea8e-685c-41d4-a9dd-b76eb411f0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿る", "is_correct": true, "explanation": "正解。神様などが大木の内にとどまる意味で、「〜と信じられている」と自然につながる。"}, {"text": "踊る", "is_correct": false, "explanation": "踊るは体を動かして舞う意味。神様が踊ると信じられているとは言えず、内にとどまる意味にならない。"}, {"text": "散る", "is_correct": false, "explanation": "散るは花や葉がばらばらに離れ落ちる意味。神様が散ると言っても文の内容が成り立たない。"}, {"text": "流れる", "is_correct": false, "explanation": "流れるは水や時間が移動する意味。神様が大木の中を流れるとすると、とどまる意味の文脈に合わない。"}], "explanations": {"宿る": "正解。神様などが大木の内にとどまる意味で、「〜と信じられている」と自然につながる。", "踊る": "踊るは体を動かして舞う意味。神様が踊ると信じられているとは言えず、内にとどまる意味にならない。", "散る": "散るは花や葉がばらばらに離れ落ちる意味。神様が散ると言っても文の内容が成り立たない。", "流れる": "流れるは水や時間が移動する意味。神様が大木の中を流れるとすると、とどまる意味の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "宿る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱には、大切な書類が宿っている。", "explanation": "ここは〈中に収まっている〉の意味で、収めるが適切。宿るは心やちからがものにとどまる意味なので、書類のような物品の収納には使わない。"}, {"text": "岩陰には、小さな魚が宿っている。", "explanation": "ここは〈身を隠してじっとしている〉の意味で、潜むが適切。宿るは心や力の存在を言う語なので、生き物が身をひそめる場面には合わない。"}, {"text": "この一年が、あっという間に宿った。", "explanation": "ここは〈時が過ぎる〉の意味で、過ぎるが適切。宿るは心やちからがものにとどまる意味なので、時間の経過には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿る", "is_correct": true, "explanation": "正解。心が人形などのものの内にとどまる意味で、文の内容に合う。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "泳ぐは水中を進む動き。心が泳ぐとは言わず、ものにとどまる意味にならない。"}, {"text": "転がる", "is_correct": false, "explanation": "転がるは物が回って移動する意味。心が転がると言うと文が不自然になる。"}, {"text": "這う", "is_correct": false, "explanation": "這うは体を地につけて進む動き。心が這うとは言えず、文の意味に合わない。"}], "explanations": {"宿る": "正解。心が人形などのものの内にとどまる意味で、文の内容に合う。", "泳ぐ": "泳ぐは水中を進む動き。心が泳ぐとは言わず、ものにとどまる意味にならない。", "転がる": "転がるは物が回って移動する意味。心が転がると言うと文が不自然になる。", "這う": "這うは体を地につけて進む動き。心が這うとは言えず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "宿る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この工場では、昨夜、大きな事故が宿った。", "explanation": "ここは〈出来事が起こる〉の意味で、生じるが適切。宿るは心や力がものにとどまる意味なので、事故のような出来事には使わない。"}, {"text": "床には、割れた皿の破片が宿っていた。", "explanation": "ここは〈広がって散らばる〉の意味で、散らばるが適切。宿るは心や力の存在に使うので、破片が床に散る場面には合わない。"}, {"text": "湖の底には、古い船の残骸が宿っている。", "explanation": "ここは〈水底に沈んでいる〉の意味で、沈むが適切。宿るは心やちからの存在を言う語なので、残骸が水底にある場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その古い剣には、先祖の魂を宿っている。", "corrected_sentence": "その古い剣には、先祖の魂が宿っている。", "error_description": "助詞の誤り。宿るは〈魂が〉のように〈が〉で主語を示す自動詞なので、〈を〉は使えない。正しくは〈が〉。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "宿っ", "is_correct": true, "explanation": "正解。文中の「宿っていた」の「宿っ」部分で、過去の状態を表す。"}, {"text": "宿る", "is_correct": false, "explanation": "基本形。「〜ていた」に続けるには促音形の「宿っ」が必要で、ここには基本形は入らない。"}, {"text": "宿らない", "is_correct": false, "explanation": "否定形。意志が宿っていた事実を述べる文なので、宿らなかったという否定の内容は合わない。"}, {"text": "宿れば", "is_correct": false, "explanation": "仮定形。条件を表す形で、宿っていたという既成の事実を述べる文には合わない。"}], "correct_form": "宿っ", "base_form": "宿る", "form_label": "〜ていた（過去の状態）", "sentence_index": 1, "explanations": {"宿っ": "正解。文中の「宿っていた」の「宿っ」部分で、過去の状態を表す。", "宿る": "基本形。「〜ていた」に続けるには促音形の「宿っ」が必要で、ここには基本形は入らない。", "宿らない": "否定形。意志が宿っていた事実を述べる文なので、宿らなかったという否定の内容は合わない。", "宿れば": "仮定形。条件を表す形で、宿っていたという既成の事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52287, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父の古い時計には、長い年月の思い出が宿れている。", "corrected_sentence": "祖父の古い時計には、長い年月の思い出が宿っている。", "error_description": "活用の誤り。宿れは命令形で、〈ている〉は続かない。正しくは促音形の〈宿っている〉。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "宿っ", "is_correct": true, "explanation": "正解。「〜ている」（現在の状態）の前の促音形で、ここに入る。"}, {"text": "宿り", "is_correct": false, "explanation": "連用形。「〜ている」の前に置くと「宿りている」となり、この文では成り立たない。"}, {"text": "宿った", "is_correct": false, "explanation": "過去形。「〜ている」の前に置くと「宿ったている」となり、この位置では成り立たない。"}, {"text": "宿って", "is_correct": false, "explanation": "て形。後ろの「ている」と重なるため、「宿ってている」となり不自然になる。"}], "correct_form": "宿っ", "base_form": "宿る", "form_label": "〜ている（現在の状態）", "sentence_index": 7, "explanations": {"宿っ": "正解。「〜ている」（現在の状態）の前の促音形で、ここに入る。", "宿り": "連用形。「〜ている」の前に置くと「宿りている」となり、この文では成り立たない。", "宿った": "過去形。「〜ている」の前に置くと「宿ったている」となり、この位置では成り立たない。", "宿って": "て形。後ろの「ている」と重なるため、「宿ってている」となり不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f77dfd3-7adb-4101-b22a-94fb8627af12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
