INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「完成した」の主語を示す「が」。骨格が完成したので正しい"}, {"text": "に", "is_correct": false, "explanation": "「骨格に完成」は対象と結びつかず、文が成立しない"}, {"text": "へ", "is_correct": false, "explanation": "「骨格へ完成」は方向の意味になり、文が成立しない"}, {"text": "より", "is_correct": false, "explanation": "「骨格より完成」は比較の意味になり、文脈に合わない"}], "correct_answer": "が", "explanations": {"が": "「完成した」の主語を示す「が」。骨格が完成したので正しい", "に": "「骨格に完成」は対象と結びつかず、文が成立しない", "へ": "「骨格へ完成」は方向の意味になり、文が成立しない", "より": "「骨格より完成」は比較の意味になり、文脈に合わない"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの形を支える大事な部分のこと。", "primary_collocate": null, "pronunciation": "こっかく", "ipa": "kokkakɯ", "syllable_count": 4, "sentences": [{"text": "この模型は、細い金属の骨格に紙を貼って作ってある。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "この模型[もけい]は、細[ほそ]い金属[きんぞく]の骨格[こっかく]に紙[かみ]を貼[は]って作[つく]ってある。", "sentence_source": "generated"}, {"text": "粘土で像を作るときは、まず針金で骨格を作ってから粘土をつける。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "粘土[ねんど]で像[ぞう]を作[つく]るときは、まず針金[はりがね]で骨格[こっかく]を作[つく]ってから粘土[ねんど]をつける。", "sentence_source": "generated"}, {"text": "家の骨格にあたる柱と梁が先に組み上がった。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "家[いえ]の骨格[こっかく]にあたる柱[はしら]と梁[はり]が先[さき]に組[く]み上[あ]がった。", "sentence_source": "generated"}, {"text": "鳥の骨格は軽く作られているので、空を飛ぶことができる。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "鳥[とり]の骨格[こっかく]は軽[かる]く作[つく]られているので、空[そら]を飛[と]ぶことができる。", "sentence_source": "generated"}, {"text": "ロボットの骨格は軽い合金でできていて、とても丈夫だ。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "ロボットの骨格[こっかく]は軽[かる]い合金[ごうきん]でできていて、とても丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "彫刻家は、人形の骨格を先に作り、その上に布を巻いていった。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "彫刻家[ちょうこくか]は、人形[にんぎょう]の骨格[こっかく]を先[さき]に作[つく]り、その上[うえ]に布[ぬの]を巻[ま]いていった。", "sentence_source": "generated"}, {"text": "魚の骨格を図鑑で調べて、体のつくりがよくわかった。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "魚[さかな]の骨格[こっかく]を図鑑[ずかん]で調[しら]べて、体[からだ]のつくりがよくわかった。", "sentence_source": "generated"}, {"text": "橋の骨格が完成したので、次は道路を敷く工事が始まる。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "橋[はし]の骨格[こっかく]が完成[かんせい]したので、次[つぎ]は道路[どうろ]を敷[し]く工事[こうじ]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "この車は、骨格が強いので、事故のときも中の人を守りやすい。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "この車[くるま]は、骨格[こっかく]が強[つよ]いので、事故[じこ]のときも中[なか]の人[ひと]を守[まも]りやすい。", "sentence_source": "generated"}, {"text": "凧は竹の骨格に紙を張って作る。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "凧[たこ]は竹[たけ]の骨格[こっかく]に紙[かみ]を張[は]って作[つく]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "骨格", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物の形を内側から支える芯や土台となる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骨格", "is_correct": true, "explanation": "「金属の骨格に紙を貼る」で、模型の芯となる部分の意味に合う"}, {"text": "色彩", "is_correct": false, "explanation": "金属の色彩に紙を貼るとは言わず、芯の意味にならない"}, {"text": "音色", "is_correct": false, "explanation": "金属の音色に紙を貼るのは意味が通らない"}, {"text": "香り", "is_correct": false, "explanation": "金属の香りに紙を貼るのは不自然"}], "explanations": {"骨格": "「金属の骨格に紙を貼る」で、模型の芯となる部分の意味に合う", "色彩": "金属の色彩に紙を貼るとは言わず、芯の意味にならない", "音色": "金属の音色に紙を貼るのは意味が通らない", "香り": "金属の香りに紙を貼るのは不自然"}, "sentence_index": 0, "correct_answer": "骨格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このろうそくは骨格が甘く、部屋中に広がる。", "explanation": "ここは〈香り〉の意味。骨格は内側の支えなので、香りの甘さには使わない"}, {"text": "この箱は骨格が派手で、店でよく目立つ。", "explanation": "ここは〈外装〉（表面の包み）の意味。骨格は内側の支えなので、派手さや見た目には合わない"}, {"text": "この布は骨格が高く、一着に予算がかかる。", "explanation": "ここは〈価格〉の意味。骨格は構造を指すので、値段の高さには使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骨格", "is_correct": true, "explanation": "「魚の骨格を図鑑で調べる」で、体のつくりの意味に合う"}, {"text": "手触り", "is_correct": false, "explanation": "魚の手触りを図鑑で調べても体のつくりはわからず、文脈に合わない"}, {"text": "響き", "is_correct": false, "explanation": "魚の響きを図鑑で調べるのは不自然で、体のつくりに合わない"}, {"text": "歌声", "is_correct": false, "explanation": "魚には歌声がなく、図鑑で調べる対象にならない"}], "explanations": {"骨格": "「魚の骨格を図鑑で調べる」で、体のつくりの意味に合う", "手触り": "魚の手触りを図鑑で調べても体のつくりはわからず、文脈に合わない", "響き": "魚の響きを図鑑で調べるのは不自然で、体のつくりに合わない", "歌声": "魚には歌声がなく、図鑑で調べる対象にならない"}, "sentence_index": 6, "correct_answer": "骨格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "焼きたてのパンは香りと骨格を楽しめる。", "explanation": "ここは〈風味〉（味わい）の意味。骨格は形を支える部分で、味わうものではない"}, {"text": "この楽器は骨格が澄んでいる。", "explanation": "ここは〈音〉の意味。骨格は構造を指すので、澄んだ響きには使わない"}, {"text": "このワンピースは骨格が鮮やかだ。", "explanation": "ここは〈色〉の意味。骨格は見えない内部の支えなので、鮮やかさには使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この模型は骨格が針金で組んでいる。", "corrected_sentence": "この模型は骨格が針金で組まれている。", "error_description": "骨格を主語にするなら受身の「組まれている」が正しい。能動の「組んでいる」は骨格が組み立てる主体になり、不自然", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52289, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この船は骨格を軽いので、速く進める。", "corrected_sentence": "この船は骨格が軽いので、速く進める。", "error_description": "「軽い」は主語（骨格）に「が」を取る形容詞。「を」では不自然", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「定める」の目的語を示す「を」。制度の骨格を定めるので正しい"}, {"text": "は", "is_correct": false, "explanation": "連体節の主語には「は」を使えず、「定めた」の修飾が成立しない"}, {"text": "に", "is_correct": false, "explanation": "「骨格に定める」は対象を示す形として不自然"}, {"text": "へ", "is_correct": false, "explanation": "「定める」の対象は「を」で示す。「へ」では方向となり文が成立しない"}], "correct_answer": "を", "explanations": {"を": "「定める」の目的語を示す「を」。制度の骨格を定めるので正しい", "は": "連体節の主語には「は」を使えず、「定めた」の修飾が成立しない", "に": "「骨格に定める」は対象を示す形として不自然", "へ": "「定める」の対象は「を」で示す。「へ」では方向となり文が成立しない"}, "error_tags": {"を": "目的語", "は": "主題（連体節で不可）", "に": "対象・方向", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「となる」の「と」で、骨格が主張の基になる関係を示す"}, {"text": "を", "is_correct": false, "explanation": "「骨格をなる」は目的語を取る形ではなく、文が成立しない"}, {"text": "で", "is_correct": false, "explanation": "「骨格でなる」は手段の意味になり、「なる」と合わない"}, {"text": "まで", "is_correct": false, "explanation": "「まで」は程度や限界を示し、「骨格まで（主張が）なる」は成立しない"}], "correct_answer": "と", "explanations": {"と": "「となる」の「と」で、骨格が主張の基になる関係を示す", "を": "「骨格をなる」は目的語を取る形ではなく、文が成立しない", "で": "「骨格でなる」は手段の意味になり、「なる」と合わない", "まで": "「まで」は程度や限界を示し、「骨格まで（主張が）なる」は成立しない"}, "error_tags": {"と": "変化・内容", "を": "目的語", "で": "手段・場所", "まで": "程度・限界"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人体や物事の、全体を支える基本的な構造や枠組み。", "primary_collocate": null, "pronunciation": "こっかく", "ipa": "kokkakɯ", "syllable_count": 4, "sentences": [{"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "数日[すうじつ]かけて培養[ばいよう]されたルヴァン種[しゅ]は、独特[どくとく]の酸味[さんみ]と芳醇[ほうじゅん]な香[かお]りを纏[まと]い、パンの骨格[こっかく]を形成[けいせい]する。", "sentence_source": "mined"}, {"text": "この法律は、制度全体の骨格を定めたもので、細かい規則は後から作られる。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "この法律[ほうりつ]は、制度[せいど]全体[ぜんたい]の骨格[こっかく]を定[さだ]めたもので、細[こま]かい規則[きそく]は後[あと]から作[つく]られる。", "sentence_source": "generated"}, {"text": "彼女は骨格がしっかりしているので、どんな服でも美しく着こなせる。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は骨格[こっかく]がしっかりしているので、どんな服[ふく]でも美[うつく]しく着[き]こなせる。", "sentence_source": "generated"}, {"text": "医師はレントゲン写真を見て、子どもの骨格に異常がないことを確かめた。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "医師[いし]はレントゲン写真[しゃしん]を見[み]て、子[こ]どもの骨格[こっかく]に異常[いじょう]がないことを確[たし]かめた。", "sentence_source": "generated"}, {"text": "小説の骨格ができてから、登場人物の細かい性格を考えることにした。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の骨格[こっかく]ができてから、登場[とうじょう]人物[じんぶつ]の細[こま]かい性格[せいかく]を考[かんが]えることにした。", "sentence_source": "generated"}, {"text": "古い建物だが、骨格は丈夫なので、内装を直せばまだ十分に使える。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]だが、骨格[こっかく]は丈夫[じょうぶ]なので、内装[ないそう]を直[なお]せばまだ十分[じゅうぶん]に使[つか]える。", "sentence_source": "generated"}, {"text": "この計画は骨格だけを示したもので、予算などはまだ決まっていない。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "この計画[けいかく]は骨格[こっかく]だけを示[しめ]したもので、予算[よさん]などはまだ決[き]まっていない。", "sentence_source": "generated"}, {"text": "論文の骨格となる主張を、最初の段落で短くまとめた。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "論文[ろんぶん]の骨格[こっかく]となる主張[しゅちょう]を、最初[さいしょ]の段落[だんらく]で短[みじか]くまとめた。", "sentence_source": "generated"}, {"text": "日本人と欧米人では、顔の骨格に少し違いがある。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "日本人[にほんじん]と欧米人[おうべいじん]では、顔[かお]の骨格[こっかく]に少[すこ]し違[ちが]いがある。", "sentence_source": "generated"}, {"text": "恐竜の骨格が発見され、その大きさに研究者たちも驚いた。", "target_word": "骨格", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]の骨格[こっかく]が発見[はっけん]され、その大[おお]きさに研究者[けんきゅうしゃ]たちも驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "骨格", "label": "基本形"}], "register": "標準", "sense_fingerprint": "人体や計画・文章などの全体を支える基本構造・枠組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)']::text[], 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骨格", "is_correct": true, "explanation": "「パンの骨格を形成する」で、全体を支える基本構造の意味に合う"}, {"text": "原料", "is_correct": false, "explanation": "原料は材料のことで、「パンの原料を形成する」とは言えず文が通らない"}, {"text": "香料", "is_correct": false, "explanation": "香料は香りづけの材料で、形成する対象の構造にはならない"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は工程の名前で、「パンの発酵を形成する」は不自然"}], "explanations": {"骨格": "「パンの骨格を形成する」で、全体を支える基本構造の意味に合う", "原料": "原料は材料のことで、「パンの原料を形成する」とは言えず文が通らない", "香料": "香料は香りづけの材料で、形成する対象の構造にはならない", "発酵": "発酵は工程の名前で、「パンの発酵を形成する」は不自然"}, "sentence_index": 0, "correct_answer": "骨格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この列車は骨格が速く、予定より早く着く。", "explanation": "ここは〈速さ〉の意味。骨格は構造を指すので、速度の速さには使わない"}, {"text": "この教室は骨格が多く、生徒が集まる。", "explanation": "ここは〈人数〉の意味。骨格は構造を指すので、数の多さには使わない"}, {"text": "この料理は骨格が豊かで、食欲をそそる。", "explanation": "ここは〈香り〉の意味。骨格は構造を指すので、香りの豊かさには使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骨格", "is_correct": true, "explanation": "「骨格だけを示した」で、計画の全体の枠組みを示す意味に合う"}, {"text": "体温", "is_correct": false, "explanation": "計画には体温がなく、「体温だけを示した」は文脈に合わない"}, {"text": "発音", "is_correct": false, "explanation": "計画には発音がなく、「発音だけを示した」は不自然"}, {"text": "香り", "is_correct": false, "explanation": "計画には香りがなく、「香りだけを示した」は文脈が通らない"}], "explanations": {"骨格": "「骨格だけを示した」で、計画の全体の枠組みを示す意味に合う", "体温": "計画には体温がなく、「体温だけを示した」は文脈に合わない", "発音": "計画には発音がなく、「発音だけを示した」は不自然", "香り": "計画には香りがなく、「香りだけを示した」は文脈が通らない"}, "sentence_index": 6, "correct_answer": "骨格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本は骨格が濃く、何度読んでも発見がある。", "explanation": "ここは〈中身〉（内容の充実）の意味。骨格は構造を指すので、内容の濃さには使えない"}, {"text": "店は骨格が落ち着いていて、長居したくなる。", "explanation": "ここは〈雰囲気〉の意味。骨格は構造を指すので、空間の感じには使えない"}, {"text": "読後の骨格を友人に話した。", "explanation": "ここは〈感想〉の意味。骨格は構造を指すので、読んだ後の感じ方には使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計画は、事業全体の骨格に示すものだ。", "corrected_sentence": "この計画は、事業全体の骨格を示すものだ。", "error_description": "「示す」は目的語に「を」を取る。「骨格に示す」は誤りで、「を」が正しい", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52290, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年度の事業計画の骨格を固まった。", "corrected_sentence": "来年度の事業計画の骨格が固まった。", "error_description": "「固まる」は主語（骨格）に「が」を取る自動詞。「を」では不自然", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高温", "is_correct": true, "explanation": "低温の対義語で、温度が高い状態を表す"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の温度で、低温の対義語ではない"}, {"text": "室温", "is_correct": false, "explanation": "室温は部屋の温度で、低温の対義語の関係にはない"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度で、低温の対義語の関係にはない"}], "correct_answer": "高温", "explanations": {"高温": "低温の対義語で、温度が高い状態を表す", "体温": "体温は人の体の温度で、低温の対義語ではない", "室温": "室温は部屋の温度で、低温の対義語の関係にはない", "気温": "気温は空気の温度で、低温の対義語の関係にはない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
