INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "とても低い温度のことです。", "primary_collocate": null, "pronunciation": "ていおん", "ipa": "teːoɴ", "syllable_count": 4, "sentences": [{"text": "北極は低温が続き、夏でも氷がほとんど溶けない。", "target_word": "低温", "complexity_tier": "T3", "furigana": "北極[ほっきょく]は低温[ていおん]が続[つづ]き、夏[なつ]でも氷[こおり]がほとんど溶[と]けない。", "sentence_source": "generated"}, {"text": "低温のせいで、車のエンジンがなかなかかからなかった。", "target_word": "低温", "complexity_tier": "T3", "furigana": "低温[ていおん]のせいで、車[くるま]のエンジンがなかなかかからなかった。", "sentence_source": "generated"}, {"text": "今年の冬は低温の日が多く、水道管が凍ってしまった。", "target_word": "低温", "complexity_tier": "T3", "furigana": "今年[ことし]の冬[ふゆ]は低温[ていおん]の日[ひ]が多[おお]く、水道管[すいどうかん]が凍[こお]ってしまった。", "sentence_source": "generated"}, {"text": "低温が続いたため、田んぼの稲の成長が遅れた。", "target_word": "低温", "complexity_tier": "T3", "furigana": "低温[ていおん]が続[つづ]いたため、田[た]んぼの稲[いね]の成長[せいちょう]が遅[おく]れた。", "sentence_source": "generated"}, {"text": "液体窒素はとても低温なので、素手でさわると危ない。", "target_word": "低温", "complexity_tier": "T3", "furigana": "液体[えきたい]窒素[ちっそ]はとても低温[ていおん]なので、素手[すで]でさわると危[あぶ]ない。", "sentence_source": "generated"}, {"text": "低温に弱い植物は、冬になると家の中に入れる。", "target_word": "低温", "complexity_tier": "T3", "furigana": "低温[ていおん]に弱[よわ]い植物[しょくぶつ]は、冬[ふゆ]になると家[いえ]の中[なか]に入[い]れる。", "sentence_source": "generated"}, {"text": "山の上は低温で、夏でも上着が必要だった。", "target_word": "低温", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は低温[ていおん]で、夏[なつ]でも上着[うわぎ]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "低温の屋外では、スマートフォンの電池がすぐなくなる。", "target_word": "低温", "complexity_tier": "T3", "furigana": "低温[ていおん]の屋外[おくがい]では、スマートフォンの電池[でんち]がすぐなくなる。", "sentence_source": "generated"}, {"text": "低温の水に長く入っていると、体に悪い。", "target_word": "低温", "complexity_tier": "T3", "furigana": "低温[ていおん]の水[みず]に長[なが]く入[はい]っていると、体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "この地方は低温の影響で、果物の収穫が少なかった。", "target_word": "低温", "complexity_tier": "T3", "furigana": "この地方[ちほう]は低温[ていおん]の影響[えいきょう]で、果物[くだもの]の収穫[しゅうかく]が少[すく]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低温", "label": "基本形"}], "register": "標準", "sense_fingerprint": "気候や環境の、かなり低い気温・温度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低温", "is_correct": true, "explanation": "「低温が続き」で、気候として低い温度が続く意味に合う"}, {"text": "光線", "is_correct": false, "explanation": "「光線が続き」は意味が通らず、北極の気候を表せない"}, {"text": "音量", "is_correct": false, "explanation": "「音量が続き」は文脈に合わない"}, {"text": "色合い", "is_correct": false, "explanation": "「色合いが続き」は不自然で、気温の状態を表さない"}], "explanations": {"低温": "「低温が続き」で、気候として低い温度が続く意味に合う", "光線": "「光線が続き」は意味が通らず、北極の気候を表せない", "音量": "「音量が続き」は文脈に合わない", "色合い": "「色合いが続き」は不自然で、気温の状態を表さない"}, "sentence_index": 0, "correct_answer": "低温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドローンは低温で飛び、地面すれすれを進む。", "explanation": "ここは〈低空〉（低い高度）の意味。低温は温度なので、飛ぶ高さには使わない"}, {"text": "景気が低温で、新規の仕事が減っている。", "explanation": "ここは〈低調〉（振るわない様子）の意味。低温は温度の状態なので、景気の勢いには使わない"}, {"text": "あの店員は低温で、客に笑顔を見せない。", "explanation": "ここは〈冷淡〉（人への冷たい態度）の意味。低温は温度なので、人の態度には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低温", "is_correct": true, "explanation": "「山の上は低温で」で、気温が低いという意味に合う"}, {"text": "深夜", "is_correct": false, "explanation": "「山の上は深夜で」は意味が通らず、気温を表さない"}, {"text": "中庭", "is_correct": false, "explanation": "「山の上は中庭で」は場所として不自然で、気温の文脈に合わない"}, {"text": "玄関", "is_correct": false, "explanation": "「山の上は玄関で」は文が成立せず、気温を表さない"}], "explanations": {"低温": "「山の上は低温で」で、気温が低いという意味に合う", "深夜": "「山の上は深夜で」は意味が通らず、気温を表さない", "中庭": "「山の上は中庭で」は場所として不自然で、気温の文脈に合わない", "玄関": "「山の上は玄関で」は文が成立せず、気温を表さない"}, "sentence_index": 6, "correct_answer": "低温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアンプは低温の周波数を強めて、重い音を出す。", "explanation": "ここは〈低域〉（低い周波数の帯域）の意味。低温は温度なので、周波数には使わない"}, {"text": "彼女は低温に判断を下して、冷静さを保った。", "explanation": "ここは〈冷静〉（落ち着いている様子）の意味。低温は温度なので、判断の仕方には使わない"}, {"text": "会議で低温の姿勢を示し、同僚の意見を尊重した。", "explanation": "ここは〈低姿勢〉（へりくだる態度）の意味。低温は温度の状態なので、人の態度には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北極は低温を続くため、夏でも雪が解けにくい。", "corrected_sentence": "北極は低温が続くため、夏でも雪が解けにくい。", "error_description": "「続く」の主語は「低温が」。「を」では不自然", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "標高が高い地域は低温でなりやすい。", "corrected_sentence": "標高が高い地域は低温になりやすい。", "error_description": "「なる」は変化の先を「に」で示す。「で」では不自然", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高温", "is_correct": true, "explanation": "低温の対義語で、温度が高い状態を表す"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の温度で、低温の対義語ではない"}, {"text": "室温", "is_correct": false, "explanation": "室温は部屋の温度で、低温の対義語の関係にはない"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度で、低温の対義語の関係にはない"}], "correct_answer": "高温", "explanations": {"高温": "低温の対義語で、温度が高い状態を表す", "体温": "体温は人の体の温度で、低温の対義語ではない", "室温": "室温は部屋の温度で、低温の対義語の関係にはない", "気温": "気温は空気の温度で、低温の対義語の関係にはない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
