INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "周囲よりも温度が低い状態。特に、冷蔵庫や冷凍庫の中のような冷たい温度を指すことが多い。", "primary_collocate": null, "pronunciation": "ていおん", "ipa": "teːoɴ", "syllable_count": 4, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "低温", "complexity_tier": "T3", "furigana": "その後[そのご]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "肉は低温で保存しないと、すぐに傷んでしまう。", "target_word": "低温", "complexity_tier": "T3", "furigana": "肉[にく]は低温[ていおん]で保存[ほぞん]しないと、すぐに傷[いた]んでしまう。", "sentence_source": "generated"}, {"text": "冷蔵庫の中は低温なので、夏でも牛乳が長持ちする。", "target_word": "低温", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]は低温[ていおん]なので、夏[なつ]でも牛乳[ぎゅうにゅう]が長持[ながも]ちする。", "sentence_source": "generated"}, {"text": "このチョコレートは低温の場所に置かないと、溶けてしまう。", "target_word": "低温", "complexity_tier": "T3", "furigana": "このチョコレートは低温[ていおん]の場所[ばしょ]に置[お]かないと、溶[と]けてしまう。", "sentence_source": "generated"}, {"text": "倉庫は一年中低温に保たれており、野菜が新鮮なまま届く。", "target_word": "低温", "complexity_tier": "T3", "furigana": "倉庫[そうこ]は一年中[いちねんじゅう]低温[ていおん]に保[たも]たれており、野菜[やさい]が新鮮[しんせん]なまま届[とど]く。", "sentence_source": "generated"}, {"text": "バナナは低温の場所に置くと、皮が黒くなりやすい。", "target_word": "低温", "complexity_tier": "T3", "furigana": "バナナは低温[ていおん]の場所[ばしょ]に置[お]くと、皮[かわ]が黒[くろ]くなりやすい。", "sentence_source": "generated"}, {"text": "ワインは低温の暗い場所に置くと、味が落ちにくい。", "target_word": "低温", "complexity_tier": "T3", "furigana": "ワインは低温[ていおん]の暗[くら]い場所[ばしょ]に置[お]くと、味[あじ]が落[お]ちにくい。", "sentence_source": "generated"}, {"text": "工場では、薬を低温で運ぶために専用のトラックを使っている。", "target_word": "低温", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、薬[くすり]を低温[ていおん]で運[はこ]ぶために専用[せんよう]のトラックを使[つか]っている。", "sentence_source": "generated"}, {"text": "卵は低温で管理されているため、スーパーでも安心して買える。", "target_word": "低温", "complexity_tier": "T3", "furigana": "卵[たまご]は低温[ていおん]で管理[かんり]されているため、スーパーでも安心[あんしん]して買[か]える。", "sentence_source": "generated"}, {"text": "刺身を低温のケースに入れて、お客さんの家まで運んだ。", "target_word": "低温", "complexity_tier": "T3", "furigana": "刺身[さしみ]を低温[ていおん]のケースに入[い]れて、お客[きゃく]さんの家[いえ]まで運[はこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低温", "label": "基本形"}], "register": "標準", "sense_fingerprint": "冷蔵・冷凍など保存や管理に使われる、周囲より低い温度の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 6 words above tier T3 (max 3): 経る (Zipf 2.96), グルテン (Zipf 2.78), 網目 (Zipf 2.67), 緻密 (Zipf 3.25), 変容 (Zipf 3.25), 遂げる (Zipf 3.13)']::text[], 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低温", "is_correct": true, "explanation": "「低温発酵」で、周囲より低い温度での保存・管理の意味に合う"}, {"text": "色合い", "is_correct": false, "explanation": "「色合い発酵」は意味をなさず、文脈に合わない"}, {"text": "強度", "is_correct": false, "explanation": "「強度発酵」は不自然で、温度の状態を表せない"}, {"text": "音量", "is_correct": false, "explanation": "「音量発酵」は意味が通らず、発酵の条件を表さない"}], "explanations": {"低温": "「低温発酵」で、周囲より低い温度での保存・管理の意味に合う", "色合い": "「色合い発酵」は意味をなさず、文脈に合わない", "強度": "「強度発酵」は不自然で、温度の状態を表せない", "音量": "「音量発酵」は意味が通らず、発酵の条件を表さない"}, "sentence_index": 0, "correct_answer": "低温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスピーカーは低温がよく響く。", "explanation": "ここは〈低音〉（低い音）の意味。低温は温度の状態なので、音の響きには使わない"}, {"text": "彼は低温の性格で、人付き合いが苦手だ。", "explanation": "ここは〈冷淡〉（人への冷たい態度）の意味。低温は温度の状態で、人の性格には使わない"}, {"text": "売り上げが低温で、店を閉める話も出ている。", "explanation": "ここは〈低調〉（振るわない様子）の意味。低温は温度なので、売り上げの勢いには使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低温", "is_correct": true, "explanation": "「低温の暗い場所に置く」で、保存に適した低い温度の意味に合う"}, {"text": "湿度", "is_correct": false, "explanation": "「湿度の暗い場所」は不自然で、保存条件として文が通らない"}, {"text": "強風", "is_correct": false, "explanation": "「強風の暗い場所」は意味が通らない"}, {"text": "直射", "is_correct": false, "explanation": "「直射の暗い場所」は矛盾する表現で、文が成立しない"}], "explanations": {"低温": "「低温の暗い場所に置く」で、保存に適した低い温度の意味に合う", "湿度": "「湿度の暗い場所」は不自然で、保存条件として文が通らない", "強風": "「強風の暗い場所」は意味が通らない", "直射": "「直射の暗い場所」は矛盾する表現で、文が成立しない"}, "sentence_index": 6, "correct_answer": "低温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前には低温のビルが並んでいる。", "explanation": "ここは〈低層〉（階数が低い建物）の意味。温度の低さとは関係がないので、建物の階数には使わない"}, {"text": "彼は低温に対応して、場を落ち着かせた。", "explanation": "ここは〈冷静〉（落ち着いている様子）の意味。低温は温度なので、対応の仕方には使わない"}, {"text": "彼は低温で、誰にでも丁寧に話す。", "explanation": "ここは〈低姿勢〉（へりくだる態度）の意味。低温は温度の状態なので、人の態度には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この魚は低温を保存すると、鮮度が保てる。", "corrected_sentence": "この魚は低温で保存すると、鮮度が保てる。", "error_description": "「保存する」の手段・場所を表す「で」が正しい。「を」は目的語を表すが、低温は保存する対象の物ではないので誤り", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チーズは低温だ場所に置くと、乾燥しにくい。", "corrected_sentence": "チーズは低温の場所に置くと、乾燥しにくい。", "error_description": "名詞「低温」が場所を修飾するときは「の」が必要。「だ」は述語の形なので「低温だ場所」は誤り", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
