INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52293, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンやめんのなかにある、ねばねばしたもののことです。", "primary_collocate": null, "pronunciation": "ぐるてん", "ipa": "ɡɯɾɯteɴ", "syllable_count": 4, "sentences": [{"text": "パンのグルテンは、ねばねばして生地をのばしてくれる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "パンのグルテンは、ねばねばして生地[きじ]をのばしてくれる。", "sentence_source": "generated"}, {"text": "うどんがのびるのは、中にグルテンがあるからだ。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "うどんがのびるのは、中[なか]にグルテンがあるからだ。", "sentence_source": "generated"}, {"text": "グルテンのない粉で作ると、パンはぼそぼそになる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "グルテンのない粉[こな]で作[つく]ると、パンはぼそぼそになる。", "sentence_source": "generated"}, {"text": "兄はグルテンを食べないようにして、米で作ったパンを選んでいる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "兄[あに]はグルテンを食[た]べないようにして、米[こめ]で作[つく]ったパンを選[えら]んでいる。", "sentence_source": "generated"}, {"text": "グルテンが多い粉で作ったパスタは、かむと弾力がある。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "グルテンが多[おお]い粉[こな]で作[つく]ったパスタは、かむと弾力[だんりょく]がある。", "sentence_source": "generated"}, {"text": "母は、グルテンを含まない粉で作られた商品を探している。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "母[はは]は、グルテンを含[ふく]まない粉[こ]で作[つく]られた商品[しょうひん]を探[さが]している。", "sentence_source": "generated"}, {"text": "手で生地を引っぱると、グルテンがのびるのが見える。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "手[て]で生地[きじ]を引[ひ]っぱると、グルテンがのびるのが見[み]える。", "sentence_source": "generated"}, {"text": "店には「グルテンなし」と書いたパンが並んでいる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "店[みせ]には「グルテンなし」と書[か]いたパンが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "ラーメンの麺がもちもちしているのは、グルテンのおかげだ。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "ラーメンの麺[めん]がもちもちしているのは、グルテンのおかげだ。", "sentence_source": "generated"}, {"text": "水で小麦粉を洗うと、手にグルテンのかたまりが残る。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "水[みず]で小麦粉[こむぎこ]を洗[あら]うと、手[て]にグルテンのかたまりが残[のこ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グルテン", "label": "基本形"}], "register": "標準", "sense_fingerprint": "パンや麺の中にある、粘りのある成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52293, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グルテン", "is_correct": true, "explanation": "ねばねばして生地をのばすのはパンのグルテンで、文脈に合う。"}, {"text": "塩", "is_correct": false, "explanation": "塩はねばねばせず、生地をのばす働きもないので合わない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は粘りのある成分ではなく、生地をのばせないので合わない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は粘りで生地をのばす成分ではないので合わない。"}], "explanations": {"グルテン": "ねばねばして生地をのばすのはパンのグルテンで、文脈に合う。", "塩": "塩はねばねばせず、生地をのばす働きもないので合わない。", "氷": "氷は粘りのある成分ではなく、生地をのばせないので合わない。", "牛乳": "牛乳は粘りで生地をのばす成分ではないので合わない。"}, "sentence_index": 0, "correct_answer": "グルテン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "グルテンが発酵して、パンがふくらむ。", "explanation": "ここは〈酵母〉の役割。発酵させるのは酵母で、グルテンはねばねばした成分なので合わない。"}, {"text": "グルテンを加えると、生地がしょっぱくなる。", "explanation": "ここは〈塩〉の意味。しょっぱくするのは塩で、グルテンには味がないので合わない。"}, {"text": "髪をグルテンで乾かす。", "explanation": "ここは〈ドライヤー〉の意味。髪を乾かす道具はドライヤーで、グルテンは乾燥させる道具にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52293, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グルテン", "is_correct": true, "explanation": "引っぱるとのびるのは生地の中のグルテンで、文脈に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は引っぱってものびないので、「砂糖がのびる」は合わない。"}, {"text": "香料", "is_correct": false, "explanation": "香料にはのびる性質がないので合わない。"}, {"text": "火", "is_correct": false, "explanation": "火は引っぱってものびないので、文脈に合わない。"}], "explanations": {"グルテン": "引っぱるとのびるのは生地の中のグルテンで、文脈に合う。", "砂糖": "砂糖は引っぱってものびないので、「砂糖がのびる」は合わない。", "香料": "香料にはのびる性質がないので合わない。", "火": "火は引っぱってものびないので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "グルテン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゼリーはグルテンで固めてある。", "explanation": "ここは〈寒天〉の意味。ゼリーを固めるのは寒天やゼラチンで、グルテンは固める働きをしないので合わない。"}, {"text": "このお菓子は、グルテンで色をつけている。", "explanation": "ここは〈色素〉の意味。色をつけるのは着色料で、グルテンは色を出さないので合わない。"}, {"text": "カレーは、グルテンで風味をつけている。", "explanation": "ここは〈香辛料〉の意味。風味を加えるのはスパイスで、グルテンには香りがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52293, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うどんをこねると、グルテンを増えて、こしが出る。", "corrected_sentence": "うどんをこねると、グルテンが増えて、こしが出る。", "error_description": "「増える」の主語は「グルテン」なので、「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52293, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生地を強くこねると、グルテンが増えるて、パンがよくふくらむ。", "corrected_sentence": "生地を強くこねると、グルテンが増えて、パンがよくふくらむ。", "error_description": "「増えて」の活用形が誤り。「増えるて」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「グルテンができて」の主語を示す「が」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「できる」は自動詞なので目的語の「を」を取らず、「グルテンをできて」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「グルテンとできて」は並列の意味にならず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「グルテンのできて」は連体修飾にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「グルテンができて」の主語を示す「が」で正しい。", "を": "「できる」は自動詞なので目的語の「を」を取らず、「グルテンをできて」は誤り。", "と": "「グルテンとできて」は並列の意味にならず、不自然。", "の": "「グルテンのできて」は連体修飾にならず、文が成り立たない。"}, "error_tags": {"を": "自動詞との誤用", "と": "並列の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「グルテンがゆるむ」の主語を示す「が」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「グルテンにゆるむ」では動作の主体が合わず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「グルテンでゆるむ」は手段の意味にならず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「グルテンからゆるむ」は起点の意味にならず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「グルテンがゆるむ」の主語を示す「が」で正しい。", "に": "「グルテンにゆるむ」では動作の主体が合わず、不自然。", "で": "「グルテンでゆるむ」は手段の意味にならず、不自然。", "から": "「グルテンからゆるむ」は起点の意味にならず、不自然。"}, "error_tags": {"に": "動作主の誤用", "で": "手段の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦粉に水を加えてこねるとできる、弾力のあるたんぱく質の一種。パンやパスタの生地に粘りとふくらみを与える。", "primary_collocate": null, "pronunciation": "ぐるてん", "ipa": "ɡɯɾɯteɴ", "syllable_count": 4, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "その後[そのご]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "小麦粉に水を入れてよくこねると、グルテンができて生地がのびる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]に水[みず]を入[い]れてよくこねると、グルテンができて生地[きじ]がのびる。", "sentence_source": "generated"}, {"text": "パン生地をたたくと、グルテンが強くなり、ふっくら焼ける。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "パン生地[きじ]をたたくと、グルテンが強[つよ]くなり、ふっくら焼[や]ける。", "sentence_source": "generated"}, {"text": "米粉にはグルテンがないので、パンが膨らみにくい。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "米粉[こめこ]にはグルテンがないので、パンが膨[ふく]らみにくい。", "sentence_source": "generated"}, {"text": "グルテンは小麦のたんぱく質で、生地に粘りを与える。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "グルテンは小麦[こむぎ]のたんぱく質[しつ]で、生地[きじ]に粘[ねば]りを与[あた]える。", "sentence_source": "generated"}, {"text": "こねすぎるとグルテンが強くなりすぎて、クッキーが硬くなる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "こねすぎるとグルテンが強[つよ]くなりすぎて、クッキーが硬[かた]くなる。", "sentence_source": "generated"}, {"text": "強力粉は薄力粉よりグルテンが多く、パン作りに向いている。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "強力粉[きょうりきこ]は薄力粉[はくりきこ]よりグルテンが多[おお]く、パン作[づく]りに向[む]いている。", "sentence_source": "generated"}, {"text": "生地を休ませると、グルテンがゆるんで形を整えやすくなる。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "生地[きじ]を休[やす]ませると、グルテンがゆるんで形[かたち]を整[ととの]えやすくなる。", "sentence_source": "generated"}, {"text": "セリアック病の人は、グルテンを含む食品を食べられない。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "セリアック病[びょう]の人[ひと]は、グルテンを含[ふく]む食品[しょくひん]を食[た]べられない。", "sentence_source": "generated"}, {"text": "麩はグルテンを主な材料にした、日本の伝統的な食べ物だ。", "target_word": "グルテン", "complexity_tier": "T3", "furigana": "麩[ふ]はグルテンを主[おも]な材料[ざいりょう]にした、日本[にほん]の伝統的[でんとうてき]な食[た]べ物[もの]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グルテン", "label": "基本形"}], "register": "標準", "sense_fingerprint": "小麦粉をこねるとできる、生地に粘りとふくらみを与えるたんぱく質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グルテン", "is_correct": true, "explanation": "低温発酵で網目が緻密になるのは小麦のたんぱく質であるグルテンで、文脈に合う。"}, {"text": "酵母", "is_correct": false, "explanation": "酵母は生き物で網目状の構造を作らないので、「酵母の網目」は合わない。"}, {"text": "塩分", "is_correct": false, "explanation": "塩分は網目の構造を作らない。ここは小麦たんぱく質の網目を指す。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は網目状の構造を持たず、「砂糖の網目」は意味をなさない。"}], "explanations": {"グルテン": "低温発酵で網目が緻密になるのは小麦のたんぱく質であるグルテンで、文脈に合う。", "酵母": "酵母は生き物で網目状の構造を作らないので、「酵母の網目」は合わない。", "塩分": "塩分は網目の構造を作らない。ここは小麦たんぱく質の網目を指す。", "砂糖": "砂糖は網目状の構造を持たず、「砂糖の網目」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "グルテン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "血液は、エネルギー源としてグルテンを全身に運ぶ。", "explanation": "ここは〈グルコース〉の意味。エネルギー源として血液で運ばれるのはブドウ糖で、グルテンは小麦のたんぱく質なので合わない。"}, {"text": "グルテンが発酵して、生地がふくらむ。", "explanation": "ここは〈酵母〉の役割。発酵させるのは酵母で、グルテンは生地に粘りを与えるたんぱく質なので合わない。"}, {"text": "このジャムは、グルテンを入れて甘くしている。", "explanation": "ここは〈甘味料〉の役割。甘くするのは砂糖などで、グルテンには甘みがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グルテン", "is_correct": true, "explanation": "薄力粉より多く、パン作りに向く成分はグルテンで、文脈に合う。"}, {"text": "香料", "is_correct": false, "explanation": "香料は粉の量を比べる対象にならず、「香料が多く」は合わない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は粉に含まれないので、「氷が多く」は成り立たない。"}, {"text": "炭酸ガス", "is_correct": false, "explanation": "炭酸ガスは粉の成分として比べる語ではなく、パン作りの向きとも合わない。"}], "explanations": {"グルテン": "薄力粉より多く、パン作りに向く成分はグルテンで、文脈に合う。", "香料": "香料は粉の量を比べる対象にならず、「香料が多く」は合わない。", "氷": "氷は粉に含まれないので、「氷が多く」は成り立たない。", "炭酸ガス": "炭酸ガスは粉の成分として比べる語ではなく、パン作りの向きとも合わない。"}, "sentence_index": 6, "correct_answer": "グルテン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゼリーはグルテンで固めてある。", "explanation": "ここは〈寒天〉の意味。ゼリーを固めるのは寒天やゼラチンで、グルテンは固める働きをしないので合わない。"}, {"text": "このお菓子は、グルテンで色をつけている。", "explanation": "ここは〈色素〉の意味。色をつけるのは着色料で、グルテンは色を出さないので合わない。"}, {"text": "カレーは、グルテンで風味をつけている。", "explanation": "ここは〈香辛料〉の意味。風味を加えるのはスパイスで、グルテンには香りがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンの生地をよくこねると、グルテンを強くなって、ふくらみがよくなる。", "corrected_sentence": "パンの生地をよくこねると、グルテンが強くなって、ふくらみがよくなる。", "error_description": "「強くなる」の主語は「グルテン」なので、主語を示す「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強力粉はグルテンが多なので、パンがよく膨らむ。", "corrected_sentence": "強力粉はグルテンが多いので、パンがよく膨らむ。", "error_description": "「グルテン」を説明する形容詞「多い」の活用が誤り。「多な」は形容詞の形ではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「編目が大きすぎて」と、編目の大きさを述べる主語の「が」になる。"}, {"text": "を", "is_correct": false, "explanation": "「編目を大きすぎて」では大きさを述べる主語が立たない。「を」は動作の対象を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "「編目に大きすぎて」は成り立たない。「に」は場所や相手を示すので、大きさの主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「編目で大きすぎて」は不自然。「で」は手段や場所を示すので、大きさの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「編目が大きすぎて」と、編目の大きさを述べる主語の「が」になる。", "を": "「編目を大きすぎて」では大きさを述べる主語が立たない。「を」は動作の対象を示す助詞。", "に": "「編目に大きすぎて」は成り立たない。「に」は場所や相手を示すので、大きさの主語にならない。", "で": "「編目で大きすぎて」は不自然。「で」は手段や場所を示すので、大きさの主語にはならない。"}, "error_tags": {"を": "対象", "に": "場所・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「見る」の対象は「を」で示すので、「私の編目を見て」となる。"}, {"text": "と", "is_correct": false, "explanation": "「編目と見て」は不自然。「と」は並列や相手を示すが、見る対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「編目へ見て」は成り立たない。「へ」は方向を示すので、見る対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「編目が見て」は不自然。「が」は主語を示すので、見る対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "正解。「見る」の対象は「を」で示すので、「私の編目を見て」となる。", "と": "「編目と見て」は不自然。「と」は並列や相手を示すが、見る対象にはならない。", "へ": "「編目へ見て」は成り立たない。「へ」は方向を示すので、見る対象を表せない。", "が": "「編目が見て」は不自然。「が」は主語を示すので、見る対象には使えない。"}, "error_tags": {"と": "相手・引用", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "編み目は、何かを編んだときにできる、糸と糸の間の小さな穴のような模様です。", "primary_collocate": null, "pronunciation": "へんもく", "ipa": "heɴmokɯ", "syllable_count": 4, "sentences": [{"text": "祖母のセーターは編目がそろっていて、とてもきれいだ。", "target_word": "編目", "complexity_tier": "T3", "furigana": "祖母[そぼ]のセーターは編目[へんもく]がそろっていて、とてもきれいだ。", "sentence_source": "generated"}, {"text": "編目が大きすぎて、手袋から指が出てしまった。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]が大[おお]きすぎて、手袋[てぶくろ]から指[ゆび]が出[で]てしまった。", "sentence_source": "generated"}, {"text": "毛糸が細いので、編目を数えるのが大変です。", "target_word": "編目", "complexity_tier": "T3", "furigana": "毛糸[けいと]が細[ほそ]いので、編目[へんもく]を数[かぞ]えるのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "編目を一つ落としたため、そこに小さな穴ができた。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]を一[ひと]つ落[お]としたため、そこに小[ちい]さな穴[あな]ができた。", "sentence_source": "generated"}, {"text": "初めて編んだマフラーは、編目がばらばらだった。", "target_word": "編目", "complexity_tier": "T3", "furigana": "初[はじ]めて編[あ]んだマフラーは、編目[へんもく]がばらばらだった。", "sentence_source": "generated"}, {"text": "太い針を使うと、編目が大きくなる。", "target_word": "編目", "complexity_tier": "T3", "furigana": "太[ふと]い針[はり]を使[つか]うと、編目[へんもく]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "編目から風が入るので、このセーターは冬には寒い。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]から風[かぜ]が入[はい]るので、このセーターは冬[ふゆ]には寒[さむ]い。", "sentence_source": "generated"}, {"text": "先生は私の編目を見て、「きつすぎますよ」と言った。", "target_word": "編目", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の編目[へんもく]を見[み]て、「きつすぎますよ」と言[い]った。", "sentence_source": "generated"}, {"text": "編目をほどいて、もう一度最初からやり直した。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]をほどいて、もう一度[いちど]最初[さいしょ]からやり直[なお]した。", "sentence_source": "generated"}, {"text": "編目が細かいほど、温かいセーターになる。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]が細[こま]かいほど、温[あたた]かいセーターになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "編目", "label": "基本形"}], "register": "中立", "sense_fingerprint": "編み物で糸と糸の間にできる小さな目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "編目", "is_correct": true, "explanation": "正解。編んだ目が規則正しく並んでいるという意味で、「編目がそろう」は自然な組み合わせ。"}, {"text": "鼻歌", "is_correct": false, "explanation": "「鼻歌がそろっていて」は意味をなさない。セーターの目の並びを表す語ではない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「昼寝がそろう」は成り立たない。昼寝は並べて揃えるものではない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨がそろっていて」はセーターの状態を表せず、不自然。"}], "explanations": {"編目": "正解。編んだ目が規則正しく並んでいるという意味で、「編目がそろう」は自然な組み合わせ。", "鼻歌": "「鼻歌がそろっていて」は意味をなさない。セーターの目の並びを表す語ではない。", "昼寝": "「昼寝がそろう」は成り立たない。昼寝は並べて揃えるものではない。", "雨": "「雨がそろっていて」はセーターの状態を表せず、不自然。"}, "sentence_index": 0, "correct_answer": "編目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ひもの編目を強く締めて、ほどけないようにした。", "explanation": "ここは〈結び目〉の意味。編目は編み物で糸が作る目なので、ひもの結び目には使わない。"}, {"text": "プリーツスカートの編目を、アイロンできれいにそろえた。", "explanation": "ここは〈ひだ〉の意味。布を折って作る筋（ひだ）は編目ではなく、編み物で糸が作る目が編目。"}, {"text": "刺繍の編目を細かくそろえると、きれいに見える。", "explanation": "ここは〈ステッチ〉（刺繍の縫い目）の意味。刺繍は編み物ではないので、編目は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "編目", "is_correct": true, "explanation": "正解。「編目から風が入る」は、編み目の隙間から風が通るという意味で自然。"}, {"text": "染料", "is_correct": false, "explanation": "「染料から風が入る」は成り立たない。染料は布を染める材料で、風の通り道にはならない。"}, {"text": "糸巻き", "is_correct": false, "explanation": "「糸巻きから風が入る」は不自然。糸巻きは糸を巻く道具で、風の出入り口を指さない。"}, {"text": "縫い糸", "is_correct": false, "explanation": "「縫い糸から風が入る」とは言わない。縫い糸は縫うための糸で、隙間を指す語ではない。"}], "explanations": {"編目": "正解。「編目から風が入る」は、編み目の隙間から風が通るという意味で自然。", "染料": "「染料から風が入る」は成り立たない。染料は布を染める材料で、風の通り道にはならない。", "糸巻き": "「糸巻きから風が入る」は不自然。糸巻きは糸を巻く道具で、風の出入り口を指さない。", "縫い糸": "「縫い糸から風が入る」とは言わない。縫い糸は縫うための糸で、隙間を指す語ではない。"}, "sentence_index": 6, "correct_answer": "編目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "セーターに編目が付いていたので、粘着テープで取った。", "explanation": "ここは〈糸くず〉の意味。編目は編み物の目の一つ一つで、セーターに付いて取り除くものではない。"}, {"text": "ミシンで縫った編目がまっすぐで、きれいに仕上がった。", "explanation": "ここは〈縫い目〉の意味。ミシンで布を縫った線は編目ではなく、編み物で糸を輪にして作るものが編目。"}, {"text": "定規の編目を一ミリずつ数える。", "explanation": "ここは〈目盛り〉の意味。定規に刻まれたしるしを数える場面で、編目（編み物の目）とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この編目に一つずつ数えると、ほどけた所がわかる。", "corrected_sentence": "この編目を一つずつ数えると、ほどけた所がわかる。", "error_description": "「数える」の対象は助詞「を」で示す。「編目に」は誤りで、正しくは「編目を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この毛糸を使うと、編目をきれいにそろう。", "corrected_sentence": "この毛糸を使うと、編目がきれいにそろう。", "error_description": "「そろう」の主語は助詞「が」で示す。「編目を」は誤りで、正しくは「編目が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「編目の細かいかご」は、編目が細かいかごという修飾関係で、「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「編目を細かいかご」は成り立たない。「を」は動作の対象を示すので、名詞の修飾に使えない。"}, {"text": "に", "is_correct": false, "explanation": "「編目に細かいかご」は不自然。「に」は場所や相手を示すので、修飾関係を作れない。"}, {"text": "で", "is_correct": false, "explanation": "「編目で細かいかご」は意味が通らない。「で」は手段や場所を示すので、修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「編目の細かいかご」は、編目が細かいかごという修飾関係で、「の」が正しい。", "を": "「編目を細かいかご」は成り立たない。「を」は動作の対象を示すので、名詞の修飾に使えない。", "に": "「編目に細かいかご」は不自然。「に」は場所や相手を示すので、修飾関係を作れない。", "で": "「編目で細かいかご」は意味が通らない。「で」は手段や場所を示すので、修飾にならない。"}, "error_tags": {"を": "対象", "に": "場所・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「編目の細かい網戸」は、編目が細かい網戸という修飾関係で、「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「編目を」と「網戸を」で「を」が二つ重なり、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「編目へ細かい網戸」は不自然。「へ」は方向を示すので、修飾にならない。"}, {"text": "から", "is_correct": false, "explanation": "「編目から細かい網戸」は成り立たない。「から」は起点を示すので、修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「編目の細かい網戸」は、編目が細かい網戸という修飾関係で、「の」が正しい。", "を": "「編目を」と「網戸を」で「を」が二つ重なり、文として不自然。", "へ": "「編目へ細かい網戸」は不自然。「へ」は方向を示すので、修飾にならない。", "から": "「編目から細かい網戸」は成り立たない。「から」は起点を示すので、修飾にならない。"}, "error_tags": {"を": "対象（「を」の重複）", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "編み物で、糸が交差してできる目の一つ一つ。織物や網などの、糸の規則正しい並び。網目のように、細かい部分まで行き届いている様子のたとえ。", "primary_collocate": null, "pronunciation": "へんもく", "ipa": "heɴmokɯ", "syllable_count": 4, "sentences": [{"text": "漁師は網の編目を一つずつ確かめている。", "target_word": "編目", "complexity_tier": "T3", "furigana": "漁師[りょうし]は網[あみ]の編目[へんもく]を一[ひと]つずつ確[たし]かめている。", "sentence_source": "generated"}, {"text": "編目の細かいかごは、小さな物を入れても落ちない。", "target_word": "編目", "complexity_tier": "T3", "furigana": "編目[へんもく]の細[こま]かいかごは、小[ちい]さな物[もの]を入[い]れても落[お]ちない。", "sentence_source": "generated"}, {"text": "このざるは編目が規則正しく並んでいる。", "target_word": "編目", "complexity_tier": "T3", "furigana": "このざるは編目[へんもく]が規則[きそく]正[ただ]しく並[なら]んでいる。", "sentence_source": "generated"}, {"text": "魚が小さいので、編目をすり抜けて逃げてしまった。", "target_word": "編目", "complexity_tier": "T3", "furigana": "魚[さかな]が小[ちい]さいので、編目[へんもく]をすり抜[ぬ]けて逃[に]げてしまった。", "sentence_source": "generated"}, {"text": "糸が交差してできる編目が、きれいな模様を作る。", "target_word": "編目", "complexity_tier": "T3", "furigana": "糸[いと]が交差[こうさ]してできる編目[へんもく]が、きれいな模様[もよう]を作[つく]る。", "sentence_source": "generated"}, {"text": "この計画は編目のように細かく、抜けがない。", "target_word": "編目", "complexity_tier": "T3", "furigana": "この計画[けいかく]は編目[へんもく]のように細[こま]かく、抜[ぬ]けがない。", "sentence_source": "generated"}, {"text": "古い布は編目が切れて、ほつれてきた。", "target_word": "編目", "complexity_tier": "T3", "furigana": "古[ふる]い布[ぬの]は編目[へんもく]が切[き]れて、ほつれてきた。", "sentence_source": "generated"}, {"text": "虫が入らないように、編目の細かい網戸を付けた。", "target_word": "編目", "complexity_tier": "T3", "furigana": "虫[むし]が入[はい]らないように、編目[へんもく]の細[こま]かい網戸[あみど]を付[つ]けた。", "sentence_source": "generated"}, {"text": "織物の編目をよく見ると、糸の並び方がわかる。", "target_word": "編目", "complexity_tier": "T3", "furigana": "織物[おりもの]の編目[へんもく]をよく見[み]ると、糸[いと]の並[なら]び方[かた]がわかる。", "sentence_source": "generated"}, {"text": "規則的な編目を作るには、力を一定にして編む。", "target_word": "編目", "complexity_tier": "T3", "furigana": "規則的[きそくてき]な編目[へんもく]を作[つく]るには、力[ちから]を一定[いってい]にして編[あ]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "編目", "label": "基本形"}], "register": "中立", "sense_fingerprint": "網や織物の規則正しい目、細部まで行き届くことのたとえ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "編目", "is_correct": true, "explanation": "正解。網の目を一つずつ確かめるという文で、「編目」が正しい語。"}, {"text": "漁船", "is_correct": false, "explanation": "「網の漁船を確かめる」とは言わない。漁船は網の目ではないので合わない。"}, {"text": "港", "is_correct": false, "explanation": "「網の港を確かめる」は意味が通らない。港は網の一部ではない。"}, {"text": "波", "is_correct": false, "explanation": "「網の波を一つずつ確かめる」は成り立たない。波は網の目を指さない。"}], "explanations": {"編目": "正解。網の目を一つずつ確かめるという文で、「編目」が正しい語。", "漁船": "「網の漁船を確かめる」とは言わない。漁船は網の目ではないので合わない。", "港": "「網の港を確かめる」は意味が通らない。港は網の一部ではない。", "波": "「網の波を一つずつ確かめる」は成り立たない。波は網の目を指さない。"}, "sentence_index": 0, "correct_answer": "編目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "靴ひもの編目がほどけたので、固く結び直した。", "explanation": "ここは〈結び目〉の意味。ほどけて結び直すのは靴ひもの結び目で、糸が交差してできる編目ではない。"}, {"text": "定規の編目は一ミリごとに刻まれている。", "explanation": "ここは〈目盛り〉の意味。定規に刻まれたしるしで、糸の交差でできる編目とは別物。"}, {"text": "ミシンの編目が曲がっていたので、縫い直した。", "explanation": "ここは〈縫い目〉の意味。ミシンで布を縫った線で、糸を交差させて作る編目ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "編目", "is_correct": true, "explanation": "正解。布の目が切れてほつれるという文で、「編目」が主語として自然。"}, {"text": "色", "is_correct": false, "explanation": "「布の色が切れてほつれる」とは言わない。色はほつれの主語にならない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が切れてほつれる」は成り立たない。布の状態を表す語ではない。"}, {"text": "染み", "is_correct": false, "explanation": "「染みが切れてほつれる」とは言わない。染みは汚れで、糸の切れ目とは関係ない。"}], "explanations": {"編目": "正解。布の目が切れてほつれるという文で、「編目」が主語として自然。", "色": "「布の色が切れてほつれる」とは言わない。色はほつれの主語にならない。", "天気": "「天気が切れてほつれる」は成り立たない。布の状態を表す語ではない。", "染み": "「染みが切れてほつれる」とは言わない。染みは汚れで、糸の切れ目とは関係ない。"}, "sentence_index": 6, "correct_answer": "編目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁に編目があいたので、修理を頼んだ。", "explanation": "ここは〈穴〉の意味。編目は糸の交差でできる目で、壁にあく穴には使わない。"}, {"text": "刺繍の編目を細かくそろえると、きれいに見える。", "explanation": "ここは〈ステッチ〉（刺繍の縫い目）の意味。編目は編み物や網の目で、刺繍には使わない。"}, {"text": "階段の編目が低いので、子どもが上りやすい。", "explanation": "ここは〈段〉（階段の一段一段）の意味。編目は糸が作る目で、階段の段差は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "網の編目を細かいので、小魚も逃げにくい。", "corrected_sentence": "網の編目が細かいので、小魚も逃げにくい。", "error_description": "「細かい」の主語は助詞「が」で示す。「編目を細かい」は誤りで、正しくは「編目が細かい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "糸を正しく交差させると、きれいな編目が現す。", "corrected_sentence": "糸を正しく交差させると、きれいな編目が現れる。", "error_description": "「現れる」は自動詞で、主語「編目が」と結びつく。「現す」は他動詞で誤り。正しくは「現れる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
